// Plots every visible, located photo on one overview map — Leaflet plus
// OpenStreetMap tiles, the only realistic option with no API key. Off by
// default: this is the *first* feature in this script to break the
// "one file, nothing else happens" promise, since it loads an external
// script and image tiles from a third party at page-load time. Has no
// effect at all unless ENABLE_PHOTO_LOCATION is also on and at least one
// photo actually has a visible location — see ENABLE_PHOTO_LOCATION's
// own doc comment for that gating. Shared as ?map
// URL, with a smaller preview embedded on the gallery root.
gallery_setting('ENABLE_MAP', false);   // (older settings files have this line: it is still understood, with no "isn't a setting" notice, and ignored; a map is available wherever locations are, and each folder's own Map switch and the visitors' map buttons are the control. The next save in Settings drops it.)

// How close together (in miles) two photos' locations have to be before
// the map merges them into a single cluster pin instead of showing each
// individually. 1 is a neighbourhood: photos of one sight share a pin and a
// trip across a city doesn't collapse into one. A dense city trip and a
// cross-country road trip want very different values, so this is
// deliberately tunable per deployment (and per folder) rather than a fixed
// constant buried in code. 0 turns grouping off.
define('MAP_CLUSTER_RADIUS_MILES', gallery_setting('MAP_CLUSTER_RADIUS_MILES', 1));
gallery_setting(null, null);   // done asking: report any name in the settings file that isn't a setting

$dir = __DIR__;
$self = basename(__FILE__);

// Imagick is what makes HEIC/HEIF support and quality resizing possible;
// GD is used as a fallback for resizing (but can't decode HEIC).
$imagickAvailable = class_exists('Imagick');
$gdAvailable = extension_loaded('gd');

// HEIC/HEIF requires Imagick to convert, and that conversion has nowhere
// to go without the thumbnail cache enabled (see ENABLE_THUMBNAIL_CACHE
// above) — so without both, those files are excluded rather than shown
// broken.
$imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'];
if ($imagickAvailable && ENABLE_THUMBNAIL_CACHE) {
    $imageExtensions[] = 'heic';
    $imageExtensions[] = 'heif';
}

/** What to call the gallery's contents in labels: "media" once videos are switched on, "photos" until then. */
function media_word() {
    return ENABLE_VIDEO ? 'media' : 'photos';
}

/** Whether a filename's extension is one of the two video formats this
 *  script recognizes when ENABLE_VIDEO is on — used everywhere a video
 *  item needs different handling than a photo (serving, the grid
 *  placeholder, cover-card selection), regardless of whether video
 *  recognition is actually turned on; it's purely an extension check. */
function is_video_file($filename) {
    $ext = strtolower(pathinfo($filename, PATHINFO_EXTENSION));
    return in_array($ext, ['mov', 'mp4'], true);
}

// $mediaExtensions is what the scan below actually filters by — photo
// extensions, plus .mov/.mp4 once ENABLE_VIDEO is on. Kept separate from
// $imageExtensions itself, which stays photo-only: it's still used
// downstream (image_cache_path, generate_resized_jpeg) for logic that
// only ever makes sense for an actual photo.
$mediaExtensions = $imageExtensions;
if (ENABLE_VIDEO) {
    $mediaExtensions[] = 'mov';
    $mediaExtensions[] = 'mp4';
}

/**
 * Recursively scans a real directory into a tree: ['files' => [bare
 * filenames loose directly here, already sorted per PHOTO_SORT_ORDER],
 * 'subdirs' => [folderName => nested node, ...]]. Only ever called when
 * AUTO_GROUP_BY_FOLDER is on — a flat folder keeps using the untouched
 * scan further below, so there is zero behavior change for the common
 * case regardless of anything in this function.
 *
 * Two things this has to get right every time it steps into a subfolder:
 * it must never follow a symlink, to a folder or to a file (a link pointing outside the gallery
 * root would otherwise let the scan's own trusted output enumerate
 * arbitrary filesystem paths as "valid," which every downstream
 * allowlist check would then trust) — checked both directly (is_link)
 * and by confirming the resolved real path actually sits under its own
 * parent's real path, so a less obvious escape doesn't slip through
 * either. And it must exclude .gallery-cache — the one *directory* among
 * this script's own infrastructure files — from being scanned as if it
 * were a photo subfolder.
 */
function scan_folder_tree($realDir, $mediaExtensions, $self, $isRoot = true) {
    $node = ['files' => [], 'subdirs' => []];
    // A folder it has no business walking into (a system or recycle folder), and a ceiling on how much one visit scans, so a gallery
    // dropped into a huge tree (a whole web root) cannot make every page crawl. The Health check says when the ceiling was hit.
    static $dirs = 0, $files = 0;
    if ($isRoot) { $dirs = 0; $files = 0; $GLOBALS['__scan_truncated'] = false; }
    if (++$dirs > SCAN_MAX_FOLDERS || $files > SCAN_MAX_FILES) { $GLOBALS['__scan_truncated'] = true; return $node; }
    $entries = @scandir($realDir);
    if ($entries === false) return $node;
    $parentReal = realpath($realDir);
    foreach ($entries as $entry) {
        if ($entry === '.' || $entry === '..') continue;
        if ($isRoot && $entry === $self) continue;
        $path = $realDir . '/' . $entry;
        if (is_link($path)) continue;   // (a link is never followed: not to a folder, and not to a file, which could be anywhere on the server)
        if (is_file($path)) {
            $ext = strtolower(pathinfo($entry, PATHINFO_EXTENSION));
            if (in_array($ext, $mediaExtensions, true)) {
                $node['files'][] = $entry; $files++;
            }
            continue;
        }
        if (!is_dir($path) || $entry[0] === '.' || is_link($path) || in_array($entry, SCAN_SKIP_FOLDERS, true)) {
            continue;   // (dot folders such as .git and .gallery-cache are never photo folders)
        }
        $childReal = realpath($path);
        if ($childReal === false || $parentReal === false
            || strpos($childReal, $parentReal . DIRECTORY_SEPARATOR) !== 0) {
            continue;
        }
        $node['subdirs'][$entry] = scan_folder_tree($path, $mediaExtensions, $self, false);
    }
    if (PHOTO_SORT_ORDER === 'mtime') {
        $times = [];   // (each file's date is read once, not at every comparison)
        foreach ($node['files'] as $f) $times[$f] = @filemtime("$realDir/$f") ?: 0;
        usort($node['files'], function ($a, $b) use ($times) {
            return $times[$a] <=> $times[$b];
        });
    } else {
        usort($node['files'], function ($a, $b) {
            return strnatcasecmp($a, $b);
        });
    }
    return $node;
}

/**
 * For when AUTO_GROUP_BY_FOLDER is off: a bounded look for photos/videos
 * sitting in subfolders, so a first-time owner who organized a trip into
 * subfolders sees *why* the gallery looks empty instead of nothing at
 * all. Bounded on purpose — this script is often dropped into a folder
 * that already has unrelated, possibly huge subtrees (a whole web root),
 * and it must never walk all of that on every request just to print a
 * hint. Visits at most $maxDirs directories, never follows symlinks, and
 * skips dot-directories (.git, .gallery-cache). Returns [count found,
 * whether the search was cut short].
 */
function count_media_in_subfolders($realDir, $mediaExtensions, $maxDirs = 40) {
    $count = 0;
    $visited = 0;
    $truncated = false;
    $queue = [];
    foreach ((@scandir($realDir) ?: []) as $entry) {
        if ($entry[0] === '.') continue;
        $path = $realDir . '/' . $entry;
        if (is_dir($path) && !is_link($path)) $queue[] = $path;
    }
    while ($queue) {
        if ($visited++ >= $maxDirs) {
            $truncated = true;
            break;
        }
        $current = array_shift($queue);
        foreach ((@scandir($current) ?: []) as $entry) {
            if ($entry[0] === '.') continue;
            $path = $current . '/' . $entry;
            if (is_link($path)) continue;
            if (is_dir($path)) {
                $queue[] = $path;
            } elseif (in_array(strtolower(pathinfo($entry, PATHINFO_EXTENSION)), $mediaExtensions, true)) {
                $count++;
            }
        }
    }
    return [$count, $truncated];
}

/** The top-level subfolders that hold photos or videos, with how many each holds (what is hidden while Show subfolders is off): a
 *  list of ['name' => .., 'count' => ..], biggest first, and whether the search was cut short. Bounded and link-safe like the count above. */
function hidden_subfolders_summary($realDir, $mediaExtensions, $maxDirs = 40) {
    $per = []; $visited = 0; $truncated = false; $queue = [];
    foreach ((@scandir($realDir) ?: []) as $entry) {
        if ($entry[0] === '.') continue;
        $path = $realDir . '/' . $entry;
        if (is_dir($path) && !is_link($path)) $queue[] = [$path, $entry];
    }
    while ($queue) {
        if ($visited++ >= $maxDirs) { $truncated = true; break; }
        [$current, $top] = array_shift($queue);
        foreach ((@scandir($current) ?: []) as $entry) {
            if ($entry[0] === '.') continue;
            $path = $current . '/' . $entry;
            if (is_link($path)) continue;
            if (is_dir($path)) $queue[] = [$path, $top];
            elseif (in_array(strtolower(pathinfo($entry, PATHINFO_EXTENSION)), $mediaExtensions, true)) $per[$top] = ($per[$top] ?? 0) + 1;
        }
    }
    arsort($per);
    $out = [];
    foreach ($per as $name => $count) $out[] = ['name' => (string) $name, 'count' => $count];
    return [$out, $truncated];
}

/**
 * For when ENABLE_VIDEO is off: a bounded count of .mov/.mp4 files
 * sitting anywhere under the gallery root (and any EXTRA_FOLDERS), so an
 * owner who makes a "Videos/" folder and sees nothing is told why instead
 * of left guessing. Same constraints as count_media_in_subfolders():
 * never follows a linked directory, skips dot-directories, and visits at
 * most $maxDirs directories so a drop into a big web root stays cheap.
 * Returns [count found, whether the search was cut short]. A count only,
 * never names — a folder holding nothing but ignored videos isn't one the
 * owner has published, and this banner is visible to every visitor.
 */
function count_ignored_videos($realDir, $maxDirs = 40) {
    $count = 0;
    $visited = 0;
    $truncated = false;
    $queue = [$realDir];
    foreach (gallery_mounts() as $extraPath) {
        if (is_string($extraPath) && is_dir($extraPath) && !is_link($extraPath)) $queue[] = $extraPath;
    }
    while ($queue) {
        if ($visited++ >= $maxDirs) {
            $truncated = true;
            break;
        }
        $current = array_shift($queue);
        foreach ((@scandir($current) ?: []) as $entry) {
            if ($entry[0] === '.') continue;
            $path = $current . '/' . $entry;
            if (is_dir($path)) {
                if (!is_link($path)) $queue[] = $path;
            } elseif (is_video_file($entry) && is_file($path)) {
                $count++;
            }
        }
    }
    return [$count, $truncated];
}

/**
 * Merges EXTRA_FOLDERS into the root node as additional virtual
 * subfolders. These point at real paths outside the gallery root on
 * purpose — the admin wrote them into a constant they control, the same
 * category of trust as ADMIN_PASSWORD — so the symlink/containment
 * checks above (which exist to stop the scan's *own* directory listing
 * from wandering outside the root) don't apply to them. A real folder of
 * the same name already found during the normal scan always wins.
 */
function merge_extra_folders($rootNode, $mediaExtensions, $self) {
    foreach (gallery_mounts() as $virtualName => $realPath) {
        if (!is_string($virtualName) || $virtualName === '' || strpbrk($virtualName, "/\\") !== false) continue;
        if (isset($rootNode['subdirs'][$virtualName])) continue;
        if (!is_dir($realPath) || is_link($realPath)) continue;
        $rootNode['subdirs'][$virtualName] = scan_folder_tree($realPath, $mediaExtensions, $self, false);
    }
    return $rootNode;
}

/** Every file in this tree as relative paths from the tree's own root
 *  (e.g. "Paris/eiffel.jpg"), folders before nothing in particular order
 *  — each node's own files are already sorted; subfolders are visited in
 *  scandir order, which is fine since real cross-folder ordering is a
 *  display-time concern (see folder-group rendering), not this one. */
function flatten_folder_tree($node, $prefix = '') {
    $out = [];
    foreach ($node['files'] as $f) {
        $out[] = $prefix === '' ? $f : $prefix . '/' . $f;
    }
    foreach ($node['subdirs'] as $name => $sub) {
        $subPrefix = $prefix === '' ? $name : $prefix . '/' . $name;
        foreach (flatten_folder_tree($sub, $subPrefix) as $rel) {
            $out[] = $rel;
        }
    }
    return $out;
}

/** Total file count across a node's entire subtree (itself + every descendant). */
function count_folder_tree_files($node) {
    $count = count($node['files']);
    foreach ($node['subdirs'] as $sub) {
        $count += count_folder_tree_files($sub);
    }
    return $count;
}

/**
 * Validates ONE claimed media path directly, without building the whole
 * file list first. ?img= and ?video= fire once per thumbnail — a grid of
 * 300 photos is 300 requests — and "scan the entire tree, then check
 * membership" costs the same on a ten-photo folder as it would, per
 * request, on thousands of photos in deep folders. This answers the same
 * question the scan's own allowlist answers, with the same rules, by
 * resolving only the path in question:
 *   - no empty, ".", ".." or NUL/backslash anywhere; no absolute path
 *   - a recognized media extension (so ENABLE_VIDEO off means no video)
 *   - never the script itself, never inside .gallery-cache
 *   - every folder along the way is a real directory, not a symlink; the
 *     first segment may instead be an EXTRA_FOLDERS virtual mount (an
 *     admin-written constant, trusted the same way — but a real folder
 *     of the same name wins, exactly as in the scan)
 *   - the final name must appear, character for character, in its
 *     folder's own listing — not merely resolve. On a case-insensitive
 *     filesystem "EIFFEL.JPG" would otherwise reach eiffel.jpg while
 *     missing the per-photo hide flag keyed on the exact name.
 *   - the folder's real path stays under its root
 * It never decides anything about *visibility*: callers still apply
 * file_is_hidden() to whatever this accepts.
 */
function valid_media_path($dir, $rel, $mediaExtensions, $self) {
    if (!is_string($rel) || $rel === '' || strlen($rel) > 2048) return false;
    if (strpbrk($rel, "\0\\") !== false) return false;
    $segments = explode('/', $rel);
    foreach ($segments as $seg) {
        if ($seg === '' || $seg === '.' || $seg === '..') return false;
    }
    $file = array_pop($segments);
    foreach ($segments as $seg) {   // (the scan never enters a dot folder or a system folder, so nothing in one is a gallery photo)
        if ($seg[0] === '.' || in_array($seg, SCAN_SKIP_FOLDERS, true)) return false;
    }
    if (!empty($segments) && !AUTO_GROUP_BY_FOLDER) return false;
    if (!in_array(strtolower(pathinfo($file, PATHINFO_EXTENSION)), $mediaExtensions, true)) return false;
    if (empty($segments) && $file === $self) return false;

    $current = $dir;
    $root = realpath($dir);
    foreach ($segments as $i => $seg) {
        if (strcasecmp($seg, '.gallery-cache') === 0) return false;
        $next = $current . '/' . $seg;
        if ($i === 0 && !(is_dir($next) && !is_link($next))) {
            $mount = gallery_mounts()[$seg] ?? null;
            if (!is_string($mount) || strpbrk($seg, "/\\") !== false || !is_dir($mount) || is_link($mount)) return false;
            $next = $mount;
            $root = realpath($mount);
        } elseif ($i > 0 && (!is_dir($next) || is_link($next))) {
            return false;
        } elseif ($i === 0 && !is_dir($next)) {
            return false;
        }
        $current = $next;
    }
    $realCurrent = realpath($current);
    if ($root === false || $realCurrent === false) return false;
    if ($realCurrent !== $root && strpos($realCurrent . '/', $root . '/') !== 0) return false;
    $listing = @scandir($current);
    if ($listing === false || !in_array($file, $listing, true)) return false;
    return is_file($current . '/' . $file) && !is_link($current . '/' . $file);
}

/**
 * Resolves a relative path (e.g. "Paris/eiffel.jpg", or
 * "OldTrip2020/x.jpg" for an EXTRA_FOLDERS virtual mount) to its real
 * filesystem path. Purely a path-construction helper — this never
 * decides whether a path is *valid*; every caller still has to check the
 * requested relative path against the real, pre-built allowlist first.
 */
function resolve_real_path($dir, $relPath) {
    $slash = strpos($relPath, '/');
    $first = $slash === false ? $relPath : substr($relPath, 0, $slash);
    $mounts = gallery_mounts();
    if (isset($mounts[$first]) && is_dir($mounts[$first])) {
        $rest = $slash === false ? '' : substr($relPath, $slash + 1);
        return rtrim($mounts[$first], '/') . ($rest === '' ? '' : '/' . $rest);
    }
    return $dir . '/' . $relPath;
}

/** The real directory containing a given relative file path — where that
 *  file's colocated .gallery-stats.* / .gallery-cache actually live. */
function containing_folder_real_path($dir, $relPath) {
    $slash = strrpos($relPath, '/');
    if ($slash === false) return $dir;
    return resolve_real_path($dir, substr($relPath, 0, $slash));
}

/** Whether the public address is closed right now: the setting is on, and there is a way in (share links on, an admin password set). */
function gallery_is_closed() {
    return CLOSE_PUBLIC_GALLERY && ENABLE_SHARE_LINKS && ADMIN_PASSWORD !== '';
}

/** True when a live link uses this photo as its preview picture: the one thing a stranger may fetch while the gallery is closed,
 *  since a chat app and the opening page ask for it with no cookie. */
function closed_gallery_serves_picture($rel, $dir) {
    if (!is_string($rel) || $rel === '') return false;
    foreach ((array) (links_read()['links'] ?? []) as $l) {
        if (!is_array($l) || link_is_public_log($l) || !link_is_live($l)) continue;
        if (link_preview_picture($l, $dir) === $rel) return true;
    }
    return false;
}

/** The addresses "admin" and "reveal" (with or without a closing slash) go to the one sign-in; other places that name them do too. */
function sign_in_redirect() {
    header('Cache-Control: no-store');
    header('Location: ' . gallery_root_href() . '?reveal', true, 302);
    exit;
}

// A closed gallery: before anything is read or served (a photo, a thumbnail, a folder, the map), a stranger gets the page of a link
// that isn't valid, the same as for any bad address, so nothing says there is a gallery here. Still open to everyone: the sign-in, the
// admin, a share link's own address, and the preview picture of a live link. "/admin/" (a folder address) is the sign-in as well.
if (isset($_GET['folder']) && is_string($_GET['folder']) && in_array(strtolower(trim($_GET['folder'], '/')), ['admin', 'reveal'], true) && !is_dir($dir . '/' . trim($_GET['folder'], '/'))) {
    sign_in_redirect();
}
/**
 * Every address that is answered by a script of its own, not by the gallery page, in the order they are tried: the first one whose
 * parameter is in the address answers, and nothing after it runs (?img=...&admin=1 is the picture's, not the admin's). This one list is
 * what the closed-gallery gate below reads and what every handler asks (request_route() === 'name'), so the gate and the handlers cannot
 * disagree about which of two parameters wins, and a new route is closed to a stranger until it is marked 'open' here. 'open' is for the
 * ways in only (the sign-in, a share link's own address, the admin's sign-in). The gallery page itself and its folder, map and photo
 * views are no route: they are the gallery, closed to a stranger like everything else.
 */
function request_routes() {
    return [
        'original'    => ['params' => ['original']],
        'linklog'     => ['params' => ['linklog']],
        'exitpreview' => ['params' => ['exitpreview']],
        'strip'       => ['params' => ['strip']],
        'preview'     => ['params' => ['preview']],
        'img'         => ['params' => ['img', 'video']],
        'download'    => ['params' => ['download']],
        'about'       => ['params' => ['about']],
        'mapicon'     => ['params' => ['mapicon'], 'when' => ENABLE_PHOTO_LOCATION],
        'appicon'     => ['params' => ['appicon']],
        'manifest'    => ['params' => ['manifest']],
        'reveal'      => ['params' => ['reveal'], 'open' => true],
        'link'        => ['params' => ['link'], 'open' => true],
        'admin'       => ['params' => ['admin'], 'open' => true],
        'track'       => ['params' => ['track']],
        'archive'     => ['params' => ['archive']],
    ];
}

/** The name of the route this request is for (see request_routes), or '' when it is the gallery page. */
function request_route($reset = false) {
    static $route = null;
    if ($reset) $route = null;
    if ($route !== null) return $route;
    $route = '';
    foreach (request_routes() as $name => $r) {
        if (array_key_exists('when', $r) && !$r['when']) continue;
        foreach ($r['params'] as $p) if (isset($_GET[$p])) return $route = $name;
    }
    return $route;
}

/** The words a bare query (?word, nothing else) means for the gallery itself. Any other single word is an address someone typed: a share link's or a
 *  Not listed photo's (see bare_query_as_address). */
function reserved_query_words() {
    $words = ['index.php', 'map', 'archive', 'all', 'csv', 'file', 'folder', 'hidden', 'name', 'photo', 'size', 'sort', 'tab', 'what', 'warm', 'shell', 'item', 'exact', 'prefix', 'inframe', 'csrf', 'k',
        'view', 'accelcheck', 'browserhist', 'filesdownload', 'linkcover', 'linkphotos', 'linkpreview', 'q', 'visits', 'visitsexport', 'linkspanel', 'browserspanel', 'changed', 'changes_list', 'since', 'after', 'pbcounts', 'privcounts', 'scope_type',
        'shellcounts', 'shellmeta', 'shelltree'];
    foreach (request_routes() as $r) foreach ($r['params'] as $p) $words[] = $p;
    return $words;
}

/** A query that is one bare word and nothing else (the address typed as /photos/?Ab3x9Qz2 where the server's one-word rule isn't set up) is the same as
 *  ?link=<word>: the one place that tells a share link's or a Not listed photo's address from a wrong guess, and counts the guess. */
function bare_query_as_address() {
    $qs = (string) ($_SERVER['QUERY_STRING'] ?? '');
    if (preg_match('/^([A-Za-z0-9._~-]{1,60})(?:&.*)?$/Ds', $qs, $m) !== 1 || in_array($m[1], reserved_query_words(), true)) return;   // (the word first, nothing like word=value; other parameters a chat app added are ignored)
    unset($_GET[str_replace(['.', ' '], '_', $m[1])]);
    $_GET['link'] = $m[1];
}
bare_query_as_address();

if (gallery_is_closed()) {
    $route = request_route();
    $routeIsOpen = $route !== '' && !empty(request_routes()[$route]['open']);
    // The one thing a stranger may fetch: the preview picture of a live link (a chat app asks for it with no cookie).
    $pictureOnly = $route === 'img' && ($_GET['size'] ?? '') === 'share' && !isset($_GET['video']);
    if (!$routeIsOpen && !is_revealed() && !is_admin_browser() && link_viewer() === null
        && !($pictureOnly && closed_gallery_serves_picture($_GET['img'], $dir))) {
        render_link_invalid_page();
        exit;
    }
}

// A code (k=...) that opens nothing is a wrong guess whether or not the path it came with exists, counted once per request when it ends: otherwise who
// gets paused would tell a Not listed photo that is there from one that is not.
if (isset($_GET['k']) && is_string($_GET['k']) && in_array(request_route(), ['', 'img', 'original', 'track', 'strip'], true)) {
    register_shutdown_function(function () use ($dir) { if (empty($GLOBALS['__photo_pass_ok']) && !photo_code_is_right_for_request($dir)) link_guess_failed($dir, (string) $_GET['k']); });
}

// ?original=<file> hands a signed-in visitor (the owner, or someone with the private-view password) the original file
// itself, as a download. Everyone else gets 404, as for any other thing that isn't there.
if (request_route() === 'original') {
    $claimed = $_GET['original'];
    $claimedList = valid_media_path($dir, $claimed, $mediaExtensions, $self) ? [$claimed] : [];
    serve_original_download($dir, $claimed, $claimedList, $claimedList ? items_get_all_for_files($dir, $claimedList) : []);
    exit;
}

// ?linklog: what someone using a share link has had on screen, opened and played (a small POST from their page).
if (request_route() === 'linklog') {
    run_linklog_route($dir, $mediaExtensions, $self);
    exit;
}

// ?exitpreview: ends "Preview as this link" in this browser and goes back to the Shares tab.
if (request_route() === 'exitpreview') {
    preview_clear_cookie();
    header('Cache-Control: no-store');
    header('Location: ?admin#links', true, 303);
    exit;
}

// ?strip=<video>: the grid of frames a finger scrubs through on a video's tile.
if (request_route() === 'strip') {
    $claimed = $_GET['strip'];
    $claimedList = valid_media_path($dir, $claimed, $mediaExtensions, $self) ? [$claimed] : [];
    serve_video_strip($dir, $claimed, $claimedList, $claimedList ? items_get_all_for_files($dir, $claimedList) : []);
    exit;
}

// ?preview=<video>: the short hover clip of a video.
if (request_route() === 'preview') {
    $claimed = $_GET['preview'];
    $claimedList = valid_media_path($dir, $claimed, $mediaExtensions, $self) ? [$claimed] : [];
    serve_video_preview($dir, $claimed, $claimedList, $claimedList ? items_get_all_for_files($dir, $claimedList) : []);
    exit;
}

// ?img= and ?video= answer here, before the tree is scanned: one
// direct path validation (see valid_media_path) instead of walking every
// folder for every thumbnail. serve_image()/serve_video() still run
// their own allowlist check and the hide check on whatever is passed in.
if (request_route() === 'img') {
    $claimedIsImg = isset($_GET['img']);
    $claimed = $claimedIsImg ? $_GET['img'] : $_GET['video'];
    $claimedList = valid_media_path($dir, $claimed, $mediaExtensions, $self) ? [$claimed] : [];
    $claimedItems = $claimedList ? items_get_all_for_files($dir, $claimedList) : [];
    if ($claimedIsImg) {
        serve_image($dir, $claimed, $_GET['size'] ?? 'thumb', $claimedList, $claimedItems);
    } else {
        serve_video($dir, $claimed, $claimedList, $claimedItems);
    }
    exit;
}

if (AUTO_GROUP_BY_FOLDER) {
    $folderTree = merge_extra_folders(
        scan_folder_tree($dir, $mediaExtensions, $self),
        $mediaExtensions,
        $self
    );
    $files = flatten_folder_tree($folderTree);
} else {
    $folderTree = null;
    [$subfolderMediaCount, $subfolderMediaTruncated] = count_media_in_subfolders($dir, $mediaExtensions);
    $files = array_filter(scandir($dir), function ($file) use ($dir, $mediaExtensions, $self) {
        if ($file === $self || $file === '.' || $file === '..') return false;
        if (!is_file("$dir/$file") || is_link("$dir/$file")) return false;   // (a link is never followed: it could point anywhere on the server)
        $ext = strtolower(pathinfo($file, PATHINFO_EXTENSION));
        return in_array($ext, $mediaExtensions);
    });

    // Base ordering, before any .md-driven repositioning — see
    // PHOTO_SORT_ORDER above.
    if (PHOTO_SORT_ORDER === 'mtime') {
        $times = [];
        foreach ($files as $f) $times[$f] = @filemtime("$dir/$f") ?: 0;
        usort($files, function ($a, $b) use ($times) {
            return $times[$a] <=> $times[$b];
        });
    } else {
        // Natural sort by filename, so groups like dp104_01, dp104_02,
        // dp104_03 stay together and in order, followed by neo98_01, etc.
        usort($files, function ($a, $b) {
            return strnatcasecmp($a, $b);
        });
    }
    $files = array_values($files);
}

// The photos inside each folder in the order chosen for it (see media_sort_apply).
$files = array_values(media_sort_apply($files, $dir));

// Snapshot of each file's position in this base sort, before any .md-
// driven repositioning happens — used as the "natural order" anchor for
// a group/cluster that has no prose to derive an early position from
// (see GROUPING and compute_zone_order() below).
$naturalRank = [];
foreach ($files as $i => $f) {
    $naturalRank[$f] = $i;
}

// Duration badge (see ENABLE_VIDEO's doc comment) — read once per video
// file here, alongside every other per-file precomputation, rather than
// re-parsed on every render. Missing/unparseable just omits the badge
// for that one file; it never blocks the rest of the page.
$videoDurations = [];
if (ENABLE_VIDEO) {
    foreach ($files as $f) {
        if (is_video_file($f)) {
            $duration = video_duration_seconds(resolve_real_path($dir, $f));
            if ($duration !== null) {
                $videoDurations[$f] = $duration;
            }
        }
    }
}

// Per-file caption/location/web data, set via the admin tool (?admin) —
// see the ".gallery-items.php" section below for the storage shape.
// Read unconditionally (not gated behind ADMIN_PASSWORD): a gallery that
// never touches the admin tool just gets an empty result per folder,
// cheaply, the same way an untouched .gallery-stats.php costs nothing.
$itemsData = items_get_all_for_files($dir, $files);

/**
 * Derive a group key from a filename by stripping a trailing "_01" /
 * "-02" style numeric suffix. Only strips when there's an explicit
 * separator before the digits, so a standalone file like "iphone15.jpg"
 * keeps its full name rather than losing the "15". A no-op entirely
 * when AUTO_GROUP_BY_FILENAME is off — the key is then just the
 * extension-stripped filename, same as always, which is what lets
 * prose mention an item by name (e.g. "the zebra print blanket") and
 * auto-link a standalone "zebra.jpg". This can still coincidentally
 * collide two unrelated files that share a base name but differ only
 * in extension (e.g. "topology.jpg" and "topology.png") — see the
 * disambiguation pass right after $groups is built, further down.
 */
function group_key($filename) {
    $base = pathinfo($filename, PATHINFO_FILENAME);
    if (!AUTO_GROUP_BY_FILENAME) {
        return $base;
    }
    $key = preg_replace('/[_\-]\d+$/', '', $base);
    return $key === '' ? $base : $key;
}

/**
 * Builds a whole-word, case-insensitive match pattern for a group key
 * appearing in free text. Uses explicit alnum/underscore lookarounds
 * instead of \b — \b only checks for a \w/\W transition, so it doesn't
 * treat a key starting or ending in punctuation (e.g. "+model") as a
 * distinct token and can match inside an unrelated word.
 */
function group_mention_pattern($key) {
    return '/(?<![\p{L}\p{N}_])' . preg_quote($key, '/') . '(?![\p{L}\p{N}_])/iu';
}

function slugify($text) {
    $text = strtolower($text);
    $text = preg_replace('/[^a-z0-9]+/', '-', $text);
    return trim($text, '-');
}

// $groups is built later (see "GROUPING" below), after .md files are
// discovered and their {group:}/{photos:} directives are extracted —
// both the ?track endpoint and the gallery renderer need the final,
// merged version, not just the filename-based auto-detection.

// ?photo=<filename-or-relative-path> deep-links straight to that photo in
// the lightbox on page load. Only ever a value that's an exact match
// against $files, the real list this script's own scan already trusts —
// never basename()'d first, since that would strip a legitimate
// subfolder prefix like "Paris/" right back off. The allowlist's exact-
// match is what actually provides the safety here, not basename(); a
// traversal attempt never matches anything the scan itself produced,
// with or without that extra step. See serve_image() below for the same
// reasoning applied to ?img=.
// A Not listed photo's own address arrives as /photos/<8 letters and digits> or /photos/?<8 letters and digits>, which is ?link=<them> to the script: when it
// is one, the request becomes that photo's page (?photo=<path>&k=<code>) here; when it is not, it goes on as a share link's address below.
if (request_route() === 'link') photo_address_translate($dir, $files, $itemsData);
$requestedPhoto = null;
if (isset($_GET['photo'])) {
    $candidate = $_GET['photo'];
    if (in_array($candidate, $files, true) && viewer_may_see_item($dir, $candidate, $itemsData)) {
        $requestedPhoto = $candidate;
    } elseif (request_route() === '') {
        render_link_invalid_page();   // a photo that is not there (or not for this visitor) is not found, like any other wrong address; nothing says which
        exit;
    }
}
// A Not listed photo opened by its own address (?photo=<path>&k=<code>): the page is that one photo and nothing else (see the filter in
// "GROUPING" below), kept out of search engines and not passed on in a Referer.
$photoPass = null;
if ($requestedPhoto !== null && !is_admin_browser() && isset($_GET['k']) && photo_pass_valid($dir, $requestedPhoto, $itemsData)) {
    $photoPass = $requestedPhoto;
    header('Referrer-Policy: no-referrer');
    header('X-Robots-Tag: noindex, nofollow');
    header('Cache-Control: private, no-store');
}

// ?download used to serve this file's own bytes directly. Redirects to
// the GitHub repo instead, so anyone with an old bookmarked or shared
// link still lands somewhere useful rather than a dead end. Removed
// outright, not scrubbed, specifically so this script can never hand out
// a copy of itself — including whatever secrets later constants define —
// to a visitor who asks. A live snapshot was also just a worse copy than
// GitHub's anyway: unversioned, possibly stale or hand-edited.
if (request_route() === 'download') {
    header('Location: https://github.com/pcmike/gallery', true, 302);
    exit;
}

// ?about renders a full documentation page (with the download link for
// this script at the top) instead of the gallery — this is what the
// "gallery" link in the footer points to.
if (request_route() === 'about') {
    render_about_page();
    exit;
}

// ?mapicon — the generic share-preview image for ?map (see
// render_map_icon_image()). Inert unless ENABLE_PHOTO_LOCATION is on, like ?map.
if (request_route() === 'mapicon') {
    render_map_icon_image();
    exit;
}

// ?appicon and ?manifest — what "Add to Home Screen" needs for the gallery to open as an app with no browser bars (the
// page only points at them for the signed-in owner for now; see home_screen_app_tags()). Nothing private in either.
if (request_route() === 'appicon') {
    render_app_icon_image(isset($_GET['size']) && $_GET['size'] === 'large' ? 512 : 180);
    exit;
}
if (request_route() === 'manifest') {
    $name = trim(preg_replace('/[\x00-\x1f]+/', ' ', (string) ($_GET['name'] ?? '')));
    $name = $name === '' ? 'Gallery' : (function_exists('mb_substr') ? mb_substr($name, 0, 40) : substr($name, 0, 40));
    $start = gallery_root_href();
    if ($start === './') {
        $path = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH);
        $start = is_string($path) ? preg_replace('#[^/]*$#', '', $path) : '/';
    }
    header('Content-Type: application/manifest+json; charset=UTF-8');
    header('Cache-Control: no-cache');
    echo json_encode([
        'name' => $name, 'short_name' => $name, 'start_url' => $start, 'scope' => $start, 'display' => 'standalone',
        'background_color' => '#0f0f10', 'theme_color' => '#0f0f10',
        'icons' => [
            ['src' => $start . '?appicon&v=2', 'sizes' => '180x180', 'type' => 'image/png'],
            ['src' => $start . '?appicon&size=large&v=2', 'sizes' => '512x512', 'type' => 'image/png'],
        ],
    ], JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP);
    exit;
}

// ?reveal — the lock in the icon strip (the one sign-in). See run_reveal_route()
// for the full HTTPS/throttle/auth flow; checked early, like ?about/
// ?download, since it's a distinct mode of this one file, not something
// that needs $groups or any of the scan below.
if (request_route() === 'reveal') {
    run_reveal_route($dir);
    exit;
}

// ?link=<token> — a share link (see the "Share links" section). Early, like ?reveal: it needs nothing from the scan below.
if (request_route() === 'link') {
    run_link_route($dir);
    exit;
}

/* -----------------------------------------------------------------------
 * Image serving: resized/cached thumbnails, HEIC conversion.
 * ----------------------------------------------------------------------- */

function guess_mime($ext) {
    $map = [
        'jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png',
        'gif' => 'image/gif', 'webp' => 'image/webp', 'bmp' => 'image/bmp',
        'heic' => 'image/heic', 'heif' => 'image/heif',
        'mp4' => 'video/mp4', 'mov' => 'video/quicktime',
    ];
    return $map[$ext] ?? 'application/octet-stream';
}

/**
 * Serves an original, untransformed file — hands it to nginx's own
 * static serving via X-Accel-Redirect once NGINX_ACCEL_REDIRECT_PREFIX
 * is configured to match a real `internal` location block for this
 * gallery's own path (see the README), instead of reading it with PHP.
 * $relativePath is the file's path relative to the gallery root, used to
 * build the URL path nginx matches against its own location blocks —
 * not a filesystem path, and it has to line up exactly with that config.
 * Falls back to plain readfile() when the prefix is unset, which is also
 * what makes leaving it empty safe to ship as the default: zero nginx
 * config required, works correctly on any host, same as always.
 */
/** True when a file lies where the web server itself would find it at the address the gallery shows it under: inside the
 *  gallery's own folder, at the same relative path. Photos and videos brought in from elsewhere on the server
 *  (EXTRA_FOLDERS, EXTRA_ROOTS) do not, so nginx cannot send them: the gallery sends those itself. */
function file_is_under_web_root($srcPath, $relativePath) {
    $real = @realpath($srcPath);
    $expected = @realpath(rtrim($GLOBALS['dir'], '/') . '/' . $relativePath);
    return $real !== false && $expected !== false && $real === $expected;
}

function serve_original_file($srcPath, $relativePath, $mimeType) {
    header('Content-Type: ' . $mimeType);
    if (NGINX_ACCEL_REDIRECT_PREFIX !== '' && file_is_under_web_root($srcPath, $relativePath)) {
        // Each path segment encoded separately — the slashes themselves
        // are the URL structure nginx's location block matches against,
        // not something to escape away.
        $urlPath = implode('/', array_map('rawurlencode', explode('/', $relativePath)));
        header('X-Accel-Redirect: ' . rtrim(NGINX_ACCEL_REDIRECT_PREFIX, '/') . '/' . $urlPath);
        return;
    }
    readfile($srcPath);
}

/* -----------------------------------------------------------------------
 * A copy of an original without its location. A photo whose location the
 * gallery does not show is downloaded with the coordinates blanked out
 * of the file, never re-encoded: location_scrub_plan() finds where the
 * location sits (EXIF's GPS block, the XMP and IPTC place fields, a
 * video's location atom) and returns same-length replacements, so the
 * picture is byte-for-byte what it was and the file keeps its size.
 * Null means the file couldn't be read safely, and then nothing is sent.
 * ----------------------------------------------------------------------- */

/** $len bytes at $off, or null if they aren't there (or the block is absurdly large for metadata). */
function scrub_read($fh, $off, $len) {
    if ($len < 0 || $off < 0 || $len > 33554432) return null;
    if ($len === 0) return '';
    if (fseek($fh, $off) !== 0) return null;
    $b = fread($fh, $len);
    return is_string($b) && strlen($b) === $len ? $b : null;
}

/** The GPS block of a TIFF (the shape EXIF uses), zeroed: [[fileOffset, bytes], ...], or null if it doesn't parse.
 *  $base is where the TIFF starts in the file. */
function scrub_tiff_gps($tiff, $base) {
    $n = strlen($tiff);
    if ($n < 8) return null;
    $le = substr($tiff, 0, 2) === 'II';
    if (!$le && substr($tiff, 0, 2) !== 'MM') return null;
    $u16 = function ($o) use ($tiff, $n, $le) { return $o >= 0 && $o + 2 <= $n ? unpack($le ? 'v' : 'n', $tiff, $o)[1] : null; };
    $u32 = function ($o) use ($tiff, $n, $le) { return $o >= 0 && $o + 4 <= $n ? unpack($le ? 'V' : 'N', $tiff, $o)[1] : null; };
    if ($u16(2) !== 42) return null;
    $sizes = [1 => 1, 2 => 1, 3 => 2, 4 => 4, 5 => 8, 6 => 1, 7 => 1, 8 => 2, 9 => 4, 10 => 8, 11 => 4, 12 => 8, 13 => 4, 16 => 8, 17 => 4, 18 => 4];
    $patches = [];
    $zero = function ($off, $len) use (&$patches, $base, $n) {
        if ($off < 0 || $len < 0 || $off + $len > $n) return false;
        if ($len > 0) $patches[] = [$base + $off, str_repeat("\0", $len)];
        return true;
    };
    $ifd = $u32(4);
    for ($guard = 0; $ifd !== null && $ifd !== 0 && $guard < 4; $guard++) {
        $count = $u16($ifd);
        if ($count === null || $count > 1000) return null;
        for ($i = 0; $i < $count; $i++) {
            $e = $ifd + 2 + 12 * $i;
            $tag = $u16($e);
            if ($tag === null) return null;
            if ($tag !== 0x8825) continue;
            $gps = $u32($e + 8);
            $g = $gps === null ? null : $u16($gps);
            if ($g === null || $g > 256) return null;
            for ($j = 0; $j < $g; $j++) {
                $ge = $gps + 2 + 12 * $j;
                $type = $u16($ge + 2); $cnt = $u32($ge + 4);
                if ($type === null || $cnt === null) return null;
                $size = ($sizes[$type] ?? 1) * $cnt;
                if ($size > 4) { $at = $u32($ge + 8); if ($at === null || !$zero($at, $size)) return null; }
            }
            if (!$zero($gps, 2 + 12 * $g + 4)) return null;
        }
        $ifd = $u32($ifd + 2 + 12 * $count);
    }
    return $patches;
}

/** XMP text: the values of GPS and place-name properties, replaced by spaces of the same length. */
function scrub_xmp_patches($xml, $base) {
    $patches = [];
    $names = 'exif:GPS[A-Za-z]+|photoshop:(?:City|State|Country)|Iptc4xmpCore:(?:Location|CountryCode)';
    foreach (['/\b(?:' . $names . ')\s*=\s*(["\'])(.*?)\1/s' => 2, '/<(' . $names . ')(?:\s[^>]*)?>(.*?)<\/\1\s*>/s' => 2] as $re => $group) {
        if (!preg_match_all($re, $xml, $m, PREG_OFFSET_CAPTURE)) continue;
        foreach ($m[$group] as [$text, $off]) {
            if ($text !== '') $patches[] = [$base + $off, str_repeat(' ', strlen($text))];
        }
    }
    return $patches;
}

/** IPTC (inside a Photoshop APP13 block): the city, sub-location, state and country fields, blanked. */
function scrub_iptc_patches($d, $base) {
    $patches = [];
    $n = strlen($d);
    $p = 0;
    while ($p + 12 <= $n && substr($d, $p, 4) === '8BIM') {
        $id = unpack('n', $d, $p + 4)[1];
        $nameLen = ord($d[$p + 6]);
        $q = $p + 7 + $nameLen; if (($nameLen + 1) % 2) $q++;
        if ($q + 4 > $n) break;
        $len = unpack('N', $d, $q)[1];
        $dataAt = $q + 4;
        if ($id === 0x0404) {
            $r = $dataAt; $end = min($n, $dataAt + $len);
            while ($r + 5 <= $end && $d[$r] === "\x1C") {
                $rec = ord($d[$r + 1]); $tag = ord($d[$r + 2]); $l = unpack('n', $d, $r + 3)[1];
                if ($l & 0x8000 || $r + 5 + $l > $end) break;
                if ($rec === 2 && in_array($tag, [90, 92, 95, 100, 101], true) && $l > 0) $patches[] = [$base + $r + 5, str_repeat(' ', $l)];
                $r += 5 + $l;
            }
        }
        $p = $dataAt + $len + ($len % 2);
    }
    return $patches;
}

function scrub_plan_jpeg($fh, $size) {
    if (scrub_read($fh, 0, 2) !== "\xFF\xD8") return null;
    $patches = [];
    $pos = 2;
    while (true) {
        if ($pos + 2 > $size) return null;
        $h = scrub_read($fh, $pos, 2);
        if ($h === null || $h[0] !== "\xFF") return null;
        $m = ord($h[1]);
        if ($m === 0xFF) { $pos++; continue; }
        if ($m === 0xD8 || $m === 0x01 || ($m >= 0xD0 && $m <= 0xD7)) { $pos += 2; continue; }
        if ($m === 0xDA || $m === 0xD9) break;   // the picture itself starts: every piece of metadata is before this
        $lenBytes = scrub_read($fh, $pos + 2, 2);
        if ($lenBytes === null) return null;
        $len = unpack('n', $lenBytes)[1];
        if ($len < 2) return null;
        $dataOff = $pos + 4; $dataLen = $len - 2;
        if ($m === 0xE1 || $m === 0xED) {
            $data = scrub_read($fh, $dataOff, $dataLen);
            if ($data === null) return null;
            if ($m === 0xE1 && strncmp($data, "Exif\0\0", 6) === 0) {
                $t = scrub_tiff_gps(substr($data, 6), $dataOff + 6);
                if ($t === null) return null;
                $patches = array_merge($patches, $t);
            } elseif ($m === 0xE1 && strncmp($data, 'http://ns.adobe.com/', 20) === 0) {
                $patches = array_merge($patches, scrub_xmp_patches($data, $dataOff));
            } elseif ($m === 0xED && strncmp($data, "Photoshop 3.0\0", 14) === 0) {
                $patches = array_merge($patches, scrub_iptc_patches(substr($data, 14), $dataOff + 14));
            }
        }
        $pos += 2 + $len;
    }
    return $patches;
}

function scrub_plan_png($fh, $size) {
    if (scrub_read($fh, 0, 8) !== "\x89PNG\r\n\x1a\n") return null;
    $patches = [];
    $pos = 8;
    while ($pos + 12 <= $size) {
        $h = scrub_read($fh, $pos, 8);
        if ($h === null) return null;
        $len = unpack('N', $h)[1]; $type = substr($h, 4, 4);
        if ($pos + 12 + $len > $size) return null;
        if ($type === 'eXIf' || $type === 'iTXt') {
            $data = scrub_read($fh, $pos + 8, $len);
            if ($data === null) return null;
            $local = null;
            if ($type === 'eXIf') $local = scrub_tiff_gps($data, 0);
            elseif (strncmp($data, 'XML:com.adobe.xmp', 17) === 0) $local = scrub_xmp_patches($data, 0);
            else $local = [];
            if ($local === null) return null;
            if ($local) {
                foreach ($local as [$o, $b]) $data = substr_replace($data, $b, $o, strlen($b));
                $patches[] = [$pos + 8, $data];
                $patches[] = [$pos + 8 + $len, pack('N', crc32($type . $data))];   // the chunk's checksum
            }
        }
        if ($type === 'IEND') break;
        $pos += 12 + $len;
    }
    return $patches;
}

function scrub_plan_webp($fh, $size) {
    $h = scrub_read($fh, 0, 12);
    if ($h === null || substr($h, 0, 4) !== 'RIFF' || substr($h, 8, 4) !== 'WEBP') return null;
    $patches = [];
    $pos = 12;
    while ($pos + 8 <= $size) {
        $c = scrub_read($fh, $pos, 8);
        if ($c === null) return null;
        $type = substr($c, 0, 4); $len = unpack('V', $c, 4)[1];
        if ($pos + 8 + $len > $size) return null;
        if ($type === 'EXIF' || $type === 'XMP ') {
            $data = scrub_read($fh, $pos + 8, $len);
            if ($data === null) return null;
            if ($type === 'EXIF') {
                $skip = strncmp($data, "Exif\0\0", 6) === 0 ? 6 : 0;
                $t = scrub_tiff_gps(substr($data, $skip), $pos + 8 + $skip);
                if ($t === null) return null;
                $patches = array_merge($patches, $t);
            } else {
                $patches = array_merge($patches, scrub_xmp_patches($data, $pos + 8));
            }
        }
        $pos += 8 + $len + ($len % 2);
    }
    return $patches;
}

/** The boxes (size, type) laid end to end between $from and $to of an MP4/MOV/HEIC file. */
function scrub_boxes($fh, $from, $to) {
    $out = [];
    $pos = $from;
    while ($pos + 8 <= $to && count($out) < 4096) {
        $h = scrub_read($fh, $pos, 8);
        if ($h === null) return null;
        $len = unpack('N', $h)[1]; $type = substr($h, 4, 4); $head = 8;
        if ($len === 1) {
            $big = scrub_read($fh, $pos + 8, 8);
            if ($big === null) return null;
            $len = unpack('J', $big)[1]; $head = 16;
        } elseif ($len === 0) {
            $len = $to - $pos;
        }
        if ($len < $head || $pos + $len > $to) return null;
        $out[] = ['at' => $pos, 'type' => $type, 'data' => $pos + $head, 'end' => $pos + $len];
        $pos += $len;
    }
    return $out;
}

function scrub_plan_mp4($fh, $size) {
    $patches = [];
    $walk = function ($from, $to, $depth) use (&$walk, &$patches, $fh) {
        $boxes = scrub_boxes($fh, $from, $to);
        if ($boxes === null) return false;
        foreach ($boxes as $b) {
            $type = $b['type'];
            if ($type === "\xA9xyz" || $type === 'loci') {
                if ($b['end'] > $b['data']) $patches[] = [$b['data'], str_repeat("\0", $b['end'] - $b['data'])];
            } elseif (in_array($type, ['moov', 'trak', 'udta'], true) && $depth < 6) {
                if (!$walk($b['data'], $b['end'], $depth + 1)) return false;
            } elseif ($type === 'meta' && $depth < 6) {
                // ISO's meta box has a 4-byte version first; QuickTime's doesn't.
                $probe = scrub_read($fh, $b['data'] + 4, 4);
                $inner = $probe === 'hdlr' ? $b['data'] : $b['data'] + 4;
                $kids = scrub_boxes($fh, $inner, $b['end']);
                if ($kids === null) return false;
                $locationKeys = [];
                foreach ($kids as $k) {
                    if ($k['type'] !== 'keys') continue;
                    $head = scrub_read($fh, $k['data'], 8);
                    if ($head === null) return false;
                    $entries = unpack('N', $head, 4)[1];
                    $at = $k['data'] + 8;
                    for ($i = 1; $i <= $entries && $i < 512; $i++) {
                        $eh = scrub_read($fh, $at, 8);
                        if ($eh === null) return false;
                        $elen = unpack('N', $eh)[1];
                        if ($elen < 8 || $at + $elen > $k['end']) return false;
                        $name = scrub_read($fh, $at + 8, $elen - 8);
                        if ($name !== null && stripos($name, 'location') !== false) $locationKeys[$i] = true;
                        $at += $elen;
                    }
                }
                foreach ($kids as $k) {
                    if ($k['type'] !== 'ilst' || !$locationKeys) continue;
                    $items = scrub_boxes($fh, $k['data'], $k['end']);
                    if ($items === null) return false;
                    foreach ($items as $item) {
                        if (!isset($locationKeys[unpack('N', $item['type'])[1]])) continue;
                        $datas = scrub_boxes($fh, $item['data'], $item['end']);
                        if ($datas === null) return false;
                        foreach ($datas as $d) {
                            if ($d['type'] === 'data' && $d['end'] - $d['data'] > 8) $patches[] = [$d['data'] + 8, str_repeat(' ', $d['end'] - $d['data'] - 8)];
                        }
                    }
                }
            }
        }
        return true;
    };
    return $walk(0, $size, 0) ? $patches : null;
}

function scrub_plan_heif($fh, $size) {
    $top = scrub_boxes($fh, 0, $size);
    if ($top === null) return null;
    $meta = null;
    foreach ($top as $b) if ($b['type'] === 'meta') $meta = $b;
    if ($meta === null) return [];
    $kids = scrub_boxes($fh, $meta['data'] + 4, $meta['end']);
    if ($kids === null) return null;
    $items = [];   // item id => 'exif' | 'xmp'
    foreach ($kids as $k) {
        if ($k['type'] !== 'iinf') continue;
        $ver = scrub_read($fh, $k['data'], 1);
        $skip = $ver === "\0" ? 6 : 8;
        $infes = scrub_boxes($fh, $k['data'] + $skip, $k['end']);
        if ($infes === null) return null;
        foreach ($infes as $inf) {
            if ($inf['type'] !== 'infe') continue;
            $body = scrub_read($fh, $inf['data'], min(256, $inf['end'] - $inf['data']));
            if ($body === null || strlen($body) < 12) continue;
            $v = ord($body[0]);
            if ($v < 2) continue;
            $id = $v === 2 ? unpack('n', $body, 4)[1] : unpack('N', $body, 4)[1];
            $o = $v === 2 ? 8 : 10;
            $itemType = substr($body, $o, 4);
            if ($itemType === 'Exif') $items[$id] = 'exif';
            elseif ($itemType === 'mime' && stripos(substr($body, $o + 4), 'rdf+xml') !== false) $items[$id] = 'xmp';
        }
    }
    if (!$items) return [];
    $patches = [];
    foreach ($kids as $k) {
        if ($k['type'] !== 'iloc') continue;
        $h = scrub_read($fh, $k['data'], 8);
        if ($h === null) return null;
        $ver = ord($h[0]);
        $offSize = ord($h[4]) >> 4; $lenSize = ord($h[4]) & 15; $baseSize = ord($h[5]) >> 4; $idxSize = $ver > 0 ? ord($h[5]) & 15 : 0;
        $count = $ver < 2 ? unpack('n', $h, 6)[1] : unpack('N', scrub_read($fh, $k['data'] + 6, 4))[1];
        $at = $k['data'] + ($ver < 2 ? 8 : 10);
        $num = function ($len) use ($fh, &$at) {
            if ($len === 0) return 0;
            $b = scrub_read($fh, $at, $len); $at += $len;
            if ($b === null) return null;
            $v = 0; for ($i = 0; $i < $len; $i++) $v = ($v << 8) | ord($b[$i]);
            return $v;
        };
        for ($i = 0; $i < $count && $i < 4096; $i++) {
            $id = $num($ver < 2 ? 2 : 4);
            $method = 0;
            if ($ver > 0) { $m = $num(2); if ($m === null) return null; $method = $m & 15; }
            $num(2);
            $base = $num($baseSize); $ext = $num(2);
            if ($id === null || $base === null || $ext === null || $ext > 64) return null;
            $extents = [];
            for ($e = 0; $e < $ext; $e++) {
                if ($idxSize) $num($idxSize);
                $eo = $num($offSize); $el = $num($lenSize);
                if ($eo === null || $el === null) return null;
                $extents[] = [$base + $eo, $el];
            }
            if (!isset($items[$id])) continue;
            if ($method !== 0 || count($extents) !== 1) return null;   // not where it can be safely reached
            [$eo, $el] = $extents[0];
            $data = scrub_read($fh, $eo, $el);
            if ($data === null) return null;
            if ($items[$id] === 'exif') {
                if (strlen($data) < 12) return null;
                $skip = 4 + unpack('N', $data)[1];
                $t = scrub_tiff_gps(substr($data, $skip), $eo + $skip);
                if ($t === null) return null;
                $patches = array_merge($patches, $t);
            } else {
                $patches = array_merge($patches, scrub_xmp_patches($data, $eo));
            }
        }
    }
    return $patches;
}

/** What to overwrite in this file to take its location out: [[fileOffset, bytes], ...] sorted, not overlapping, each
 *  replacing as many bytes as it holds; [] when there is nothing to remove; null when the file can't be read
 *  safely (a damaged or unusual one), in which case it must not be handed out. */
function location_scrub_plan($path) {
    $size = @filesize($path);
    $fh = $size === false ? false : @fopen($path, 'rb');
    if (!$fh) return null;
    try {
        $ext = strtolower(pathinfo($path, PATHINFO_EXTENSION));
        if ($ext === 'jpg' || $ext === 'jpeg') $plan = scrub_plan_jpeg($fh, $size);
        elseif ($ext === 'png') $plan = scrub_plan_png($fh, $size);
        elseif ($ext === 'webp') $plan = scrub_plan_webp($fh, $size);
        elseif ($ext === 'heic' || $ext === 'heif') $plan = scrub_plan_heif($fh, $size);
        elseif ($ext === 'mp4' || $ext === 'mov') $plan = scrub_plan_mp4($fh, $size);
        else $plan = [];   // gif, bmp: nothing in them that says where
    } catch (Throwable $e) {
        $plan = null;
    } finally {
        fclose($fh);
    }
    if ($plan === null) return null;
    usort($plan, function ($a, $b) { return $a[0] <=> $b[0]; });
    $merged = [];
    foreach ($plan as [$o, $b]) {
        $last = count($merged) - 1;
        if ($last >= 0 && $o <= $merged[$last][0] + strlen($merged[$last][1])) {
            $rel = $o - $merged[$last][0];
            $merged[$last][1] = substr($merged[$last][1], 0, $rel) . $b . substr($merged[$last][1], $rel + strlen($b));
        } else {
            $merged[] = [$o, $b];
        }
    }
    return $merged;
}

/** $chunk, which starts at byte $pos of the file, with whatever part of $patches falls inside it laid over it. */
function apply_patches_to_chunk($chunk, $pos, $patches) {
    $end = $pos + strlen($chunk);
    foreach ($patches as [$o, $b]) {
        if ($o >= $end || $o + strlen($b) <= $pos) continue;
        $from = max($o, $pos); $to = min($o + strlen($b), $end);
        $chunk = substr_replace($chunk, substr($b, $from - $o, $to - $from), $from - $pos, $to - $from);
    }
    return $chunk;
}

/** Sends $fh's bytes (from its current start, $size of them) to the visitor with $patches laid over them. */
function stream_with_patches($fh, $size, $patches, $emit) {
    $pos = 0;
    while ($pos < $size) {
        $chunk = fread($fh, min(1048576, $size - $pos));
        if ($chunk === false || $chunk === '') break;
        $emit(apply_patches_to_chunk($chunk, $pos, $patches));
        $pos += strlen($chunk);
    }
}

/** What to overwrite in the original at $srcPath before it is given to this visitor: [] for nothing (the owner, someone with the
 *  private-view password or on a share link set to show every location gets the file exactly as it is; so does anyone, for a photo
 *  whose location the gallery shows, when "Scrub location data" is switched off), a plan for any other visitor (the location is
 *  taken out of the file, whether the gallery shows it on the page or not), or null when that can't be done safely, in which case
 *  the file must not be given out. */
function visitor_scrub_plan($srcPath, $filename, $itemsData) {
    if (viewer_sees_all_locations()) return [];   // (the owner, the private-view password, a share link set to show every location: the file as it is)
    $entry = $itemsData[$filename] ?? [];
    // With the switch off, or in a folder that keeps the location in what visitors get, only a location the gallery hides is taken out.
    if ((!SCRUB_LOCATION_DATA || !empty($entry['_folderKeepLocation'])) && photo_location_visible($entry)) return [];
    return location_scrub_plan($srcPath);
}

/** Sends the original file to this visitor (see visitor_scrub_plan). False, with nothing sent, when it may not be.
 *  $cacheControl is sent with a file that is the same for everyone; a file made differently for different visitors is
 *  kept out of shared caches. */
function send_original_for_visitor($srcPath, $filename, $itemsData, $cacheControl = null) {
    $plan = visitor_scrub_plan($srcPath, $filename, $itemsData);
    if ($plan === null) return false;
    $ext = strtolower(pathinfo($filename, PATHINFO_EXTENSION));
    if ($plan === []) {
        if ($cacheControl !== null) header('Cache-Control: ' . $cacheControl);
        serve_original_file($srcPath, $filename, guess_mime($ext));
        return true;
    }
    $size = @filesize($srcPath);
    $fh = $size === false ? false : @fopen($srcPath, 'rb');
    if (!$fh) return false;
    header('Content-Type: ' . guess_mime($ext));
    header('Content-Length: ' . $size);
    header('Cache-Control: private, max-age=86400');
    header('Vary: Cookie');
    stream_with_patches($fh, $size, $plan, function ($chunk) { echo $chunk; flush(); });
    fclose($fh);
    return true;
}

/* -----------------------------------------------------------------------
 * ?archive: every original in the gallery (or in one folder and below) as
 * one ZIP, for the owner and for visitors with the private-view password.
 * It is written to the visitor's connection as it is built, so nothing is
 * stored on the server however big the gallery is: each file is read once,
 * in small pieces, and sent. Files are stored, not compressed (photos and
 * videos are already compressed, so it would only cost time), each with a
 * "data descriptor" after it carrying its checksum and size, which is what
 * lets the header go out before the file has been read. The total size is
 * known in advance (nothing is compressed), so the download has a real
 * progress bar and an interrupted one is noticed as incomplete. Over 4 GB or
 * 65,535 files it switches to the ZIP64 variant, which every current unzip
 * tool reads. Only a couple of archives are made at the same time.
 * ----------------------------------------------------------------------- */

/** The files an archive of $files would hold: [{rel, path, size, mtime}], skipping anything unreadable. */
function archive_entries($dir, $files) {
    $out = [];
    foreach ($files as $rel) {
        $path = resolve_real_path($dir, $rel);
        $st = is_file($path) && is_readable($path) ? @stat($path) : false;
        if ($st) $out[] = ['rel' => $rel, 'path' => $path, 'size' => (int) $st['size'], 'mtime' => (int) $st['mtime']];
    }
    return $out;
}

/** "1.4 GB" */
function human_bytes($n) {
    if ($n < 1024) return $n . ' bytes';
    foreach (['KB', 'MB', 'GB', 'TB'] as $i => $unit) {
        $n /= 1024;
        if ($n < 1024 || $unit === 'TB') return ($n >= 100 ? number_format($n, 0) : number_format($n, 1)) . ' ' . $unit;
    }
}

/** [dosTime, dosDate] for a ZIP entry. */
function archive_dos_time($ts) {
    $d = getdate(max(315532800, $ts));
    return [($d['hours'] << 11) | ($d['minutes'] << 5) | intdiv($d['seconds'], 2), (($d['year'] - 1980) << 9) | ($d['mon'] << 5) | $d['mday']];
}

/** A path as a ZIP entry name: UTF-8, forward slashes, nothing that could climb out of the folder it is unpacked into. */
function archive_entry_name($name) {
    if (!preg_match('//u', $name)) $name = mb_convert_encoding($name, 'UTF-8', 'ISO-8859-1');
    $name = preg_replace('/[\x00-\x1F\x7F\\\\]/', '_', $name);
    $parts = array_filter(explode('/', $name), function ($p) { return $p !== '' && $p !== '.' && $p !== '..'; });
    return implode('/', $parts);
}

/** The exact size of the ZIP that archive_stream() will send. */
function archive_total_size($sizes, $names, $zip64) {
    $total = 0;
    foreach ($sizes as $i => $size) {
        $n = strlen($names[$i]);
        $total += 30 + $n + ($zip64 ? 20 : 0) + $size + ($zip64 ? 24 : 16) + 46 + $n + ($zip64 ? 28 : 0);
    }
    return $total + 22 + ($zip64 ? 56 + 20 : 0);
}

/** Sends the ZIP of $entries ([{name, path, size, mtime}]) to the visitor. Returns false (having sent nothing) if the
 *  total size is beyond what a ZIP can describe. */
function archive_stream($entries, $zip64) {
    $offset = 0;
    $central = '';
    $emit = function ($bytes) use (&$offset) {
        echo $bytes;
        $offset += strlen($bytes);
    };
    foreach ($entries as $e) {
        if (connection_aborted()) return;
        $name = $e['name']; $size = $e['size'];
        [$time, $date] = archive_dos_time($e['mtime']);
        $at = $offset;
        $emit(pack('VvvvvvVVVvv', 0x04034b50, $zip64 ? 45 : 20, 0x0808, 0, $time, $date, 0, $zip64 ? 0xFFFFFFFF : 0, $zip64 ? 0xFFFFFFFF : 0, strlen($name), $zip64 ? 20 : 0)
            . $name . ($zip64 ? pack('vvPP', 1, 16, 0, 0) : ''));
        if (isset($e['data'])) { $fh = fopen('php://memory', 'r+b'); fwrite($fh, $e['data']); rewind($fh); } else $fh = @fopen($e['path'], 'rb');
        if (!$fh) return;   // the connection ends short of its length, so the download shows as failed, never as a good file
        $ctx = hash_init('crc32b');
        for ($left = $size, $at0 = 0; $left > 0;) {
            $chunk = fread($fh, min(1048576, $left));
            if ($chunk === false || $chunk === '') { fclose($fh); return; }
            if (!empty($e['patches'])) $chunk = apply_patches_to_chunk($chunk, $at0, $e['patches']);   // same length: the size worked out in advance stays right
            $at0 += strlen($chunk);
            hash_update($ctx, $chunk);
            $emit($chunk);
            $left -= strlen($chunk);
            if (connection_aborted()) { fclose($fh); return; }
            flush();
        }
        fclose($fh);
        $crc = hexdec(hash_final($ctx));
        $emit(pack('VV', 0x08074b50, $crc) . ($zip64 ? pack('PP', $size, $size) : pack('VV', $size, $size)));
        $central .= pack('VvvvvvvVVVvvvvvVV', 0x02014b50, 0x0300 | ($zip64 ? 45 : 20), $zip64 ? 45 : 20, 0x0808, 0, $time, $date, $crc,
                $zip64 ? 0xFFFFFFFF : $size, $zip64 ? 0xFFFFFFFF : $size, strlen($name), $zip64 ? 28 : 0, 0, 0, 0, 0x81A40000, $zip64 ? 0xFFFFFFFF : $at)
            . $name . ($zip64 ? pack('vvPPP', 1, 24, $size, $size, $at) : '');
    }
    $n = count($entries);
    $cdAt = $offset;
    $emit($central);
    if ($zip64) {
        $emit(pack('VPvvVVPPPP', 0x06064b50, 44, 45, 45, 0, 0, $n, $n, strlen($central), $cdAt));
        $emit(pack('VVPV', 0x07064b50, 0, $cdAt + strlen($central), 1));
        $emit(pack('VvvvvVVv', 0x06054b50, 0, 0, 0xFFFF, 0xFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0));
    } else {
        $emit(pack('VvvvvVVv', 0x06054b50, 0, 0, $n, $n, strlen($central), $cdAt, 0));
    }
    flush();
}

/** One of a couple of places to make an archive at once, or null if they are all taken. The lock goes when the request ends. */
function archive_take_slot() {
    $base = sys_get_temp_dir() . '/gallery-archive-' . substr(hash('sha256', __DIR__), 0, 10) . '-';
    for ($i = 1; $i <= 2; $i++) {
        $fh = @fopen($base . $i . '.lock', 'c');
        if ($fh && flock($fh, LOCK_EX | LOCK_NB)) return $fh;
        if ($fh) fclose($fh);
    }
    return null;
}

/** The files of $files this visitor may have in a ZIP: everything for the owner and the private-view password; for someone using a
 *  share link, what their link's ZIP answer covers, public or private; nothing for anyone else. */
function archive_files_for_viewer($dir, $files) {
    if (is_admin_browser()) return $files;
    if (is_revealed()) return array_values(array_filter($files, function ($f) use ($dir) { return !file_is_unlisted($dir, $f); }));   // (a Not listed folder is in nobody's ZIP but the owner's)
    $l = link_viewer();
    if ($l === null || ($l['zip']['mode'] ?? 'off') === 'off') return [];
    global $itemsData;
    return array_values(array_filter($files, function ($f) use ($dir, $l, $itemsData) {
        return (!file_is_hidden($dir, $f, $itemsData) || link_allows_item($l, $dir, $f, $itemsData)) && link_capability_allows($l, 'zip', $dir, $f, $itemsData);
    }));
}

/** ?archive[&folder=...]: the originals of this gallery or folder as one ZIP. $files is every file the visitor may see;
 *  $folder is the folder asked for (null for the whole gallery). The owner and the private-view password get files exactly as
 *  they are; someone using a share link gets what the link allows, with any location the gallery hides taken out. */
function run_archive_route($dir, $files, $folder, $rootTitle, $folderName) {
    send_sensitive_page_headers();
    $files = archive_files_for_viewer($dir, $files);
    $entries = $files ? archive_entries($dir, $files) : [];
    if ($entries && !viewer_sees_all_locations()) {
        global $itemsData;
        foreach ($entries as $i => $e) {
            $plan = visitor_scrub_plan($e['path'], $e['rel'], $itemsData);
            if ($plan === null) unset($entries[$i]); else $entries[$i]['patches'] = $plan;   // a file whose location can't be taken out safely is left out
        }
        $entries = array_values($entries);
    }
    if (!$entries) {
        http_response_code(404);
        return;
    }
    if (count($entries) > 100000) {
        http_response_code(413);
        header('Content-Type: text/plain; charset=UTF-8');
        echo 'That is more files than one archive can hold. Download a folder at a time.';
        return;
    }
    $root = archive_entry_name($folder === null ? $rootTitle : $folderName);
    if ($root === '') $root = 'gallery';
    $prefix = $folder === null ? '' : $folder . '/';
    foreach ($entries as $i => $e) {
        $entries[$i]['name'] = $root . '/' . archive_entry_name($prefix !== '' && strncmp($e['rel'], $prefix, strlen($prefix)) === 0 ? substr($e['rel'], strlen($prefix)) : $e['rel']);
    }
    $sizes = array_column($entries, 'size'); $names = array_column($entries, 'name');
    $zip64 = count($entries) >= 0xFFFF || max($sizes) >= 0xFFFFFFFF || archive_total_size($sizes, $names, false) >= 0xFFFFFFF0;
    $total = archive_total_size($sizes, $names, $zip64);
    $slot = archive_take_slot();
    if ($slot === null) {
        http_response_code(503);
        header('Retry-After: 30');
        header('Content-Type: text/plain; charset=UTF-8');
        echo 'An archive is already being made for someone else. Try again in a minute.';
        return;
    }
    $ascii = preg_replace('/[^A-Za-z0-9._-]+/', '_', $root); $ascii = trim($ascii, '_') !== '' ? $ascii : 'gallery';
    @set_time_limit(0);
    ignore_user_abort(false);
    @ini_set('zlib.output_compression', '0');
    if (function_exists('apache_setenv')) @apache_setenv('no-gzip', '1');
    while (ob_get_level() > 0) @ob_end_clean();
    header('Content-Type: application/zip');
    shell_frame_headers();   // (a download may sit in this site's own admin frame, as it does on a desktop; no other site may frame it)
    header('Content-Disposition: attachment; filename="' . $ascii . '.zip"; filename*=UTF-8\'\'' . rawurlencode($root . '.zip'));
    header('Content-Length: ' . $total);
    header('X-Content-Type-Options: nosniff');
    header('X-Accel-Buffering: no');
    header('Cache-Control: no-store');
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'HEAD') return;
    if (($linkNote = link_viewer()) !== null && !is_revealed()) {   // noted in the link's log: one line for the ZIP, each file as saved
        $pairs = [['z', ($folder ?? '') . "\0" . count($entries)]];
        foreach ($entries as $e) $pairs[] = ['d', $e['rel']];
        link_queue_deliveries($linkNote, $pairs);
    }
    archive_stream($entries, $zip64);
}

/** ?original=: the original file as a download. Offered to anyone signed in, and to everyone when ENABLE_PUBLIC_DOWNLOAD is
 *  on; a visitor who isn't signed in gets a photo whose location the gallery hides with the location blanked out. */
function serve_original_download($dir, $filename, $validFiles, $itemsData = []) {
    send_sensitive_page_headers();
    if (!is_string($filename) || !in_array($filename, $validFiles, true) || !viewer_may_see_item($dir, $filename, $itemsData)
        || !viewer_may_download($dir, $filename, $itemsData)) {
        http_response_code(404);
        return;
    }
    $srcPath = resolve_real_path($dir, $filename);
    $size = @filesize($srcPath);
    if (!is_file($srcPath) || $size === false) {
        http_response_code(404);
        return;
    }
    $name = basename($filename);
    $ascii = preg_replace('/[^A-Za-z0-9._ -]/', '_', $name);
    // Checked before anything is sent: a file whose location can't be removed safely is not handed out.
    if (visitor_scrub_plan($srcPath, $filename, $itemsData) === null) {
        http_response_code(422);
        header('Content-Type: text/plain; charset=UTF-8');
        echo "This file's location can't be removed safely, so it isn't offered as a download.";
        return;
    }
    shell_frame_headers();   // (a download may sit in this site's own admin frame, as it does on a desktop; no other site may frame it)
    header('Content-Disposition: attachment; filename="' . $ascii . '"; filename*=UTF-8\'\'' . rawurlencode($name));
    header('X-Content-Type-Options: nosniff');
    if (($linkNote = link_viewer()) !== null && !is_revealed()) link_queue_delivery($linkNote, 'd', $filename);   // saved: noted in the link's log
    if (!send_original_for_visitor($srcPath, $filename, $itemsData)) http_response_code(404);
}

/* -----------------------------------------------------------------------
 * A picture for a video. ffmpeg, when this server has it, takes one frame
 * (about a third of a second in, or the first frame of a very short clip),
 * once per video; that frame is kept in the thumbnail cache and everything
 * else (the grid thumbnail, the folder cover, the share preview) is cut from
 * it exactly as for a photo. ffmpeg is started with a fixed list of
 * arguments (never through a shell), with a time limit, one at a time, and
 * what it writes carries no metadata. A video it can't read, or no ffmpeg,
 * gives the generic placeholder as before.
 * ----------------------------------------------------------------------- */

/** Where ffmpeg is on this server, or '' if it can't be used: the setting is off, the functions to start a program are
 *  not available, or no ffmpeg answers. Looked up once a day and remembered outside the web folder. */
function ffmpeg_binary() {
    static $found = null;
    if ($found !== null) return $found;
    $found = '';
    if (!function_exists('proc_open')) return $found;
    $remember = sys_get_temp_dir() . '/gallery-ffmpeg-' . substr(hash('sha256', __DIR__ . '|' . FFMPEG_PATH), 0, 10) . '.txt';
    if (is_file($remember) && time() - (int) @filemtime($remember) < 86400) {
        return $found = trim((string) @file_get_contents($remember));
    }
    $candidates = FFMPEG_PATH !== '' ? [FFMPEG_PATH] : ['ffmpeg', '/usr/bin/ffmpeg', '/usr/local/bin/ffmpeg', '/opt/homebrew/bin/ffmpeg', '/snap/bin/ffmpeg'];
    foreach ($candidates as $c) {
        if ($c !== 'ffmpeg' && !is_executable($c)) continue;
        if (run_quietly([$c, '-version'], 5) === 0) { $found = $c; break; }
    }
    @file_put_contents($remember, $found, LOCK_EX);
    return $found;
}

/** Runs a program (the arguments as a list, no shell), with a time limit; its exit code, or null if it couldn't be run
 *  or was stopped for taking too long. Whatever it prints is thrown away. */
function run_quietly($args, $seconds) {
    $proc = @proc_open($args, [0 => ['file', '/dev/null', 'r'], 1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']], $pipes);
    if (!is_resource($proc)) return null;
    $deadline = microtime(true) + $seconds;
    while (true) {
        $st = proc_get_status($proc);
        if (!$st['running']) { $code = $st['exitcode']; proc_close($proc); return $code; }
        if (microtime(true) > $deadline) { proc_terminate($proc, 9); proc_close($proc); return null; }
        usleep(20000);
    }
}

/** Takes the one ffmpeg place (only one runs at a time), waiting up to $seconds for whoever has it to finish, so a request
 *  that arrives during another's work is served in its turn rather than refused. Null if it never came free. */
function ffmpeg_take_turn($seconds) {
    $lock = @fopen(sys_get_temp_dir() . '/gallery-ffmpeg-' . substr(hash('sha256', __DIR__), 0, 10) . '.lock', 'c');
    if (!$lock) return null;
    $deadline = microtime(true) + $seconds;
    while (!flock($lock, LOCK_EX | LOCK_NB)) {
        if (microtime(true) > $deadline) { fclose($lock); return null; }
        usleep(100000);
    }
    return $lock;
}

/** The path of the frame taken from this video (a JPEG up to 1600 pixels), making it first if need be; null if it can't
 *  be had now (no ffmpeg, a video it can't read, someone else's frame is being taken, a cache that can't be written). */
function video_poster_path($srcPath, $cacheDir, $filename) {
    if (!ENABLE_VIDEO_THUMBNAILS || !ENABLE_THUMBNAIL_CACHE) return null;
    $poster = image_cache_path($cacheDir, $filename, 'poster', $srcPath);
    if ($poster === null) return null;
    if (is_file($poster) && filesize($poster) > 0) return $poster;
    $failed = $poster . '.failed';
    if (is_file($failed) && time() - (int) @filemtime($failed) < 21600) return null;   // it didn't work lately; not again for a few hours
    $bin = ffmpeg_binary();
    if ($bin === '') return null;
    $lock = ffmpeg_take_turn(20);   // one at a time, in turn
    if (!$lock) return null;
    if (is_file($poster) && filesize($poster) > 0) { flock($lock, LOCK_UN); fclose($lock); return $poster; }   // made by whoever had the turn before
    try {
        $duration = video_duration_seconds($srcPath);
        $tmp = $poster . '.tmp' . bin2hex(random_bytes(3));
        foreach ([$duration !== null ? max(0, min(1.0, $duration / 3)) : 0, 0] as $at) {
            $code = run_quietly([$bin, '-v', 'error', '-nostdin', '-y', '-ss', sprintf('%.2f', $at), '-i', $srcPath, '-map_metadata', '-1', '-frames:v', '1',
                '-vf', "scale='min(1600,iw)':'min(1600,ih)':force_original_aspect_ratio=decrease", '-q:v', '3', '-f', 'image2', $tmp], 25);
            if ($code === 0 && is_file($tmp) && filesize($tmp) > 0) { @chmod($tmp, 0644); if (@rename($tmp, $poster)) return $poster; }
            @unlink($tmp);
        }
        @touch($failed);
        return null;
    } finally {
        flock($lock, LOCK_UN); fclose($lock);
    }
}

/** True when a picture couldn't be taken from this video lately (ffmpeg is there but couldn't read it). */
function video_poster_failed($file) {
    $srcPath = resolve_real_path($GLOBALS['dir'], $file);
    $poster = image_cache_path(containing_folder_real_path($GLOBALS['dir'], $file) . '/.gallery-cache', $file, 'poster', $srcPath);
    return $poster !== null && !is_file($poster) && is_file($poster . '.failed');
}

/** The short clip for a video (a small silent H.264 .mp4), making it first if need be; null if it can't be had now. Same
 *  care as video_poster_path(): fixed arguments, no shell, a time limit, one ffmpeg at a time, and not retried for hours
 *  after a failure. */
function video_preview_path($srcPath, $cacheDir, $filename) {
    if (!ENABLE_VIDEO_PREVIEWS || !ENABLE_THUMBNAIL_CACHE) return null;
    $base = image_cache_path($cacheDir, $filename, 'preview2', $srcPath);
    if ($base === null) return null;
    $clip = substr($base, 0, -4) . '.mp4';
    if (is_file($clip) && filesize($clip) > 0) return $clip;
    $failed = $clip . '.failed';
    if (is_file($failed) && time() - (int) @filemtime($failed) < 21600) return null;
    $bin = ffmpeg_binary();
    if ($bin === '') return null;
 
    $lock = ffmpeg_take_turn(15);
    if (!$lock) return null;
    if (is_file($clip) && filesize($clip) > 0) { flock($lock, LOCK_UN); fclose($lock); return $clip; }
    try {
        $duration = video_duration_seconds($srcPath);
        $start = $duration !== null && $duration > 3.5 ? min($duration / 3, $duration - 3) : 0;
        $tmp = $clip . '.tmp' . bin2hex(random_bytes(3));
        $code = run_quietly([$bin, '-v', 'error', '-nostdin', '-y', '-ss', sprintf('%.2f', $start), '-t', '3', '-i', $srcPath, '-an', '-map_metadata', '-1',
            '-vf', 'scale=w=min(640\\,iw):h=-2,fps=15', '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '27', '-pix_fmt', 'yuv420p', '-movflags', '+faststart', '-f', 'mp4', $tmp], 45);
        if ($code === 0 && is_file($tmp) && filesize($tmp) > 0) { @chmod($tmp, 0644); if (@rename($tmp, $clip)) return $clip; }
        @unlink($tmp);
        @touch($failed);
        return null;
    } finally {
        flock($lock, LOCK_UN); fclose($lock);
    }
}

/** Where this video's clip is (or would be) kept, or null if the cache can't be used. */
function video_preview_file($file) {
    $base = image_cache_path(containing_folder_real_path($GLOBALS['dir'], $file) . '/.gallery-cache', $file, 'preview2', resolve_real_path($GLOBALS['dir'], $file));
    return $base === null ? null : substr($base, 0, -4) . '.mp4';
}

/** The grid of frames a video's scrub sprite holds: ten columns and one row for every five seconds (1 to 6 rows), so a frame
 *  about every half second for a video of half a minute or more, spread over its whole length. [columns, rows]. */
function video_strip_layout($duration) {
    return [10, (int) max(1, min(6, ceil($duration / 5)))];
}

/** The sprite of frames for a video (one JPEG, small square frames in a grid, spread over the whole video), which a finger
 *  dragged across a video's tile scrubs through. Made once with ffmpeg, like the clip; null if it can't be had. */
function video_strip_path($srcPath, $cacheDir, $filename) {
    if (!ENABLE_VIDEO_PREVIEWS || !ENABLE_THUMBNAIL_CACHE) return null;
    $strip = image_cache_path($cacheDir, $filename, 'strip2', $srcPath);
    if ($strip === null) return null;
    if (is_file($strip) && filesize($strip) > 0) return $strip;
    $failed = $strip . '.failed';
    if (is_file($failed) && time() - (int) @filemtime($failed) < 21600) return null;
    $duration = video_duration_seconds($srcPath);
    if ($duration === null || $duration < 1) return null;
    $bin = ffmpeg_binary();
    if ($bin === '') return null;
    $lock = ffmpeg_take_turn(30);
    if (!$lock) return null;
    if (is_file($strip) && filesize($strip) > 0) { flock($lock, LOCK_UN); fclose($lock); return $strip; }
    try {
        $tmp = $strip . '.tmp' . bin2hex(random_bytes(3));
        [$cols, $rows] = video_strip_layout($duration);
        $args = [$bin, '-v', 'error', '-nostdin', '-y'];
        if ($duration > 20) array_push($args, '-skip_frame', 'nokey');   // a long video: only its key frames are read, which is much quicker
        array_push($args, '-i', $srcPath, '-an', '-map_metadata', '-1', '-vf',
            sprintf('fps=%.5F,crop=min(iw\\,ih):min(iw\\,ih),scale=320:320,tile=%dx%d', $cols * $rows / $duration * 1.05, $cols, $rows),
            '-frames:v', '1', '-q:v', '4', '-f', 'image2', $tmp);
        $code = run_quietly($args, 90);
        if ($code === 0 && is_file($tmp) && filesize($tmp) > 0) { @chmod($tmp, 0644); if (@rename($tmp, $strip)) return $strip; }
        @unlink($tmp);
        @touch($failed);
        return null;
    } finally {
        flock($lock, LOCK_UN); fclose($lock);
    }
}

/** ?strip=<video>: that sprite, for anyone who may see the video (same gates as the video itself); &warm only makes it. */
function serve_video_strip($dir, $filename, $validFiles, $itemsData = []) {
    if (!is_string($filename) || !in_array($filename, $validFiles, true) || !is_video_file($filename)
        || !viewer_may_see_item($dir, $filename, $itemsData)) {
        http_response_code(404);
        return;
    }
    $strip = video_strip_path(resolve_real_path($dir, $filename), containing_folder_real_path($dir, $filename) . '/.gallery-cache', $filename);
    if (isset($_GET['warm'])) {
        http_response_code($strip === null ? 404 : 204);
        header('Cache-Control: no-store');
        return;
    }
    if ($strip === null) {
        http_response_code(404);
        return;
    }
    header('Content-Type: image/jpeg');
    header('Cache-Control: ' . file_cache_control($dir, $filename, $itemsData));
    header('X-Content-Type-Options: nosniff');
    header('Content-Length: ' . filesize($strip));
    readfile($strip);
}

/** True when a hover over a video tile can play a made clip. */
function video_previews_expected() {
    return ENABLE_VIDEO_PREVIEWS && ENABLE_THUMBNAIL_CACHE && ffmpeg_binary() !== '';
}

/** ?preview=<video>: the short clip, for anyone who may see the video (the same gates as the video itself), with Range
 *  support (Safari plays nothing without it). Nothing is sent that wasn't made by ffmpeg from the video: no metadata. */
function serve_video_preview($dir, $filename, $validFiles, $itemsData = []) {
    if (!is_string($filename) || !in_array($filename, $validFiles, true) || !is_video_file($filename)
        || !viewer_may_see_item($dir, $filename, $itemsData)) {
        http_response_code(404);
        return;
    }
    $srcPath = resolve_real_path($dir, $filename);
    $clip = video_preview_path($srcPath, containing_folder_real_path($dir, $filename) . '/.gallery-cache', $filename);
    if (isset($_GET['warm'])) {
        // Only make it (the page asks quietly for the clips of the tiles in view, one at a time): no body to download.
        http_response_code($clip === null ? 404 : 204);
        header('Cache-Control: no-store');
        return;
    }
    $size = $clip === null ? false : @filesize($clip);
    if ($size === false || $size < 1) {
        http_response_code(404);
        return;
    }
    $start = 0; $end = $size - 1;
    if (preg_match('/^bytes=(\d*)-(\d*)$/', trim($_SERVER['HTTP_RANGE'] ?? ''), $m) && ($m[1] !== '' || $m[2] !== '')) {
        if ($m[1] === '') { $start = max(0, $size - (int) $m[2]); }
        else { $start = (int) $m[1]; $end = $m[2] === '' ? $size - 1 : min((int) $m[2], $size - 1); }
        if ($start >= $size || $start > $end) { http_response_code(416); header('Content-Range: bytes */' . $size); return; }
        http_response_code(206);
        header('Content-Range: bytes ' . $start . '-' . $end . '/' . $size);
    }
    header('Content-Type: video/mp4');
    header('Accept-Ranges: bytes');
    header('Cache-Control: ' . file_cache_control($dir, $filename, $itemsData));
    header('X-Content-Type-Options: nosniff');
    header('Content-Length: ' . ($end - $start + 1));
    $fh = @fopen($clip, 'rb');
    if (!$fh) return;
    fseek($fh, $start);
    for ($left = $end - $start + 1; $left > 0 && !feof($fh);) {
        $chunk = fread($fh, min(65536, $left));
        if ($chunk === false || $chunk === '') break;
        echo $chunk;
        $left -= strlen($chunk);
    }
    fclose($fh);
}

/** True when this server can make a real picture of a video, so the page can leave the browser's own first frame out. */
function video_pictures_expected() {
    return ENABLE_VIDEO_THUMBNAILS && ENABLE_THUMBNAIL_CACHE && ffmpeg_binary() !== '';
}

/**
 * Renders a generic "this is a video" placeholder graphic — a dark tile
 * with a plain play triangle — wherever a video's "thumbnail" or share-
 * preview image is requested. No frame extraction: that would mean
 * adding a video-processing dependency (ffmpeg or similar) this project
 * has never carried and isn't worth adding just for this. Same role for
 * every video regardless of filename, so nothing to cache — generating
 * one is cheap enough to just do on every request.
 */
function render_video_placeholder_image($maxDim) {
    $w = max(1, (int) $maxDim);
    $h = max(1, (int) round($w * 0.75));
    $img = imagecreatetruecolor($w, $h);
    imagefilledrectangle($img, 0, 0, $w, $h, imagecolorallocate($img, 28, 28, 30));
    $triangleColor = imagecolorallocate($img, 200, 200, 205);
    $size = min($w, $h) * 0.22;
    $cx = $w / 2;
    $cy = $h / 2;
    $points = [
        $cx - $size * 0.55, $cy - $size,
        $cx - $size * 0.55, $cy + $size,
        $cx + $size * 0.85, $cy,
    ];
    imagefilledpolygon($img, $points, $triangleColor);
    header('Content-Type: image/jpeg');
    header('Cache-Control: public, max-age=31536000, immutable');
    imagejpeg($img, null, 82);
    unset($img);
}

/**
 * The ?map page's share-preview image: a dark tile with a plain map
 * pin. Not a rendered snapshot of the actual map — that needs a
 * third-party static-maps API, the same dependency objection that ruled
 * out geocoding — so, same honesty standard as the video placeholder, a
 * generic icon that says "this link is a map" and nothing more. 1200x630
 * is the usual large-link-preview size. Identical for every gallery, so
 * nothing to cache or key; cheap enough to draw per request.
 */
function render_map_icon_image() {
    $w = 1200;
    $h = 630;
    $img = imagecreatetruecolor($w, $h);
    $bg = imagecolorallocate($img, 28, 28, 30);
    imagefilledrectangle($img, 0, 0, $w, $h, $bg);
    $pin = imagecolorallocate($img, 224, 138, 60);
    $r = (int) round($h * 0.19);
    $cx = (int) ($w / 2);
    $cy = (int) round($h * 0.42);
    imagefilledellipse($img, $cx, $cy, $r * 2, $r * 2, $pin);
    // Tangent-ish taper from the circle's lower flanks down to the point.
    $tipY = (int) round($h * 0.82);
    $dx = (int) round($r * 0.86);
    $dy = (int) round($r * 0.5);
    $points = [$cx - $dx, $cy + $dy, $cx + $dx, $cy + $dy, $cx, $tipY];
    imagefilledpolygon($img, $points, $pin);
    imagefilledellipse($img, $cx, $cy, (int) round($r * 0.8), (int) round($r * 0.8), $bg);
    header('Content-Type: image/jpeg');
    header('Cache-Control: public, max-age=31536000, immutable');
    imagejpeg($img, null, 85);
    unset($img);
}

/** The home-screen icon: a dark square with a small mountain-and-sun picture, as a PNG of $px pixels. */
function render_app_icon_image($px) {
    // The same line drawing as the gallery icon in the icon strip (a rounded frame, a sun, a hill line; ui_icon_paths()'s 'gallery'),
    // drawn here in PHP so no image file is needed. Drawn four times larger and shrunk, which smooths the edges.
    $k = 4; $big = $px * $k;
    $img = imagecreatetruecolor($big, $big);
    $bg = imagecolorallocate($img, 15, 15, 16);
    $ink = imagecolorallocate($img, 234, 234, 234);
    imagefilledrectangle($img, 0, 0, $big, $big, $bg);
    $u = $big * 0.58 / 18;                       // one unit of the 24-unit drawing; the frame (18 wide) fills 58% of the icon
    $X = function ($x) use ($big, $u) { return $big / 2 + ($x - 12) * $u; };
    $Y = function ($y) use ($big, $u) { return $big / 2 + ($y - 12) * $u; };
    $w = 1.8 * $u;                               // the icon's stroke width
    $rrect = function ($x1, $y1, $x2, $y2, $r, $col) use ($img) {
        imagefilledrectangle($img, (int) round($x1 + $r), (int) round($y1), (int) round($x2 - $r), (int) round($y2), $col);
        imagefilledrectangle($img, (int) round($x1), (int) round($y1 + $r), (int) round($x2), (int) round($y2 - $r), $col);
        foreach ([[$x1 + $r, $y1 + $r], [$x2 - $r, $y1 + $r], [$x1 + $r, $y2 - $r], [$x2 - $r, $y2 - $r]] as [$cx, $cy]) {
            imagefilledellipse($img, (int) round($cx), (int) round($cy), (int) round($r * 2), (int) round($r * 2), $col);
        }
    };
    // the frame: x 3..21, y 4..20, corner radius 2, a stroke centred on that outline
    $rrect($X(3) - $w / 2, $Y(4) - $w / 2, $X(21) + $w / 2, $Y(20) + $w / 2, 2 * $u + $w / 2, $ink);
    $rrect($X(3) + $w / 2, $Y(4) + $w / 2, $X(21) - $w / 2, $Y(20) - $w / 2, max(1, 2 * $u - $w / 2), $bg);
    // the sun: a circle of radius 1.7 at (9,10)
    imagefilledellipse($img, (int) round($X(9)), (int) round($Y(10)), (int) round(($u * 1.7 + $w / 2) * 2), (int) round(($u * 1.7 + $w / 2) * 2), $ink);
    imagefilledellipse($img, (int) round($X(9)), (int) round($Y(10)), (int) round(($u * 1.7 - $w / 2) * 2), (int) round(($u * 1.7 - $w / 2) * 2), $bg);
    // the hill line: (7,20) up to (16,11) down to (21,16), round ends and corner
    foreach ([[[7, 20], [16, 11]], [[16, 11], [21, 16]]] as [[$ax, $ay], [$bx, $by]]) {   // each segment as a filled strip of the stroke's width
        $dx = $X($bx) - $X($ax); $dy = $Y($by) - $Y($ay); $len = sqrt($dx * $dx + $dy * $dy);
        $nx = -$dy / $len * $w / 2; $ny = $dx / $len * $w / 2;
        imagefilledpolygon($img, [(int) round($X($ax) + $nx), (int) round($Y($ay) + $ny), (int) round($X($bx) + $nx), (int) round($Y($by) + $ny), (int) round($X($bx) - $nx), (int) round($Y($by) - $ny), (int) round($X($ax) - $nx), (int) round($Y($ay) - $ny)], $ink);
    }
    foreach ([[7, 20], [16, 11], [21, 16]] as [$x, $y]) imagefilledellipse($img, (int) round($X($x)), (int) round($Y($y)), (int) round($w), (int) round($w), $ink);
    $out = imagecreatetruecolor($px, $px);
    imagecopyresampled($out, $img, 0, 0, 0, 0, $px, $px, $big, $big);
    unset($img);
    header('Content-Type: image/png');
    header('Cache-Control: public, max-age=31536000, immutable');   // the address carries a version (v=), so a new drawing is a new address
    imagepng($out);
    unset($out);
}

/**
 * Reads a clip's duration (in seconds) straight out of its MP4/MOV
 * container's mvhd box — no transcoding, no external dependency, just
 * walking a handful of well-documented box headers. iPhone video
 * commonly places the moov atom at the *end* of the file (mdat written
 * first, moov finalized after recording stops), so this walks top-level
 * boxes by their declared size rather than assuming moov is near the
 * start — each step is a seek + an 8-or-16-byte read, so a large
 * preceding mdat costs nothing extra to skip over. Returns null on
 * anything that doesn't parse as a well-formed enough container — a
 * missing duration badge is a fine degradation, not worth failing the
 * whole page over.
 */
function video_duration_seconds($path) {
    $fh = @fopen($path, 'rb');
    if ($fh === false) return null;
    $fileSize = @filesize($path);
    if ($fileSize === false || $fileSize < 8) {
        fclose($fh);
        return null;
    }

    $maxBoxes = 10000; // sanity guard against a corrupt/adversarial file forcing an infinite loop
    $findBox = function ($startOffset, $rangeEnd, $wantType) use ($fh, &$maxBoxes) {
        $pos = $startOffset;
        $count = 0;
        while ($pos < $rangeEnd && $count++ < $maxBoxes) {
            if (fseek($fh, $pos) !== 0) return null;
            $header = fread($fh, 8);
            if ($header === false || strlen($header) < 8) return null;
            $size = unpack('N', substr($header, 0, 4))[1];
            $type = substr($header, 4, 4);
            $headerLen = 8;
            if ($size === 1) {
                $ext = fread($fh, 8);
                if ($ext === false || strlen($ext) < 8) return null;
                $size = unpack('J', $ext)[1];
                $headerLen = 16;
            }
            if ($size !== 0 && $size < $headerLen) return null; // corrupt
            if ($type === $wantType) {
                return ['offset' => $pos + $headerLen, 'size' => $size === 0 ? ($rangeEnd - $pos - $headerLen) : $size - $headerLen];
            }
            if ($size === 0) return null; // box extends to EOF and it's not the one we want
            $pos += $size;
        }
        return null;
    };

    $moov = $findBox(0, $fileSize, 'moov');
    if ($moov === null) {
        fclose($fh);
        return null;
    }
    $mvhd = $findBox($moov['offset'], $moov['offset'] + $moov['size'], 'mvhd');
    if ($mvhd === null) {
        fclose($fh);
        return null;
    }

    fseek($fh, $mvhd['offset']);
    $body = fread($fh, min($mvhd['size'], 32));
    fclose($fh);
    if ($body === false || strlen($body) < 1) return null;

    $version = ord($body[0]);
    if ($version === 1) {
        if (strlen($body) < 32) return null;
        $timescale = unpack('N', substr($body, 20, 4))[1];
        $duration = unpack('J', substr($body, 24, 8))[1];
    } else {
        if (strlen($body) < 20) return null;
        $timescale = unpack('N', substr($body, 12, 4))[1];
        $duration = unpack('N', substr($body, 16, 4))[1];
    }
    if ($timescale <= 0) return null;
    return $duration / $timescale;
}

/** Formats a duration in seconds as a plain "M:SS" badge (no leading
 *  hours unit — these are short trip clips, not feature-length video). */
function format_duration($seconds) {
    $seconds = (int) round($seconds);
    if ($seconds < 0) $seconds = 0;
    $m = intdiv($seconds, 60);
    $s = $seconds % 60;
    return $m . ':' . str_pad((string) $s, 2, '0', STR_PAD_LEFT);
}

/** The name (without its extension) a made file is kept under: 32 hex characters of a keyed hash of the file's path, which kind it is and
 *  when the original was changed. Keyed with this install's secret, so nobody can work out where a private photo's thumbnail is kept
 *  from the photo's name and date alone (the cache folder is also closed by a server rule, but that is one setting). The secret is made
 *  at the first sign-in; until then (a gallery nobody has signed in to) the unkeyed name earlier versions used stays, and a page view
 *  renames those files once the secret exists (see gc_image_cache). */
function cache_name($file, $variant, $mtime) {
    $secret = install_secret();   // (made at the first sign-in; a gallery nobody has signed in to has nothing private to protect, and a visitor never makes a file but a thumbnail)
    $text = $file . '|' . $variant . '|' . $mtime;
    return $secret === '' ? md5($text) : substr(hash_hmac('sha256', $text, $secret), 0, 32);
}

function image_cache_path($cacheDir, $filename, $variant, $srcPath) {
    if (!ENABLE_THUMBNAIL_CACHE) return null;
    if (!is_dir($cacheDir) && !@mkdir($cacheDir, 0775, true)) return null;
    if (!is_writable($cacheDir)) return null;
    $mtime = @filemtime($srcPath);
    return $cacheDir . '/' . cache_name($filename, $variant, $mtime) . '.jpg';
}

/** What a folder's .gallery-cache holds for its files, by name: [the names this gallery would make or read now (including capture dates
 *  and the file data), the names an unkeyed older version used => the keyed name they become]. $folderFiles are paths as the gallery
 *  knows them (relative to $dir). Shared by the clean-up (anything else is removed) and by the list of leftovers (see moved_in_leftovers). */
function image_cache_expected_names($dir, $folderFiles, $imagickAvailable) {
    $valid = []; $renamed = [];
    foreach ($folderFiles as $file) {
        $ext = strtolower(pathinfo($file, PATHINFO_EXTENSION));
        $isHeic = in_array($ext, ['heic', 'heif'], true) && $imagickAvailable;
        $variants = $isHeic ? ['thumb', 'tile', 'tilehd', 'share', 'full', 'cover', 'coverlg'] : ['thumb', 'tile', 'tilehd', 'share', 'cover', 'coverlg'];
        if (is_video_file($file)) { $variants[] = 'poster'; $variants[] = 'strip2'; }   // the frame taken from a video, and its sprite of frames
        $mtime = @filemtime(resolve_real_path($dir, $file));
        $valid['taken3.json'] = true;   // the capture dates found for sorting (see media_taken_times)
        $valid[MEDIA_META_FILE] = true;   // what was read from the files: when taken, where (see media_meta_ensure)
        if (is_video_file($file)) { $valid[cache_name($file, 'preview2', $mtime) . '.mp4'] = true; $renamed[md5($file . '|preview2|' . $mtime) . '.mp4'] = cache_name($file, 'preview2', $mtime) . '.mp4'; }   // and its short clip (see video_preview_path)
        foreach ($variants as $variant) {
            $valid[cache_name($file, $variant, $mtime) . '.jpg'] = true;
            $renamed[md5($file . '|' . $variant . '|' . $mtime) . '.jpg'] = cache_name($file, $variant, $mtime) . '.jpg';
        }
    }
    return [$valid, $renamed];
}

/**
 * Deletes cached thumbnails that no longer correspond to any current
 * photo. A cache entry is keyed by filename+variant+mtime (see
 * image_cache_path), so a renamed/deleted/edited photo just orphans its
 * old cache file rather than overwriting it — this sweeps those away,
 * so a folder whose photos get swapped out over time doesn't
 * accumulate stale thumbnails forever. Only runs on normal gallery page
 * loads (never on ?img/?track), so it doesn't add overhead to the
 * requests that actually serve images.
 *
 * $files are relative paths, and each one's cache lives colocated in its
 * *own* containing folder (see containing_folder_real_path()) rather
 * than one centralized cache at the root — so this groups by containing
 * folder first and GCs each one independently. A flat gallery has
 * exactly one such group (the root itself), so this is a no-op change
 * in shape for that case, not just in effect.
 */
function gc_image_cache($dir, $files, $imagickAvailable) {
    if (!ENABLE_THUMBNAIL_CACHE) return;
    $byFolder = [];
    foreach ($files as $file) {
        $byFolder[containing_folder_real_path($dir, $file)][] = $file;
    }
    $ownRoot = rtrim((string) (realpath($dir) ?: $dir), '/') . '/';
    foreach ($byFolder as $folderPath => $folderFiles) {
        $cacheDir = $folderPath . '/.gallery-cache';
        if (!is_dir($cacheDir)) continue;
        // A place from elsewhere on the server may also be shown by another gallery (an older copy still running there): its
        // thumbnails are named with that gallery's own key, so to this one they look like leftovers. Nothing is swept there.
        if (strpos(rtrim((string) (realpath($folderPath) ?: $folderPath), '/') . '/', $ownRoot) !== 0) continue;
        [$valid, $renamed] = image_cache_expected_names($dir, $folderFiles, $imagickAvailable);
        foreach (scandir($cacheDir) as $entry) {
            if ($entry === '.' || $entry === '..') continue;
            // LEGACY (see docs/LEGACY-REMOVAL.md): before 2.4.0 the names were an unkeyed md5; a made file under the old name is moved to the new one, not made again.
            if (isset($renamed[$entry]) && $renamed[$entry] !== $entry) {
                if (!file_exists($cacheDir . '/' . $renamed[$entry])) @rename($cacheDir . '/' . $entry, $cacheDir . '/' . $renamed[$entry]);
                continue;
            }
            // A video's "didn't work lately" note and a picture still being written belong to a current video.
            $base = preg_replace('/\.(failed|tmp[0-9a-f]*)$/', '', $entry);
            if ($base !== $entry && isset($valid[$base]) && ($base === $entry || time() - (int) @filemtime($cacheDir . '/' . $entry) < 21600)) continue;
            if (!isset($valid[$entry])) {
                @unlink($cacheDir . '/' . $entry);
            }
        }
    }
}

/** Resizes (and, for HEIC, converts) an image to JPEG using Imagick if
 *  available, otherwise GD. Returns true on success. The long side ends up at most $maxDim (a picture is never enlarged).
 *  The JPEG is progressive: it paints coarse-to-fine while it loads. */
function generate_resized_jpeg($srcPath, $destPath, $maxDim, $quality = 82) {
    if (class_exists('Imagick')) {
        try {
            $img = new Imagick();
            $img->readImage($srcPath);
            if (method_exists($img, 'autoOrient')) {
                $img->autoOrient();
            }
            $img->setImageFormat('jpeg');
            $img->setImageCompressionQuality($quality);
            $w = $img->getImageWidth();
            $h = $img->getImageHeight();
            if (max($w, $h) > $maxDim) {
                $img->thumbnailImage($maxDim, $maxDim, true);
                if (max($w, $h) > $maxDim * 2 && method_exists($img, 'unsharpMaskImage')) $img->unsharpMaskImage(0, 0.5, 0.5, 0.02);   // a picture shrunk a lot comes out a touch soft
            }
            if (defined('Imagick::INTERLACE_PLANE')) $img->setInterlaceScheme(Imagick::INTERLACE_PLANE);
            $img->stripImage();
            $ok = $img->writeImage($destPath);
            $img->clear();
            $img->destroy();
            if ($ok) return true;
        } catch (Exception $e) {
            // Fall through to GD — won't help with HEIC, but keeps
            // standard formats working if Imagick chokes on a given file.
        }
    }
    if (extension_loaded('gd')) {
        $data = @file_get_contents($srcPath);
        if ($data === false) return false;
        $src = @imagecreatefromstring($data);
        if (!$src) return false;

        $ext = strtolower(pathinfo($srcPath, PATHINFO_EXTENSION));
        if (function_exists('exif_read_data') && in_array($ext, ['jpg', 'jpeg'], true)) {
            $exif = @exif_read_data($srcPath);
            if (!empty($exif['Orientation'])) {
                if ($exif['Orientation'] === 3) $src = imagerotate($src, 180, 0);
                if ($exif['Orientation'] === 6) $src = imagerotate($src, -90, 0);
                if ($exif['Orientation'] === 8) $src = imagerotate($src, 90, 0);
            }
        }

        $w = imagesx($src);
        $h = imagesy($src);
        $scale = min(1, $maxDim / max($w, $h));
        $nw = max(1, (int) round($w * $scale));
        $nh = max(1, (int) round($h * $scale));
        $dst = imagecreatetruecolor($nw, $nh);
        imagecopyresampled($dst, $src, 0, 0, 0, 0, $nw, $nh, $w, $h);
        imageinterlace($dst, true);
        $ok = imagejpeg($dst, $destPath, $quality);
        unset($src);
        unset($dst);
        return $ok;
    }
    return false;
}

/**
 * A square cut of a photo for a folder's cover card, taken from the original so it stays sharp at any card size. The
 * square is the largest one that fits; its position keeps the middle across a landscape photo, and the upper-middle
 * (38% of the way down the spare height) of a portrait one, where faces and horizons usually are, so most of the scene
 * survives the crop. $dim is the side of the finished square.
 */
function generate_cover_jpeg($srcPath, $destPath, $dim) {
    if (class_exists('Imagick')) {
        try {
            $img = new Imagick();
            $img->readImage($srcPath);
            if (method_exists($img, 'autoOrient')) $img->autoOrient();
            $img->setImageFormat('jpeg');
            $img->setImageCompressionQuality(84);
            $w = $img->getImageWidth();
            $h = $img->getImageHeight();
            $side = min($w, $h);
            $img->cropImage($side, $side, (int) round(($w - $side) / 2), (int) round(($h - $side) * 0.38));
            $img->setImagePage(0, 0, 0, 0);
            if ($side > $dim) $img->thumbnailImage($dim, $dim);
            $img->stripImage();
            $ok = $img->writeImage($destPath);
            $img->clear();
            $img->destroy();
            if ($ok) return true;
        } catch (Exception $e) {
            // Fall through to GD.
        }
    }
    if (extension_loaded('gd')) {
        $data = @file_get_contents($srcPath);
        if ($data === false) return false;
        $src = @imagecreatefromstring($data);
        if (!$src) return false;
        $ext = strtolower(pathinfo($srcPath, PATHINFO_EXTENSION));
        if (function_exists('exif_read_data') && in_array($ext, ['jpg', 'jpeg'], true)) {
            $exif = @exif_read_data($srcPath);
            if (!empty($exif['Orientation'])) {
                if ($exif['Orientation'] === 3) $src = imagerotate($src, 180, 0);
                if ($exif['Orientation'] === 6) $src = imagerotate($src, -90, 0);
                if ($exif['Orientation'] === 8) $src = imagerotate($src, 90, 0);
            }
        }
        $w = imagesx($src);
        $h = imagesy($src);
        $side = min($w, $h);
        $out = min($dim, $side);
        $dst = imagecreatetruecolor($out, $out);
        imagecopyresampled($dst, $src, 0, 0, (int) round(($w - $side) / 2), (int) round(($h - $side) * 0.38), $out, $out, $side, $side);
        $ok = imagejpeg($dst, $destPath, 84);
        unset($src);
        unset($dst);
        return $ok;
    }
    return false;
}

/** The longest side, in pixels, a size of picture is cut to. */
function image_variant_dim($variant) {
    if (isset(TILE_SIZES[$variant])) return TILE_SIZES[$variant][0];
    return ['thumb' => 480, 'share' => 1200, 'full' => 2400, 'cover' => 640, 'coverlg' => 1200][$variant] ?? 480;
}

/** Makes the cached picture of one size ($variant) of a photo, whatever way that size is cut. True when it was written. */
function make_image_variant($pictureSrc, $cachePath, $variant) {
    // A folder's cover card is a square cut from the original photo (not from its small thumbnail), so it stays sharp.
    if ($variant === 'cover' || $variant === 'coverlg') return generate_cover_jpeg($pictureSrc, $cachePath, image_variant_dim($variant));
    if (isset(TILE_SIZES[$variant])) return generate_tile_jpegs($pictureSrc, [$variant => $cachePath]);
    return generate_resized_jpeg($pictureSrc, $cachePath, image_variant_dim($variant));
}

/** The square cut from the middle of a photo that a tile shows (the tile crops the same way, so nothing it would show is
 *  lost), made at each size asked for from one reading of the photo: $targets is [variant => where to write it].
 *  Never enlarged: a small photo gives a smaller square. Progressive JPEGs, touched up a little after shrinking. True
 *  when every one was written. */
function generate_tile_jpegs($srcPath, $targets) {
    $done = 0;
    if (class_exists('Imagick')) {
        try {
            $img = new Imagick();
            $img->readImage($srcPath);
            if (method_exists($img, 'autoOrient')) $img->autoOrient();
            $img->setImageFormat('jpeg');
            $w = $img->getImageWidth();
            $h = $img->getImageHeight();
            $side = min($w, $h);
            $img->cropImage($side, $side, (int) round(($w - $side) / 2), (int) round(($h - $side) / 2));
            $img->setImagePage(0, 0, 0, 0);
            $img->stripImage();
            foreach ($targets as $variant => $dest) {
                [$dim, $quality] = TILE_SIZES[$variant];
                $one = clone $img;
                $one->setImageCompressionQuality($quality);
                if ($side > $dim) {
                    $one->thumbnailImage($dim, $dim);
                    if ($side > $dim * 2 && method_exists($one, 'unsharpMaskImage')) $one->unsharpMaskImage(0, 0.5, 0.5, 0.02);
                }
                if (defined('Imagick::INTERLACE_PLANE')) $one->setInterlaceScheme(Imagick::INTERLACE_PLANE);
                if ($one->writeImage($dest)) $done++;
                $one->clear(); $one->destroy();
            }
            $img->clear(); $img->destroy();
            if ($done === count($targets)) return true;
        } catch (Exception $e) {
            // Fall through to GD for whatever is left.
        }
        $targets = array_filter($targets, function ($dest) { return !is_file($dest) || filesize($dest) === 0; });
        $done = 0;
        if (!$targets) return true;
    }
    if (extension_loaded('gd')) {
        $data = @file_get_contents($srcPath);
        if ($data === false) return false;
        $src = @imagecreatefromstring($data);
        if (!$src) return false;
        $ext = strtolower(pathinfo($srcPath, PATHINFO_EXTENSION));
        if (function_exists('exif_read_data') && in_array($ext, ['jpg', 'jpeg'], true)) {
            $exif = @exif_read_data($srcPath);
            if (!empty($exif['Orientation'])) {
                if ($exif['Orientation'] === 3) $src = imagerotate($src, 180, 0);
                if ($exif['Orientation'] === 6) $src = imagerotate($src, -90, 0);
                if ($exif['Orientation'] === 8) $src = imagerotate($src, 90, 0);
            }
        }
        $w = imagesx($src);
        $h = imagesy($src);
        $side = min($w, $h);
        foreach ($targets as $variant => $dest) {
            [$dim, $quality] = TILE_SIZES[$variant];
            $out = min($dim, $side);
            $dst = imagecreatetruecolor($out, $out);
            imagecopyresampled($dst, $src, 0, 0, (int) round(($w - $side) / 2), (int) round(($h - $side) / 2), $out, $out, $side, $side);
            imageinterlace($dst, true);
            if (imagejpeg($dst, $dest, $quality)) $done++;
            unset($dst);
        }
        unset($src);
        return $done === count($targets);
    }
    return false;
}

/** Which of a video's three made files the settings ask for: its poster frame, its hover clip and its scrub strip. */
function video_made_wanted() {
    $cache = ENABLE_THUMBNAIL_CACHE;
    return ['poster' => $cache && ENABLE_VIDEO_THUMBNAILS, 'clip' => $cache && ENABLE_VIDEO_PREVIEWS, 'strip' => $cache && ENABLE_VIDEO_PREVIEWS];
}

/** Where each of a video's made files is (or would be) kept: 'poster', 'clip', 'strip' => a path. Nothing is created. */
function video_made_paths($dir, $file) {
    $src = resolve_real_path($dir, $file);
    $cacheDir = containing_folder_real_path($dir, $file) . '/.gallery-cache';
    $mt = @filemtime($src);
    return ['poster' => $cacheDir . '/' . cache_name($file, 'poster', $mt) . '.jpg', 'clip' => $cacheDir . '/' . cache_name($file, 'preview2', $mt) . '.mp4', 'strip' => $cacheDir . '/' . cache_name($file, 'strip2', $mt) . '.jpg'];
}

/** The state of each of a video's made files: 'ready', 'missing' (to be made), 'failed' (ffmpeg could not, lately: not tried again for six
 *  hours), 'unavailable' (no scrub strip can be made: the length can't be read) or 'off' (the settings don't ask for it). */
function video_made_state($dir, $file) {
    $want = video_made_wanted(); $paths = video_made_paths($dir, $file); $out = [];
    foreach ($paths as $k => $path) {
        if (!$want[$k]) { $out[$k] = 'off'; continue; }
        if (is_file($path) && filesize($path) > 0) $out[$k] = 'ready';
        elseif (is_file($path . '.failed') && time() - (int) @filemtime($path . '.failed') < 21600) $out[$k] = 'failed';
        else $out[$k] = 'missing';
    }
    if ($out['strip'] === 'missing') { $d = video_duration_seconds(resolve_real_path($dir, $file)); if ($d === null || $d < 1) $out['strip'] = 'unavailable'; }
    return $out;
}

/** What Prepare media still has to do: how many files there are, how many photos lack some tile size, how many files have no usable
 *  record of what they say about themselves (when taken, where), how many videos lack their poster, clip or strip (when ffmpeg is there to
 *  make them), and how many files need any of it (that is what the progress counts). */
function media_readiness($dir, $files) {
    $ff = ffmpeg_binary() !== '';
    $r = ['total' => 0, 'photos' => 0, 'tilesReady' => 0, 'metaLeft' => 0, 'left' => 0, 'videos' => 0, 'videosReady' => 0, 'posters' => 0, 'clips' => 0, 'strips' => 0, 'videoFailed' => 0, 'videoLeft' => 0, 'ffmpeg' => $ff, 'videoWanted' => array_values(array_filter(array_keys(video_made_wanted()), function ($k) { return video_made_wanted()[$k]; }))];
    foreach ($files as $file) {
        $src = resolve_real_path($dir, $file);
        if (!$src) continue;
        $r['total']++;
        $needTiles = false; $needVideo = false;
        if (!is_video_file($file)) {
            $r['photos']++;
            $cacheDir = containing_folder_real_path($dir, $file) . '/.gallery-cache';
            $all = true;
            foreach (array_keys(TILE_SIZES) as $variant) {
                $path = $cacheDir . '/' . cache_name($file, $variant, @filemtime($src)) . '.jpg';
                if (!is_file($path)) { $all = false; break; }
            }
            if ($all) $r['tilesReady']++; else $needTiles = true;
        } else {
            $r['videos']++;
            $vs = video_made_state($dir, $file);
            foreach (['poster' => 'posters', 'clip' => 'clips', 'strip' => 'strips'] as $k => $count) if ($vs[$k] === 'ready') $r[$count]++;
            if (!in_array('missing', $vs, true) && !in_array('failed', $vs, true)) $r['videosReady']++;
            if (in_array('failed', $vs, true)) $r['videoFailed']++;
            if ($ff && in_array('missing', $vs, true)) { $needVideo = true; $r['videoLeft']++; }
        }
        $needMeta = !media_meta_fresh(media_meta_load(containing_folder_real_path($dir, $file))[basename($file)] ?? null, $src);   // (one that couldn't be read is tried again by a run, but isn't counted as left)
        if ($needMeta) $r['metaLeft']++;
        if ($needTiles || $needMeta || $needVideo) $r['left']++;
    }
    return $r;
}

/** Prepare media, one slice: from file number $from onward, every $step-th one (several requests share the work, each with its own
 *  start and the same step), for about $budget seconds, then says where to carry on. For each file: a photo's missing tile pictures are
 *  made (all of them again when $remake), and what the file says about itself is read and recorded when it has no usable record (every
 *  file again when $again, which also lets a location in the file show for photos carrying an old "read, nothing found" mark, see
 *  media_file_location). A file that can't be handled, such as a damaged one, is counted and passed over rather than tried forever.
 *  'worked' is how many files needed something in this call. */
function media_prepare_batch($dir, $files, $from, $budget, $step = 1, $again = false, $remake = false) {
    $total = count($files);
    $start = microtime(true);
    $made = 0; $failed = 0; $worked = 0; $read = 0; $unreadable = 0; $i = max(0, (int) $from); $step = max(1, (int) $step);
    $records = []; $unmark = [];   // folderReal => [bare name => record], folderReal => [bare names whose old "read, nothing found" mark goes]
    for (; $i < $total; $i += $step) {
        if ($worked > 0 && microtime(true) - $start > $budget) break;
        $file = $files[$i];
        $src = resolve_real_path($dir, $file);
        if (!$src || !is_file($src)) continue;
        $folderReal = containing_folder_real_path($dir, $file);
        $did = false;
        if (!is_video_file($file)) {
            $cacheDir = $folderReal . '/.gallery-cache';
            $missing = [];
            foreach (array_keys(TILE_SIZES) as $variant) {
                $cachePath = image_cache_path($cacheDir, $file, $variant, $src);
                if ($cachePath === null) { $failed++; continue; }
                if (!$remake && is_file($cachePath) && filemtime($cachePath) >= @filemtime($src)) continue;
                $missing[$variant] = $cachePath;
            }
            if ($missing) {   // one reading of the photo makes every size that is missing
                $did = true;
                if (generate_tile_jpegs($src, $missing)) $made += count($missing); else $failed += count($missing);
            }
        }
        $videoMade = false;
        if (is_video_file($file) && ffmpeg_binary() !== '') {   // a video's poster frame, hover clip and scrub strip: seconds each, so one video per call
            $vs = video_made_state($dir, $file); $paths = video_made_paths($dir, $file); $cacheDir = $folderReal . '/.gallery-cache';
            $need = array_keys(array_filter($vs, function ($st) use ($remake) { return $st === 'missing' || ($remake && ($st === 'ready' || $st === 'failed')); }));
            if ($need && (is_dir($cacheDir) || @mkdir($cacheDir, 0775, true)) && is_writable($cacheDir)) {
                $did = true; $videoMade = true;
                foreach ($need as $k) {
                    if ($remake) { @unlink($paths[$k]); @unlink($paths[$k] . '.failed'); }
                    $res = $k === 'poster' ? video_poster_path($src, $cacheDir, $file) : ($k === 'clip' ? video_preview_path($src, $cacheDir, $file) : video_strip_path($src, $cacheDir, $file));
                    if ($res !== null) $made++; else $failed++;
                }
            }
        }
        $bare = basename($file);
        if (media_meta_enabled() && ($again || !media_meta_ready(media_meta_load($folderReal)[$bare] ?? null, $src))) {
            $did = true;
            $rec = media_meta_read_file($src);
            $records[$folderReal][$bare] = $rec;
            $read++;
            if ($rec['gs'] === 'unreadable') $unreadable++;
            if ($again) $unmark[$folderReal][] = $bare;
        }
        if ($did) $worked++;
        if ($videoMade) { $i += $step; break; }   // (one video per call: the page asks again at once)
    }
    foreach ($records as $folderReal => $recs) {
        media_meta_store($folderReal, $recs);
        if (!empty($unmark[$folderReal])) {
            $names = $unmark[$folderReal];
            items_update($folderReal, function (&$d) use ($names) {
                foreach ($names as $n) {
                    if (isset($d['items'][$n]) && empty($d['items'][$n]['location']) && empty($d['items'][$n]['locationCleared'])) unset($d['items'][$n]['gpsChecked']);
                }
            });
        }
    }
    return ['next' => $i, 'total' => $total, 'made' => $made, 'failed' => $failed, 'worked' => $worked, 'read' => $read, 'unreadable' => $unreadable, 'done' => $i >= $total];
}

/** The backups Tidy up made: every .gallery-items.before-tidy-<date>.php in the folders that hold files, newest last. [['folder', 'file', 'at', 'bytes'], ...] */
function media_tidy_backups($dir, $files) {
    $reals = [];
    foreach ($files as $file) $reals[containing_folder_real_path($dir, $file)] = ($slash = strrpos($file, '/')) === false ? '' : substr($file, 0, $slash);
    $out = [];
    foreach ($reals as $real => $folder) {
        foreach (glob($real . '/.gallery-items.before-tidy-*.php') ?: [] as $f) {
            if (!preg_match('/^\.gallery-items\.before-tidy-\d{8}-\d{6}\.php$/', basename($f)) || !is_file($f) || is_link($f)) continue;
            $out[] = ['folder' => $folder, 'file' => $f, 'at' => (int) @filemtime($f), 'bytes' => (int) @filesize($f)];
        }
    }
    usort($out, function ($a, $b) { return $a['at'] <=> $b['at'] ?: strcmp($a['file'], $b['file']); });
    return $out;
}

/** Removes the Tidy up backups (only files named exactly like them, in the folders that hold files); how many went. */
function media_tidy_backups_delete($dir, $files) {
    $n = 0;
    foreach (media_tidy_backups($dir, $files) as $b) if (@unlink($b['file'])) $n++;
    return $n;
}

/** What a person might want to look at in the media, in groups: [['key', 'title', 'hint', 'actionable', 'count', 'items' => [file, ...]], ...]
 *  (empty groups left out). 'actionable' ones are things to deal with; the others are for information. 'attention' counts the files in
 *  the first kind. */
function media_attention($dir, $files) {
    static $memo = [];
    $key = count($files) . '|' . (string) ($files[0] ?? '') . '|' . (string) ($files[count($files) - 1] ?? '');
    if (isset($memo[$key])) return $memo[$key];
    $g = ['unreadable' => [], 'unread' => [], 'legacy' => [], 'videoFailed' => [], 'videoMissing' => [], 'undated' => [], 'differs' => []];
    $ff = ffmpeg_binary() !== '';
    $byFolder = [];
    foreach ($files as $file) $byFolder[containing_folder_real_path($dir, $file)][] = $file;
    foreach ($byFolder as $folderReal => $list) {
        $items = items_read($folderReal)['items'] ?? [];
        $recs = media_meta_enabled() ? media_meta_load($folderReal) : [];
        foreach ($list as $file) {
            $bare = basename($file); $entry = $items[$bare] ?? [];
            if (media_meta_enabled()) {
                $rec = $recs[$bare] ?? null;
                if (!media_meta_fresh($rec, $folderReal . '/' . $bare)) $g['unread'][] = $file;
                else {
                    if (($rec['gs'] ?? '') === 'unreadable') $g['unreadable'][] = $file;
                    if (($rec['t'] ?? null) === null) $g['undated'][] = $file;
                }
                if (!empty($entry['gpsChecked']) && empty($entry['location']) && empty($entry['locationCleared'])) $g['legacy'][] = $file;
            }
            if (is_video_file($file) && $ff) {
                $vs = video_made_state($dir, $file);
                if (in_array('failed', $vs, true)) $g['videoFailed'][] = $file;
                elseif ($vs['poster'] === 'missing') $g['videoMissing'][] = $file;
            }
        }
    }
    if (media_meta_enabled() && ENABLE_THUMBNAIL_CACHE) {
        foreach (media_tidy_run($dir, $files, false, false)['rows'] as $row) foreach ($row['lists']['edited'] ?? [] as $x) $g['differs'][] = ($row['folder'] === '' ? '' : $row['folder'] . '/') . $x['name'];
    }
    // [title, hint, to deal with (else for information), counted as "needs attention"]: files not read yet and videos not made yet are
    // to be done by the Prepare button, which is routine (every new photo is that until it is first shown), so they are listed but not counted.
    $meta = [
        'unreadable' => ['Files that could not be read', 'The gallery could not get a capture date or location from these (a damaged file, or a kind it cannot read). They still show.', true, true],
        'unread' => ['Files not read yet', 'Prepare the rest reads them.', true, false],
        'legacy' => ['Old "nothing found" marks', 'An earlier version looked at these and found no location; they are left alone. Tidy up and Read everything again deal with them.', true, true],
        'videoFailed' => ['Videos ffmpeg could not make pictures for', 'Not tried again for six hours.', true, true],
        'videoMissing' => ['Videos without a poster frame yet', 'Prepare the rest makes them.', true, false],
        'undated' => ['Files with no capture date', 'They are ordered by when the file was changed. Nothing to fix: screenshots, downloads and some videos carry no date.', false, false],
        'differs' => ['Saved locations that differ from their file', 'Yours, kept as they are. Tidy up would not touch them in its careful mode.', false, false],
    ];
    $groups = []; $attention = 0;
    foreach ($meta as $k => [$title, $hint, $actionable, $counted]) {
        if (!$g[$k]) continue;
        $groups[] = ['key' => $k, 'title' => $title, 'hint' => $hint, 'actionable' => $actionable, 'count' => count($g[$k]), 'items' => array_slice($g[$k], 0, 40)];
        if ($counted) $attention += count($g[$k]);
    }
    return $memo[$key] = ['groups' => $groups, 'attention' => $attention];
}

/** One group of media_attention() as a folded list of file names, each linked to that file's editor (for the Health check's Media rows). */
function render_media_group_html($grp) {
    $esc = function ($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); };
    $out = '<details class="media-attn media-attn-' . $esc($grp['key']) . '"><summary>Show the file' . ($grp['count'] === 1 ? '' : 's') . '</summary><ul class="media-attn-list">';
    foreach ($grp['items'] as $file) $out .= '<li><a href="' . admin_find_href($file) . '" title="Show it in its folder">' . $esc($file) . '</a></li>';
    if ($grp['count'] > count($grp['items'])) $out .= '<li class="muted">and ' . number_format($grp['count'] - count($grp['items'])) . ' more</li>';
    return $out . '</ul></details>';
}

/** The "Backups from Tidy up" line of the Prepare media panel, as HTML; empty when there are none. */
function render_media_backups_html($backups) {
    if (!$backups) return '';
    $folders = []; foreach ($backups as $b) $folders[$b['folder']] = true;
    $first = $backups[0]['at']; $last = $backups[count($backups) - 1]['at'];
    $fmt = function ($t) { return gmdate('j M Y', $t); };
    return '<p class="hint media-backups-line"><strong>' . count($backups) . ' backup' . (count($backups) === 1 ? '' : 's') . ' from Tidy up</strong> (the folders\' data as it was before, in ' . count($folders) . ' folder' . (count($folders) === 1 ? '' : 's') . ', ' . ($fmt($first) === $fmt($last) ? $fmt($first) : $fmt($first) . ' to ' . $fmt($last)) . '). Keep them until you have looked through the gallery. <button type="button" class="secondary media-backups-delete">Delete the backups&hellip;</button> <span class="media-backups-out" aria-live="polite"></span></p>';
}

/** Everything Prepare media's list says, one row per folder that has files: the folder, its files, how many photos have their tile pictures, and
 *  media_folder_summary()'s counts. */
function media_report($dir, $files) {
    $byFolder = [];
    foreach ($files as $file) {
        $slash = strrpos($file, '/');
        $byFolder[$slash === false ? '' : substr($file, 0, $slash)][] = $file;
    }
    ksort($byFolder, SORT_NATURAL | SORT_FLAG_CASE);
    $rows = [];
    foreach ($byFolder as $path => $list) {
        $folderReal = containing_folder_real_path($dir, $list[0]);
        $sum = media_folder_summary($dir, $folderReal, $list);
        $tiles = 0; $photos = 0;
        foreach ($list as $file) {
            if (is_video_file($file)) continue;
            $photos++;
            $src = resolve_real_path($dir, $file);
            $ok = true;
            foreach (array_keys(TILE_SIZES) as $variant) {
                if (!is_file($folderReal . '/.gallery-cache/' . cache_name($file, $variant, @filemtime($src)) . '.jpg')) { $ok = false; break; }
            }
            if ($ok) $tiles++;
        }
        $vids = 0; $posters = 0; $clips = 0; $strips = 0; $vfail = 0;
        foreach ($list as $file) {
            if (!is_video_file($file)) continue;
            $vids++; $vs = video_made_state($dir, $file);
            if ($vs['poster'] === 'ready') $posters++;
            if ($vs['clip'] === 'ready') $clips++;
            if ($vs['strip'] === 'ready') $strips++;
            if (in_array('failed', $vs, true)) $vfail++;
        }
        $rows[] = ['folder' => $path, 'photos' => $photos, 'tiles' => $tiles, 'videos' => $vids, 'posters' => $posters, 'clips' => $clips, 'strips' => $strips, 'videoFailed' => $vfail] + $sum;
    }
    return $rows;
}

/** Serves ?img=<filename-or-relative-path>&size=thumb|share|full,
 *  resizing/caching/converting as needed. $filename is validated by exact
 *  match against $validFiles — the real list this script's own scan
 *  already trusts — never basename()'d first, since that would strip a
 *  legitimate subfolder prefix like "Paris/" right back off. The exact-
 *  match allowlist is what actually provides the safety here: a
 *  traversal attempt never matches anything the scan itself produced,
 *  with or without that extra step, and nothing resembling "../" can
 *  survive that match regardless of how many segments the path has. */
function serve_image($dir, $filename, $variant, $validFiles, $itemsData = []) {
    // ?size[]=x arrives as an array; anything that isn't a plain string
    // is just the default size.
    if (!is_string($variant)) $variant = 'thumb';
    if (!in_array($filename, $validFiles, true)) {
        http_response_code(404);
        return;
    }
    // A checkbox that only skips a thumbnail in the grid isn't real
    // privacy if the file itself is still fetchable directly — this
    // refuses it to anyone without a valid reveal, the same allowlist-
    // plus-identity-check discipline as the line above.
    if (!viewer_may_see_item($dir, $filename, $itemsData)) {
        http_response_code(404);
        return;
    }
    // Someone using a share link is sent a private picture: noted in that link's log (their browser reports what was on screen too).
    if ($variant !== 'full' && ($linkNote = link_viewer()) !== null && !is_revealed() && file_is_hidden($dir, $filename, $itemsData)) link_queue_delivery($linkNote, 's', $filename);
    $cacheControl = file_cache_control($dir, $filename, $itemsData);
    $maxDim = image_variant_dim($variant);

    // No frame extraction (see ENABLE_VIDEO's doc comment) — every size
    // of a video's "thumbnail," grid tile or Open Graph share preview
    // alike, gets the same generic placeholder graphic instead.
    $srcPath = resolve_real_path($dir, $filename);
    $cacheDir = containing_folder_real_path($dir, $filename) . '/.gallery-cache';
    $pictureSrc = $srcPath;   // where the pixels come from: the file itself, or for a video the frame taken from it
    if (is_video_file($filename)) {
        // A real frame from the video when ffmpeg can take one; everything below then treats that picture as the source.
        $poster = video_poster_path($srcPath, $cacheDir, $filename);
        if ($poster === null) {
            render_video_placeholder_image(min($maxDim, 640));
            return;
        }
        if ($variant === 'full') {
            header('Content-Type: image/jpeg');
            header('Cache-Control: ' . $cacheControl);
            readfile($poster);
            return;
        }
        $pictureSrc = $poster;
    }
    $ext = strtolower(pathinfo($filename, PATHINFO_EXTENSION));
    $isHeic = in_array($ext, ['heic', 'heif'], true);

    // Non-HEIC files at full size are served untouched — no need to
    // resize or re-encode the original the lightbox already opens fine.
    // (Except for a visitor who isn't signed in and a photo whose location is hidden: the file is the original, with its
    // GPS, so that visitor is sent it with the location blanked out, or the re-encoded copy below if that can't be done.)
    if (!$isHeic && $variant === 'full') {
        if (send_original_for_visitor($srcPath, $filename, $itemsData, $cacheControl)) return;
    }

    $cachePath = image_cache_path($cacheDir, $filename, $variant, $srcPath);
    if ($cachePath && file_exists($cachePath) && filemtime($cachePath) >= @filemtime($srcPath)) {
        header('Content-Type: image/jpeg');
        header('Cache-Control: ' . $cacheControl);
        readfile($cachePath);
        return;
    }

    $ok = $cachePath ? make_image_variant($pictureSrc, $cachePath, $variant) : false;
    if ($ok) {
        header('Content-Type: image/jpeg');
        header('Cache-Control: ' . $cacheControl);
        readfile($cachePath);
        // The first time the gallery meets this file: now that its picture is made, read what the file says about itself
        // (when it was taken, where) and keep it, after the visitor has been answered where the server allows.
        if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request();
        media_meta_ensure($dir, $filename);
        return;
    }
    if ($pictureSrc !== $srcPath) {
        render_video_placeholder_image(min($maxDim, 640));   // the frame couldn't be cut down: the placeholder, never the video file as a picture
        return;
    }

    // Couldn't generate (no Imagick/GD, cache folder unwritable, or a
    // HEIC file with no capable backend). Non-HEIC formats can still just
    // serve the original; HEIC genuinely cannot be shown without conversion.
    if ($isHeic) {
        http_response_code(415);
        return;
    }
    // Ordinary photos keep the headers they have always had on this path
    // (none); a hidden one must still never be stored by a shared cache.
    if (!send_original_for_visitor($srcPath, $filename, $itemsData, $cacheControl === 'private, no-store' ? $cacheControl : null)) {
        http_response_code(404);
    }
}

/**
 * A short tag that changes whenever a photo or video is replaced — a hash
 * of its modification time and size, so replacing a file under the same
 * name (even with one the same size, or an old timestamp preserved by a
 * copy tool) gives it a new tag in all but freak cases. It rides along on
 * the image/video address as &v=..., because those responses are cached
 * by browsers for a year ("immutable") and the address alone never
 * changed: without it, a replaced photo kept showing the old picture to
 * anyone who had seen it. Hashed rather than the raw timestamp, so a
 * visitor can't read when each file was uploaded or last touched. The
 * server ignores it. One stat per file per request, remembered.
 */
function file_version($file) {
    static $seen = [];
    if (isset($seen[$file])) return $seen[$file];
    $stat = @stat(resolve_real_path($GLOBALS['dir'], $file));
    return $seen[$file] = $stat ? substr(hash('sha256', $stat['mtime'] . '|' . $stat['size']), 0, 10) : '';
}

function img_url($file, $size) {
    $v = file_version($file);
    return '?img=' . rawurlencode($file) . '&size=' . $size . ($v !== '' ? '&v=' . $v : '') . (($GLOBALS['photoPass'] ?? null) === $file ? '&k=' . rawurlencode((string) ($_GET['k'] ?? '')) : '');   // (on a photo's own address its pictures ask with the same code)
}

/** The extra attributes that let the browser choose a tile's picture by how big the tile really is and how dense the screen
 *  is: the 560 pixel one for an ordinary screen, the 1080 one for a phone. (The tile is one column wide on a phone in
 *  portrait, otherwise 180 to 250 points.) Where thumbnails are off there is only the one picture. */
function tile_srcset_attrs($file) {
    if (!ENABLE_THUMBNAIL_CACHE) return '';
    return ' srcset="' . htmlspecialchars(img_url($file, 'tile') . ' ' . TILE_SIZES['tile'][0] . 'w, ' . img_url($file, 'tilehd') . ' ' . TILE_SIZES['tilehd'][0] . 'w', ENT_QUOTES, 'UTF-8')
         . '" sizes="(max-width: 417px) calc(100vw - 48px), 250px"';
}

/** A location-pin badge's link target — OpenStreetMap needs no API key
 *  and no dependency this project doesn't already avoid adding, unlike
 *  a full in-app map (a later, dedicated phase). */
function osm_location_url($lat, $lng) {
    return 'https://www.openstreetmap.org/?mlat=' . rawurlencode($lat) . '&mlon=' . rawurlencode($lng)
         . '#map=16/' . rawurlencode($lat) . '/' . rawurlencode($lng);
}


/**
 * Serves ?video=<filename-or-relative-path> with HTTP Range support —
 * the one genuinely new piece of serving logic video needs. The file is
 * never transcoded or re-encoded, but video playback does need seeking,
 * and a browser seeks by issuing a Range request; without honoring it,
 * seeking either breaks outright or forces re-downloading the whole file
 * from the start. $filename is validated the same exact-allowlist way as
 * serve_image() above — and since ENABLE_VIDEO=false simply never adds
 * .mov/.mp4 to $validFiles in the first place, a request here fails
 * closed on its own with no extra check needed for the feature being off.
 * The hidden-item check below runs before any Range handling, not after
 * — a second code path added later just for partial requests is exactly
 * the kind of place a gate like this gets forgotten.
 */
function serve_video($dir, $filename, $validFiles, $itemsData = []) {
    if (!in_array($filename, $validFiles, true)) {
        http_response_code(404);
        return;
    }
    if (!viewer_may_see_item($dir, $filename, $itemsData)) {
        http_response_code(404);
        return;
    }
    $cacheControl = file_cache_control($dir, $filename, $itemsData);
    $srcPath = resolve_real_path($dir, $filename);
    $size = @filesize($srcPath);
    if ($size === false) {
        http_response_code(404);
        return;
    }
    $ext = strtolower(pathinfo($filename, PATHINFO_EXTENSION));
    // A visitor who isn't signed in, and a video whose location is hidden: the location is blanked out of what is sent.
    $plan = visitor_scrub_plan($srcPath, $filename, $itemsData);
    if ($plan === null) {
        http_response_code(404);
        return;
    }
    if ($plan !== []) $cacheControl = 'private, max-age=86400';

    // Once nginx is configured for this (see serve_original_file()),
    // hand the whole request to its own static serving instead — nginx
    // already handles Range requests correctly on its own, a free
    // upgrade over the plain-PHP handling below, which stays as the
    // baseline that works on any host regardless.
    if (NGINX_ACCEL_REDIRECT_PREFIX !== '' && $plan === [] && file_is_under_web_root($srcPath, $filename)) {
        header('Cache-Control: ' . $cacheControl);
        serve_original_file($srcPath, $filename, guess_mime($ext));
        return;
    }

    header('Content-Type: ' . guess_mime($ext));
    header('Cache-Control: ' . $cacheControl);
    if ($plan !== []) header('Vary: Cookie');
    header('Accept-Ranges: bytes');

    $start = 0;
    $end = $size - 1;
    $range = $_SERVER['HTTP_RANGE'] ?? '';
    $isRangeRequest = false;
    if ($range !== '' && preg_match('/^bytes=(\d*)-(\d*)$/', trim($range), $m) && ($m[1] !== '' || $m[2] !== '')) {
        $isRangeRequest = true;
        if ($m[1] === '') {
            // Suffix range ("bytes=-500"): the last N bytes.
            $suffixLen = (int) $m[2];
            $start = max(0, $size - $suffixLen);
            $end = $size - 1;
        } else {
            $start = (int) $m[1];
            $end = $m[2] === '' ? $size - 1 : min((int) $m[2], $size - 1);
        }
        if ($start >= $size || $start > $end) {
            http_response_code(416);
            header('Content-Range: bytes */' . $size);
            return;
        }
    }
    // A Range header present but not matching "bytes=..." at all (some
    // other unit, or genuinely malformed) is simply ignored — falls back
    // to serving the whole file with a normal 200, rather than erroring.

    $fh = @fopen($srcPath, 'rb');
    if ($fh === false) {
        http_response_code(404);
        return;
    }
    if ($isRangeRequest) {
        http_response_code(206);
        header('Content-Range: bytes ' . $start . '-' . $end . '/' . $size);
    }
    $length = $end - $start + 1;
    header('Content-Length: ' . $length);

    fseek($fh, $start);
    $remaining = $length;
    $at = $start;
    $chunkSize = 8192;
    while ($remaining > 0 && !feof($fh)) {
        $chunk = fread($fh, min($chunkSize, $remaining));
        if ($chunk === false || $chunk === '') break;
        echo $plan === [] ? $chunk : apply_patches_to_chunk($chunk, $at, $plan);
        $remaining -= strlen($chunk);
        $at += strlen($chunk);
    }
    fclose($fh);
}


/* -----------------------------------------------------------------------
 * Moved in from another gallery. A folder shown here that another gallery showed before (the old copy being retired) holds two things
 * that gallery left behind and this one cannot reuse:
 *   - its thumbnails and video pictures, named with that gallery's own key, which sit in the folder's .gallery-cache for ever when the
 *     folder is a place from elsewhere on the server (the clean-up skips those, see gc_image_cache; a folder inside the gallery's own
 *     folder is swept clean by itself); and
 *   - its view counts, kept in the folder's own .gallery-stats.sqlite under the path as that gallery saw the photo.
 * Prepare media offers both: add the old counts to this gallery's own (once per folder, old rows never changed), and remove the
 * leftover thumbnails (only after the owner says no other gallery still shows the folders). Nothing here ever touches a photo, a
 * caption, a flag, or the files that hold what was read from the photos.
 * ----------------------------------------------------------------------- */

/** The folders of $files (paths relative to $dir) as ['real' => real path, 'rel' => the folder as the gallery names it, 'files' => [...]]. */
function moved_in_folders($dir, $files) {
    $by = [];
    foreach ($files as $file) {
        $real = containing_folder_real_path($dir, $file);
        if (!isset($by[$real])) $by[$real] = ['real' => $real, 'rel' => ($slash = strrpos($file, '/')) === false ? '' : substr($file, 0, $slash), 'files' => []];
        $by[$real]['files'][] = $file;
    }
    return array_values($by);
}

/** The picture and clip files in places from elsewhere on the server that this gallery would not make or read now, named like a made
 *  picture (32 hex digits and .jpg or .mp4). [['folder' => as the gallery names it, 'real', 'names' => [...], 'count', 'bytes'], ...] and totals. */
function moved_in_leftovers($dir, $files) {
    $ownRoot = rtrim((string) (realpath($dir) ?: $dir), '/') . '/';
    $imagick = !empty($GLOBALS['imagickAvailable']);
    $folders = []; $count = 0; $bytes = 0;
    foreach (moved_in_folders($dir, $files) as $f) {
        $cacheDir = $f['real'] . '/.gallery-cache';
        if (!is_dir($cacheDir) || is_link($cacheDir)) continue;
        if (strpos(rtrim((string) (realpath($f['real']) ?: $f['real']), '/') . '/', $ownRoot) === 0) continue;   // (a folder inside the gallery's own folder is tidied by the clean-up itself)
        [$valid, $renamed] = image_cache_expected_names($dir, $f['files'], $imagick);
        $names = []; $b = 0;
        foreach (scandir($cacheDir) ?: [] as $entry) {
            if (!preg_match('/^[0-9a-f]{32}\.(jpg|mp4)$/', $entry) || isset($valid[$entry]) || isset($renamed[$entry])) continue;
            $path = $cacheDir . '/' . $entry;
            if (!is_file($path) || is_link($path)) continue;
            $names[] = $entry; $b += (int) @filesize($path);
        }
        if (!$names) continue;
        $folders[] = ['folder' => $f['rel'] === '' ? '(top level)' : $f['rel'], 'real' => $f['real'], 'names' => $names, 'count' => count($names), 'bytes' => $b];
        $count += count($names); $bytes += $b;
    }
    return ['count' => $count, 'bytes' => $bytes, 'folders' => $folders];
}

/** What a Left behind row of the Health check is about, as [how many, a fingerprint of exactly those things] (null for a row that is not one of these). "Set aside" keeps the fingerprint:
 *  the row stays quiet only while it is about the very same things, so anything new (or anything gone) brings it back, and a count that happens to match does not hide different things. */
function health_aside_state($key, $dir, $files) {
    if ($key === 'earlier-views') { $ev = moved_in_earlier_views($dir, $files); return [(int) $ev['views'], md5(json_encode($ev['rows']))]; }
    if ($key === 'leftover-thumbs') {
        $lo = moved_in_leftovers($dir, $files); $all = [];
        foreach ($lo['folders'] as $f) foreach ($f['names'] as $nm) $all[] = $f['real'] . '/' . $nm;
        sort($all); return [(int) $lo['count'], md5(implode("\n", $all))];
    }
    if ($key === 'loose-photos') { $l = EXTRA_ROOTS ? loose_media_in_roots() : []; sort($l); return [count($l), md5(implode("\n", $l))]; }
    return null;
}

/** Removes those leftovers (the list is worked out again here, never taken from the request). Returns how many files and bytes went. */
function moved_in_remove_leftovers($dir, $files) {
    $n = 0; $bytes = 0;
    foreach (moved_in_leftovers($dir, $files)['folders'] as $f) {
        foreach ($f['names'] as $name) {
            $path = $f['real'] . '/.gallery-cache/' . $name;
            if (!preg_match('/^[0-9a-f]{32}\.(jpg|mp4)$/', $name) || !is_file($path) || is_link($path)) continue;
            $size = (int) @filesize($path);
            if (@unlink($path)) { $n++; $bytes += $size; }
        }
    }
    return ['count' => $n, 'bytes' => $bytes];
}

/** The shorter paths an older gallery may have saved a photo's views under: $file without its leading folders, one at a time, down to the bare name
 *  (a gallery showing "Eurotrip/paris/a.jpg" here may have shown "paris/a.jpg", or, with the folder as its top, "a.jpg"). */
function moved_in_old_paths($file) {
    $parts = explode('/', $file); $out = [];
    for ($i = 1; $i < count($parts); $i++) $out[] = implode('/', array_slice($parts, $i));
    return $out;
}

/** The marker kept in a folder's stats file once its earlier views were added, so that pressing the button again adds nothing. */
function moved_in_marker_key($folderRel) {
    return 'carried:' . stats_key((string) $folderRel);
}

/** Views other galleries counted for the photos shown here, found in each folder's own stats file under an older path, and not added yet.
 *  Read-only. ['views' => total waiting, 'folders' => number with some, 'done' => folders already added, 'rows' => [folder => ['found' => n, 'added' => bool]]]. */
function moved_in_earlier_views($dir, $files, $apply = false) {
    $out = ['views' => 0, 'folders' => 0, 'done' => 0, 'rows' => [], 'added' => 0, 'addedFolders' => 0];
    $drivers = class_exists('PDO') ? PDO::getAvailableDrivers() : [];
    if (!in_array('sqlite', $drivers, true)) return $out;   // (no SQLite: the older flat-file counts are not read)
    foreach (moved_in_folders($dir, $files) as $f) {
        $db = $f['real'] . '/.gallery-stats.sqlite';
        if (!is_file($db) || is_link($db)) continue;
        try {
            $pdo = new PDO('sqlite:' . $db);
            $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
            $has = $pdo->query("SELECT name FROM sqlite_master WHERE type='table' AND name='photo_views_h'")->fetchColumn();
            if (!$has) continue;
            $rowsByKey = [];
            foreach ($pdo->query('SELECT key, views FROM photo_views_h') as $r) $rowsByKey[$r['key']] = (int) $r['views'];
            $marker = moved_in_marker_key($f['rel']);
            $hasStats = $pdo->query("SELECT name FROM sqlite_master WHERE type='table' AND name='stats'")->fetchColumn();
            $done = false;
            if ($hasStats) { $m = $pdo->prepare('SELECT value FROM stats WHERE key = :k'); $m->execute([':k' => $marker]); $done = $m->fetchColumn() !== false; }
            $found = 0; $adds = [];
            foreach ($f['files'] as $file) {
                $own = stats_key($file); $sum = 0; $seen = [];
                foreach (moved_in_old_paths($file) as $old) {
                    $k = stats_key($old);
                    if ($k === $own || isset($seen[$k]) || !isset($rowsByKey[$k])) continue;
                    $seen[$k] = true; $sum += $rowsByKey[$k];
                }
                if ($sum > 0) { $found += $sum; $adds[$own] = $sum; }
            }
            if ($found === 0 && !$done) continue;
            $out['rows'][$f['rel']] = ['found' => $done ? 0 : $found, 'added' => $done];
            if ($done) { $out['done']++; continue; }
            $out['views'] += $found; $out['folders']++;
            if ($apply && $adds) {
                $pdo->exec('PRAGMA busy_timeout = 5000');
                $pdo->exec('CREATE TABLE IF NOT EXISTS stats (key TEXT PRIMARY KEY, value INTEGER NOT NULL DEFAULT 0)');
                $pdo->beginTransaction();
                $up = $pdo->prepare('INSERT INTO photo_views_h(key, views) VALUES(:k, :v) ON CONFLICT(key) DO UPDATE SET views = views + :v');
                foreach ($adds as $key => $v) $up->execute([':k' => $key, ':v' => $v]);
                $pdo->prepare('INSERT OR REPLACE INTO stats(key, value) VALUES(:k, 1)')->execute([':k' => $marker]);
                $pdo->commit();
                $out['added'] += $found; $out['addedFolders']++;
            }
        } catch (Exception $e) {
            continue;
        }
    }
    return $out;
}
/* -----------------------------------------------------------------------
 * GROUPING: discover qualifying .md files, extract {group:}/{photos:}
 * directives, and build the final $groups (auto-detected + explicit)
 * before anything below (stats, ?track, rendering) needs it.
 * ----------------------------------------------------------------------- */

// Collected as issues are found below; surfaced as an HTML comment near
// the top of the page (never anything a normal visitor would notice) so
// a typo'd filename or a missing {gallery} marker doesn't just fail
// silently with no way to ever find out why.
$galleryNotices = [];
foreach (($GLOBALS['__gallery_config_problems'] ?? []) as $configProblem) $galleryNotices[] = $configProblem;
if (!empty($subfolderMediaCount)) {
    $galleryNotices[] = ($subfolderMediaTruncated ? 'At least ' : '') . $subfolderMediaCount
        . ' photo' . ($subfolderMediaCount === 1 ? '' : 's') . '/video' . ($subfolderMediaCount === 1 ? ' was' : 's were')
        . ' found in subfolders but ' . ($subfolderMediaCount === 1 ? 'isn\'t' : 'aren\'t')
        . ' shown. Open the admin and turn on Show subfolders (Settings → Folders and photos) to include them.';
}

if (!ENABLE_VIDEO) {
    [$ignoredVideoCount, $ignoredVideoTruncated] = count_ignored_videos($dir);
    if ($ignoredVideoCount > 0) {
        $galleryNotices[] = ($ignoredVideoTruncated ? 'At least ' : '') . $ignoredVideoCount
            . ' video file' . ($ignoredVideoCount === 1 ? ' (.mov/.mp4) was' : 's (.mov/.mp4) were')
            . ' found but ' . ($ignoredVideoCount === 1 ? 'isn\'t' : 'aren\'t')
            . ' shown, because Show videos is off. Open the admin and turn it on (Settings → Videos and thumbnails) to include them.';
    }
}

if (AUTO_GROUP_BY_FOLDER && EXTRA_ROOTS && ($looseInRoots = count_loose_media_in_roots()) > 0) {
    $galleryNotices[] = $looseInRoots . ' photo' . ($looseInRoots === 1 ? ' or video lies' : 's or videos lie')
        . ' directly in a place added from elsewhere on the server. Only the folders inside such a place are shown at the top of the gallery, so move '
        . ($looseInRoots === 1 ? 'it' : 'them') . ' into a folder to include ' . ($looseInRoots === 1 ? 'it' : 'them') . '.';
}

// A place from elsewhere on the server (EXTRA_ROOTS / EXTRA_FOLDERS) that has gone missing or can't be read just shows nothing;
// say so (without naming the path: a fresh install shows these notices to whoever opens the page).
$unreadableExtra = 0;
foreach (array_merge(array_values((array) EXTRA_ROOTS), array_values((array) EXTRA_FOLDERS)) as $extraPath) {
    if (is_string($extraPath) && (!is_dir($extraPath) || !is_readable($extraPath))) $unreadableExtra++;
}
if (AUTO_GROUP_BY_FOLDER && $unreadableExtra > 0) {
    $galleryNotices[] = ($unreadableExtra === 1 ? 'A folder from elsewhere on the server is missing or can\'t be read' : $unreadableExtra . ' folders from elsewhere on the server are missing or can\'t be read')
        . ', so nothing from ' . ($unreadableExtra === 1 ? 'it is' : 'them is') . ' shown. The Health check in Settings names ' . ($unreadableExtra === 1 ? 'it' : 'them') . '.';
}

// Only a .md file whose first non-blank line is exactly "{gallery}" is
// treated as content for this script — anything else in the folder (a
// personal notes.md, a leftover README, etc.) is left completely alone.
$mdCandidates = scan_md_candidates($dir);

$mdScan = scan_gallery_md_files($dir);
$mdFiles = $mdScan['files'];
$rejectedMdCount = $mdScan['rejectedCount'];
if ($rejectedMdCount > 0) {
    // Deliberately doesn't name the file(s): unlike every other notice
    // here, this one would otherwise reveal the exact filename of a .md
    // the folder owner specifically did *not* choose to expose via the
    // gallery — and since a .md is served as a plain static file with
    // no access control tied to the {gallery} marker (that's a PHP-
    // application concept, not a permissions mechanism), naming it would
    // hand a visitor the literal URL to go read its contents directly.
    $galleryNotices[] = $rejectedMdCount === 1
        ? 'A .md file was found but ignored because its first line isn\'t the required {gallery} marker. If it\'s meant to be your gallery notes, add {gallery} as its very first line.'
        : $rejectedMdCount . ' .md files were found but ignored because none of them start with the required {gallery} marker. If one is meant to be your gallery notes, add {gallery} as its very first line.';
}

$folderName = basename($dir);

// If the first non-empty line remaining (after the marker) is a
// "# Heading", use it as the page title instead of the folder name —
// and strip it out of that file's content so it isn't shown twice.
$pageTitle = $folderName;
$mdContents = [];
foreach ($mdFiles as $idx => $mdFile) {
    $content = $mdScan['contents'][$mdFile];
    if ($idx === 0) {
        $lines = explode("\n", str_replace("\r\n", "\n", $content));
        foreach ($lines as $li => $l) {
            if (trim($l) === '') continue;
            if (preg_match('/^#\s+(.+)$/', trim($l), $m)) {
                $pageTitle = unprotect_inline_code(trim($m[1]));
                unset($lines[$li]);
                $content = implode("\n", $lines);
            }
            break; // only ever check the very first non-empty line
        }
    }
    $mdContents[$mdFile] = $content;
}
// The admin's gallery title (the root's own settings) wins over a "# Heading"
// in a notes file, which wins over the folder name.
$rootMeta = root_display_meta($dir);
if ($rootMeta['label'] !== '') $pageTitle = $rootMeta['label'];

// Extract {photos:}/{group:} directives across all qualifying .md files,
// in file order, tracking each directive's approximate position so it
// can be interleaved with auto-detected mention-order positions below.
$rootDirectives = collect_explicit_directives($mdContents, array_values(array_filter($files, function ($f) { return strpos($f, '/') === false; })), '', $files, $galleryNotices);
$explicitClaims = $rootDirectives['claims'];           // filename => true (removed from auto-detection)
$explicitGroups = $rootDirectives['groups'];           // slug => ['name' => .., 'files' => [...], 'position' => N]
$positionalClusters = $rootDirectives['clusters'];     // list of ['files' => [...], 'position' => N]

// Folder-groups: each top-level subfolder (an immediate child of the
// gallery root, or an EXTRA_FOLDERS virtual mount) with any files
// anywhere in its own subtree becomes one group, keyed by its own
// relative path. Every file inside a qualifying subfolder is claimed
// here, the same way a {photos:}-claimed file already is — removed from
// the filename-auto-grouping pool entirely below, so it's never
// re-clustered by its filename suffix a second time inside a folder it's
// already a member of. A folder's default label is its raw, unmodified
// name — {group: Name} in the root's own .md still renames it, the same
// mechanism that already renames any auto-detected group.
$folderGroups = [];       // relative folder path => [recursive member files]
$folderClaims = [];       // filename => true (removed from auto-detection, same as $explicitClaims)
if (AUTO_GROUP_BY_FOLDER && $folderTree !== null) {
    foreach ($folderTree['subdirs'] as $topName => $topNode) {
        $members = flatten_folder_tree($topNode, $topName);
        if (empty($members)) continue;
        $members = media_sort_apply($members, $dir);   // each folder's photos in its own order (see media_sort_apply)
        $folderGroups[$topName] = $members;
        foreach ($members as $m) {
            $folderClaims[$m] = true;
        }
    }
}
// Collections shown on the front page (those in it, and those marked to show there) are cards among the folders. They claim no photo: every
// member stays where it really is, and a card shows only the members this visitor may see (the filter below drops one with none).
if (AUTO_GROUP_BY_FOLDER && !folder_style_flat() && collections_any()) {
    foreach (collection_cards($dir, '', $files, $files) as [$collectionKey, $collectionRec, $collectionFiles]) {
        if (!isset($folderGroups[$collectionKey])) $folderGroups[$collectionKey] = $collectionFiles;
    }
}
$folderGroupKeys = array_fill_keys(array_keys($folderGroups), true);

// Build the final groups: filename-based auto-detection (unless
// AUTO_GROUP_BY_FILENAME is off, or a file was explicitly claimed above)
// plus explicit named groups. A file claimed via a bare {photos:} (no
// {group:}) stays its own standalone single, keyed by its own filename
// so it can never merge with an unrelated auto-detected group.
$groups = [];
foreach ($files as $file) {
    if (isset($explicitClaims[$file]) || isset($folderClaims[$file])) continue;
    $groups[group_key($file)][] = $file;
}
foreach ($folderGroups as $folderKey => $members) {
    $groups[$folderKey] = $members;
}

// A key shared by 2+ files is either a real, intended multi-angle group
// (members' pre-extension names differ and only converge after suffix-
// stripping, e.g. "dp104_01"/"dp104_02" -> "dp104") or a coincidence:
// files whose pre-extension names were already identical before any
// stripping happened at all (e.g. "topology.jpg" and "topology.png",
// both already "topology" — nothing was stripped for either). Only the
// first case is an intentional grouping signal; split the second case
// back into individually-keyed standalone singles instead of merging
// files that just happen to share a name.
foreach ($groups as $key => $groupFiles) {
    if (count($groupFiles) < 2 || isset($folderGroups[$key])) continue;   // (a folder's photos are its own by their folders: the same file name in two of its subfolders is nothing to split)
    $rawBases = array_map(function ($f) { return pathinfo($f, PATHINFO_FILENAME); }, $groupFiles);
    $counts = array_count_values($rawBases);
    $keep = [];
    foreach ($groupFiles as $i => $f) {
        if ($counts[$rawBases[$i]] > 1) {
            $groups[$f] = [$f];
        } else {
            $keep[] = $f;
        }
    }
    if (count($keep) !== count($groupFiles)) {
        if (empty($keep)) {
            unset($groups[$key]);
        } else {
            $groups[$key] = $keep;
        }
    }
}

foreach ($explicitClaims as $file => $claimed) {
    $inNamedGroup = false;
    foreach ($explicitGroups as $g) {
        if (in_array($file, $g['files'], true)) { $inNamedGroup = true; break; }
    }
    if (!$inNamedGroup) {
        // Keyed by the file's own full filename (with extension) — see
        // group_key()'s docblock for why the extension-stripped base
        // isn't safe to use as a per-file key.
        $groups[$file][] = $file;
    }
}
foreach ($explicitGroups as $slug => $g) {
    $groups[$slug] = $g['files'];
}

// Explicit group slugs, so the renderer knows to box these even with
// just a single photo — an auto-detected single never gets a box, but
// an explicitly named one always does; that's the point of naming it. A
// folder-group gets the same treatment: a photo deliberately organized
// into its own named folder deserves a box (or, in 'overview' mode, a
// cover card) regardless of how many other photos share it. Computed
// here (not just once, further down) because zone membership during
// ordering depends on it too.
$explicitGroupKeys = array_fill_keys(
    array_merge(array_keys($explicitGroups), array_keys($folderGroups)),
    true
);

/**
 * Determines display order within a single zone (either "boxes" or
 * "singles+clusters" — see compute_zone_order() below, which calls this
 * once per zone). Two tiers, in order:
 *
 *  1. Anything with prose in its paragraph — a classic text-mention (an
 *     auto-detected group's name found in the .md), or an explicit
 *     {group:}/{photos:} directive whose paragraph has other text —
 *     sorted earliest-first by where that prose sits in the .md. This
 *     mirrors the narrative: a reader sees a description, then its
 *     photos, in the order they were written about.
 *  2. Anything without prose (a textless directive, or never
 *     mentioned/claimed at all) falls back to natural order
 *     ($naturalRank). A textless multi-file group/cluster is anchored
 *     on whichever file was listed *first* in its {photos:} directive —
 *     never re-sorted — with its other members following immediately
 *     after, in the exact order listed.
 *
 * $keysInZone restricts consideration to keys belonging to this zone;
 * every key in $keysInZone appears exactly once in the result.
 */
/** Whether a notes file actually places any photo: a {photos:} or {group:} directive, or a paragraph that names one. A notes file that is
 *  only a title and some words leaves the photos where the order setting puts them (so the sort button stays). */
function notes_place_photos($mdContents, $groups, $explicitGroups, $positionalClusters) {
    if (!empty($explicitGroups) || !empty($positionalClusters)) return true;
    foreach ($mdContents as $content) {
        $masked = mask_directives($content);
        foreach (array_keys($groups) as $key) {
            if (preg_match(group_mention_pattern($key), $masked)) return true;
        }
    }
    return false;
}

function order_within_zone($keysInZone, $mdContents, $groups, $explicitGroups, $positionalClusters, $naturalRank, $rankOverride = []) {
    $inZone = array_fill_keys($keysInZone, true);
    $handled = [];
    $positioned = []; // ['position' => N, 'keys' => [...]]
    $natural = [];    // ['rank' => N, 'keys' => [...]]

    $offset = 0;
    $mentionPos = [];
    foreach ($mdContents as $content) {
        // Search prose only — a filename sitting inside some *other*
        // paragraph's {photos: a.jpg, b.jpg} list must never count as a
        // mention of that name (masking preserves offsets exactly, so
        // this stays comparable to the raw-content-based positions
        // computed during extraction, further up).
        $maskedContent = mask_directives($content);
        foreach ($keysInZone as $key) {
            if (isset($mentionPos[$key]) || isset($explicitGroups[$key])) continue;
            if (preg_match(group_mention_pattern($key), $maskedContent, $m, PREG_OFFSET_CAPTURE)) {
                $mentionPos[$key] = $offset + $m[0][1];
            }
        }
        $offset += strlen($content) + 1;
    }
    foreach ($mentionPos as $key => $pos) {
        $positioned[] = ['position' => $pos, 'keys' => [$key]];
        $handled[$key] = true;
    }

    foreach ($explicitGroups as $slug => $g) {
        if (!isset($inZone[$slug]) || isset($handled[$slug])) continue;
        if ($g['hasProse']) {
            $positioned[] = ['position' => $g['position'], 'keys' => [$slug]];
        } else {
            $natural[] = ['rank' => $naturalRank[$g['files'][0]] ?? PHP_INT_MAX, 'keys' => [$slug]];
        }
        $handled[$slug] = true;
    }

    foreach ($positionalClusters as $cluster) {
        $keys = [];
        foreach ($cluster['files'] as $f) {
            if (isset($inZone[$f]) && !isset($handled[$f])) $keys[] = $f;
        }
        if (empty($keys)) continue;
        if ($cluster['hasProse']) {
            $positioned[] = ['position' => $cluster['position'], 'keys' => $keys];
        } else {
            $natural[] = ['rank' => $naturalRank[$cluster['files'][0]] ?? PHP_INT_MAX, 'keys' => $keys];
        }
        foreach ($keys as $k) $handled[$k] = true;
    }

    foreach ($keysInZone as $key) {
        if (isset($handled[$key])) continue;
        $natural[] = ['rank' => $rankOverride[$key] ?? ($naturalRank[$groups[$key][0]] ?? PHP_INT_MAX), 'keys' => [$key]];
        $handled[$key] = true;
    }

    usort($positioned, function ($a, $b) { return $a['position'] <=> $b['position']; });
    usort($natural, function ($a, $b) { return $a['rank'] <=> $b['rank']; });

    $order = [];
    foreach ($positioned as $block) {
        foreach ($block['keys'] as $k) $order[] = $k;
    }
    foreach ($natural as $block) {
        foreach ($block['keys'] as $k) $order[] = $k;
    }
    return $order;
}

/**
 * Splits $groups into two zones and orders each independently — see
 * order_within_zone() above. Boxes (2+ files, or an explicitly named
 * group even with just one photo) always render before every single
 * and unboxed {photos:} cluster; a box is a full-width grid item, so
 * putting all of them first guarantees the singles wall that follows
 * always starts on a fresh row, instead of a box interrupting a
 * partially-filled row of cards.
 */
function compute_zone_order($mdContents, $groups, $explicitGroups, $positionalClusters, $explicitGroupKeys, $naturalRank, $rankOverride = [], $folderGroupKeys = []) {
    $boxKeys = [];
    $singleKeys = [];
    $folderKeys = [];   // (Flat: the folders' photos come after the page's own, in one run)
    foreach ($groups as $key => $groupFiles) {
        if (isset($folderGroupKeys[$key]) && folder_style_flat()) { $folderKeys[] = $key; continue; }
        // A folder-group is always in the box zone, even with one photo:
        // its cover card is a folder, not a single photo's card, and an
        // admin-set position has to be able to reorder it against every
        // other folder, not only the ones that happen to hold 2+ photos.
        if (count($groupFiles) >= 2 || isset($explicitGroupKeys[$key]) || isset($folderGroupKeys[$key])) {
            $boxKeys[] = $key;
        } else {
            $singleKeys[] = $key;
        }
    }
    $boxOrder = order_within_zone($boxKeys, $mdContents, $groups, $explicitGroups, $positionalClusters, $naturalRank, $rankOverride);
    $singleOrder = order_within_zone($singleKeys, $mdContents, $groups, $explicitGroups, $positionalClusters, $naturalRank, $rankOverride);
    return array_merge($boxOrder, $singleOrder, $folderKeys ? order_within_zone($folderKeys, $mdContents, $groups, $explicitGroups, $positionalClusters, $naturalRank, $rankOverride) : []);
}

// Reorders $groups per compute_zone_order() (boxes first, singles+
// clusters after; prose-position within each, natural order otherwise),
// then rebuilds the flat photo list to match, so the lightbox's index
// numbering (shared by both the note thumbnails and the gallery cards)
// stays consistent with the new display order.
// Folder-groups order among themselves by order_folder_children(): an
// admin-set position first (see ?admin), then natural name order — or
// folder mtime when PHOTO_SORT_ORDER says so. They take over each
// other's existing natural-order *slots* rather than jumping ahead of
// everything, so how folders interleave with filename groups doesn't
// change; only the folders' order among themselves does. It replaces
// only the natural ranking, so a prose mention in the root's own .md
// still positions a folder first, same precedence as for any group.
$folderSlots = [];
foreach ($folderGroupKeys as $folderKey => $_true) {
    $folderSlots[] = $naturalRank[$groups[$folderKey][0]] ?? PHP_INT_MAX;
}
sort($folderSlots);
$folderSortRank = [];
foreach (order_folder_children($dir, '', array_keys($folderGroupKeys)) as $slot => $folderKey) {
    $folderSortRank[$folderKey] = $folderSlots[$slot];
}
$groupOrder = compute_zone_order($mdContents, $groups, $explicitGroups, $positionalClusters, $explicitGroupKeys, $naturalRank, $folderSortRank, $folderGroupKeys);
$orderedGroups = [];
foreach ($groupOrder as $key) {
    if (isset($groups[$key]) && !isset($orderedGroups[$key])) {
        $orderedGroups[$key] = $groups[$key];
    }
}
$groups = $orderedGroups;

$files = [];
foreach ($groups as $groupFiles) {
    foreach ($groupFiles as $f) {
        $files[] = $f;
    }
}
$files = array_values(array_unique($files));   // (a photo can be on two cards: in its folder and in a collection)

// Reverse lookup used by ?track below: which $groups key currently
// contains a given filename. Needed because an explicit named group's
// key is a slug chosen by the .md author, not something group_key()
// could ever derive from the filename itself.
$fileToGroupKey = [];
foreach ($groups as $key => $groupFiles) {
    foreach ($groupFiles as $gf) {
        $fileToGroupKey[$gf] = $key;
    }
}

// ?admin — checked here, as soon as $groups exists, and before anything
// below it (stats, ?track, the public page) does any work a management
// request has no business triggering. See run_admin_route()'s own
// docblock, further down, for the full auth/CSRF flow.
if (request_route() === 'admin') {
    changes_check($dir, $files, !is_admin_browser());   // (the owner's own pages always look: what changed on disk since the last look is written down, see the Changes tab; anyone else's request at most once a minute)
    run_admin_route($dir, $files, $groups, $folderGroupKeys, $explicitGroups, $explicitGroupKeys, $videoDurations, $galleryNotices);
    exit;
}

// A snapshot of every real file, taken before the hiding filter below
// ever touches $files — gc_image_cache()/gc_items_data() further down
// need the *complete* picture to tell "genuinely deleted" apart from
// "hidden from this particular unrevealed visitor." Using the
// already-filtered $files there would make every hidden item look
// deleted to the garbage collector, which would wipe out its own hide
// flag (and its cached thumbnails) the next time an unrevealed visitor
// just loads the page — the opposite of what hiding is supposed to do.
$allFiles = $files;
changes_check($dir, $allFiles, !is_admin_browser());   // (every page of the gallery looks at what changed on disk: the owner's every time, a visitor's at most once a minute)
// Whether anything in the gallery is private: the lock in the icon strip only appears when there is something to unlock.
$hasPrivateItems = false;
foreach ($allFiles as $privateProbe) {
    if (file_is_hidden($dir, $privateProbe, $itemsData)) { $hasPrivateItems = true; break; }
}

// Private view, for everything from here on (the public page, ?track=,
// ?folder=): a hidden item — or an entirely-hidden folder-group — is
// removed from $groups/$files outright for an unrevealed visitor, not
// merely skipped in a display loop. That's what makes every downstream
// count, the lightbox's own file list, and every allowlist check below
// all naturally agree with what's actually rendered — a count that
// doesn't match what's visible would itself be a leak. (?img=/?video= answer even earlier, before the tree is scanned, with
// their own check; ?photo= runs its own just above — this filter runs
// too late to help them.) If
// every member of a group ends up hidden, the group itself disappears
// here too, rather than rendering an empty "0 photos" box, which would
// be its own tell that something's being withheld.
if (is_admin_browser() || (!is_revealed() && ($linkHere = link_viewer()) !== null && ($linkHere['scope']['type'] ?? 'all') !== 'all')) link_scan_ambiguity($dir, $allFiles);   // (the owner's own look keeps the list current too, so a photo address in a copied folder is refused by the pictures as well)   // a folder copied with its id is shown to nobody
if (!is_admin_browser()) {   // (someone with the private-view password is filtered too, but only of what is Not listed: viewer_may_see_item says so)
    foreach ($groups as $key => $groupFiles) {
        $visibleMembers = array_values(array_filter($groupFiles, function ($f) use ($dir, $itemsData, $photoPass) {
            return $photoPass !== null ? $f === $photoPass : viewer_may_see_item($dir, $f, $itemsData);   // (opened by its own address: that photo, not the gallery's public rest)
        }));
        if (empty($visibleMembers)) {
            unset($groups[$key], $folderGroupKeys[$key], $explicitGroupKeys[$key]);
        } else {
            $groups[$key] = $visibleMembers;
        }
    }
    $visibleSet = [];
    foreach ($groups as $groupFiles) {
        foreach ($groupFiles as $f) {
            $visibleSet[$f] = true;
        }
    }
    $files = array_values(array_filter($files, function ($f) use ($visibleSet) {
        return isset($visibleSet[$f]);
    }));
    // A link's own photos are loose tiles on the front page, not folder cards: each leaves its folder's group and stands alone,
    // after the rest. (A folder the link shares stays a card; ?folder= pages are built from $files and are not affected.)
    if ($photoPass !== null) {   // the photo stands alone: no folder card around it (its name would say where it lives)
        foreach ($folderGroupKeys as $folderKey => $_true) { unset($groups[$folderKey], $folderGroupKeys[$folderKey], $explicitGroupKeys[$folderKey]); }
        $looseKey = group_key(basename($photoPass));
        if (isset($groups[$looseKey])) $looseKey = $photoPass;
        $groups[$looseKey] = [$photoPass];
        $fileToGroupKey[$photoPass] = $looseKey;
    } elseif (($pickLink = link_viewer()) !== null && !is_revealed()) {
        $pickedOut = [];
        foreach ($folderGroupKeys as $folderKey => $_true) {
            if (!isset($groups[$folderKey])) continue;
            $stay = [];
            foreach ($groups[$folderKey] as $f) {
                if (link_item_is_picked_photo($pickLink, $dir, $f)) $pickedOut[] = $f; else $stay[] = $f;
            }
            if ($stay) { $groups[$folderKey] = $stay; continue; }
            unset($groups[$folderKey], $folderGroupKeys[$folderKey], $explicitGroupKeys[$folderKey]);
        }
        foreach ($pickedOut as $f) {
            $looseKey = group_key(basename($f));
            if (isset($groups[$looseKey])) $looseKey = $f;
            $groups[$looseKey] = [$f];
            $fileToGroupKey[$f] = $looseKey;
        }
    }
}

/* -----------------------------------------------------------------------
 * Small generic JSON file storage, flock-protected the same way the
 * stats JSON fallback below is — reused by two otherwise-unrelated
 * concerns (the admin tool's .gallery-items.php, and the login-attempt
 * throttle's .gallery-login-attempts.php) so the locking mechanics
 * aren't duplicated a third time. Deliberately generic over the data
 * shape, unlike stats_update_file below, since callers here have
 * genuinely different shapes rather than variations on the same one.
 * ----------------------------------------------------------------------- */

/** Reads a JSON file, merging it over $defaultData (missing file or
 *  corrupt content just yields $defaultData untouched). */
/**
 * The first line of every generated data file (.gallery-items.php,
 * .gallery-stats.php, .gallery-login-attempts.php). These hold captions,
 * GPS coordinates, hide flags — and with them the exact filenames of
 * hidden items — and a web server serves any file in the folder to
 * anyone who asks for its URL. Stored as a .php file starting with this
 * line, a direct request is handed to PHP instead, which hits the exit
 * on the first line and answers 404 with nothing else: the JSON below
 * is never sent, on any host that runs PHP, with no server rule needed.
 * (A server rule that blocks ".gallery-*" is still worth adding as a
 * second layer — see the README.) This script itself never *executes*
 * these files; it reads them as plain text and drops this line.
 */
function data_file_guard_line() {
    return "<?php http_response_code(404); exit; ?>\n";
}

/** The JSON text of a guarded data file: raw contents with the guard
 *  line removed. Tolerates a file with no guard (plain JSON). */
function data_file_strip_guard($raw) {
    $raw = (string) $raw;
    if (strncmp($raw, '<?php', 5) === 0) {
        $newline = strpos($raw, "\n");
        return $newline === false ? '' : substr($raw, $newline + 1);
    }
    return $raw;
}

/** JSON for a guarded data file. JSON_HEX_TAG writes "<" and ">" as
 *  \u003C/\u003E, so a caption that happens to contain "<?php" can never
 *  put a PHP open tag into the file — nothing after the guard line is
 *  ever parsed as code, even by a server with short tags on. */
function data_file_encode($data) {
    return data_file_guard_line() . json_encode($data, JSON_HEX_TAG);
}

/** Reads a JSON data file and says how it went: ['missing', $defaultData] when there is no file, ['ok', data merged over the
 *  defaults], or ['broken', $defaultData] when the file is there but can't be read or what is in it isn't JSON (cut short by a full
 *  disk, a half-finished copy, a typo in a hand edit). A file that can't be read is not the same as a file with nothing in it: the
 *  callers that guard something decide what that means (see items_read, json_file_update). */
function json_file_load($path, $defaultData) {
    if (!file_exists($path)) return ['missing', $defaultData];
    $raw = @file_get_contents($path);
    $decoded = $raw === false ? null : json_decode(data_file_strip_guard($raw), true);
    if (!is_array($decoded)) return ['broken', $defaultData];
    return ['ok', array_merge($defaultData, $decoded)];
}

/** Reads a JSON file, merging it over $defaultData (a missing or broken file yields $defaultData untouched). */
function json_file_read($path, $defaultData) {
    return json_file_load($path, $defaultData)[1];
}

/** Changes a JSON data file under a lock and returns the new data. The new content is written to a temporary file next to it and
 *  renamed over it, so a reader (which takes no lock) sees the whole old file or the whole new one, never a half-written or empty
 *  one. With $protect (the owner's own data: the folder settings and the share links), a file that exists but can't be read is left
 *  exactly as it is and nothing is saved ($GLOBALS['__data_refused'] names it): writing over it would replace something the owner may
 *  still be able to restore with an almost empty file. The other files (sign-in throttle, logs) are rebuilt instead. */
function json_file_update($path, $defaultData, $modifier, $protect = false) {
    $data = $defaultData;
    $existed = file_exists($path);
    // A writer that waited on the lock may be holding a file that was replaced (renamed over) in the meantime; it must start again
    // on the current one, or it would save its change on top of a version that no longer exists.
    for ($try = 0, $fp = false; $try < 5; $try++) {
        $fp = @fopen($path, 'c+');
        if (!$fp || !flock($fp, LOCK_EX)) break;
        clearstatcache(true, $path);
        $here = @stat($path); $mine = fstat($fp);
        if ($here && $mine && $here['ino'] === $mine['ino'] && $here['dev'] === $mine['dev']) break;
        fclose($fp); $fp = false;
    }
    if (!$fp) {
        // Usually the folder isn't writable by the web server. Remember it
        // so the admin can say so instead of reporting a save that never
        // happened (see run_admin_route).
        $GLOBALS['__data_write_failed'] = true;
        return $data;
    }
    $raw = stream_get_contents($fp);
    $decoded = json_decode(data_file_strip_guard($raw), true);
    if (is_array($decoded)) $data = array_merge($data, $decoded);
    if ($protect && !is_array($decoded) && $existed) {
        $GLOBALS['__data_write_failed'] = true;
        $GLOBALS['__data_refused'][$path] = true;
    } else {
        $modifier($data);
        if (!json_file_replace($path, data_file_encode($data), $fp)) $GLOBALS['__data_write_failed'] = true;   // disk full, quota, ...
    }
    flock($fp, LOCK_UN);
    fclose($fp);
    return $data;
}

/** Puts $encoded in $path as a whole: written to a temporary file in the same folder, then renamed over the original (atomic on
 *  the same filesystem). If a temporary file can't be made (a folder that allows changing the file but not adding to it) it writes
 *  into the open handle $fp instead, as before. */
function json_file_replace($path, $encoded, $fp) {
    $tmp = $path . '.' . bin2hex(random_bytes(4)) . '.php';   // (ends in .php and starts with the guard line, so a leftover is answered with a 404 like the real file)
    $ok = false;
    if (!is_link($path) && @file_put_contents($tmp, $encoded) === strlen($encoded)) {   // (a symlinked data file is written through, so the link stays a link)
        @chmod($tmp, (@fileperms($path) ?: 0644) & 0777);
        $ok = @rename($tmp, $path);
    }
    if ($ok) return true;
    @unlink($tmp);
    ftruncate($fp, 0);
    rewind($fp);
    $wrote = fwrite($fp, $encoded) === strlen($encoded);
    fflush($fp);
    return $wrote;
}

/** How a failed save names a folder: "this folder", or, for a place from elsewhere on the server, its real path (the owner may not know where
 *  that is, and it is the folder that has to be made writable). */
function data_write_failure_place($dir, $folderReal) {
    $own = rtrim((string) (realpath($dir) ?: $dir), '/') . '/';
    $real = rtrim((string) (realpath((string) $folderReal) ?: $folderReal), '/');
    return ($real !== '' && strpos($real . '/', $own) !== 0) ? 'the folder ' . $real : 'this folder';
}

/** What to tell the owner when a save did not happen: the data file that could not be read (nothing was changed), or the folder not
 *  being writable. $folder is how the sentence says where ("this folder"). */
function data_write_failure_text($folder = 'this folder') {
    if (!empty($GLOBALS['__data_refused'])) {
        return 'Nothing was saved: a settings file in ' . $folder . ' can\'t be read (it may have been cut short or edited by hand), so it was left exactly as it is. Restore .gallery-items.php there from a backup, or delete it to start that folder fresh. Until then its photos stay hidden from visitors. The Health check in Settings names it.';
    }
    return 'Nothing was saved: ' . $folder . ' isn\'t writable by the web server. Give the web server\'s user write permission on it (on many hosts: chmod 755 or 775 on the folder, owned by that user), then try again.';
}

/* -----------------------------------------------------------------------
 * Admin auth: HTTP Basic Auth (checked with hash_equals — no timing
 * leak), an HTTPS requirement, a session-carried CSRF token for the
 * actual save actions, and a failed-attempt throttle shared with any
 * future second password this script grows (see ADMIN_PASSWORD's own
 * doc comment above; PRIVATE_VIEW_PASSWORD, when it exists, reuses this
 * unchanged).
 * ----------------------------------------------------------------------- */

/** True for a request this script considers already-local — the one
 *  exception to the HTTPS requirement below, so ?admin is still testable
 *  on a bare `php -S localhost:8000` during development. */
function is_local_request() {
    // Deliberately keyed off REMOTE_ADDR alone — the actual TCP peer
    // address, which a client can't forge in an ordinary request —
    // rather than also trusting the Host header. A request's Host header
    // is attacker-controlled: on a real public deployment, anyone could
    // send "Host: localhost" and bypass the HTTPS requirement entirely
    // if that were accepted here on its own.
    return in_array($_SERVER['REMOTE_ADDR'] ?? '', ['127.0.0.1', '::1'], true);
}

/** True if this request arrived over HTTPS — checks the same three
 *  signals current_base_url() already does (a direct TLS connection, a
 *  trusted reverse-proxy header, or port 443), so a site behind a
 *  load balancer or CDN that terminates TLS upstream is still correctly
 *  recognized as HTTPS. */
function is_https_request() {
    return (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
        || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https')
        || (($_SERVER['SERVER_PORT'] ?? '') == 443);
}

/**
 * Lightweight failed-login throttle, tracking failures per client IP in
 * a small flock-protected file at the gallery root — same mechanism the
 * view-stats JSON fallback already uses, nothing new conceptually,
 * shared across every password prompt this script has rather than one
 * per feature. 5 failures from one IP within 15 minutes forces a flat
 * 60-second lockout on that IP's *next* attempt — rejected outright,
 * without even checking the password it carries, matching "the next
 * attempt is not even evaluated." A flat delay, not a permanent
 * lockout: a legitimate visitor who fat-fingers a password a few times
 * just waits a minute, not calls the site owner.
 */
function login_throttle_path($rootDir) {
    return $rootDir . '/.gallery-login-attempts.php';
}

function login_throttle_key($realm, $ip) {
    // An IPv6 customer is given a whole /64 (billions of addresses) and can change address at will, so the /64 is the unit, not the address.
    $bin = ip_binary($ip);
    if ($bin !== null && strlen($bin) === 16) $ip = bin2hex(substr($bin, 0, 8)) . '/64';
    return $realm . '|' . $ip;
}

/** True if this IP is currently clear to even have its password
 *  checked for the given realm (e.g. 'admin'). */
function login_throttle_allows($rootDir, $realm, $ip) {
    $data = json_file_read(login_throttle_path($rootDir), []);
    $entry = $data[login_throttle_key($realm, $ip)] ?? null;
    if ($entry === null) return true;
    return time() >= ($entry['lockUntil'] ?? 0);
}

/** Seconds left on this realm's lockout for this address (0 when there is none). The lockout pages count these down. */
function login_throttle_wait($rootDir, $realm, $ip) {
    $data = json_file_read(login_throttle_path($rootDir), []);
    $entry = $data[login_throttle_key($realm, $ip)] ?? null;
    return $entry === null ? 0 : max(0, (int) ($entry['lockUntil'] ?? 0) - time());
}

/** Records one failed attempt; imposes a 60-second lockout once $limit (5 for a password, more for a guessed address) have
 *  landed from the same IP within the last 15 minutes. */
function login_throttle_record_failure($rootDir, $realm, $ip, $limit = 5) {
    $key = login_throttle_key($realm, $ip);
    $tripped = false;
    json_file_update(login_throttle_path($rootDir), [], function (&$data) use ($key, $limit, &$tripped) {
        $now = time();
        $entry = $data[$key] ?? ['attempts' => [], 'lockUntil' => 0];
        $entry['attempts'] = array_values(array_filter($entry['attempts'], function ($t) use ($now) {
            return $t > $now - 900; // keep only the last 15 minutes
        }));
        $entry['attempts'][] = $now;
        if (count($entry['attempts']) >= $limit) {
            $entry['lockUntil'] = $now + 60;
            $entry['attempts'] = [];
            $tripped = true;
        }
        $data[$key] = $entry;
        // The file is read on every sign-in and share-link visit, so it must not grow: forget whoever has no lockout running and no
        // recent failure, and keep at most the 2,000 most recent of the rest.
        foreach ($data as $k => $e) {
            $last = max((int) ($e['lockUntil'] ?? 0), (int) max(array_merge([0], (array) ($e['attempts'] ?? []))));
            if ($k !== $key && $last < $now - 900) unset($data[$k]);
        }
        if (count($data) > 2000) {
            uasort($data, function ($a, $b) { return max((int) ($b['lockUntil'] ?? 0), (int) max(array_merge([0], (array) ($b['attempts'] ?? [])))) <=> max((int) ($a['lockUntil'] ?? 0), (int) max(array_merge([0], (array) ($a['attempts'] ?? [])))); });
            $data = array_slice($data, 0, 2000, true);
        }
    });
    if ($tripped) lockout_noted($realm, $ip);   // (a lockout has just begun: it is written down, see lockout_noted)
}

/** Clears a realm/IP's failure history after a successful login. */
function login_throttle_record_success($rootDir, $realm, $ip) {
    $key = login_throttle_key($realm, $ip);
    json_file_update(login_throttle_path($rootDir), [], function (&$data) use ($key) {
        unset($data[$key]);
    });
}

/** Headers for every admin / private-view response: it can't be put in
 *  someone else's frame (clickjacking a "Hide folder" button), must never
 *  be cached (it lists everything, hidden items included), and its forms
 *  may only post back to this site. */
function send_sensitive_page_headers() {
    header('Cache-Control: no-store');
    header('X-Frame-Options: DENY');
    header("Content-Security-Policy: frame-ancestors 'none'; base-uri 'none'; form-action 'self'; object-src 'none'");
}
/** For pages whose content differs by who is asking (the public gallery,
 *  the map, ?track): tell caches so, and never let one keep a copy made
 *  for a trusted viewer — it would list hidden items to the next
 *  anonymous request for the same URL. */
function send_viewer_aware_cache_headers() {
    header('Vary: Cookie');
    if (is_revealed() || link_viewer() !== null) {
        header('Cache-Control: private, no-store');
    }
}
function admin_session_name() {
    return 'gallery_admin_' . substr(hash('sha256', __DIR__), 0, 10);
}

/** What a logged-in admin session carries. Derived from the password and
 *  this install's folder, so changing ADMIN_PASSWORD logs every existing
 *  session out, and a session from another gallery means nothing here. */
function admin_session_marker($stored = null) {
    return hash('sha256', 'admin|' . ($stored ?? ADMIN_PASSWORD) . '|' . __DIR__);
}

/* -----------------------------------------------------------------------
 * What each signed-in browser has done. Next to its token (see "Browsers that are signed in") every browser keeps a history: one
 * line, appended to its own guarded file (.gallery-signin-<id>.php), each time it turns up from a different address or as a different
 * device, with the time, the full address, the country when it is known and what the browser said it was. A line is added the moment
 * the address changes, whether it is new or one the browser has used before; coming back from the same address as the last request
 * only refreshes "last seen", at most once an hour. Nothing limits how much is kept inside BROWSER_HISTORY_DAYS: the owner can see how
 * big each history has grown (the list, the Health check and a daily size note) and decides.
 *
 * Four things raise a flag on a browser, each answerable with "Looks fine" and each with its own switch to sign the browser out
 * at once (BROWSER_END_ON_*): the device it was made on is now a different one of the same kind (warning), a different kind of device,
 * a country it has not been used from, and more than BROWSER_NETWORKS_ALARM networks in 24 hours (all action needed). A new address on
 * its own is shown, not flagged. A browser that is signed out (by the owner, a log out, an expiry, a password change or a switch above)
 * stays listed for BROWSER_ENDED_DAYS with its history, which is what is wanted when something looked wrong.
 *
 * A "network" is an IPv4 /24 (a block of 256 addresses: one carrier pool, one office) or an IPv6 /64 (one home, one phone connection).
 * ----------------------------------------------------------------------- */

function signin_log_path() {
    return __DIR__ . '/.gallery-browsers-log.php';
}
function signin_log_default() {
    return ['ended' => [], 'sizes' => []];
}
function signin_log_read() {
    return json_file_read(signin_log_path(), signin_log_default());
}
function signin_log_update($fn) {
    return json_file_update(signin_log_path(), signin_log_default(), $fn);
}
function signin_history_path($id) {
    return __DIR__ . '/.gallery-signin-' . $id . '.php';
}

/** The network an address belongs to, as text: "203.0.113" for IPv4 (its /24), "2001:0db8:85a3:0000" for IPv6 (its /64). */
function signin_net_key($ip) {
    $bin = ip_binary($ip);
    if ($bin === null) return (string) $ip;
    if (strlen($bin) === 4) return ord($bin[0]) . '.' . ord($bin[1]) . '.' . ord($bin[2]);
    return implode(':', str_split(bin2hex(substr($bin, 0, 8)), 4));
}

/** The kind of device a label ("iPhone · Safari") is: apple (iPhone, iPad, Mac), android, windows, linux, or other (not known). */
/** True for the identities Apple's own networking sends on a phone's behalf (NetworkingExtension, CFNetwork, Darwin): the same device, not a new one. */
function signin_is_system_ua($ua) {
    return (bool) preg_match('~NetworkingExtension|CFNetwork|Darwin/~', (string) $ua);
}

/** The device a browser really is, as far as its last ordinary request said: its record's 'real', else its last label unless that was
 *  a system identity (then the one it was made on). */
function signin_real_label(array $r) {
    $real = (string) ($r['real'] ?? '');
    if ($real !== '') return $real;
    $lab0 = (string) ($r['lab0'] ?? $r['label'] ?? '');
    $lab = (string) ($r['lab'] ?? $lab0);
    return $lab === 'A device · a browser' ? $lab0 : $lab;
}

function signin_family($label) {
    $dev = explode(' · ', (string) $label)[0];
    if (in_array($dev, ['iPhone', 'iPad', 'Mac'], true)) return 'apple';
    $map = ['Android' => 'android', 'Windows' => 'windows', 'Linux' => 'linux'];
    return $map[$dev] ?? 'other';
}

/** Adds one line to a browser's history file ($id: the start of its token's hash). The first line of a new file is the guard line. */
function signin_history_append($id, array $line) {
    $fp = @fopen(signin_history_path($id), 'a');
    if (!$fp) return false;
    flock($fp, LOCK_EX);
    $st = fstat($fp);
    fwrite($fp, (($st && (int) $st['size'] === 0) ? data_file_guard_line() : '') . json_encode($line, JSON_HEX_TAG | JSON_HEX_AMP | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . "\n");
    flock($fp, LOCK_UN);
    fclose($fp);
    return true;
}

/** Every line of a browser's history, oldest first: [['t' => time, 'ip' => address, 'cc' => country or '', 'ua' => what it said, 'e' => 'signin'|'change']]. */
function signin_history_read($id) {
    $raw = @file_get_contents(signin_history_path($id));
    $out = [];
    if (!is_string($raw)) return $out;
    foreach (explode("\n", $raw) as $l) {
        if ($l === '' || $l[0] !== '{') continue;
        $j = json_decode($l, true);
        if (is_array($j) && isset($j['t'], $j['ip'])) $out[] = $j;
    }
    return $out;
}

/** What a history file holds, counted: ['lines', 'ips' (different addresses), 'dev' (times the identity changed from one line to the next),
 *  'sys' (how many of those changes were to or from Apple's system networking, which is never flagged)]. */
function signin_history_stats($id, $lines = null) {
    $lines = $lines ?? signin_history_read($id);
    $ips = []; $dev = 0; $sys = 0; $prev = null; $prevSys = false;
    foreach ($lines as $l) {
        $ips[(string) $l['ip']] = true;
        $ua = (string) ($l['ua'] ?? ''); $lab = browser_label($ua); $isSys = signin_is_system_ua($ua);
        if ($prev !== null && $lab !== $prev) { $dev++; if ($isSys || $prevSys) $sys++; }
        $prev = $lab; $prevSys = $isSys;
    }
    return ['lines' => count($lines), 'ips' => count($ips), 'dev' => $dev, 'sys' => $sys];
}

/** "1 address · 0 device changes · 3 lines", the line that heads a history. */
function signin_stats_text(array $st) {
    return number_format($st['ips']) . ' address' . ($st['ips'] === 1 ? '' : 'es') . ' · ' . number_format($st['dev']) . ' device change' . ($st['dev'] === 1 ? '' : 's')
        . ($st['sys'] > 0 ? ' (' . ($st['sys'] === $st['dev'] ? ($st['dev'] === 1 ? 'it was' : 'all') : $st['sys'] . ' of them') . ' Apple system networking, not flagged)' : '') . ' · ' . number_format($st['lines']) . ' line' . ($st['lines'] === 1 ? '' : 's');
}

/** Why a browser's sign-in ended, in words. */
function signin_reason_text($reason) {
    $map = ['you' => 'Signed out by you', 'logout' => 'Logged out', 'expired' => 'Expired', 'password' => 'Password changed', 'auto' => 'Signed out automatically', 'again' => 'Signed in again'];
    return $map[$reason] ?? 'Ended';
}

/** What each flag is called, and how loud: 'bad' (action needed) or 'warn'. */
function signin_flag_info($name) {
    $map = [
        'device' => ['A different device of the same kind', 'warn'],
        'family' => ['A different kind of device', 'bad'],
        'country' => ['A new country', 'bad'],
        'networks' => ['Many networks in 24 hours', 'bad'],
    ];
    return $map[$name] ?? [$name, 'warn'];
}

/** Notes a browser that has gone out of the list (signed out, expired...) in the ended list; its history stays on disk meanwhile. */
function signin_ended_add($id, array $rec, $reason, $detail = '', $at = null) {
    if (($rec['via'] ?? '') === 'script') return;
    $at = $at ?? time();
    signin_log_update(function (&$d) use ($id, $rec, $reason, $detail, $at) {
        $d['ended'][] = ['id' => $id, 'kind' => (string) ($rec['kind'] ?? ''), 'label' => (string) ($rec['label'] ?? ''), 'made' => (int) ($rec['made'] ?? 0), 'ended' => $at, 'reason' => $reason, 'detail' => (string) $detail,
            'n' => (int) ($rec['n'] ?? 0), 'peak' => (int) ($rec['peak'] ?? 0), 'flags' => array_keys((array) ($rec['flags'] ?? []))];
    });
}

/**
 * This request's browser has come from a different address, or as a different device, than its last request. Writes the line, updates
 * its record, and raises the flags that apply; if one of them has its sign-out switch on, ends the browser and returns false.
 */
function browser_note_event($h, $ip, $label) {
    $now = time(); $id = substr($h, 0, 12); $cc = geo_country($ip); $net = signin_net_key($ip);
    $ua = substr((string) ($_SERVER['HTTP_USER_AGENT'] ?? ''), 0, 300);
    $sys = signin_is_system_ua($ua);
    $raised = []; $detailOf = []; $ended = null;
    json_file_update(browsers_path(), [], function (&$d) use ($h, $now, $ip, $label, $cc, $net, $sys, &$raised, &$detailOf, &$ended) {
        if (!isset($d[$h]) || !is_array($d[$h])) return;
        $r =& $d[$h];
        $days = browser_days($r['kind']);
        $r['exp'] = $now + ($days >= 1 ? $days * 86400 : 86400);
        $lab0 = (string) ($r['lab0'] ?? $r['label'] ?? '');
        $prevReal = signin_real_label($r);
        $r['seen'] = $now; $r['ip'] = $ip; $r['lab'] = $label; $r['n'] = (int) ($r['n'] ?? 0) + 1;
        if (!$sys) $r['real'] = $label;
        $nets = [];
        foreach ((array) ($r['nets'] ?? []) as $k => $t) if ((int) $t > $now - 86400) $nets[(string) $k] = (int) $t;
        $nets[$net] = $now;
        if (count($nets) > 500) { arsort($nets); $nets = array_slice($nets, 0, 500, true); }   // (what is tracked for the 24-hour count, not the history: that is in the file)
        $r['nets'] = $nets;
        $count = count($nets);
        if ($count > (int) ($r['peak'] ?? 0)) { $r['peak'] = $count; $r['peakAt'] = $now; }
        $flag = function ($name, $detail, $v = 0) use (&$r, $now, &$raised, &$detailOf) {
            $f = $r['flags'][$name] ?? null;
            $again = $f === null || ((int) ($f['a'] ?? 0) > 0 && ($name !== 'networks' || $v > (int) ($f['v'] ?? 0)));
            if ($again) { $r['flags'][$name] = ['t' => $now, 'd' => $detail, 'a' => 0, 'v' => $v]; $raised[] = $name; $detailOf[$name] = $detail; }
            else { $r['flags'][$name]['d'] = $detail; $r['flags'][$name]['v'] = $v; }
        };
        if (!$sys && $label !== $prevReal && $label !== $lab0) {   // (a system identity is logged and counted but never flagged)
            $f0 = signin_family($lab0); $f1 = signin_family($label);
            if ($f0 !== 'other' && $f1 !== 'other' && $f0 !== $f1) $flag('family', 'Made on ' . $lab0 . ', now used as ' . $label);
            else $flag('device', 'Made on ' . $lab0 . ', now used as ' . $label);
        }
        $ccs = array_values((array) ($r['ccs'] ?? []));
        if ($cc !== '') {
            if ($ccs && !in_array($cc, $ccs, true)) $flag('country', 'Used from ' . implode(', ', $ccs) . ' before, now from ' . $cc);
            if (!in_array($cc, $ccs, true)) $ccs[] = $cc;
            $r['ccs'] = $ccs;
        }
        if ($count > BROWSER_NETWORKS_ALARM) $flag('networks', $count . ' networks in the last 24 hours (the limit is ' . BROWSER_NETWORKS_ALARM . ')', $count);
        $switch = ['device' => BROWSER_END_ON_DEVICE, 'family' => BROWSER_END_ON_FAMILY, 'country' => BROWSER_END_ON_COUNTRY, 'networks' => BROWSER_END_ON_NETWORKS];
        foreach ($raised as $name) {
            if (!empty($switch[$name])) { $ended = [$r, $detailOf[$name]]; break; }
        }
        unset($r);
        if ($ended !== null) unset($d[$h]);
    });
    signin_history_append($id, ['t' => $now, 'ip' => $ip, 'cc' => $cc, 'ua' => $ua, 'e' => 'change']);
    if ($ended !== null) {
        signin_ended_add($id, $ended[0], 'auto', $ended[1]);
        gallery_cookie_expire(REVEAL_COOKIE_NAME, 'Lax');
        return false;
    }
    return true;
}

/** "Looks fine": a flag is cleared until something new raises it again. */
function browser_ack($id, $name) {
    $n = 0;
    json_file_update(browsers_path(), [], function (&$d) use ($id, $name, &$n) {
        foreach ($d as $h => &$r) {
            if (!is_array($r) || strncmp((string) $h, $id, 12) !== 0 || !isset($r['flags'][$name])) continue;
            $r['flags'][$name]['a'] = time(); $n++;
        }
        unset($r);
    });
    return $n;
}

/** The flags of a record that are showing (not answered with "Looks fine"): name => [detail, time, 'bad'|'warn']. */
function browser_flags_of(array $rec) {
    $out = [];
    foreach ((array) ($rec['flags'] ?? []) as $name => $f) {
        if (!is_array($f) || (int) ($f['a'] ?? 0) > 0) continue;
        $out[$name] = [(string) ($f['d'] ?? ''), (int) ($f['t'] ?? 0), signin_flag_info($name)[1]];
    }
    return $out;
}

/**
 * The tidying that keeps the files in order: browsers whose end has come (expired, or made under a password that has changed) move to the
 * ended list; ended entries and their histories go after BROWSER_ENDED_DAYS; a live history loses lines older than BROWSER_HISTORY_DAYS
 * (once a day each); a history file nothing refers to goes after the same time; and today's size is noted (kept 90 days). Once per request.
 */
function browser_housekeeping() {
    static $done = false;
    if ($done) return;
    $done = true;
    $now = time(); $moved = [];
    if (is_file(browsers_path())) {
        json_file_update(browsers_path(), [], function (&$d) use ($now, &$moved) {
            foreach ($d as $k => $r) {
                if (!is_array($r)) { unset($d[$k]); continue; }
                $kind = (string) ($r['kind'] ?? '');
                $m = in_array($kind, ['owner', 'view'], true) ? browser_marker($kind) : '';
                $expired = (int) ($r['exp'] ?? 0) <= $now;
                if ($expired || $m === '' || !hash_equals($m, (string) ($r['pw'] ?? ''))) {
                    $moved[] = [(string) $k, $r, $expired ? 'expired' : 'password', $expired ? (int) $r['exp'] : $now];
                    unset($d[$k]);
                }
            }
        });
    }
    foreach ($moved as [$k, $r, $why, $at]) signin_ended_add(substr($k, 0, 12), $r, $why, '', $at);
    $live = [];
    foreach (json_file_read(browsers_path(), []) as $k => $r) if (is_array($r)) $live[substr((string) $k, 0, 12)] = (int) ($r['trim'] ?? 0);
    $keepEnded = []; $dropFiles = [];
    signin_log_update(function (&$d) use ($now, &$keepEnded, &$dropFiles) {
        $cut = $now - BROWSER_ENDED_DAYS * 86400;
        $kept = [];
        foreach ((array) ($d['ended'] ?? []) as $e) {
            if (is_array($e) && (int) ($e['ended'] ?? 0) > $cut) { $kept[] = $e; $keepEnded[(string) $e['id']] = true; }
            elseif (is_array($e)) $dropFiles[] = (string) $e['id'];
        }
        $d['ended'] = $kept;
        $sizes = (array) ($d['sizes'] ?? []);
        $bytes = 0; $files = 0;
        foreach ((array) @glob(__DIR__ . '/.gallery-signin-*.php') as $f) { $bytes += (int) @filesize($f); $files++; }
        $sizes[date('Y-m-d', $now)] = [$bytes, $files];
        krsort($sizes);
        $d['sizes'] = array_slice($sizes, 0, 90, true);
    });
    foreach ($dropFiles as $id) if (preg_match('/^[0-9a-f]{12}$/', $id) && !isset($live[$id])) @unlink(signin_history_path($id));
    foreach ((array) @glob(__DIR__ . '/.gallery-signin-*.php') as $f) {   // a history nothing refers to (a record that was pushed out of the sixty)
        if (!preg_match('/\.gallery-signin-([0-9a-f]{12})\.php$/', $f, $m) || isset($live[$m[1]]) || isset($keepEnded[$m[1]])) continue;
        if ($now - (int) @filemtime($f) > max(1, BROWSER_ENDED_DAYS) * 86400) @unlink($f);
    }
    $trimmed = [];
    foreach ($live as $id => $at) {
        if ($now - $at < 86400) continue;
        $lines = signin_history_read($id);
        $cut = $now - BROWSER_HISTORY_DAYS * 86400;
        $keep = array_values(array_filter($lines, fn ($l) => (int) $l['t'] > $cut));
        if (count($keep) !== count($lines)) {
            $body = data_file_guard_line();
            foreach ($keep as $l) $body .= json_encode($l, JSON_HEX_TAG | JSON_HEX_AMP | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . "\n";
            @file_put_contents(signin_history_path($id), $body, LOCK_EX);
        }
        $trimmed[$id] = $now;
    }
    if ($trimmed) json_file_update(browsers_path(), [], function (&$d) use ($trimmed) { foreach ($d as $k => &$r) if (is_array($r) && isset($trimmed[substr((string) $k, 0, 12)])) $r['trim'] = $trimmed[substr((string) $k, 0, 12)]; unset($r); });
}

/** The ended browsers for the list, newest first. */
function browser_ended_rows() {
    $rows = array_values(array_filter((array) (signin_log_read()['ended'] ?? []), 'is_array'));
    usort($rows, fn ($a, $b) => (int) $b['ended'] <=> (int) $a['ended']);
    return $rows;
}

/** One browser's history file size in bytes. */
function signin_history_size($id) {
    return (int) @filesize(signin_history_path($id));
}

/** "96 KB", "1.2 MB". */
function signin_size_text($bytes) {
    $bytes = (int) $bytes;
    if ($bytes < 1024) return $bytes . ' B';
    if ($bytes < 1048576) return number_format($bytes / 1024, $bytes < 10240 ? 1 : 0) . ' KB';
    return number_format($bytes / 1048576, 1) . ' MB';
}

/* -----------------------------------------------------------------------
 * The country of an address. A proxy in front (Cloudflare and a few others) can say which country a visitor is in; almost nobody has one.
 * So there is an option that works anywhere: a small file of address ranges per country, kept in a guarded .gallery- file beside this one
 * and read by a short reader below (the MaxMind DB format, which DB-IP publishes free as "IP to Country Lite", CC BY 4.0, a new one on the
 * first of each month: https://db-ip.com/db/download/ip-to-country-lite). Nothing about a visitor ever leaves the server: the only outside
 * request is the download of that public file, made when the owner turns the option on and then about once a month (it checks every 7
 * days whether there is a newer one) from an ordinary page load, after the visitor has been answered where PHP allows, never making
 * a visitor wait. It is off until the owner switches it on in Settings, which first says how much room it needs.
 * ----------------------------------------------------------------------- */

function geo_db_path() {
    return __DIR__ . '/.gallery-geo.php';
}
function geo_state_path() {
    return __DIR__ . '/.gallery-geo-state.php';
}

/** The state of the file we hold: ['ym' => '2026-11', 'modified' => the Last-Modified it came with, 'length' => bytes it came as, 'at' => when we got it,
 *  'error' => why the last try failed or '', 'triedAt' => when the last try was, 'raw' => bytes unpacked]. */
function geo_state() {
    return json_file_read(geo_state_path(), ['ym' => '', 'modified' => '', 'length' => 0, 'at' => 0, 'error' => '', 'triedAt' => 0, 'raw' => 0]);
}

/** An address a download may come from: https anywhere, or plain http only to this very machine (for tests). */
function geo_url_ok($url) {
    $p = parse_url((string) $url);
    if (!is_array($p) || empty($p['host']) || isset($p['user']) || isset($p['pass'])) return false;
    if (($p['scheme'] ?? '') === 'https') return true;
    return ($p['scheme'] ?? '') === 'http' && in_array(strtolower($p['host']), ['127.0.0.1', 'localhost', '[::1]'], true);
}

/** The address of a month's file: the setting COUNTRY_DB_URL with {ym} replaced by the month ("2026-11"), or DB-IP's own. */
function geo_url_for($ym) {
    $base = COUNTRY_DB_URL !== '' ? COUNTRY_DB_URL : 'https://download.db-ip.com/free/dbip-country-lite-{ym}.mmdb.gz';
    return str_replace('{ym}', $ym, $base);
}

/** The months to try, newest first: this one (the file appears on the 1st), then last month's. */
function geo_months() {
    return [gmdate('Y-m'), gmdate('Y-m', strtotime('first day of last month 00:00:00 UTC'))];
}

/** One request, with curl if this PHP has it, else PHP's own streams. Returns ['status' => int (0: no answer), 'headers' => [lowercase name => value], 'body' => string, 'error' => text]. */
function geo_http($url, $method = 'GET', array $headers = [], $maxBytes = 30000000, $timeout = 40) {
    $out = ['status' => 0, 'headers' => [], 'body' => '', 'error' => ''];
    if (!geo_url_ok($url)) { $out['error'] = 'That address is not allowed (it must be https).'; return $out; }
    if (function_exists('curl_init')) {
        $ch = curl_init($url); $hd = [];
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 3, CURLOPT_TIMEOUT => $timeout, CURLOPT_CONNECTTIMEOUT => 8, CURLOPT_NOBODY => $method === 'HEAD',
            CURLOPT_HTTPHEADER => $headers, CURLOPT_USERAGENT => 'Drop-in Photo Gallery ' . GALLERY_VERSION, CURLOPT_PROTOCOLS => CURLPROTO_HTTP | CURLPROTO_HTTPS, CURLOPT_REDIR_PROTOCOLS => CURLPROTO_HTTPS | CURLPROTO_HTTP,
            CURLOPT_HEADERFUNCTION => function ($c, $l) use (&$hd) { if (strpos($l, ':') !== false) { [$k, $v] = explode(':', $l, 2); $hd[strtolower(trim($k))] = trim($v); } return strlen($l); },
            CURLOPT_WRITEFUNCTION => function ($c, $d) use (&$out, $maxBytes) { $out['body'] .= $d; return strlen($out['body']) > $maxBytes ? 0 : strlen($d); }]);
        curl_exec($ch);
        $out['status'] = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE); $out['headers'] = $hd;
        if (curl_errno($ch) !== 0 && $out['status'] === 0) $out['error'] = curl_error($ch);
        curl_close($ch);
        return $out;
    }
    if (!filter_var(ini_get('allow_url_fopen'), FILTER_VALIDATE_BOOLEAN)) { $out['error'] = 'This server does not allow PHP to fetch addresses (allow_url_fopen is off and curl is not installed).'; return $out; }
    $ctx = stream_context_create(['http' => ['method' => $method, 'header' => implode("\r\n", array_merge($headers, ['User-Agent: Drop-in Photo Gallery ' . GALLERY_VERSION])), 'timeout' => $timeout, 'ignore_errors' => true, 'follow_location' => 1, 'max_redirects' => 3]]);
    $fh = @fopen($url, 'rb', false, $ctx);
    if (!$fh) { $out['error'] = 'Could not connect.'; return $out; }
    $meta = stream_get_meta_data($fh);
    foreach ((array) ($meta['wrapper_data'] ?? []) as $line) {
        if (preg_match('#^HTTP/\S+\s+(\d+)#', $line, $m)) { $out['status'] = (int) $m[1]; $out['headers'] = []; }
        elseif (strpos($line, ':') !== false) { [$k, $v] = explode(':', $line, 2); $out['headers'][strtolower(trim($k))] = trim($v); }
    }
    if ($method !== 'HEAD') while (!feof($fh) && strlen($out['body']) <= $maxBytes) { $d = fread($fh, 65536); if ($d === false || $d === '') break; $out['body'] .= $d; }
    fclose($fh);
    return $out;
}

/**
 * What the file for the newest month would need and say, without downloading it: ['ok' => true, 'ym', 'gz' => bytes to download, 'raw' => bytes unpacked,
 * 'exact' => whether 'raw' was read from the file (the last four bytes of a gzip file say how big it unpacks to) or only estimated, 'modified', 'url']
 * or ['ok' => false, 'error' => why].
 */
function geo_probe() {
    $err = 'Could not reach the country list.';
    foreach (geo_months() as $ym) {
        $url = geo_url_for($ym);
        $h = geo_http($url, 'HEAD', [], 1000, 12);
        if ($h['status'] === 0) { $err = $h['error'] !== '' ? $h['error'] : $err; break; }
        if ($h['status'] !== 200) { $err = 'The file for ' . $ym . ' is not there yet (' . $h['status'] . ').'; continue; }
        $gz = (int) ($h['headers']['content-length'] ?? 0);
        $raw = null;
        if ($gz > 4) {
            $t = geo_http($url, 'GET', ['Range: bytes=' . ($gz - 4) . '-' . ($gz - 1)], 64, 12);
            if ($t['status'] === 206 && strlen($t['body']) === 4) $raw = (int) unpack('V', $t['body'])[1];
        }
        return ['ok' => true, 'ym' => $ym, 'gz' => $gz, 'raw' => $raw !== null ? $raw : (int) round($gz * 2.03), 'exact' => $raw !== null, 'modified' => (string) ($h['headers']['last-modified'] ?? ''), 'url' => $url];
    }
    return ['ok' => false, 'error' => $err];
}

/** Writes the settings file with $changes merged in, safely (locked, read back, then swapped in), like choosing the first password does. Returns '' or why not. */
function gallery_config_merge(array $changes) {
    $lock = @fopen(__FILE__, 'r');
    if ($lock) flock($lock, LOCK_EX);
    try {
        $path = gallery_config_path();
        $raw = is_file($path) ? @file_get_contents($path) : '';
        if ($raw === false) return 'The settings file can\'t be read.';
        [$status, $cfg] = gallery_config_parse((string) $raw);
        if ($status !== 'ok') return 'The settings file (.gallery-config.php) isn\'t valid, so nothing was changed. Fix or delete it first.';
        foreach ($changes as $k => $v) { if ($v === null) unset($cfg[$k]); else $cfg[$k] = $v; }
        $content = gallery_config_render($cfg);
        if ($content === null || !is_writable(__DIR__)) return 'The settings file can\'t be written.';
        $tmp = $path . '.tmp.' . bin2hex(random_bytes(4));
        if (@file_put_contents($tmp, $content, LOCK_EX) === false) { @unlink($tmp); return 'The settings file can\'t be written.'; }
        @chmod($tmp, 0600);
        [$st, $round] = gallery_config_parse((string) @file_get_contents($tmp));
        if ($st !== 'ok' || $round != $cfg || !@rename($tmp, $path)) { @unlink($tmp); return 'The settings file didn\'t read back correctly, so it was not changed.'; }
        return '';
    } finally {
        if ($lock) { flock($lock, LOCK_UN); fclose($lock); }
    }
}

/* ---- The reader: just enough of the MaxMind DB format to find a country (https://maxmind.github.io/MaxMind-DB/) ---- */

function geo_rd($fh, $pos, $n) {
    fseek($fh, $pos);
    $s = $n > 0 ? fread($fh, $n) : '';
    return $s === false ? '' : $s;
}

/** Decodes one value of the data section at $pos (moved on past it); $base is where the data section (or the metadata) starts, which pointers are counted from. */
function geo_mmdb_value($fh, &$pos, $base, $depth = 0) {
    if ($depth > 8) return null;
    $ctrl = ord(geo_rd($fh, $pos, 1)); $pos++;
    $type = $ctrl >> 5;
    if ($type === 1) {   // a pointer: the value is somewhere else in the data section
        $ss = ($ctrl >> 3) & 3; $vvv = $ctrl & 7;
        $b = geo_rd($fh, $pos, $ss + 1); $pos += $ss + 1;
        $n = array_values(unpack('C*', $b));
        $p = $ss === 0 ? ($vvv << 8) + $n[0] : ($ss === 1 ? ($vvv << 16) + ($n[0] << 8) + $n[1] + 2048 : ($ss === 2 ? ($vvv << 24) + ($n[0] << 16) + ($n[1] << 8) + $n[2] + 526336 : ($n[0] << 24) + ($n[1] << 16) + ($n[2] << 8) + $n[3]));
        $at = $base + $p;
        return geo_mmdb_value($fh, $at, $base, $depth + 1);
    }
    if ($type === 0) { $type = 7 + ord(geo_rd($fh, $pos, 1)); $pos++; }
    $size = $ctrl & 31;
    if ($size >= 29) {
        $k = $size - 28; $e = array_values(unpack('C*', geo_rd($fh, $pos, $k))); $pos += $k;
        $size = $size === 29 ? 29 + $e[0] : ($size === 30 ? 285 + ($e[0] << 8) + $e[1] : 65821 + ($e[0] << 16) + ($e[1] << 8) + $e[2]);
    }
    switch ($type) {
        case 2: $s = geo_rd($fh, $pos, $size); $pos += $size; return $s;
        case 3: $s = geo_rd($fh, $pos, 8); $pos += 8; return $size === 8 ? unpack('E', $s)[1] : 0.0;
        case 4: $s = geo_rd($fh, $pos, $size); $pos += $size; return $s;
        case 5: case 6: case 9: case 10: case 8:
            $s = geo_rd($fh, $pos, $size); $pos += $size; $v = 0;
            for ($i = 0; $i < strlen($s); $i++) $v = ($v << 8) + ord($s[$i]);
            return $v;
        case 7:
            $m = [];
            for ($i = 0; $i < $size; $i++) { $k = geo_mmdb_value($fh, $pos, $base, $depth + 1); $v = geo_mmdb_value($fh, $pos, $base, $depth + 1); if (is_string($k)) $m[$k] = $v; }
            return $m;
        case 11:
            $a = [];
            for ($i = 0; $i < $size; $i++) $a[] = geo_mmdb_value($fh, $pos, $base, $depth + 1);
            return $a;
        case 14: return $size === 1;
        case 15: $s = geo_rd($fh, $pos, 4); $pos += 4; return unpack('G', $s)[1];
    }
    return null;
}

/** Opens a country file (with or without the guard line in front): ['fh', 'off', 'nodes', 'rec', 'ver', 'treeSize', 'nodeBytes'] or null if it is not a usable one. */
function geo_mmdb_open($path) {
    static $cache = [];
    if (array_key_exists($path, $cache)) return $cache[$path];
    $cache[$path] = null;
    $fh = @fopen($path, 'rb');
    if (!$fh) return null;
    $guard = data_file_guard_line();
    $off = geo_rd($fh, 0, strlen($guard)) === $guard ? strlen($guard) : 0;
    $st = fstat($fh); $size = (int) ($st['size'] ?? 0) - $off;
    if ($size < 100) { fclose($fh); return null; }
    $tail = min($size, 131072);
    $buf = geo_rd($fh, $off + $size - $tail, $tail);
    $p = strrpos($buf, "\xAB\xCD\xEFMaxMind.com");
    if ($p === false) { fclose($fh); return null; }
    $at = $off + $size - $tail + $p + 14; $metaBase = $at;
    $meta = geo_mmdb_value($fh, $at, $metaBase);
    if (!is_array($meta) || empty($meta['node_count']) || !in_array($meta['record_size'] ?? 0, [24, 28, 32], true) || !in_array($meta['ip_version'] ?? 0, [4, 6], true) || ($meta['binary_format_major_version'] ?? 2) !== 2) { fclose($fh); return null; }
    $nodeBytes = (int) $meta['record_size'] * 2 / 8;
    $treeSize = (int) $meta['node_count'] * $nodeBytes;
    if ($treeSize + 16 > $size) { fclose($fh); return null; }
    return $cache[$path] = ['fh' => $fh, 'off' => $off, 'nodes' => (int) $meta['node_count'], 'rec' => (int) $meta['record_size'], 'ver' => (int) $meta['ip_version'], 'treeSize' => $treeSize, 'nodeBytes' => (int) $nodeBytes, 'meta' => $meta];
}

/** One record of a search tree node: the node a bit leads to (or, past the node count, where the data is). */
function geo_mmdb_record(array $db, $node, $bit) {
    $b = array_values(unpack('C*', geo_rd($db['fh'], $db['off'] + $node * $db['nodeBytes'], $db['nodeBytes'])));
    if ($db['rec'] === 24) return $bit === 0 ? ($b[0] << 16) + ($b[1] << 8) + $b[2] : ($b[3] << 16) + ($b[4] << 8) + $b[5];
    if ($db['rec'] === 28) return $bit === 0 ? (($b[3] & 0xF0) << 20) + ($b[0] << 16) + ($b[1] << 8) + $b[2] : (($b[3] & 0x0F) << 24) + ($b[4] << 16) + ($b[5] << 8) + $b[6];
    return $bit === 0 ? ($b[0] << 24) + ($b[1] << 16) + ($b[2] << 8) + $b[3] : ($b[4] << 24) + ($b[5] << 16) + ($b[6] << 8) + $b[7];
}

/** The two-letter country the file gives an address ("US"), or ''. */
function geo_mmdb_lookup(array $db, $ip) {
    $bin = @inet_pton((string) $ip);
    if ($bin === false) return '';
    if (strlen($bin) === 16 && strncmp($bin, str_repeat("\0", 10) . "\xff\xff", 12) === 0) $bin = substr($bin, 12);   // an IPv4 address written the IPv6 way
    if ($db['ver'] === 4 && strlen($bin) === 16) return '';
    if ($db['ver'] === 6 && strlen($bin) === 4) $bin = str_repeat("\0", 12) . $bin;   // IPv4 lives under ::/96 in an IPv6 tree
    $bits = strlen($bin) * 8; $node = 0;
    for ($i = 0; $i < $bits && $node < $db['nodes']; $i++) $node = geo_mmdb_record($db, $node, (ord($bin[$i >> 3]) >> (7 - ($i & 7))) & 1);
    if ($node <= $db['nodes'] || $node === 0) return '';
    $pos = $db['off'] + $db['treeSize'] + ($node - $db['nodes']); $base = $db['off'] + $db['treeSize'] + 16;
    $rec = geo_mmdb_value($db['fh'], $pos, $base);
    $c = is_array($rec) ? ($rec['country']['iso_code'] ?? $rec['registered_country']['iso_code'] ?? '') : '';
    return is_string($c) && preg_match('/^[A-Z]{2}$/', $c) ? $c : '';
}

/** The country of an address from the file, or '' (the option is off, there is no usable file, or the address is not in it). */
function geo_db_country($ip) {
    static $memo = [];
    if (!COUNTRY_LOOKUP) return '';
    if (isset($memo[$ip])) return $memo[$ip];
    $db = is_file(geo_db_path()) ? geo_mmdb_open(geo_db_path()) : null;
    return $memo[$ip] = $db ? geo_mmdb_lookup($db, $ip) : '';
}

/** The country of an address: what a trusted proxy says when it is this request's own address, else the file. */
function geo_country($ip) {
    return $ip === client_ip() ? client_country() : geo_db_country($ip);
}

/**
 * Gets the newest country file if there is one we do not have: asks first (a small request) whether the newest month's file differs from ours
 * (its date and size), and only then downloads, unpacks and checks it (the header must read and a known address must come out right) before it
 * replaces the old one. Returns ['ok' => bool, 'changed' => bool, 'error' => text]. Records the try either way; a failure waits a day.
 */
function geo_refresh($force = false) {
    $state = geo_state(); $now = time();
    $fail = function ($why) use ($state, $now) {
        $state['error'] = $why; $state['triedAt'] = $now;
        json_file_update(geo_state_path(), [], function (&$d) use ($state) { $d = $state; });
        @touch(geo_state_path(), $now - 6 * 86400);   // (due again in a day)
        return ['ok' => false, 'changed' => false, 'error' => $why];
    };
    if (!function_exists('gzdecode')) return $fail('This PHP has no zlib, which unpacking the file needs.');
    $probe = geo_probe();
    if (!$probe['ok']) return $fail($probe['error']);
    if (!$force && is_file(geo_db_path()) && $state['modified'] === $probe['modified'] && (int) $state['length'] === $probe['gz'] && $state['ym'] === $probe['ym']) {
        $state['error'] = ''; $state['triedAt'] = $now;
        json_file_update(geo_state_path(), [], function (&$d) use ($state) { $d = $state; });
        @touch(geo_state_path(), $now);
        return ['ok' => true, 'changed' => false, 'error' => ''];
    }
    $free = @disk_free_space(__DIR__);
    if ($free !== false && $free < ($probe['gz'] + 2 * $probe['raw'] + 1048576)) return $fail('Not enough room on this server\'s disk (about ' . signin_size_text($probe['gz'] + 2 * $probe['raw']) . ' is needed, ' . signin_size_text((int) $free) . ' is free).');
    @set_time_limit(120);
    $dl = geo_http($probe['url'], 'GET', [], 40000000, 100);
    if ($dl['status'] !== 200 || strlen($dl["body"]) < 100) return $fail($dl['status'] === 0 ? ($dl['error'] !== '' ? $dl['error'] : 'The download did not finish.') : 'The download answered ' . $dl['status'] . '.');
    $raw = @gzdecode($dl['body']); unset($dl);
    if (!is_string($raw) || strlen($raw) < 100) return $fail('The downloaded file could not be unpacked.');
    $tmp = __DIR__ . '/.gallery-geo.' . bin2hex(random_bytes(4)) . '.php';   // (ends in .php and starts with the guard line, so a leftover is answered with a 404 like the real file)
    if (@file_put_contents($tmp, data_file_guard_line() . $raw, LOCK_EX) === false) { @unlink($tmp); return $fail('The folder can\'t be written to.'); }
    $rawLen = strlen($raw); unset($raw);
    $db = geo_mmdb_open($tmp);
    $good = $db !== null && (COUNTRY_DB_URL !== '' || geo_mmdb_lookup($db, '8.8.8.8') !== '');   // (a file from an address of your own only has to read; DB-IP's must also know a well-known address)
    if ($db !== null) { @fclose($db['fh']); }
    if (!$good) { @unlink($tmp); return $fail('The downloaded file is not a country list this gallery can read.'); }
    if (!@rename($tmp, geo_db_path())) { @unlink($tmp); return $fail('The new file could not be put in place.'); }
    $state = ['ym' => $probe['ym'], 'modified' => $probe['modified'], 'length' => $probe['gz'], 'at' => $now, 'error' => '', 'triedAt' => $now, 'raw' => $rawLen];
    json_file_update(geo_state_path(), [], function (&$d) use ($state) { $d = $state; });
    @touch(geo_state_path(), $now);
    return ['ok' => true, 'changed' => true, 'error' => ''];
}

/**
 * Called from a gallery page, a link's opening page and the admin: if the option is on and it has been 7 days since the last look (or the file is
 * not there), looks for a newer file. The cost of asking whether it is time is one look at one file's date. The work happens after the visitor has
 * been answered when PHP can do that (php-fpm); otherwise only in the admin, so a visitor never waits for a download.
 */
function geo_maybe_refresh($inAdmin = false) {
    static $armed = false;
    if ($armed || !COUNTRY_LOOKUP) return;
    $stamp = (int) @filemtime(geo_state_path());
    if (is_file(geo_db_path()) && $stamp > 0 && time() - $stamp < 7 * 86400) return;
    if (!$inAdmin && !function_exists('fastcgi_finish_request')) return;
    $armed = true;
    register_shutdown_function(function () use ($inAdmin) {
        if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request();
        @ignore_user_abort(true);
        $lock = @fopen(geo_state_path() . '.lock', 'c');
        if (!$lock || !flock($lock, LOCK_EX | LOCK_NB)) return;   // (someone else is already doing it)
        try { geo_refresh(); } catch (Throwable $e) { error_log('gallery: country file refresh: ' . $e->getMessage()); }
        flock($lock, LOCK_UN); fclose($lock); @unlink(geo_state_path() . '.lock');
    });
}

/** Turns the option on: gets the file (which must work), then writes the setting. Returns ['ok', 'text']. */
function geo_enable() {
    $r = geo_refresh(true);
    if (!$r['ok']) return ['ok' => false, 'text' => $r['error']];
    $why = gallery_config_merge(['COUNTRY_LOOKUP' => true]);
    return $why === '' ? ['ok' => true, 'text' => 'Done: the country file is in place and addresses are looked up.'] : ['ok' => false, 'text' => $why];
}

/** Turns the option off, and removes the file and its notes when asked. Only those two names are ever removed. */
function geo_disable($deleteFile) {
    $why = gallery_config_merge(['COUNTRY_LOOKUP' => null]);
    if ($why !== '') return ['ok' => false, 'text' => $why];
    if ($deleteFile) foreach ([geo_db_path(), geo_state_path()] as $f) if (is_file($f) && !is_link($f) && dirname($f) === __DIR__) @unlink($f);
    return ['ok' => true, 'text' => $deleteFile ? 'Turned off, and the country file is deleted.' : 'Turned off. The file stays, in case you turn it on again.'];
}

/** The admin's buttons for the option: geo_probe (what it needs, exactly), geo_enable, geo_refresh and geo_disable. Answers JSON and ends the request. */
function geo_admin_action($action) {
    if ($action === 'geo_probe') {
        $p = geo_probe();
        if (!$p['ok']) admin_json_exit(['ok' => false, 'text' => $p['error'] . ' You can download the file yourself and put it here as ' . basename(geo_db_path()) . '.']);
        $free = @disk_free_space(__DIR__);
        $need = $p['gz'] + 2 * $p['raw'];
        admin_json_exit(['ok' => true, 'gz' => signin_size_text($p['gz']), 'raw' => signin_size_text($p['raw']), 'exact' => $p['exact'], 'need' => signin_size_text($need), 'free' => $free === false ? '' : signin_size_text((int) $free), 'enough' => $free === false || $free > $need + 1048576,
            'canFetch' => function_exists('curl_init') || filter_var(ini_get('allow_url_fopen'), FILTER_VALIDATE_BOOLEAN), 'zlib' => function_exists('gzdecode'), 'url' => $p['url']]);
    }
    if ($action === 'geo_enable') admin_json_exit(geo_enable());
    if ($action === 'geo_refresh') { $r = geo_refresh(false); admin_json_exit(['ok' => $r['ok'], 'text' => $r['ok'] ? ($r['changed'] ? 'Fetched the newest file.' : 'You already have the newest file.') : $r['error']]); }
    if ($action === 'geo_disable') admin_json_exit(geo_disable(($_POST['delete'] ?? '') === '1'));
    admin_json_exit(['ok' => false, 'text' => 'Unknown action.']);
}

/* -----------------------------------------------------------------------
 * New versions. The gallery can ask GitHub (the project's releases page) which version is the newest, at most once a day, from the Settings
 * page and never while a page is being built: the page asks afterwards, in the background, and says nothing when it can't be reached. If the
 * newest is newer than this one, the Health check says so with two buttons, View release and Update now. The only thing sent is an ordinary
 * request for the releases page (so GitHub sees this server's address); nothing about the gallery, its photos or its visitors. CHECK_FOR_UPDATES
 * turns the daily check off (the Check now button still works).
 *
 * Update now replaces this file (index.php) and nothing else. It downloads the release's index.php and its .sha256 from the project's own
 * release address, refuses anything whose checksum differs or that isn't a PHP file for the version named, keeps the file it replaces
 * (guarded, as .gallery-previous.php) and swaps the new one in with a single rename. Go back puts the kept file in again. Photos, settings and
 * every other file are never touched.
 * ----------------------------------------------------------------------- */

function update_state_path() {
    return __DIR__ . '/.gallery-update.php';
}
function update_backup_path() {
    return __DIR__ . '/.gallery-previous.php';
}

/** What we last learned: ['triedAt' => when we last asked, 'checkedAt' => when an answer last came, 'latest' => '2.7.0' or '', 'page' => the release's page, 'indexUrl'/'sumUrl' => its two files,
 *  'error' => why the last try failed or '', 'updatedFrom' => the version we replaced, 'updatedAt' => when]. */
function update_state() {
    return json_file_read(update_state_path(), ['triedAt' => 0, 'checkedAt' => 0, 'latest' => '', 'page' => '', 'indexUrl' => '', 'sumUrl' => '', 'error' => '', 'updatedFrom' => '', 'updatedAt' => 0]);
}
function update_state_save(array $state) {
    return @file_put_contents(update_state_path(), data_file_encode($state), LOCK_EX) !== false;
}

/** Where the newest release is announced: GitHub's own, unless the setting UPDATE_FEED_URL names another (a mirror of your own, or a test). */
function update_feed_url() {
    return UPDATE_FEED_URL !== '' ? UPDATE_FEED_URL : 'https://api.github.com/repos/pcmike/gallery/releases/latest';
}
/** The start every address the feed names must have: the project's own release files, or (with a feed of your own) the feed's own server. */
function update_allowed_prefix() {
    if (UPDATE_FEED_URL === '') return 'https://github.com/pcmike/gallery/releases/';
    $p = parse_url(UPDATE_FEED_URL);
    return is_array($p) && !empty($p['host']) ? ($p['scheme'] ?? 'https') . '://' . $p['host'] . (isset($p['port']) ? ':' . $p['port'] : '') . '/' : '';
}

/** Asks the feed what the newest release is and remembers the answer (or the failure). Returns the state. */
function update_fetch() {
    $st = update_state();
    $st['triedAt'] = time();
    $fail = function ($why) use (&$st) { $st['error'] = $why; update_state_save($st); return $st; };
    $r = geo_http(update_feed_url(), 'GET', ['Accept: application/vnd.github+json'], 1000000, 10);
    if ($r['status'] === 0) return $fail($r['error'] !== '' ? $r['error'] : 'Could not reach the releases page.');
    if ($r['status'] !== 200) return $fail('The releases page answered ' . $r['status'] . '.');
    $j = json_decode($r['body'], true);
    $tag = is_array($j) ? ltrim((string) ($j['tag_name'] ?? ''), 'vV') : '';
    if (!preg_match('/^\d+\.\d+\.\d+$/', $tag)) return $fail('The releases page did not name a version.');
    $prefix = update_allowed_prefix();
    $ok = function ($u) use ($prefix) { return is_string($u) && $prefix !== '' && strncmp($u, $prefix, strlen($prefix)) === 0 && geo_url_ok($u); };
    $st['latest'] = $tag; $st['checkedAt'] = time(); $st['error'] = '';
    $st['page'] = $ok($j['html_url'] ?? null) ? (string) $j['html_url'] : '';
    $st['indexUrl'] = ''; $st['sumUrl'] = '';
    foreach ((array) ($j['assets'] ?? []) as $a) {
        if (!is_array($a)) continue;
        if (($a['name'] ?? '') === 'index.php' && $ok($a['browser_download_url'] ?? null)) $st['indexUrl'] = (string) $a['browser_download_url'];
        if (($a['name'] ?? '') === 'index.php.sha256' && $ok($a['browser_download_url'] ?? null)) $st['sumUrl'] = (string) $a['browser_download_url'];
    }
    update_state_save($st);
    return $st;
}

/** Is it time for the daily look? (Only where the answer can be kept: without that, every Settings page would ask.) */
function update_check_due() {
    if (!CHECK_FOR_UPDATES || !is_writable(__DIR__)) return false;
    return time() - (int) update_state()['triedAt'] >= 86400;
}

/** The newest version, when it is newer than this one (from what we last learned; nothing is asked here). Else null. */
function update_newer() {
    $st = update_state();
    if ($st['latest'] === '' || !version_compare($st['latest'], GALLERY_VERSION, '>')) return null;
    return $st;
}

/** Can this file be replaced here? ['ok' => bool, 'why' => the reason when not]. */
function update_can_write() {
    if (is_link(__FILE__)) return ['ok' => false, 'why' => 'index.php is a link to a file elsewhere'];
    if (!is_writable(__FILE__) || !is_writable(__DIR__)) return ['ok' => false, 'why' => 'the web server can\'t write to index.php here'];
    return ['ok' => true, 'why' => ''];
}
/** Can this gallery fetch a new one and replace its own file here? */
function update_can_replace() {
    if (!function_exists('curl_init') && !filter_var(ini_get('allow_url_fopen'), FILTER_VALIDATE_BOOLEAN)) return ['ok' => false, 'why' => 'this server doesn\'t let PHP fetch addresses'];
    return update_can_write();
}

/** The version a PHP text says it is (its GALLERY_VERSION line), or ''. */
function update_text_version($code) {
    return preg_match("/define\\('GALLERY_VERSION', '(\\d+\\.\\d+\\.\\d+)'\\)/", (string) $code, $m) ? $m[1] : '';
}

/** Does this text read as PHP, start to end? (A download cut short, or a page of something else, does not.) Without the tokenizer, true: the checksum has already agreed. */
function update_php_parses($code) {
    if (!function_exists('token_get_all') || !defined('TOKEN_PARSE')) return true;
    $limit = (string) ini_get('memory_limit');
    if ($limit !== '-1' && (int) $limit < 256 && !preg_match('/[gG]$/', $limit)) @ini_set('memory_limit', '256M');
    try { $t = token_get_all((string) $code, TOKEN_PARSE); unset($t); return true; } catch (\Throwable $e) { return false; }
}

/** The version of the file kept by the last update ('' when there is none). */
function update_backup_version() {
    $raw = is_file(update_backup_path()) ? @file_get_contents(update_backup_path(), false, null, 0, 40000) : '';
    return is_string($raw) ? update_text_version($raw) : '';
}

/** Puts $content where index.php is, in one rename, and checks what landed. Returns '' or why not. */
function update_swap_in($content) {
    $tmp = __DIR__ . '/.gallery-update-' . bin2hex(random_bytes(4)) . '.tmp';
    if (@file_put_contents($tmp, $content) !== strlen($content)) { @unlink($tmp); return 'The new file could not be written beside index.php.'; }
    @chmod($tmp, @fileperms(__FILE__) & 0777 ?: 0644);
    if (!@rename($tmp, __FILE__)) { @unlink($tmp); return 'index.php could not be replaced.'; }
    clearstatcache(true, __FILE__);
    if (function_exists('opcache_invalidate')) @opcache_invalidate(__FILE__, true);
    return hash_file('sha256', __FILE__) === hash('sha256', $content) ? '' : 'The file that was written did not read back the same.';
}

/** Update now. Returns ['ok' => bool, 'text' => what to tell the owner, 'version' => the new one]. */
function update_apply() {
    $can = update_can_replace();
    if (!$can['ok']) return ['ok' => false, 'text' => 'Nothing was changed: ' . $can['why'] . '. Download it from the release page instead.'];
    $st = update_fetch();
    if ($st['error'] !== '') return ['ok' => false, 'text' => 'Nothing was changed: ' . $st['error']];
    $new = $st['latest'];
    if (!version_compare($new, GALLERY_VERSION, '>')) return ['ok' => false, 'text' => 'You already have the newest version.'];
    if ($st['indexUrl'] === '' || $st['sumUrl'] === '') return ['ok' => false, 'text' => 'Nothing was changed: that release has no index.php with a checksum to update from. Download it from the release page.'];
    $lock = @fopen(__FILE__, 'r');
    if ($lock) flock($lock, LOCK_EX);
    try {
        $f = geo_http($st['indexUrl'], 'GET', [], 12000000, 120);
        if ($f['status'] !== 200 || strlen($f['body']) < 100000) return ['ok' => false, 'text' => 'Nothing was changed: the file could not be downloaded' . ($f['error'] !== '' ? ' (' . $f['error'] . ')' : '') . '.'];
        $s = geo_http($st['sumUrl'], 'GET', [], 4096, 30);
        if ($s['status'] !== 200 || !preg_match('/^([0-9a-fA-F]{64})\b/', trim($s['body']), $m)) return ['ok' => false, 'text' => 'Nothing was changed: the checksum could not be downloaded.'];
        $code = $f['body'];
        if (!hash_equals(strtolower($m[1]), hash('sha256', $code))) return ['ok' => false, 'text' => 'Nothing was changed: the download did not match its checksum.'];
        if (strncmp($code, '<?php', 5) !== 0 || update_text_version($code) !== $new || !update_php_parses($code)) return ['ok' => false, 'text' => 'Nothing was changed: the download is not the PHP file for version ' . $new . '.'];
        $old = (string) @file_get_contents(__FILE__);
        $guarded = data_file_guard_line() . $old;
        if ($old === '' || @file_put_contents(update_backup_path(), $guarded) !== strlen($guarded)) return ['ok' => false, 'text' => 'Nothing was changed: the current file could not be kept first (is the folder writable?).'];
        $why = update_swap_in($code);
        if ($why !== '') {
            $back = update_swap_in($old);
            return ['ok' => false, 'text' => 'Updating failed: ' . $why . ($back === '' ? ' The old file is back in place.' : ' The old file could not be put back either: it is kept as ' . basename(update_backup_path()) . '.')];
        }
        $st['updatedFrom'] = GALLERY_VERSION; $st['updatedAt'] = time();
        update_state_save($st);
        return ['ok' => true, 'text' => 'Updated to ' . $new . '.', 'version' => $new];
    } finally {
        if ($lock) { flock($lock, LOCK_UN); fclose($lock); }
    }
}

/** Go back: puts the file the last update kept back in place. Returns ['ok' => bool, 'text' => ...]. */
function update_undo() {
    $can = update_can_write();
    if (!is_file(update_backup_path())) return ['ok' => false, 'text' => 'There is no earlier version kept.'];
    if (!$can['ok']) return ['ok' => false, 'text' => 'Nothing was changed: ' . $can['why'] . '.'];
    $lock = @fopen(__FILE__, 'r');
    if ($lock) flock($lock, LOCK_EX);
    try {
        $old = data_file_strip_guard((string) @file_get_contents(update_backup_path()));
        $v = update_text_version($old);
        if (strncmp($old, '<?php', 5) !== 0 || $v === '' || !update_php_parses($old)) return ['ok' => false, 'text' => 'Nothing was changed: the kept file is not a whole gallery file.'];
        $why = update_swap_in($old);
        if ($why !== '') return ['ok' => false, 'text' => 'Going back failed: ' . $why];
        @unlink(update_backup_path());
        $st = update_state(); $st['updatedFrom'] = ''; $st['updatedAt'] = 0; update_state_save($st);
        return ['ok' => true, 'text' => 'Back on ' . $v . '.', 'version' => $v];
    } finally {
        if ($lock) { flock($lock, LOCK_UN); fclose($lock); }
    }
}

/** The "new version" heads-up for the Health check, or the "just updated" one (with Go back), or null. Same shape as health_headsups(): label, detail, html (buttons). */
function update_headsups() {
    $e = function ($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); };
    $out = [];
    $st = update_state();
    $back = update_backup_version();
    if ($back !== '' && $st['updatedAt'] > 0 && time() - (int) $st['updatedAt'] < 86400 && version_compare($back, GALLERY_VERSION, '<'))
        $out[] = ['label' => 'Updated from ' . $back . ' to ' . GALLERY_VERSION, 'detail' => 'The file it replaced is kept, in case something doesn\'t look right.',
            'html' => '<div class="health-act"><button type="button" class="secondary" data-update="undo">Go back to ' . $e($back) . '</button></div>', 'attr' => ' data-update-row'];
    $n = update_newer();
    if ($n !== null) {
        $can = update_can_replace();
        $btns = ($can['ok'] ? '<button type="button" class="secondary" data-update="apply">Update now</button> ' : '')
            . ($n['page'] !== '' ? '<a class="secondary btn-link" href="' . $e($n['page']) . '" target="_blank" rel="noopener noreferrer">View release</a>' : '');
        $out[] = ['label' => 'Version ' . $n['latest'] . ' is out', 'detail' => 'You are on ' . GALLERY_VERSION . '.' . ($can['ok'] ? '' : ' This gallery can\'t update itself here (' . $can['why'] . '), so download it from the release page.') . ' ',
            'html' => '<div class="health-act">' . $btns . '</div>', 'attr' => ' data-update-row'];
    }
    return $out;
}

/** What the "Updates" row says: when it was last looked, and what it found. */
function update_status_text() {
    $st = update_state();
    if ($st['error'] !== '' && $st['triedAt'] > 0) return 'Could not check (' . $st['error'] . ')';
    if ($st['checkedAt'] > 0) return (update_newer() ? 'A newer version is out' : 'Up to date') . ' · checked ' . date('M j, g:i a', (int) $st['checkedAt']);
    return CHECK_FOR_UPDATES ? 'Not checked yet' : 'Not checking (switched off in Settings)';
}
/** The "Updates" row's own line, under its label: what it found, and Check now. */
function update_status_html() {
    return '<div class="health-detail"><span data-update-text>' . htmlspecialchars(update_status_text(), ENT_QUOTES, 'UTF-8') . '</span> <button type="button" class="linklike" data-update="check">Check now</button></div>';
}

/** The Health check's buttons for this (Settings, answers JSON and ends the request): update_check, update_apply, update_undo. */
function update_admin_action($action) {
    if ($action === 'update_check') {
        if (($_POST['force'] ?? '') === '1' || update_check_due()) update_fetch();
        $rows = array_map('health_headsup_row_html', update_headsups());
        admin_json_exit(['ok' => true, 'rows' => $rows, 'text' => update_status_text(), 'newer' => update_newer() !== null]);
    }
    if ($action === 'update_apply') admin_json_exit(update_apply());
    if ($action === 'update_undo') admin_json_exit(update_undo());
    admin_json_exit(['ok' => false, 'text' => 'Unknown action.']);
}
/* -----------------------------------------------------------------------
 * Passwords at rest. The settings file keeps each password as a bcrypt hash
 * (password_hash), so a copy of that file — a backup, a zip, a repository, a
 * server that sends .php files as text — does not hand over the password
 * itself, only something that has to be guessed at one try at a time. A
 * password written there in plain text still works (hand-edited files, older
 * versions); the first successful sign-in replaces it with its hash.
 * ----------------------------------------------------------------------- */

/** True if $v is a password hash made by password_hash(), not a password. */
function password_is_hashed($v) {
    return is_string($v) && $v !== '' && (password_get_info($v)['algo'] ?? null) !== null;
}

/** Does $supplied match the stored password: a hash (checked with
 *  password_verify) or, for a file not yet upgraded, the plain text. */
function password_matches($stored, $supplied) {
    if (!is_string($stored) || $stored === '' || !is_string($supplied)) return false;
    return password_is_hashed($stored) ? password_verify($supplied, $stored) : hash_equals($stored, $supplied);
}

/** What the settings file keeps for a new password. */
function password_for_storage($plain) {
    return password_hash($plain, PASSWORD_DEFAULT);
}

/** A random secret that belongs to this install, kept in its own small data
 *  file (.gallery-secret.php, answers 404 like the others). The sign-in
 *  cookies are keyed with it, so someone who only has a copy of the settings
 *  file (and so the password hashes) still can't make a valid cookie. $create
 *  makes it if it doesn't exist (at a sign-in); without it, a missing secret
 *  is just ''. If the folder can't be written the cookies fall back to being
 *  derived from the stored password alone. */
function install_secret($create = false) {
    static $secret = null;
    if ($secret !== null && ($secret !== '' || !$create)) return $secret;
    $path = __DIR__ . '/.gallery-secret.php';
    $read = function () use ($path) {
        $raw = is_file($path) ? (string) @file_get_contents($path) : '';
        return preg_match('/^[0-9a-f]{64}$/m', $raw, $m) ? $m[0] : '';
    };
    $secret = $read();
    if ($secret !== '' || !$create || !is_writable(__DIR__)) return $secret;
    $tmp = $path . '.tmp.' . bin2hex(random_bytes(4));
    if (@file_put_contents($tmp, data_file_guard_line() . bin2hex(random_bytes(32)) . "\n", LOCK_EX) === false) { @unlink($tmp); return $secret; }
    @chmod($tmp, 0600);
    // link() refuses to replace a file that appeared meanwhile, so two first sign-ins can't end up with different secrets.
    if (!@link($tmp, $path) && !is_file($path)) @rename($tmp, $path);
    @unlink($tmp);
    return $secret = $read();
}

/** After a successful sign-in: any password the settings file still holds in
 *  plain text is replaced there by its hash (both at once, so one write).
 *  Returns the values now in force, name => stored value, for the passwords
 *  it changed ([] if none, or if the file can't be rewritten: then nothing
 *  changes and the plain text keeps working). */
function upgrade_plaintext_passwords() {
    $state = gallery_config_load();
    if ($state['status'] !== 'ok') return [];
    $names = [];
    foreach (['ADMIN_PASSWORD', 'PRIVATE_VIEW_PASSWORD'] as $n) {
        if (isset($state['cfg'][$n]) && is_string($state['cfg'][$n]) && $state['cfg'][$n] !== '' && !password_is_hashed($state['cfg'][$n])) $names[] = $n;
    }
    if (!$names || !is_writable(__DIR__)) return [];
    $lock = @fopen(__FILE__, 'r');
    if ($lock) flock($lock, LOCK_EX);
    try {
        $path = gallery_config_path();
        $raw = @file_get_contents($path);
        if ($raw === false) return [];
        [$status, $cfg] = gallery_config_parse($raw);
        if ($status !== 'ok') return [];
        $changed = [];
        foreach ($names as $n) {
            // Only what the file still holds, unchanged since this request began.
            if (($cfg[$n] ?? null) === $state['cfg'][$n]) { $cfg[$n] = password_for_storage($state['cfg'][$n]); $changed[$n] = $cfg[$n]; }
        }
        if (!$changed) return [];
        $content = gallery_config_render($cfg);
        if ($content === null) return [];
        $tmp = $path . '.tmp.' . bin2hex(random_bytes(4));
        if (@file_put_contents($tmp, $content, LOCK_EX) === false) { @unlink($tmp); return []; }
        @chmod($tmp, 0600);
        [$roundStatus, $roundTrip] = gallery_config_parse((string) @file_get_contents($tmp));
        ksort($roundTrip); ksort($cfg);
        if ($roundStatus !== 'ok' || $roundTrip !== $cfg || !@rename($tmp, $path)) { @unlink($tmp); return []; }
        return $changed;
    } finally {
        if ($lock) { flock($lock, LOCK_UN); fclose($lock); }
    }
}

function admin_session_authed() {
    return isset($_SESSION['admin_auth']) && is_string($_SESSION['admin_auth'])
        && hash_equals(admin_session_marker(), $_SESSION['admin_auth']);
}

/* -----------------------------------------------------------------------
 * Browsers that are signed in. The owner and anyone given the private-view password are each recognised by one cookie
 * (REVEAL_COOKIE_NAME) that holds a random token. The server keeps only the token's hash (.gallery-browsers.php), with who it is for
 * ('owner' or 'view'), when it was made and last used, when it ends, a short label for the device ("iPhone · Safari") and a mark of the
 * password it was made under. So a token can't be forged, Log out ends that browser's for good, the owner can end any one from
 * Settings, and changing a password ends every token made under the old one. A token lasts ADMIN_STAY_SIGNED_IN_DAYS (the owner) or
 * PRIVATE_VIEW_SIGNED_IN_DAYS (a guest) from the last visit; 0 is until the browser closes (and, on the server, a day).
 * ----------------------------------------------------------------------- */
function browsers_path() {
    return __DIR__ . '/.gallery-browsers.php';
}

function browser_days($kind) {
    return $kind === 'owner' ? ADMIN_STAY_SIGNED_IN_DAYS : PRIVATE_VIEW_SIGNED_IN_DAYS;
}

/** What a token carries to show which password it was made under ($stored: the stored password, passed right after it changed, when
 *  the constant may still hold the old one). '' when there is no such password, so no token of that kind can be good. */
function browser_marker($kind, $stored = null) {
    if ($kind === 'owner') return ($stored ?? ADMIN_PASSWORD) === '' ? '' : admin_session_marker($stored);
    $pw = $stored ?? PRIVATE_VIEW_PASSWORD;
    return $pw === '' ? '' : hash('sha256', 'view|' . $pw . '|' . __DIR__);
}

/** A short, plain name for the device that is asking ("iPhone · Safari"), for the owner's list. Never the raw user-agent. */
function browser_label($ua = null) {
    $ua = $ua ?? (string) ($_SERVER['HTTP_USER_AGENT'] ?? '');
    $dev = preg_match('/iPhone/i', $ua) ? 'iPhone' : (preg_match('/iPad/i', $ua) ? 'iPad' : (preg_match('/Android/i', $ua) ? 'Android' : (preg_match('/Macintosh|Mac OS X/i', $ua) ? 'Mac' : (preg_match('/Windows/i', $ua) ? 'Windows' : (preg_match('/Linux|X11/i', $ua) ? 'Linux' : 'A device')))));
    $app = preg_match('/Edg(e|A|iOS)?\//', $ua) ? 'Edge' : (preg_match('/OPR\/|Opera/', $ua) ? 'Opera' : (preg_match('/Firefox|FxiOS/', $ua) ? 'Firefox' : (preg_match('/CriOS|Chrome\//', $ua) ? 'Chrome' : (preg_match('/Safari\//', $ua) ? 'Safari' : ($ua === '' ? '' : 'a browser')))));
    return $dev . ($app !== '' ? ' · ' . $app : '');
}

function browser_cookie($token, $expiresAt) {
    if (headers_sent()) return;
    setcookie(REVEAL_COOKIE_NAME, $token, ['expires' => $expiresAt, 'path' => gallery_cookie_path(), 'secure' => is_https_request(), 'httponly' => true, 'samesite' => 'Lax']);
}

/** The signed-in browser this request is: ['hash', 'kind' => 'owner'|'view', 'rec'], or null (no cookie, not genuine, ended, expired, made under a
 *  password that has changed since, or signed out just now because of a flag). A request from a different address or as a different device
 *  than the browser's last one is noted in its history (browser_note_event); otherwise once an hour of use its last-seen time and end move on. */
function browser_lookup($reset = false) {
    static $found = null;
    if ($reset) { $found = null; return null; }
    if ($found !== null) return $found ?: null;
    $found = false;
    $c = $_COOKIE[REVEAL_COOKIE_NAME] ?? '';
    if (!is_string($c) || !preg_match('/^[0-9a-f]{64}$/', $c)) return null;
    $h = hash('sha256', $c);
    $r = json_file_read(browsers_path(), [])[$h] ?? null;
    if (!is_array($r) || !in_array($r['kind'] ?? '', ['owner', 'view'], true) || (int) ($r['exp'] ?? 0) <= time()) return null;
    $m = browser_marker($r['kind']);
    if ($m === '' || !hash_equals($m, (string) ($r['pw'] ?? ''))) return null;
    $found = ['hash' => $h, 'kind' => $r['kind'], 'rec' => $r];
    $now = time();
    if (($r['via'] ?? '') !== 'script' && !headers_sent()) {
        $ip = client_ip(); $lab = browser_label();
        if (!isset($r['ip']) || $ip !== $r['ip'] || $lab !== (string) ($r['lab'] ?? '')) {
            if (!browser_note_event($h, $ip, $lab)) { $found = false; return null; }
            return $found;
        }
    }
    if ($now - (int) ($r['seen'] ?? 0) >= 3600 && !headers_sent()) {
        $days = browser_days($r['kind']); $exp = $now + ($days >= 1 ? $days * 86400 : 86400);
        json_file_update(browsers_path(), [], function (&$d) use ($h, $now, $exp) { if (isset($d[$h])) { $d[$h]['seen'] = $now; $d[$h]['exp'] = $exp; } });
        if ($days >= 1) browser_cookie($c, $exp);
    }
    return $found;
}

/** A new token for this browser, after a sign-in or a password change. $stored is passed only then. This browser's earlier token goes (it is
 *  listed as signed in again); expired ones and ones made under another password are moved to the ended list by browser_housekeeping();
 *  at most sixty are kept (the most recently used), and ten of the one-hour tokens a script makes. */
function browser_issue($kind, $stored = null, $viaScript = false) {
    $marker = browser_marker($kind, $stored);
    if ($marker === '') return;
    install_secret(true);   // (the key the made files' names use; made at the first sign-in)
    $days = browser_days($kind); $now = time(); $exp = $now + ($days >= 1 ? $days * 86400 : 86400);
    if ($viaScript) $exp = min($exp, $now + 3600);   // (a request that carried the password itself, not a person at a browser: an hour is plenty)
    $token = bin2hex(random_bytes(32));
    $old = is_string($_COOKIE[REVEAL_COOKIE_NAME] ?? null) ? hash('sha256', $_COOKIE[REVEAL_COOKIE_NAME]) : '';
    $label = browser_label(); $ip = client_ip(); $cc = $viaScript ? '' : geo_country($ip); $newHash = hash('sha256', $token);
    $replaced = null;
    $rec = ['kind' => $kind, 'made' => $now, 'seen' => $now, 'exp' => $exp, 'label' => $label, 'pw' => $marker];
    $rec += $viaScript ? ['via' => 'script'] : ['lab0' => $label, 'lab' => $label, 'ip' => $ip, 'n' => 1, 'nets' => [signin_net_key($ip) => $now], 'peak' => 1, 'peakAt' => $now, 'ccs' => $cc !== '' ? [$cc] : [], 'flags' => []];
    json_file_update(browsers_path(), [], function (&$d) use ($newHash, $rec, $old, $viaScript, &$replaced) {
        if ($old !== '' && isset($d[$old])) { $replaced = $d[$old]; unset($d[$old]); }
        $d = [$newHash => $rec] + $d;   // (first, so that when several were made in the same second the newest is the one that stays)
        // A script that sends the password with every request makes a token each time: those are kept to the last ten, and never push a
        // person's browser out of the sixty.
        uasort($d, fn ($x, $y) => ($y['seen'] ?? 0) <=> ($x['seen'] ?? 0));
        $scripts = 0;
        foreach ($d as $k => $r) if (is_array($r) && ($r['via'] ?? '') === 'script' && ++$scripts > 10) unset($d[$k]);
        if (count($d) > 60) $d = array_slice($d, 0, 60, true);
    });
    if (!$viaScript) signin_history_append(substr($newHash, 0, 12), ['t' => $now, 'ip' => $ip, 'cc' => $cc, 'ua' => substr((string) ($_SERVER['HTTP_USER_AGENT'] ?? ''), 0, 300), 'e' => 'signin']);
    if (is_array($replaced)) signin_ended_add(substr($old, 0, 12), $replaced, 'again');
    browser_cookie($token, $days >= 1 ? $exp : 0);
    $_COOKIE[REVEAL_COOKIE_NAME] = $token;   // (so the rest of this request already is that browser)
    browser_lookup(true);
    if ($stored === null) browser_housekeeping();   // (not right after a password was set or changed: the constants still hold the old value, which would make the token just made look old)
}

function browser_revoke_current() {
    $c = $_COOKIE[REVEAL_COOKIE_NAME] ?? '';
    if (is_string($c) && preg_match('/^[0-9a-f]{64}$/', $c) && is_file(browsers_path())) {
        $h = hash('sha256', $c); $gone = null;
        json_file_update(browsers_path(), [], function (&$d) use ($h, &$gone) { if (isset($d[$h])) { $gone = $d[$h]; unset($d[$h]); } });
        if (is_array($gone)) signin_ended_add(substr($h, 0, 12), $gone, 'logout');
    }
    gallery_cookie_expire(REVEAL_COOKIE_NAME, 'Lax');
    legacy_stay_forget();
    browser_lookup(true);
}

/** The signed-in browsers for the owner's list, newest use first. Each: id (the start of the hash), kind, label (what it was made on), lab (what it
 *  last said it was), made, seen, exp, ip (its last address) and its country, n (address changes), peak/peakAt (most networks in 24 hours), size
 *  of its history in bytes, flags (those showing), current (this very browser). */
function browser_rows() {
    browser_housekeeping();
    $me = browser_lookup(); $now = time(); $rows = [];
    foreach (json_file_read(browsers_path(), []) as $h => $r) {
        if (!is_array($r) || !in_array($r['kind'] ?? '', ['owner', 'view'], true) || (int) ($r['exp'] ?? 0) <= $now || ($r['via'] ?? '') === 'script') continue;
        $m = browser_marker($r['kind']);
        if ($m === '' || !hash_equals($m, (string) ($r['pw'] ?? ''))) continue;
        $id = substr((string) $h, 0, 12);
        $rows[] = ['id' => $id, 'kind' => $r['kind'], 'label' => (string) ($r['label'] ?? ''), 'lab' => signin_real_label($r), 'made' => (int) ($r['made'] ?? 0), 'seen' => (int) ($r['seen'] ?? 0), 'exp' => (int) $r['exp'],
            'ip' => (string) ($r['ip'] ?? ''), 'n' => (int) ($r['n'] ?? 0), 'peak' => (int) ($r['peak'] ?? 0), 'peakAt' => (int) ($r['peakAt'] ?? 0), 'size' => signin_history_size($id),
            'ccs' => array_values((array) ($r['ccs'] ?? [])), 'flags' => browser_flags_of($r), 'current' => $me !== null && $me['hash'] === $h];
    }
    usort($rows, fn ($a, $b) => $b['seen'] <=> $a['seen']);
    return $rows;
}

function browser_cancel($id, $allOthers = false) {
    $me = browser_lookup(); $mine = $me['hash'] ?? ''; $gone = [];
    json_file_update(browsers_path(), [], function (&$d) use ($id, $allOthers, $mine, &$gone) {
        foreach (array_keys($d) as $h) {
            if ($h === $mine) continue;
            if ($allOthers || ($id !== '' && strncmp((string) $h, $id, strlen($id)) === 0)) { if (is_array($d[$h])) $gone[(string) $h] = $d[$h]; unset($d[$h]); }
        }
    });
    foreach ($gone as $h => $r) signin_ended_add(substr($h, 0, 12), $r, 'you');
    return count($gone);
}

/* LEGACY (see docs/LEGACY-REMOVAL.md): the "stay signed in" token of 2.3.2 lived in its own cookie and file (.gallery-stay.php). A
 * browser that still holds one is signed in by it once more and given a token of the new kind. */
function legacy_stay_path() {
    return __DIR__ . '/.gallery-stay.php';
}

/** True (and the old token used up) when this request carries a good 2.3.2 stay-signed-in token. */
function legacy_stay_take() {
    if (ADMIN_STAY_SIGNED_IN_DAYS < 1 || ADMIN_PASSWORD === '') return false;
    $c = $_COOKIE[ADMIN_STAY_COOKIE_NAME] ?? '';
    if (!is_string($c) || !preg_match('/^[0-9a-f]{64}$/', $c)) return false;
    $h = hash('sha256', $c);
    $r = json_file_read(legacy_stay_path(), [])[$h] ?? null;
    if (!is_array($r) || (int) ($r['exp'] ?? 0) <= time() || !hash_equals(admin_session_marker(), (string) ($r['pw'] ?? ''))) return false;
    legacy_stay_forget();
    return true;
}

/** Ends the 2.3.2 stay token this request carries, if any (its record and its cookie). */
function legacy_stay_forget() {
    $c = $_COOKIE[ADMIN_STAY_COOKIE_NAME] ?? '';
    if (is_string($c) && preg_match('/^[0-9a-f]{64}$/', $c) && is_file(legacy_stay_path())) {
        $h = hash('sha256', $c);
        json_file_update(legacy_stay_path(), [], function (&$d) use ($h) { unset($d[$h]); });
    }
    if ($c !== '') gallery_cookie_expire(ADMIN_STAY_COOKIE_NAME, 'Strict');
}

/** The session is gone but the owner's token is good (or a 2.3.2 one is, and is swapped for a new one): sign in again without the password. */
function browser_owner_may_resume() {
    if (ADMIN_STAY_SIGNED_IN_DAYS < 1) return false;
    $b = browser_lookup();
    if ($b !== null) return $b['kind'] === 'owner';
    if (!legacy_stay_take()) return false;
    browser_issue('owner');
    return true;
}

/** The path this gallery's cookies are kept to: the folder the script is installed in ("/trip" for /trip/index.php, so a blog or another
 *  application elsewhere on the same domain is never sent the gallery's sign-in cookies), or "/" for one installed at the top. Used only
 *  when the address the visitor typed really is under that folder; behind a rewrite or a proxy that maps another address onto the
 *  script it stays "/" (the cookie would otherwise never come back). */
function gallery_cookie_path() {
    static $path = null;
    if ($path !== null) return $path;
    $path = '/';
    $dir = rtrim(str_replace('\\', '/', dirname($_SERVER['SCRIPT_NAME'] ?? '/')), '/');
    if ($dir !== '' && preg_match('#^/[A-Za-z0-9._~/-]*$#', $dir)) {   // (a folder name with anything else in it keeps the whole domain: no escaping to get wrong)
        $uri = (string) parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH);
        if ($uri === $dir || strncmp($uri, $dir . '/', strlen($dir) + 1) === 0) $path = $dir;
    }
    return $path;
}

/** Ends a cookie: expired on the gallery's own path and on "/" (where every cookie was kept before 2.4.0, and where a browser may still hold one). */
function gallery_cookie_expire($name, $sameSite) {
    foreach (array_unique([gallery_cookie_path(), '/']) as $path) {
        setcookie($name, '', ['expires' => 1, 'path' => $path, 'secure' => is_https_request(), 'httponly' => true, 'samesite' => $sameSite]);
    }
}

/** Starts (or resumes) the PHP session used to carry the admin CSRF
 *  token, with a 4-hour server-side lifetime — set here, before
 *  session_start(), so no server or php.ini change is needed. The
 *  browser-side cookie itself keeps no explicit expiry (a plain session
 *  cookie), so on its own a login lasts up to 4 hours without a visit, or until the browser
 *  closes; the owner's sign-in token (browser_*, ADMIN_STAY_SIGNED_IN_DAYS) brings a
 *  browser that lost the session back in without the password. Only ever
 *  called for ?admin requests — an ordinary visitor's page load never
 *  starts a session or sets this cookie. */
function admin_start_session() {
    if (session_status() === PHP_SESSION_ACTIVE) return;
    ini_set('session.gc_maxlifetime', 14400);
    // Reject a session id the server never issued (blocks fixation), and give
    // the admin session its own name: a gallery living inside another PHP
    // site would otherwise share — and clobber — that site's PHPSESSID.
    ini_set('session.use_strict_mode', '1');
    session_name(admin_session_name());
    // Secure matches is_https_request() rather than being hardcoded true
    // — the one exception this feature already makes for localhost
    // testing over plain HTTP would otherwise never get the cookie back
    // from the browser at all, since a Secure cookie is withheld from
    // any non-HTTPS request.
    session_set_cookie_params([
        'lifetime' => 0,
        'path' => gallery_cookie_path(),
        'secure' => is_https_request(),
        'httponly' => true,
        'samesite' => 'Strict',
    ]);
    session_start();
}

function admin_csrf_token() {
    if (empty($_SESSION['csrf_token'])) {
        $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
    }
    return $_SESSION['csrf_token'];
}

function admin_csrf_valid($submittedToken) {
    return isset($_SESSION['csrf_token']) && is_string($submittedToken)
        && hash_equals($_SESSION['csrf_token'], $submittedToken);
}

/** Checks the request's HTTP Basic Auth credentials against
 *  ADMIN_PASSWORD. Any username is accepted — there's only one account. */
function admin_credentials_valid() {
    $pass = $_SERVER['PHP_AUTH_PW'] ?? null;
    if (!is_string($pass)) return false;
    return password_matches(ADMIN_PASSWORD, $pass);
}

/** A request carried an HTTP Basic password that is wrong: a script's typo, or
 *  — more often — a browser re-sending a password it saved when an older
 *  version of this gallery asked for one. The answer is 401 (so a script can
 *  tell) with the ordinary login form, and never a WWW-Authenticate header:
 *  that header is what makes a browser open its own username/password dialog,
 *  and a stale saved password must not bring that dialog back. */
function admin_reject_saved_credentials() {
    http_response_code(401);
    render_login_page('Enter your access code', '', 'Your browser sent a saved login that no longer matches. Type your current access code.');
}

/** The password form for ?admin and ?reveal: one field, no username, no
 *  browser pop-up. Never indexed or cached or framed. $error is shown above
 *  the field after a wrong password. */
/** The query string of the page a visitor was on when they asked to sign in or out ("?folder=Paris&photo=...&map"), so they
 *  can be brought back to it. Only these three are carried; anything odd is dropped. */
function login_return_query() {
    $ok = function ($k) { return isset($_REQUEST[$k]) && is_string($_REQUEST[$k]) && $_REQUEST[$k] !== '' && strlen($_REQUEST[$k]) < 1024 && strpbrk($_REQUEST[$k], "\0\r\n") === false; };
    $parts = [];
    if ($ok('folder')) $parts[] = 'folder=' . rawurlencode($_REQUEST['folder']);
    if ($ok('photo')) $parts[] = 'photo=' . rawurlencode($_REQUEST['photo']);
    if (isset($_REQUEST['map'])) $parts[] = 'map';
    return $parts ? '?' . implode('&', $parts) : '';
}

/** The password typed into the sign-in form, or null if this request isn't that form being sent. The box is called
 *  access_code (not a name a password manager recognises); login_password is still read, for scripts and older pages. */
function login_form_password() {
    if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') return null;
    foreach (['access_code', 'login_password'] as $name) {
        if (isset($_POST[$name]) && is_string($_POST[$name])) return $name === 'access_code' ? str_replace(["\r", "\n"], '', $_POST[$name]) : $_POST[$name];
    }
    return null;
}

function render_login_page($heading, $blurb, $error = '') {
    header('Content-Type: text/html; charset=UTF-8');
    header('X-Robots-Tag: noindex, nofollow');
    // (This page is deliberately bare: one large line drawing and one box. A heading, a "Continue" button or the words
    // "password" and "sign in" are what make a phone's Autofill decide it is a login form and offer a saved one.)
?>
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="robots" content="noindex, nofollow">
<title>Access</title>
<style>
  :root { color-scheme: dark; }
  html, body { height:100%; }
  body { background:#0f0f10; color:#eaeaea; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; line-height:1.5; margin:0; }
  .wrap { box-sizing:border-box; min-height:100%; max-width:360px; margin:0 auto; padding:12vh 24px 0; display:flex; flex-direction:column; justify-content:flex-start; }
  .mark { display:block; width:104px; height:104px; margin:0 auto 14px; color:#8a8a93; transition:color .2s; }
  .mark:hover, .mark:focus-visible { color:#eaeaea; outline:none; }
  .mark svg { width:100%; height:100%; fill:none; stroke:currentColor; stroke-width:1.1; stroke-linecap:round; stroke-linejoin:round; }
  p { color:#9a9aa0; font-size:0.9rem; margin:0 0 18px; text-align:center; }
  .gate { display:block; width:100%; box-sizing:border-box; padding:12px 14px; font:inherit; font-size:1.05rem; text-align:center; background:#1a1a1c; color:#eaeaea; border:1px solid #3a3a3e; border-radius:10px; -webkit-text-security:disc; text-security:disc; }
  .gate:focus { outline:2px solid #5865f2; outline-offset:1px; }
  /* Safari's own key / contacts Autofill button inside a field */
  .gate::-webkit-credentials-auto-fill-button, .gate::-webkit-contacts-auto-fill-button, .gate::-webkit-autofill-button { display:none !important; visibility:hidden !important; pointer-events:none !important; }
  .err { background:rgba(237,66,69,0.15); color:#ff8a8c; padding:8px 12px; border-radius:8px; font-size:0.9rem; margin-bottom:14px; text-align:center; }
</style>
</head>
<body>
<div class="wrap">
  <a class="mark" id="goback" href="./<?= htmlspecialchars(login_return_query(), ENT_QUOTES, 'UTF-8') ?>" aria-label="Back to the gallery"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="11" width="14" height="9.5" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/><path d="M12 14.6v2.8"/></svg></a>
  <?php if ($blurb !== ''): ?><p><?= htmlspecialchars($blurb, ENT_QUOTES, 'UTF-8') ?></p><?php endif; ?>
  <?php if ($error !== ''): ?><div class="err" role="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
  <form method="post" action="" autocomplete="off">
    <?php // Not a password field (a browser or manager offers to fill, and to save, whatever is typed into one): a text box
          // drawn as dots, named nothing a manager recognises, every common manager told to leave it alone, and read-only
          // until it is focused, which keeps iOS Safari's Autofill from picking it up when the page loads. Return sends it. ?>
    <input type="text" class="gate" id="gate" name="access_code" readonly onfocus="this.removeAttribute('readonly');" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" enterkeyhint="go" autofocus required
           data-lpignore="true" data-1p-ignore="true" data-bwignore="true" data-form-type="other">
  </form>
</div>
<script>
  (function () {
    var box = document.getElementById('gate');
    // Where the browser can't draw text as dots, showing what is typed would be worse than a manager's pop-up: use a real password box.
    if (!(window.CSS && CSS.supports && (CSS.supports('-webkit-text-security', 'disc') || CSS.supports('text-security', 'disc')))) {
      var pw = document.createElement('input');
      pw.type = 'password'; pw.name = box.name; pw.id = box.id; pw.className = box.className; pw.required = true; pw.autocomplete = 'current-password';
      box.parentNode.replaceChild(pw, box); pw.focus();
    }
  })();
  // The lock drawing is the way back, and really goes back to where the visitor was (same scroll position, same open photo)
  // when they came from a page of this site; otherwise its link takes them to that page.
  document.getElementById('goback').addEventListener('click', function (e) {
    try {
      var ref = document.referrer ? new URL(document.referrer) : null;
      if (ref && ref.origin === location.origin && history.length > 1 && !/[?&](reveal|admin)\b/.test(ref.search)) { e.preventDefault(); history.back(); }
    } catch (x) {}
  });
</script>
</body>
</html>
<?php
}

/** A plain-English refusal page for ?admin or ?reveal over an insecure
 *  connection — HTTP Basic Auth credentials are plaintext-equivalent
 *  without TLS, so this fails closed rather than just documenting the
 *  risk. Explains itself and points toward a free certificate, rather
 *  than a bare error that teaches a visitor nothing about what to do
 *  next. */
function render_https_required_page() {
    http_response_code(403);
?>
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>HTTPS required</title>
<style>
  body { background:#0f0f10; color:#eaeaea; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; line-height:1.6; margin:0; }
  .wrap { max-width:560px; margin:0 auto; padding:48px 24px; }
  h1 { font-size:1.4rem; }
  a { color:#aab2ff; text-decoration:none; border-radius:3px; }
  p a:hover { color:#e1e4ff; background:rgba(170,178,255,0.16); box-shadow:0 0 0 3px rgba(170,178,255,0.16); border-radius:3px; }
  code { background:rgba(255,255,255,0.08); padding:1px 6px; border-radius:4px; }
</style>
</head>
<body>
<div class="wrap">
  <h1>HTTPS required</h1>
  <p>This page asks for a password, and over a plain <code>http://</code> connection that password travels in a form anyone on the network path can read. To protect it, this page refuses to run at all without HTTPS.</p>
  <p>If you're testing this on your own machine, visiting it as <code>localhost</code> or <code>127.0.0.1</code> is allowed over plain HTTP. For a real deployment, put this site behind HTTPS — <a href="https://letsencrypt.org/" target="_blank" rel="noopener noreferrer">Let's Encrypt</a> issues free certificates, and most hosting control panels can set one up in a few clicks.</p>
</div>
</body>
</html>
<?php
}

/* -----------------------------------------------------------------------
 * Private view: a hidden item (or an entirely hidden folder-group) is
 * omitted from the public page outright, for any visitor without a
 * valid "reveal" — either the ?reveal password, or a valid admin login
 * (one-directional: admin implies revealed, revealed never implies
 * admin). The reveal cookie holds a random token that the server
 * recognises (see "Browsers that are signed in"), so one browser can be
 * signed out without touching any other; a visitor who never entered a
 * real password has no way to produce a good one. Each item's restriction is a small named value ("public" /
 * "private"), not a bare boolean, so a second audience tier later is an
 * addition, not a rewrite of the flag itself.
 * ----------------------------------------------------------------------- */

/** Sets the private-view token, after a successful ?reveal login: this browser is then recognised as a guest for PRIVATE_VIEW_SIGNED_IN_DAYS
 *  (see "Browsers that are signed in"). A plain cookie, not a PHP session, since this has to survive on the *public*, unauthenticated
 *  page view, not just inside ?admin/?reveal themselves. */
function set_reveal_cookie($stored = null) {
    if (PRIVATE_VIEW_PASSWORD === '' && $stored === null) return;
    browser_issue('view', $stored);
}

/** Makes sure this browser carries the owner's token, on every authenticated admin request: it is how "a valid admin login counts as
 *  revealed too" works, so the owner sees their own hidden items (in the admin's thumbnails and when browsing the plain gallery) without a
 *  second credential, and without needing a private-view password to exist. $password is passed only right after the password was just
 *  set or changed, when the constant still holds the old value: that always makes a new token. */
function set_admin_reveal_cookie($password = null) {
    if (ADMIN_PASSWORD === '' && $password === null) return;
    $b = browser_lookup();
    if ($password === null && $b !== null && $b['kind'] === 'owner') return;   // (already the owner's; its end slides with use)
    browser_issue('owner', $password, $password === null && (isset($_SERVER['PHP_AUTH_PW']) || isset($_SERVER['PHP_AUTH_USER'])) && !(session_status() === PHP_SESSION_ACTIVE && admin_session_authed()));
}

/** True if this visitor can see hidden items: they carry a good token, either the guest's (from ?reveal) or the owner's (from an ?admin
 *  login). With neither password set, no token can be good, so a hidden item simply stays hidden: the same closed-by-default
 *  posture as every other gate in this script. */
function is_revealed() {
    if (link_preview() !== null) return false;   // while previewing a link this browser is not the owner's (gallery and media pages only)
    return browser_lookup() !== null;
}

/** Normalizes a stored restriction value to exactly "inherit", "public",
 *  or "private" — missing/corrupt/unrecognized all degrade to "inherit",
 *  the always-safe default of "nothing changes until you touch it." Used
 *  both for an item's own three-state override (inherit the folder's
 *  setting / always show / always hide — same shape as location-
 *  visibility's own tri-state) and for a folder's own entry, where only
 *  the "private" value is ever meaningful (a folder has nothing to
 *  "inherit" from in this one-level-deep model). */
function item_restriction($entry) {
    $r = is_array($entry) ? ($entry['restriction'] ?? 'inherit') : 'inherit';
    return in_array($r, ['public', 'private'], true) ? $r : 'inherit';
}

/** Whether $file is hidden from an unrevealed visitor. An item's own
 *  explicit "public"/"private" always wins, in either direction — a
 *  folder hidden entirely can still have one specific item deliberately
 *  shown, and a public folder can still have one sensitive item hidden;
 *  neither needs the other's permission. "Inherit" (the default) falls
 *  through to the folders $file sits in: hidden if *any* ancestor, at any
 *  depth, is flagged private (see AUTO_GROUP_BY_FOLDER). */
function file_is_hidden($dir, $file, $itemsData) {
    $own = item_restriction($itemsData[$file] ?? null);
    if ($own === 'private') return true;
    if ($own === 'public') return file_is_unlisted($dir, $file);   // (inside a Not listed folder a public mark changes nothing: the folder is the owner's alone)
    return folder_above_is_private($dir, $file);
}

/** Whether any folder $file sits in, at any depth, is private (what an item with no setting of its own inherits). A folder
 *  made private at any depth hides everything beneath it, the same way a private top-level folder always has. */
function folder_above_is_private($dir, $file) {
    if (AUTO_GROUP_BY_FOLDER && strpos($file, '/') !== false) {
        $path = '';
        foreach (explode('/', dirname($file)) as $segment) {
            $path = $path === '' ? $segment : $path . '/' . $segment;
            if (folder_restriction_cached($dir, $path) === 'private') {
                return true;
            }
        }
    }
    return false;
}

/** Whether any folder $file sits in, at any depth, is Not listed: private, with the owner's "not listed" flag (a folder the owner keeps for
 *  themselves and shares from one photo at a time). It is stored as private plus the flag, so a version that doesn't know the flag
 *  still treats the folder as private. Anything beneath a Not listed folder is Not listed too. */
function folder_above_is_unlisted($dir, $file) {
    return unlisted_root_depth($dir, $file) > 0;
}

/** How many path segments of $file's folders it takes to reach the topmost Not listed folder above it (1 for a top-level folder), or 0
 *  when none of them is. */
function unlisted_root_depth($dir, $file) {
    if (AUTO_GROUP_BY_FOLDER && strpos($file, '/') !== false) {
        $path = ''; $depth = 0;
        foreach (explode('/', dirname($file)) as $segment) {
            $path = $path === '' ? $segment : $path . '/' . $segment;
            $depth++;
            if (folder_unlisted_cached($dir, $path)) return $depth;
        }
    }
    return 0;
}

/** Is the item in a Not listed folder? (Its own marks make no difference: see file_is_hidden.) */
function file_is_unlisted($dir, $file) {
    return folder_above_is_unlisted($dir, $file);
}

/** Is this folder Not listed, on its own or because a folder above it is? */
function folder_is_unlisted($dir, $folderPath) {
    return folder_unlisted_cached($dir, $folderPath) || folder_above_is_unlisted($dir, $folderPath . '/x');
}

/** One folder's own Not listed flag, read once per request like folder_restriction_cached (and reset with it). True only while the
 *  folder is also private, so removing the privacy removes this too. */
function folder_unlisted_cached($dir, $folderRel, $reset = false) {
    static $cache = [];
    if ($reset) {
        $cache = [];
        return null;
    }
    if (!isset($cache[$folderRel])) {
        $data = items_read(resolve_real_path($dir, $folderRel));
        $cache[$folderRel] = item_restriction($data) === 'private' && ($data['unlisted'] ?? null) === true;
    }
    return $cache[$folderRel];
}

/** One folder's own "Gallery of its own" mark, read once per request (and reset with the others when a folder's settings are saved). */
function folder_own_gallery_cached($dir, $folderRel, $reset = false) {
    static $cache = [];
    if ($reset) {
        $cache = [];
        return null;
    }
    if (!isset($cache[$folderRel])) {
        $coll = $folderRel !== '' && collections_any() ? collection_at($dir, $folderRel) : null;   // (a collection keeps its own mark in its own record)
        $cache[$folderRel] = $coll !== null ? !empty($coll['ownGallery']) : (items_read(resolve_real_path($dir, $folderRel))['ownGallery'] ?? null) === true;
    }
    return $cache[$folderRel];
}

/** Is any folder marked "Gallery of its own"? The gallery's own settings file says so (kept by the switch), so a gallery that uses none
 *  reads nothing more and sets no cookie. */
function own_galleries_in_use($dir) {
    static $in = null;
    return $in ?? ($in = (items_read($dir)['ownGalleries'] ?? null) === true);
}

/** The nearest folder at or above $folderPath marked "Gallery of its own", or null: the top of what someone who arrived inside it is offered. */
function own_gallery_boundary($dir, $folderPath) {
    $parts = explode('/', (string) $folderPath);
    for ($n = count($parts); $n >= 1; $n--) {
        $p = implode('/', array_slice($parts, 0, $n));
        if ($p !== '' && folder_own_gallery_cached($dir, $p)) return $p;
    }
    return null;
}

/** Does the collection at $collectionPath hold the folder at $folderPath (the folder itself or one above it, as a member)? That is what makes a click from the
 *  collection into a folder a way someone came, and so a way back. */
function collection_leads_to($dir, $collectionPath, $folderPath) {
    $c = collection_at($dir, $collectionPath);
    if ($c === null || empty($c['ownGallery'])) return false;
    $reg = collections_registry($dir);
    foreach ($c['items'] as $it) {
        if (isset($it['file'])) continue;
        $p = $reg['idPaths'][$it['fid']] ?? null;
        if ($p !== null && $p !== '' && ($folderPath === $p || strpos($folderPath . '/', $p . '/') === 0)) return true;
    }
    return false;
}

/** How high this visitor may go from a folder page: '' for the whole gallery (nothing is limited), or the path of the folder that is the top.
 *  It only matters where a folder is marked "Gallery of its own" and the visitor is not the owner or on a share link (a link decides what its
 *  people see). Someone who arrives inside such a folder (a pasted or typed address, a link from a chat or another site: Sec-Fetch-Site is
 *  not same-origin) has it as their top; someone who came through the gallery above it (a click on one of its own links) keeps the way back,
 *  which a short cookie remembers. A browser that doesn't say keeps what the cookie says. This is tidiness, not a lock: the address of any
 *  public page can still be typed. $folderPath null is a page of the gallery's own front. */
function nav_top($dir, $folderPath) {
    if (!own_galleries_in_use($dir) || is_admin_browser() || link_viewer() !== null || link_preview() !== null || is_bot_request()) return '';
    $boundary = $folderPath === null ? null : own_gallery_boundary($dir, $folderPath);
    $site = strtolower((string) ($_SERVER['HTTP_SEC_FETCH_SITE'] ?? ''));
    $fresh = $site !== '' && $site !== 'same-origin';
    $raw = isset($_COOKIE['gallery_top']) && is_string($_COOKIE['gallery_top']) ? $_COOKIE['gallery_top'] : null;
    $cookieTop = $raw !== null && $raw !== '' && $raw[0] === '/' && strpos($raw, '..') === false ? substr($raw, 1) : null;
    $mine = $boundary ?? '';
    if ($fresh || $cookieTop === null) $top = $mine;
    elseif ($boundary === null) $top = (!is_string($folderPath) || $cookieTop === '' || !collection_leads_to($dir, $cookieTop, $folderPath)) ? '' : $cookieTop;   // (someone who came in through a collection that is a gallery of its own, and clicked into one of its folders, keeps the way back to it)
    else $top = ($cookieTop === '' || $cookieTop === $boundary || strncmp($boundary, $cookieTop . '/', strlen($cookieTop) + 1) === 0) ? $cookieTop : $mine;   // (they came in above it, or at it; anything else is not a way they came)
    if (($fresh || $cookieTop === null) && !headers_sent()) {
        setcookie('gallery_top', '/' . $mine, ['path' => gallery_cookie_path(), 'secure' => is_https_request(), 'httponly' => true, 'samesite' => 'Lax']);
    }
    if (!headers_sent()) { header('Cache-Control: private'); header('Vary: Cookie, Sec-Fetch-Site', false); }
    return $top;
}

/** The owner's view of one photo's privacy: its own setting ("private", "public", or "" when it has none and follows its folder),
 *  whether a folder above it is private (what "" would give it), and what that makes it. */
function owner_privacy_state($dir, $file, $itemsData) {
    $own = item_restriction($itemsData[$file] ?? null);
    $inh = folder_above_is_private($dir, $file);
    return ['own' => $own === 'inherit' ? '' : $own, 'inh' => $inh, 'priv' => $own === 'private' || ($own === 'inherit' && $inh)];
}

/** What pressing a photo's lock does, in words (its tooltip). In a private folder the lock goes round three states; elsewhere it is two. */
function owner_lock_title($ps) {
    if ($ps['inh']) {
        if ($ps['own'] === 'private') return 'Kept private on its own: press to make it public';
        if ($ps['own'] === 'public') return 'Public, though its folder is private: press to follow the folder again';
        return 'Private because its folder is: press to keep it private on its own';
    }
    return $ps['own'] === 'private' ? 'Private: press to make it public' : 'Public: press to make it private';
}

/** "3 photos" (or "3 items" when videos are shown too): a count with its noun, for the private-folder counts. */
function count_noun($n) {
    return number_format((int) $n) . ' ' . (ENABLE_VIDEO ? 'item' : 'photo') . ((int) $n === 1 ? '' : 's');
}

/** What opening a private folder would do, for the owner: how many of the photos and videos under $folderPath would still be
 *  hidden once the folder itself is public (switched private on their own, or inside another private folder) and how many would
 *  become public. Counts everything beneath the folder, to any depth. */
function folder_privacy_counts($dir, $files, $folderPath) {
    $stay = 0; $open = 0;
    $prefix = $folderPath . '/';
    $folders = [];   // each folder's items, read once
    foreach ($files as $f) {
        if (strncmp($f, $prefix, strlen($prefix)) !== 0) continue;
        $where = dirname($f);
        if (!isset($folders[$where])) $folders[$where] = items_read(resolve_real_path($dir, $where))['items'] ?? [];
        $own = item_restriction($folders[$where][basename($f)] ?? null);
        if ($own === 'private') { $stay++; continue; }
        if ($own === 'public') { $open++; continue; }
        $hiddenElsewhere = false;
        if (AUTO_GROUP_BY_FOLDER) {
            $path = '';
            foreach (explode('/', $where) as $segment) {
                $path = $path === '' ? $segment : $path . '/' . $segment;
                if ($path !== $folderPath && folder_restriction_cached($dir, $path) === 'private') { $hiddenElsewhere = true; break; }
            }
        }
        if ($hiddenElsewhere) $stay++; else $open++;
    }
    return ['stay' => $stay, 'open' => $open];
}

/** What the owner sees on a folder's card and button: whether it is private on its own ("own"), only because a folder above it is
 *  ("inh") or neither (""), and, for the first and last, how many photos and videos under it are private (so stay hidden from a
 *  visitor even if the folder is opened). Nothing for anyone but the owner. $withCount is false where only the state is drawn. */
function owner_folder_privacy($dir, $files, $folderPath, $withCount = true) {
    $none = ['state' => '', 'stay' => 0];
    if (!AUTO_GROUP_BY_FOLDER || !is_admin_browser()) return $none;
    $state = folder_restriction_cached($dir, $folderPath) === 'private' ? 'own' : (folder_above_is_private($dir, $folderPath) ? 'inh' : '');
    $stay = $withCount && $state !== 'inh' ? folder_privacy_counts($dir, $files, $folderPath)['stay'] : 0;
    return ['state' => $state, 'stay' => $stay];
}

/** Where "See them" goes for a folder: the folder's page with the photos that are private on their own first, in the order the
 *  folder already has (a ?sort= lasts for that visit only). $folderPath '' is the gallery's own page. */
function folder_private_first_href($dir, $folderPath) {
    $spec = media_sort_spec_for_folder($folderPath === '' ? $dir : resolve_real_path($dir, $folderPath));
    $spec['private'] = true;
    return ($folderPath === '' ? '?' : '?folder=' . rawurlencode($folderPath) . '&') . 'sort=' . media_sort_encode($spec);
}

/** Cache-Control for a photo/video response. Ordinary files are immutable
 *  and public (the URL changes when the file does not, and a CDN is welcome
 *  to hold them). A *hidden* item is only ever served to a trusted viewer,
 *  and a shared cache or CDN keys on the URL, not the cookie: letting one
 *  store it would hand it to the next anonymous request for the same URL.
 *  So hidden items are private and never stored. */
function file_cache_control($dir, $file, $itemsData) {
    return file_is_hidden($dir, $file, $itemsData)
        ? 'private, no-store'
        : 'public, max-age=31536000, immutable';
}

/** Whether a folder is private (on its own, or because a folder above it is). */
function folder_is_private($dir, $folderPath) {
    return folder_restriction_cached($dir, $folderPath) === 'private' || folder_above_is_private($dir, $folderPath);
}

/** One folder's own restriction, read once per request — file_is_hidden()
 *  asks about every ancestor of every file, so without this a deep tree
 *  would re-read the same small JSON files thousands of times.
 *  items_update() resets it, so an admin save is never read back stale. */
function folder_restriction_cached($dir, $folderRel, $reset = false) {
    static $cache = [];
    if ($reset) {
        $cache = [];
        folder_unlisted_cached(null, null, true);
        folder_own_gallery_cached(null, null, true);
        return null;
    }
    if (!isset($cache[$folderRel])) {
        $cache[$folderRel] = item_restriction(items_read(resolve_real_path($dir, $folderRel)));
    }
    return $cache[$folderRel];
}

/* -----------------------------------------------------------------------
 * Where a visitor's IP address comes from. REMOTE_ADDR is the other end of
 * the connection, which behind a CDN (Cloudflare) is the CDN, so every
 * visitor looks like one of a few addresses. The real address arrives in a
 * header, but a header is whatever the sender says: it is only believed when
 * the connection itself comes from a proxy the owner has said to trust (see
 * TRUSTED_PROXY). Used by the share-link logs and the sign-in throttle; the
 * "is this request local" test deliberately stays on the raw connection.
 * ----------------------------------------------------------------------- */

/** An address as raw bytes (4 for IPv4, 16 for IPv6; an IPv4 address written as ::ffff:a.b.c.d becomes 4), or null. */
function ip_binary($ip) {
    $bin = is_string($ip) ? @inet_pton($ip) : false;
    if ($bin === false) return null;
    if (strlen($bin) === 16 && strncmp($bin, str_repeat("\0", 10) . "\xff\xff", 12) === 0) return substr($bin, 12);
    return $bin;
}

/** True if $ip lies in $cidr ("173.245.48.0/20", "2400:cb00::/32", or one bare address). */
function ip_in_cidr($ip, $cidr) {
    $ipBin = ip_binary($ip);
    if ($ipBin === null || !is_string($cidr)) return false;
    $parts = explode('/', $cidr, 2);
    $netBin = ip_binary($parts[0]);
    if ($netBin === null || strlen($netBin) !== strlen($ipBin)) return false;
    $bits = isset($parts[1]) ? (ctype_digit($parts[1]) ? (int) $parts[1] : -1) : strlen($netBin) * 8;
    if ($bits < 0 || $bits > strlen($netBin) * 8) return false;
    $whole = intdiv($bits, 8);
    if ($whole > 0 && strncmp($ipBin, $netBin, $whole) !== 0) return false;
    $rest = $bits % 8;
    if ($rest === 0) return true;
    $mask = (0xFF << (8 - $rest)) & 0xFF;
    return ((ord($ipBin[$whole]) ^ ord($netBin[$whole])) & $mask) === 0;
}

function ip_in_ranges($ip, $ranges) {
    foreach ($ranges as $r) if (ip_in_cidr($ip, $r)) return true;
    return false;
}

/** Cloudflare's published address ranges (https://www.cloudflare.com/ips/), as of October 2026. They change rarely; an
 *  address that isn't listed here can be added with TRUSTED_PROXY_RANGES. */
function cloudflare_ranges() {
    return ['173.245.48.0/20', '103.21.244.0/22', '103.22.200.0/22', '103.31.4.0/22', '141.101.64.0/18', '108.162.192.0/18',
            '190.93.240.0/20', '188.114.96.0/20', '197.234.240.0/22', '198.41.128.0/17', '162.158.0.0/15', '104.16.0.0/13',
            '104.24.0.0/14', '172.64.0.0/13', '131.0.72.0/22',
            '2400:cb00::/32', '2606:4700::/32', '2803:f800::/32', '2405:b500::/32', '2405:8100::/32', '2a06:98c0::/29', '2c0f:f248::/32'];
}

/** The proxy addresses whose headers are believed under the current TRUSTED_PROXY setting. */
function trusted_proxy_ranges() {
    $own = array_values(array_filter((array) TRUSTED_PROXY_RANGES, 'is_string'));
    return TRUSTED_PROXY === 'cloudflare' ? array_merge(cloudflare_ranges(), $own) : $own;
}

/** The visitor's address: the connection's, unless it comes from a trusted proxy, which says who is behind it. */
function client_ip() {
    static $ip = null;
    if ($ip !== null) return $ip;
    $peer = (string) ($_SERVER['REMOTE_ADDR'] ?? '');
    $ip = $peer;
    if ($peer !== '' && TRUSTED_PROXY !== 'direct' && ip_in_ranges($peer, trusted_proxy_ranges())) {
        if (TRUSTED_PROXY === 'cloudflare') {
            $header = trim((string) ($_SERVER['HTTP_CF_CONNECTING_IP'] ?? ''));
            if (filter_var($header, FILTER_VALIDATE_IP)) $ip = $header;
        } else {
            // The proxies add the address they received from to the right-hand end: the client is the first one, reading
            // from the right, that is not itself a trusted proxy.
            $chain = array_map('trim', explode(',', (string) ($_SERVER['HTTP_X_FORWARDED_FOR'] ?? '')));
            for ($i = count($chain) - 1; $i >= 0; $i--) {
                if (!filter_var($chain[$i], FILTER_VALIDATE_IP)) break;
                $ip = $chain[$i];
                if (!ip_in_ranges($chain[$i], trusted_proxy_ranges())) break;
            }
        }
    }
    return $ip === '' ? 'unknown' : $ip;
}

/** What to tell the owner when "The connection" is chosen but the request looks like it came through a proxy: only when the
 *  connection itself is a proxy's (inside Cloudflare's ranges, or a private or loopback address with a forwarding header), since a
 *  web server that already passes the real address on (nginx's real-ip rule) leaves a Cloudflare header behind and is right as it is. */
function client_ip_proxy_hint() {
    if (TRUSTED_PROXY !== 'direct') return '';
    $peer = (string) ($_SERVER['REMOTE_ADDR'] ?? '');
    if (!filter_var($peer, FILTER_VALIDATE_IP)) return '';
    $cf = trim((string) ($_SERVER['HTTP_CF_CONNECTING_IP'] ?? '')) !== '';
    $fwd = $cf || trim((string) ($_SERVER['HTTP_X_FORWARDED_FOR'] ?? '')) !== '';
    if ($cf && ip_in_ranges($peer, cloudflare_ranges())) return 'This request came through Cloudflare: choose Cloudflare so the real address is used.';
    $private = !filter_var($peer, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE);
    if ($fwd && $private && !is_local_request()) return 'This request came through a proxy: choose the matching setting so the real address is used.';
    return '';
}

/** The country of this visitor ("US"), or '': what a trusted proxy says (Cloudflare's header; CloudFront's and Vercel's when the proxy setting is "another
 *  proxy" and the connection comes from one you named), else the country file when that option is on. */
function client_country() {
    static $c = null;
    if ($c !== null) return $c;
    $peer = (string) ($_SERVER['REMOTE_ADDR'] ?? '');
    $h = '';
    if ($peer !== '' && TRUSTED_PROXY !== 'direct' && ip_in_ranges($peer, trusted_proxy_ranges())) {
        $h = TRUSTED_PROXY === 'cloudflare' ? (string) ($_SERVER['HTTP_CF_IPCOUNTRY'] ?? '') : (string) ($_SERVER['HTTP_CLOUDFRONT_VIEWER_COUNTRY'] ?? $_SERVER['HTTP_X_VERCEL_IP_COUNTRY'] ?? '');
    }
    $h = strtoupper(trim($h));
    if (!preg_match('/^[A-Z]{2}$/', $h) || $h === 'XX' || $h === 'T1') $h = '';
    return $c = $h !== '' ? $h : geo_db_country(client_ip());
}

/* -----------------------------------------------------------------------
 * Share links. A link is a record in .gallery-links.php (a guarded data file
 * beside this script, like the others): who it is for, what it may show, how
 * many times it may be opened and until when. Opening the address
 * (?link=<token>, or the tidy /<token> the server rule maps onto it) shows a page with one button; pressing it
 * counts a use (unless this browser, or this address a moment ago, already
 * did) and sets a cookie that is checked against the record on every request,
 * so pausing, revoking or ending a link cuts off people already in. A person
 * holding a link is never the owner, and never sees more than the link says.
 * ----------------------------------------------------------------------- */


function links_path() { return __DIR__ . '/.gallery-links.php'; }
function links_default() { return ['links' => [], 'folderIndex' => [], 'seenAt' => 0]; }
function links_read() { return json_file_read(links_path(), links_default()); }
function links_update($modifier) { return json_file_update(links_path(), links_default(), $modifier, true); }

/** A random token of letters and digits, LINK_TOKEN_LENGTH long (8: about 48 bits; the lockout allows few guesses), with no modulo bias. */
function link_new_token() {
    $alphabet = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
    $token = '';
    while (strlen($token) < LINK_TOKEN_LENGTH) {
        $v = ord(random_bytes(1));
        if ($v < 248) $token .= $alphabet[$v % 62];   // 248 = 4 x 62
    }
    return $token;
}
function link_new_id() { return bin2hex(random_bytes(5)); }
/** An address a link can have: the random token, or a custom name (4 to 40 letters, digits and hyphens, none at either end). */
function link_token_format_ok($t) { return is_string($t) && preg_match('/^[A-Za-z0-9](?:[A-Za-z0-9-]{2,38})[A-Za-z0-9]$/', $t) === 1; }

/** The name of a folder or file at the gallery's top level that has this custom link name (ignoring case), or ''. A link added before the folder
 *  (an FTP upload later) is fine with the current server rule, but worth saying, and a clue when an older rule is still in place. */
function link_name_shadowed_by($name, $dir) {
    $n = strtolower((string) $name);
    foreach ((array) @scandir($dir) as $entry) if ($entry !== '.' && $entry !== '..' && strtolower($entry) === $n) return $entry;
    foreach (array_keys(gallery_mounts()) as $mountName) if (strtolower((string) $mountName) === $n) return (string) $mountName;
    return '';
}

/** What is wrong with this custom name, in words, or '' when it can be used: the shape, the reserved words, a folder or file of
 *  the gallery's top level, or another link's address (current or replaced). $exceptId is the link being edited. */
function link_custom_name_problem($name, $dir, $exceptId = '') {
    $n = strtolower($name);
    if (strlen($n) < 4 || strlen($n) > 40 || preg_match('/^[a-z0-9][a-z0-9-]*[a-z0-9]$/', $n) !== 1) return 'An address needs 4 to 40 letters, digits or hyphens, and cannot start or end with a hyphen.';
    if (in_array($n, LINK_RESERVED_NAMES, true)) return '"' . $n . '" is an address the gallery uses itself: pick another.';
    foreach ([$dir, __DIR__] as $d) {
        foreach ((array) @scandir($d) as $entry) {
            if ($entry === '.' || $entry === '..') continue;
            if (strtolower($entry) === $n || strtolower(pathinfo($entry, PATHINFO_FILENAME)) === $n && pathinfo($entry, PATHINFO_EXTENSION) === 'php') return 'A folder or file called "' . $entry . '" is in the gallery, and it would hide this address: pick another.';
        }
    }
    foreach (array_keys(gallery_mounts()) as $mountName) {
        if (strtolower((string) $mountName) === $n) return 'A folder called "' . $mountName . '" is in the gallery, and it would hide this address: pick another.';
    }
    foreach ((array) (links_read()['links'] ?? []) as $l) {
        if (!is_array($l) || ($l['id'] ?? '') === $exceptId) continue;
        foreach (link_all_addresses($l) as $t) {
            if (strtolower($t) === $n) return 'Another link has (or had) that address: pick another.';
        }
    }
    return '';
}

/** A new link record with every field at its default. */
function link_record_new($now) {
    return [
        'id' => link_new_id(), 'label' => '', 'token' => link_new_token(), 'custom' => false, 'status' => 'active', 'created' => $now,
        'startsAt' => 0, 'endsAt' => 0, 'maxOpens' => 0, 'opens' => 0,
        'note' => '', 'titleMode' => 'gallery', 'titleText' => '', 'picture' => false, 'pictureSeed' => '', 'pictureFile' => '',
        'scope' => ['type' => 'all', 'folders' => [], 'photos' => []], 'openIn' => '',
        'downloads' => ['mode' => 'off', 'folders' => []], 'zip' => ['mode' => 'off', 'folders' => []],
        'locations' => 'public', 'headsUp' => 'default',
        'lastOpened' => 0, 'lastOpen' => ['ip' => '', 'at' => 0], 'revokedAt' => 0, 'pausedAt' => 0,
    ];
}

/** The link with this token (compared in constant time against every link), or null. */
function link_find_by_token($data, $token) {
    $found = null;
    foreach ((array) ($data['links'] ?? []) as $l) {
        if (!is_array($l) || link_is_public_log($l) || !isset($l['token']) || !is_string($l['token'])) continue;
        // (a custom name is stored in lower case and answers in any case; a random token is exact)
        if (!empty($l['custom']) ? hash_equals(strtolower($l['token']), strtolower((string) $token)) : hash_equals($l['token'], (string) $token)) $found = $l;
    }
    return $found;
}

/** Every address a link answers to or holds: its own, the replaced ones and the ones kept working. */
function link_all_addresses($l) {
    $out = [(string) ($l['token'] ?? '')];
    foreach ((array) ($l['oldTokens'] ?? []) as $t) $out[] = (string) $t;
    foreach ((array) ($l['aliases'] ?? []) as $a) if (is_array($a)) $out[] = (string) ($a['name'] ?? '');
    return array_values(array_filter($out, function ($t) { return $t !== ''; }));
}

/** [the link, the kept address it was reached by] for an old address that was kept working, or null. */
function link_find_by_alias($data, $token) {
    $found = null;
    foreach ((array) ($data['links'] ?? []) as $l) {
        if (!is_array($l) || link_is_public_log($l)) continue;
        foreach ((array) ($l['aliases'] ?? []) as $a) {
            if (!is_array($a) || !is_string($a['name'] ?? null)) continue;
            if (!empty($a['custom']) ? hash_equals(strtolower($a['name']), strtolower((string) $token)) : hash_equals($a['name'], (string) $token)) $found = [$l, $a['name']];
        }
    }
    return $found;
}

/** True for an address that looks like a name of the owner's own; a random code is 8 letters and digits (16 before 2.6.5) with a capital among them. */
function link_address_is_custom($name) {
    $name = (string) $name;
    return !(preg_match('/^(?:[A-Za-z0-9]{8}|[A-Za-z0-9]{16})$/', $name) === 1 && preg_match('/[A-Z]/', $name) === 1);
}

/** An address as it is shown in the log: a name of your own whole, a random code as its first four and last four characters (the first two and last
 *  two of an 8-character one, so the full address is never on the page). */
function link_address_label($name, $custom) {
    $name = (string) $name;
    if ($custom || strlen($name) < 8) return $name;
    return strlen($name) === 8 ? substr($name, 0, 2) . '…' . substr($name, -2) : substr($name, 0, 4) . '…' . substr($name, -4);
}

/** Counts one use of a kept address (how many times, and when last), so the owner can tell whether it can go. */
function link_alias_used($id, $name) {
    links_update(function (&$d) use ($id, $name) {
        foreach ((array) ($d['links'][$id]['aliases'] ?? []) as $i => $a) {
            if (is_array($a) && ($a['name'] ?? '') === $name) { $d['links'][$id]['aliases'][$i]['hits'] = (int) ($a['hits'] ?? 0) + 1; $d['links'][$id]['aliases'][$i]['last'] = time(); }
        }
    });
}

/** What the log says about one old address: [uses, distinct IPs, last time] from its 'via' notes (a kept address) or 'tried' notes (a paused one). */
function link_address_log_stats($log, $kind, $name) {
    $uses = 0; $ips = []; $last = 0;
    foreach ((array) ($log[$kind] ?? []) as $e) {
        if (!isset($e['n'][$name])) continue;
        $uses += (int) $e['n'][$name]; $ips[(string) ($e['ip'] ?? '')] = true; $last = max($last, (int) ($e['last'] ?? 0));
    }
    return [$uses, count($ips), $last];
}

/** The stored spelling of the replaced address that matches this one (a custom name answers in any case), or ''. */
function link_old_name($link, $token) {
    foreach ((array) ($link['oldTokens'] ?? []) as $old) if (is_string($old) && hash_equals(strtolower($old), strtolower((string) $token))) return $old;
    return '';
}

/** The link that used to have this address (before "Replace address"), or null. */
function link_find_by_old_token($data, $token) {
    $found = null;
    foreach ((array) ($data['links'] ?? []) as $l) {
        foreach ((array) ($l['oldTokens'] ?? []) as $old) if (is_string($old) && hash_equals(strtolower($old), strtolower((string) $token))) $found = $l;
    }
    return $found;
}

/** What a link is right now: active, paused, revoked, scheduled (not started), expired, used_up (no opens left). */
function link_state($l, $now = null) {
    $now = $now ?? time();
    $status = $l['status'] ?? 'active';
    if ($status === 'revoked') return 'revoked';
    if ($status === 'paused') return 'paused';
    if ((int) ($l['endsAt'] ?? 0) > 0 && $now >= (int) $l['endsAt']) return 'expired';
    if ((int) ($l['startsAt'] ?? 0) > $now) return 'scheduled';
    if ((int) ($l['maxOpens'] ?? 0) > 0 && (int) ($l['opens'] ?? 0) >= (int) $l['maxOpens']) return 'used_up';
    return 'active';
}
/** Someone already signed in through the link keeps access while it is active or only out of opens. */
function link_is_live($l, $now = null) { return in_array(link_state($l, $now), ['active', 'used_up'], true); }

/* The public address's log. It is kept in the visitor log like a link's, under the fixed source id PUBLIC_LOG_ID. It is never a link
 * anyone can use: nothing looks it up by address or by cookie. (Versions before 2.6.5 kept a stand-in record for it in the links file;
 * Tidy up removes it.) */
function link_is_public_log($l) { return is_array($l) && ($l['kind'] ?? '') === 'public'; }

/** Is this visitor one the public address's log should record? Not the owner, nor the private-view password, nor someone using a share
 *  link (they have their own log), nor a link-preview bot. */
function public_log_wanted() {
    static $w = null;
    if ($w !== null) return $w;
    return $w = LOG_PUBLIC_VISITS && visitlog_ready() && link_viewer() === null && !is_revealed() && !is_admin_browser() && link_preview() === null && !is_bot_request();
}

/** How this page was reached, for the public address's log: an arrival (an address typed or pasted, a bookmark, a link from another site or an app: the
 *  browser says it was not a click inside the gallery) as [folder path ('' is the front page) or, for a Not listed photo opened by its address, the photo,
 *  how, whether it was that photo]; null for a click inside the gallery, or a browser that doesn't say. */
function public_log_arrival() {
    if (!public_log_wanted()) return null;
    $site = strtolower((string) ($_SERVER['HTTP_SEC_FETCH_SITE'] ?? ''));
    if ($site === '' || $site === 'same-origin') return null;
    $how = $site === 'none' ? 'typed' : (in_array($site, ['cross-site', 'same-site'], true) ? 'link' : 'other');
    $pass = $GLOBALS['photoPass'] ?? null;
    if ($pass !== null) return ['f' => $pass, 'h' => $how, 'u' => true];
    $folder = $GLOBALS['currentFolderPath'] ?? null;
    return ['f' => $folder === null ? '' : $folder, 'h' => $how];
}

/** The public address's records have no record of their own in the links file: this stands for them wherever a log is written (null while the public log is not wanted). */
function public_log_link() {
    return ['id' => PUBLIC_LOG_ID, 'label' => 'Public', 'token' => '', 'kind' => 'public'];
}

function link_cookie_value($l) {
    return $l['id'] . '.' . hash_hmac('sha256', 'link|' . $l['id'] . '|' . $l['token'] . '|' . __DIR__, install_secret());
}
function link_set_cookie($l) {
    install_secret(true);
    $expires = time() + 31536000;
    if ((int) ($l['endsAt'] ?? 0) > 0) $expires = min($expires, (int) $l['endsAt']);
    setcookie(LINK_COOKIE_NAME, link_cookie_value($l), ['expires' => $expires, 'path' => gallery_cookie_path(), 'secure' => is_https_request(), 'httponly' => true, 'samesite' => 'Lax']);
}

/** The link record this request is signed in through, or null. Reads the links file only when the cookie is there, so an
 *  ordinary visitor costs nothing. The owner's own browser is never a link holder. */
function link_viewer() {
    static $resolved = false, $link = null;
    if ($resolved) return $link;
    $resolved = true;
    if (!ENABLE_SHARE_LINKS) return null;
    if (($previewed = link_preview()) !== null) return $link = $previewed;
    $cookie = $_COOKIE[LINK_COOKIE_NAME] ?? '';
    if (!is_string($cookie) || !preg_match('/^([0-9a-f]{10})\.[0-9a-f]{64}$/', $cookie, $m)) return null;
    if (is_admin_browser()) return null;
    $l = links_read()['links'][$m[1]] ?? null;
    if (!is_array($l) || link_is_public_log($l) || !isset($l['token']) || !hash_equals(link_cookie_value($l), $cookie) || !link_is_live($l)) return null;
    return $link = $l;
}
/** A person using a share link, and not someone with the owner's or the private-view sign-in. */
function viewer_is_link() { return !is_revealed() && link_viewer() !== null; }

/* Preview as this link. The owner presses it on the Shares tab; a signed cookie then makes this browser see the gallery exactly as
 * someone using that link does (the same checks, the same pages, no owner tools), and nothing is counted or logged. It never touches
 * the admin pages (?admin keeps the owner's sign-in), a thumbnail asked for by an admin page is still the owner's, and it ends by
 * itself after four hours or when "Exit preview" is pressed. */
function preview_cookie_value($l, $ts) {
    return $l['id'] . '.' . (int) $ts . '.' . hash_hmac('sha256', 'preview|' . $l['id'] . '|' . (int) $ts . '|' . $l['token'] . '|' . __DIR__, install_secret());
}
function preview_set_cookie($l) {
    install_secret(true);
    $now = time();
    setcookie(PREVIEW_COOKIE_NAME, preview_cookie_value($l, $now), ['expires' => $now + PREVIEW_SECONDS, 'path' => gallery_cookie_path(), 'secure' => is_https_request(), 'httponly' => true, 'samesite' => 'Lax']);
}
function preview_clear_cookie() {
    gallery_cookie_expire(PREVIEW_COOKIE_NAME, 'Lax');
}
/** True when the page that asked for this picture or video is one of the admin's own pages (so the owner gets the owner's version of it). */
function preview_referer_is_admin() {
    $ref = (string) ($_SERVER['HTTP_REFERER'] ?? '');
    if ($ref === '') return false;
    $query = parse_url($ref, PHP_URL_QUERY); $host = parse_url($ref, PHP_URL_HOST); $mine = parse_url('//' . (string) ($_SERVER['HTTP_HOST'] ?? ''), PHP_URL_HOST);
    if (!is_string($query) || !is_string($host) || strcasecmp($host, (string) $mine) !== 0) return false;
    parse_str($query, $q);
    return array_key_exists('admin', $q);
}
/** The link a preview cookie in this browser belongs to, if the cookie is genuine, fresh and the link isn't revoked, whatever page is being asked for. */
function preview_cookie_link() {
    static $resolved = false, $link = null;
    if ($resolved) return $link;
    $resolved = true;
    if (!ENABLE_SHARE_LINKS) return null;
    $cookie = $_COOKIE[PREVIEW_COOKIE_NAME] ?? '';
    if (!is_string($cookie) || !preg_match('/^([0-9a-f]{10})\.(\d{1,12})\.[0-9a-f]{64}$/', $cookie, $m)) return null;
    $ts = (int) $m[2];
    if ($ts > time() + 60 || time() - $ts > PREVIEW_SECONDS) return null;
    $l = links_read()['links'][$m[1]] ?? null;
    if (!is_array($l) || !isset($l['token']) || !hash_equals(preview_cookie_value($l, $ts), $cookie) || link_state($l) === 'revoked') return null;
    return $link = $l;
}
/** The link the owner is previewing, as far as THIS request is concerned: gallery and media pages only. The admin's own pages are always the
 *  owner's, and so is a picture or video that an admin page asked for. */
function link_preview() {
    static $resolved = false, $link = null;
    if ($resolved) return $link;
    $resolved = true;
    if (isset($_GET['admin'])) return null;
    if ((isset($_GET['img']) || isset($_GET['video']) || isset($_GET['strip']) || isset($_GET['preview'])) && preview_referer_is_admin()) return null;
    return $link = preview_cookie_link();
}
/** The strip across the top of a previewed gallery: who it is a preview of, a list of what the link includes, and the way out. */
function render_link_preview_banner($l, $dir, $files) {
    $esc = function ($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); };
    $map = folder_id_map($dir, $files);
    $index = (array) (links_read()['folderIndex'] ?? []);
    $rootFid = folder_id_read($dir);
    $report = link_scope_report($l, $map, $index, $dir, $rootFid);
    $state = link_state($l);
    $type = $l['scope']['type'] ?? 'all';
    $yes = function ($html) { return '<li class="yes">' . ui_icon('check') . '<span>' . $html . '</span></li>'; };
    $no = function ($html) { return '<li class="no">' . ui_icon('close') . '<span>' . $html . '</span></li>'; };
    $items = [];
    if ($type !== 'public') $items[] = $yes(($type === 'all' ? 'The whole gallery, public and private, including what you add later' : ($type === 'folders' && !array_filter(array_column($report['folders'], 'pub')) ? $esc(implode(', ', array_map(function ($x) { return $x['label']; }, $report['folders']))) . ' and everything inside ' . (count($report['folders']) === 1 ? 'it' : 'them') : link_scope_text_html($l, $report))));
    $items[] = $yes('All public folders and photos, as any visitor sees them');
    if ($type === 'public') $items[] = $no('<strong>Nothing private</strong> is shown or hinted at');
    elseif ($type !== 'all') $items[] = $no('Your other private folders and photos are <strong>not shown and not hinted at</strong>');
    if (array_filter(array_column($report['folders'], 'pub'))) $items[] = $no('Private photos and videos in the folders marked <strong>public items only</strong> are not shown (unless you named one)');
    foreach (['downloads' => ['Originals can be downloaded: ', 'Original downloads are off.'], 'zip' => ['ZIP of a folder: ', 'ZIP downloads are off.']] as $cap => [$onText, $offText]) {
        if (($l[$cap]['mode'] ?? 'off') === 'off') $items[] = $no($offText);
        else $items[] = $yes($onText . strtolower(link_capability_text_html($l, $cap, $report, $map, $index, $dir, $rootFid)));
    }
    $items[] = $yes(($l['locations'] ?? 'public') === 'all' ? 'Locations: every saved location is shown' : 'Locations: only the ones set to show');
    $quiet = $state === 'active' || $state === 'used_up' ? '' : ' This link is ' . $esc(strtolower(link_state_label($state))) . ' right now, so the people who have it see nothing until that changes.';
    return '<div class="link-preview" id="link-preview" role="status"><div class="lp-bar">' . ui_icon('eye')
        . '<span class="lp-t"><strong>Previewing as ' . $esc($l['label']) . '.</strong> You see exactly what this link shows. Nothing you do here is counted or logged.' . $quiet . '</span>'
        . '<button type="button" class="lp-more" aria-expanded="false" aria-controls="lp-panel">What\'s included ' . ui_icon('chev-down') . '</button>'
        . '<a class="lp-exit" href="?exitpreview">Exit preview</a></div>'
        . '<div class="lp-panel" id="lp-panel" hidden><h3>What this link includes</h3><ul>' . implode('', $items) . '</ul><p class="lp-note">Pressing Exit preview ends the preview and takes you back to the Shares tab.</p></div></div>'
        . '<script>(function(){var b=document.querySelector("#link-preview .lp-more"),p=document.getElementById("lp-panel");if(!b||!p)return;b.addEventListener("click",function(){var o=p.hidden;p.hidden=!o;b.setAttribute("aria-expanded",o?"true":"false");});})();</script>';
}

/** Whether a link shows the "expires on" line at the top of the gallery: its own choice, else the site setting; never when it has no end date. */
function link_headsup_on($l) {
    $h = $l['headsUp'] ?? 'default';
    return ($h === 'on' || ($h === 'default' && SHARE_HEADS_UP)) && (int) ($l['endsAt'] ?? 0) > 0;
}

/** The thin line itself. The page's script puts the time in the visitor's own zone, turns it amber in the last day and remembers a dismissal. */
function render_link_headsup($l) {
    $ends = (int) $l['endsAt'];
    return '<div class="link-headsup" id="link-headsup" role="status" data-ends="' . $ends . '" data-key="' . htmlspecialchars($l['id'] . '.' . $ends, ENT_QUOTES, 'UTF-8') . '">'
        . '<span class="lh-t">The link being used to access this media expires on <time datetime="' . gmdate('c', $ends) . '">' . htmlspecialchars(gmdate('D, M j, g:i a', $ends) . ' UTC', ENT_QUOTES, 'UTF-8') . '</time>.</span>'
        . '<button type="button" class="lh-x" aria-label="Dismiss" title="Dismiss">&times;</button></div>';
}

/* A folder's hidden id. A share link limited to chosen folders remembers each by an id kept in the folder's own settings file
 * (stamped the first time a link covers it), not by its name: renaming or moving the folder keeps the link working, a folder
 * deleted or wiped is simply gone, and a new folder that happens to reuse the old name has no id and is not covered. */

function folder_id_read($folderReal) {
    $id = items_read($folderReal)['folderId'] ?? '';
    return is_string($id) && preg_match('/^[0-9a-f]{12}$/', $id) ? $id : '';
}

/** The folder's id, giving it one first if it has none. '' when that can't be written (the folder isn't writable). */
function folder_id_stamp($folderReal) {
    $id = folder_id_read($folderReal);
    if ($id !== '') return $id;
    $new = bin2hex(random_bytes(6));
    $failedBefore = !empty($GLOBALS['__data_write_failed']);
    $GLOBALS['__data_write_failed'] = false;
    items_update($folderReal, function (&$d) use ($new) {
        if (!is_string($d['folderId'] ?? null) || $d['folderId'] === '') $d['folderId'] = $new;
    });
    $failed = !empty($GLOBALS['__data_write_failed']);
    $GLOBALS['__data_write_failed'] = $failedBefore || $failed;
    return $failed ? '' : folder_id_read($folderReal);
}

/** The id of the folder at this relative path ('' is the gallery's own folder), read once per request. */
function folder_id_cached($dir, $rel) {
    static $cache = [];
    if (!isset($cache[$rel])) $cache[$rel] = folder_id_read($rel === '' ? $dir : resolve_real_path($dir, $rel));
    return $cache[$rel];
}

/** Every id found among the folders that hold $files: id => the relative paths that carry it (more than one means a folder was copied). */
function folder_id_map_folders($dir, $files) {
    $map = [];
    foreach (all_folder_paths($files) as $rel) {
        $id = folder_id_cached($dir, $rel);
        if ($id !== '') $map[$id][] = $rel;
    }
    return $map;
}

/** The same, with the collections too: a link names a collection the way it names a folder, by an id, and it is found where it lives. */
function folder_id_map($dir, $files) {
    $map = folder_id_map_folders($dir, $files);
    if (collections_any()) foreach (collections_registry($dir, $files)['byPath'] as $cPath => $cRec) $map[$cRec['id']][] = $cPath;
    return $map;
}

/** The ids that more than one folder carries: they point at nothing until the owner sorts it out. Kept in the links file so the
 *  routes that answer before the tree is scanned know too. */
function link_ambiguous_set($set = null) {
    static $cache = null;
    if ($set !== null) { $cache = $set; return $cache; }
    if ($cache === null) $cache = array_fill_keys(array_filter((array) (links_read()['ambiguous'] ?? []), 'is_string'), true);
    return $cache;
}
function link_scan_ambiguity($dir, $allFiles) {
    $dups = [];
    foreach (folder_id_map($dir, $allFiles) as $id => $paths) if (count($paths) > 1) $dups[$id] = true;
    $stored = array_keys(link_ambiguous_set());
    $now = array_keys($dups); sort($stored); sort($now);
    if ($stored !== $now) links_update(function (&$d) use ($now) { $d['ambiguous'] = $now; });
    link_ambiguous_set($dups);
}

/** True if the item is inside one of the folders with these ids (the folder it is in, or any folder above it). */
function link_item_under_folder_ids($dir, $file, $fids) {
    $set = array_fill_keys(array_filter((array) $fids, 'is_string'), true);
    if (!$set) return false;
    $amb = link_ambiguous_set();
    $parts = explode('/', $file); array_pop($parts);
    $prefix = '';
    foreach ($parts as $seg) {
        $prefix = $prefix === '' ? $seg : $prefix . '/' . $seg;
        $id = folder_id_cached($dir, $prefix);
        if ($id !== '' && isset($set[$id]) && !isset($amb[$id])) return true;
    }
    return false;
}

/** Is the item public (not private)? Without the gallery's item settings to ask, it is not: a link never shows what it can't be sure of. */
function link_item_is_public($dir, $file, $itemsData = null) {
    $data = $itemsData ?? ($GLOBALS['itemsData'] ?? null);
    return is_array($data) && !file_is_hidden($dir, $file, $data);
}

/** How a link's folders cover an item: 'all' (it is under a folder the link shares with everything inside), 'public' (it is under folders
 *  the link shares as "public items only", and under no other), or '' (under none of them). A private folder's items are all private,
 *  so a public-only folder that is itself private covers nothing. */
function link_folder_cover($dir, $file, $fids, $publicOnly = []) {
    $set = array_fill_keys(array_filter((array) $fids, 'is_string'), true);
    if (!$set) return '';
    $pub = array_fill_keys(array_filter((array) $publicOnly, 'is_string'), true);
    $amb = link_ambiguous_set();
    $cover = '';
    foreach (array_keys($set) as $cid) {   // a collection the link names covers the files it holds (as it holds them); the link's own "public items only" applies to it as to a folder
        if ($cid[0] !== 'c' || file_is_unlisted($dir, $file) || !collection_holds_file($dir, $cid, $file)) continue;   // (a Not listed folder's photos come through no collection, as through no folder above it: it has to be picked itself)
        if (!isset($pub[$cid])) return 'all';
        $cover = 'public';
    }
    $parts = explode('/', $file); array_pop($parts);
    $prefix = '';
    $from = max(0, unlisted_root_depth($dir, $file) - 1);   // (a folder picked above a Not listed one does not bring it along; the Not listed folder, or one inside it, has to be picked)
    $n = 0;
    foreach ($parts as $seg) {
        $prefix = $prefix === '' ? $seg : $prefix . '/' . $seg;
        if ($n++ < $from) continue;
        $id = folder_id_cached($dir, $prefix);
        if ($id === '' || !isset($set[$id]) || isset($amb[$id])) continue;
        if (!isset($pub[$id])) return 'all';
        $cover = 'public';
    }
    return $cover;
}

/** May the link $l show this item? */
function link_allows_item($l, $dir, $file, $itemsData = null) {
    $type = $l['scope']['type'] ?? '';
    if ($type === 'all') return !file_is_unlisted($dir, $file);   // ("Everything" leaves out a Not listed folder: that one is shared only by picking it)
    if ($type === 'folders' || $type === 'mixed') {
        $cover = link_folder_cover($dir, $file, $l['scope']['folders'] ?? [], $l['scope']['publicOnly'] ?? []);
        if ($cover === 'all') return true;
        if ($cover === 'public' && link_item_is_public($dir, $file, $itemsData)) return true;   // ("public items only": the private ones are left out, unless one is named below)
        if ($type === 'folders') return false;
    }
    if ($type === 'photos' || $type === 'mixed') {   // ("some folders and some photos": under a picked folder, or a picked photo)
        $set = [];
        foreach ((array) ($l['scope']['photos'] ?? []) as $p) if (is_array($p) && is_string($p['fid'] ?? null) && is_string($p['name'] ?? null)) $set[$p['fid'] . "\0" . $p['name']] = true;
        if (!$set) return false;
        $slash = strrpos($file, '/');
        $fid = folder_id_cached($dir, $slash === false ? '' : substr($file, 0, $slash));
        return $fid !== '' && !isset(link_ambiguous_set()[$fid]) && isset($set[$fid . "\0" . basename($file)]);
    }
    return false;
}

/** Is this item one the link names as a photo (not merely one inside a folder it shares)? Those are shown as loose tiles, not inside a folder card. */
function link_item_is_picked_photo($l, $dir, $file, $itemsData = null) {
    $type = $l['scope']['type'] ?? '';
    if ($type !== 'photos' && $type !== 'mixed') return false;
    if ($type === 'mixed') {   // (inside a folder the link shares, it is part of that folder; named as well as private inside a "public items only" folder, it is a tile of its own)
        $cover = link_folder_cover($dir, $file, $l['scope']['folders'] ?? [], $l['scope']['publicOnly'] ?? []);
        if ($cover === 'all' || ($cover === 'public' && link_item_is_public($dir, $file, $itemsData))) return false;
    }
    return link_allows_item($l, $dir, $file, $itemsData);
}

/** The topmost Not listed folder $file sits in ('' when it is in none): the one whose own choices (downloads) cover everything beneath it. */
function unlisted_root_path($dir, $file) {
    $depth = unlisted_root_depth($dir, $file);
    return $depth > 0 ? implode('/', array_slice(explode('/', dirname($file)), 0, $depth)) : '';
}

/** The eight characters (A-Z, a-z, 0-9, none left out) of a photo's address, from a secret raw string: bytes below 248 are used, each mapped to one of the
 *  62 characters without favouring any (248 is four times 62). */
function photo_code_chars($raw) {
    $alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    $out = ''; $round = 0;
    while (strlen($out) < 8) {
        for ($i = 0, $len = strlen($raw); $i < $len && strlen($out) < 8; $i++) {
            $b = ord($raw[$i]);
            if ($b < 248) $out .= $alphabet[$b % 62];
        }
        if (strlen($out) < 8) $raw = hash('sha256', $raw . $round++, true);   // (not reached with 32 bytes of hash in practice, but it can't loop for ever)
    }
    return $out;
}

/** A photo's address when the photo is in a Not listed folder: eight letters and digits (for example Ab3x9Qz2, used as /photos/Ab3x9Qz2 or
 *  /photos/?Ab3x9Qz2) worked out from the folder's hidden id, the file name, a secret of this install and, once the owner has asked for a new address,
 *  a random string kept on the photo. Nothing else is stored, so there is no list of codes and nothing to press: the folder can be renamed or moved
 *  and its photos keep their addresses, while renaming the photo ends its address. '' when it can't be worked out (no secret yet, or the folder has
 *  no id yet, which switching Not listed on gives it): nothing then matches. */
function photo_address_code($dir, $file, $itemsData = null, $folderId = null) {
    $secret = install_secret();
    $slash = strrpos((string) $file, '/');
    if ($secret === '' || $slash === false) return '';
    $fid = $folderId ?? folder_id_cached($dir, substr($file, 0, $slash));
    if ($fid === '') return '';
    $salt = is_array($itemsData) && is_string($itemsData[$file]['addr'] ?? null) ? $itemsData[$file]['addr'] : '';
    return photo_code_chars(hash_hmac('sha256', 'photo|' . $fid . '|' . basename($file) . '|' . $salt, $secret, true));
}

/** The photo an address (eight letters and digits) belongs to, or null. Only photos in Not listed folders have one, so only those are worked out
 *  (about a microsecond each), and a folder whose id is carried by a copy of it is left out until that is sorted. Nothing is read for an address of
 *  the wrong shape. */
function photo_address_resolve($dir, $files, $itemsData, $token) {
    if (!is_string($token) || preg_match('/^[A-Za-z0-9]{8}$/D', $token) !== 1 || install_secret() === '') return null;
    link_scan_ambiguity($dir, $files);   // (looking an address up keeps the list of copied ids current: the pictures of the page this opens are refused or served by it)
    $amb = link_ambiguous_set();
    $folderId = []; $carriers = [];   // folder => its id (only a Not listed folder with one), and id => how many such folders carry it
    foreach ($files as $f) {
        $folder = dirname($f);
        if ($folder === '.' || $folder === '' || isset($folderId[$folder])) continue;
        $fid = folder_is_unlisted($dir, $folder) ? folder_id_cached($dir, $folder) : '';   // (only a Not listed folder's id is read)
        $folderId[$folder] = $fid;
        if ($fid !== '') $carriers[$fid] = ($carriers[$fid] ?? 0) + 1;
    }
    foreach ($files as $f) {
        $fid = $folderId[dirname($f)] ?? '';
        if ($fid === '' || ($carriers[$fid] ?? 0) !== 1 || isset($amb[$fid])) continue;   // (a folder copied with its id points at nothing until that is sorted)
        $want = photo_address_code($dir, $f, $itemsData, $fid);
        if ($want !== '' && hash_equals($want, $token)) return $f;
    }
    return null;
}

/** A request for /photos/<something> (or /photos/?<something>) reaches the script as ?link=<something>. When that something is a Not listed photo's
 *  address, the request becomes the photo's own page (?photo=<path>&k=<code>) and true is returned; otherwise nothing is changed and the request goes
 *  on as a share link's (where a wrong one is counted). A closed gallery shows a stranger no photo, by an address or otherwise, and a visitor held
 *  back for guessing gets no answer, a right one included. */
function photo_address_translate($dir, $files, $itemsData) {
    $token = $_GET['link'] ?? null;
    if (!is_string($token) || preg_match('/^[A-Za-z0-9]{8}$/D', $token) !== 1) return false;
    if (gallery_is_closed() && !is_revealed() && !is_admin_browser() && link_viewer() === null) return false;
    if (!is_admin_browser() && !is_revealed() && !login_throttle_allows($dir, 'link', client_ip())) return false;
    if (is_dir($dir . '/' . $token) || isset(gallery_mounts()[$token])) return false;   // (a real folder of that name is what the server would have shown)
    $rel = photo_address_resolve($dir, $files, $itemsData, $token);
    if ($rel === null) return false;
    unset($_GET['link']);
    // The folder says what its photos' addresses open: the photo in the viewer (the default), or the bare picture or video. A ?file or ?view added
    // to one address overrides that for that address only.
    $bare = !empty(items_read(resolve_real_path($dir, unlisted_root_path($dir, $rel)))['addressFile']);
    if (isset($_GET['view'])) $bare = false; elseif (isset($_GET['file'])) $bare = true;
    unset($_GET['file'], $_GET['view']);
    $_GET['k'] = $token;
    if ($bare) {
        $_GET[is_video_file($rel) ? 'video' : 'img'] = $rel; if (!is_video_file($rel)) $_GET['size'] = 'full';
        request_route(true);
        photo_address_bare($dir, $rel, $itemsData);
        exit;
    }
    $_GET['photo'] = $rel;
    request_route(true);
    return true;
}

/** A Not listed photo's address answered with the file itself: what the viewer shows at full size (a picture is the file with its location removed for a
 *  visitor, a HEIC photo its converted JPEG) or, for a video, the video, with no page around it. It is counted and logged as the page would be. */
function photo_address_bare($dir, $rel, $itemsData) {
    header('X-Robots-Tag: noindex, nofollow');
    header('Referrer-Policy: no-referrer');
    try {
        if (!is_non_viewing_request()) {
            if (TRACK_VIEWS && !is_bot_request() && !is_admin_browser() && link_viewer() === null && !view_debounce_recently_viewed($rel)) stats_bump_photo(containing_folder_real_path($dir, $rel), $rel);
            if (public_log_wanted() && ($pl = public_log_link()) !== null) {
                $site = strtolower((string) ($_SERVER['HTTP_SEC_FETCH_SITE'] ?? ''));
                $how = $site === 'none' ? 'typed' : (in_array($site, ['cross-site', 'same-site'], true) ? 'link' : 'other');
                [$vid, $ip, $label, $country] = link_visitor_identity();
                link_log_apply($pl, $vid, $ip, $label, $country, [['o', $rel]], null, ['f' => $rel, 'h' => $how, 'u' => 1]);
            }
        }
    } catch (Throwable $e) { error_log('gallery: counting or logging a bare-file open failed: ' . $e->getMessage()); }   // (it must never stop the picture)
    $claimed = [$rel]; $items = items_get_all_for_files($dir, $claimed);
    if (isset($_GET['video'])) serve_video($dir, $rel, $claimed, $items); else serve_image($dir, $rel, 'full', $claimed, $items);
}

/** Is the k= of this request the right code for the photo the request names? Asked when a request ends without having been let in by its code, to tell
 *  a wrong guess (counted) from a right code that was turned away for another reason (a download that is switched off, a video strip of a photo). The
 *  name is only ever hashed and looked up inside the gallery's folders: anything with a dot-dot, a backslash or a NUL is not asked about. */
function photo_code_is_right_for_request($dir) {
    $k = $_GET['k'] ?? null;
    if (!is_string($k) || $k === '') return false;
    foreach (['photo', 'img', 'original', 'track', 'strip', 'video'] as $param) {
        $f = $_GET[$param] ?? null;
        if (!is_string($f) || $f === '' || $f[0] === '/' || strpbrk($f, "\0\\") !== false || preg_match('#(^|/)\.\.?(/|$)#', $f) === 1) continue;
        $want = photo_address_code($dir, $f, items_get_all_for_files($dir, [$f]));
        if ($want !== '' && hash_equals($want, $k)) return true;
    }
    return false;
}

/** Does this request carry the right code for this very photo, and is the photo one that has an address (in a Not listed folder, and not
 *  marked private on its own)? The code is for that one photo: it opens nothing else. */
function photo_pass_valid($dir, $file, $itemsData) {
    static $held = null;
    $k = $_GET['k'] ?? null;
    if (!is_string($k) || $k === '' || strlen($k) > 40 || !is_string($file) || !file_is_unlisted($dir, $file)) return false;
    // The code is for the photo the request names (as ?photo=, ?img=, ?original=, ?track=, ?strip= or ?video=), not for that photo wherever it might turn up on another page.
    $named = false;
    foreach (['photo', 'img', 'original', 'track', 'strip', 'video'] as $param) if (($_GET[$param] ?? null) === $file) { $named = true; break; }
    if (!$named) return false;
    if (item_restriction(is_array($itemsData) ? ($itemsData[$file] ?? null) : null) === 'private') return false;
    $fid = folder_id_cached($dir, (string) dirname($file));
    if ($fid !== '' && isset(link_ambiguous_set()[$fid])) return false;   // (a folder copied with its id: its photos' addresses open nothing until that is sorted, as at /photos/<code>)
    // The code can be tried here as well as at /photos/<code> (any request that names a Not listed photo and carries one), so a visitor held back for
    // guessing is not asked at all. (A wrong code is counted at the end of the request, see 003, whether or not the photo it came with exists.)
    if ($held === null) $held = !is_admin_browser() && !is_revealed() && !login_throttle_allows($dir, 'link', client_ip());
    if ($held) return false;
    $want = photo_address_code($dir, $file, $itemsData);
    if ($want === '' || !hash_equals($want, $k)) return false;
    $GLOBALS['__photo_pass_ok'] = true;
    return true;
}

/** May this visitor see the item (a public one, or a private one they were given)? */
function viewer_may_see_item($dir, $file, $itemsData) {
    if (is_admin_browser()) return true;
    if (isset($_GET['k']) && photo_pass_valid($dir, $file, $itemsData)) return true;   // (a Not listed photo, by its own address)
    if (is_revealed()) return !file_is_unlisted($dir, $file);   // (what the private-view password opens is everything private except a Not listed folder, which is the owner's alone)
    $l = link_viewer();
    if ($l !== null && link_shows_only_its_own($l) && !link_allows_item($l, $dir, $file, $itemsData)) return false;   // a link that shows only its own things: not the public rest of the gallery either
    if (!file_is_hidden($dir, $file, $itemsData)) return true;
    return $l !== null && link_allows_item($l, $dir, $file, $itemsData);
}

/** Is this link set to show only what it covers (its photos or folders), the public rest of the gallery left out of the pages it shows? */
function link_shows_only_its_own($l) {
    return !empty($l['only']) && in_array($l['scope']['type'] ?? 'all', ['folders', 'photos', 'mixed'], true);
}

/** Does the link allow $cap ('downloads' or 'zip') for this item? The answer is one of: off; all (every item the link shows, public or
 *  private); public (every item that is not private); some (the items under the chosen folders). */
function link_capability_allows($l, $cap, $dir, $file, $itemsData = null) {
    $mode = $l[$cap]['mode'] ?? 'off';
    if ($mode === 'all') return true;
    if ($mode === 'public') return !file_is_hidden($dir, $file, $itemsData ?? ($GLOBALS['itemsData'] ?? []));
    if ($mode === 'some') return link_item_under_folder_ids($dir, $file, $l[$cap]['folders'] ?? []);
    return false;
}

/** May this visitor download the original of an item they can see? The owner and the private-view password: always. Everyone
 *  else: a public photo when the gallery lets visitors, a private one when their link says so. */
function viewer_may_download($dir, $file, $itemsData) {
    if (is_admin_browser()) return true;
    if (isset($_GET['k']) && photo_pass_valid($dir, $file, $itemsData)) return !empty(items_read(resolve_real_path($dir, unlisted_root_path($dir, $file)))['allowOriginals']);   // (a photo opened by its address: its Not listed folder's own choice, not the gallery's)
    if (is_revealed()) return !file_is_unlisted($dir, $file);
    $l = link_viewer();
    // Someone using a share link: the link's own answer decides (the gallery-wide switch is for people who came in without one).
    if ($l !== null) return (!file_is_hidden($dir, $file, $itemsData) || link_allows_item($l, $dir, $file, $itemsData)) && link_capability_allows($l, 'downloads', $dir, $file, $itemsData);
    if (!ENABLE_PUBLIC_DOWNLOAD || file_is_hidden($dir, $file, $itemsData)) return false;
    return public_download_folder_covers($file);
}

/** Does the folder the file lies directly in allow strangers to download? Each folder stands on its own: a photo in a folder inside a folder that
 *  allows it is not covered by that one. A photo on the gallery's main page is the main page's own switch. */
function public_download_folder_covers($file) {
    $slash = strrpos($file, '/');
    if ($slash === false) return PUBLIC_DOWNLOAD_ROOT;
    return in_array(substr($file, 0, $slash), PUBLIC_DOWNLOAD_FOLDERS, true);
}

/** Does this visitor see every saved location (the owner, the private-view password, or a link that says so)? */
function viewer_sees_all_locations() {
    if (is_revealed()) return true;
    $l = link_viewer();
    return $l !== null && ($l['locations'] ?? 'public') === 'all';
}

/** The gallery's own title, found without the page scan the pages themselves wait for. */
function gallery_title_early($dir) {
    $label = root_display_meta($dir)['label'];
    if ($label !== '') return $label;
    $scan = scan_gallery_md_files($dir);
    if (!empty($scan['files'])) {
        foreach (explode("\n", str_replace("\r\n", "\n", (string) $scan['contents'][$scan['files'][0]])) as $line) {
            if (trim($line) === '') continue;
            if (preg_match('/^#\s+(.+)$/', trim($line), $m)) return unprotect_inline_code(trim($m[1]));
            break;
        }
    }
    return basename($dir);
}

/** The title a link's opening page (and a chat app's preview of it) shows. */
function link_page_title($l, $dir) {
    $mode = $l['titleMode'] ?? 'gallery';
    if ($mode === 'neutral') {   // one of a few plain titles, the same one every time for a given link (a chat app keeps the title it first saw)
        $titles = ['A shared gallery', 'Some photos for you', 'A few photos to look at', 'Shared with you', 'A little gallery', 'Something to look at', 'Photos, shared', 'A collection of photos', 'Take a look', 'Photos for you'];
        $seed = (string) (($l['pictureSeed'] ?? '') !== '' ? $l['pictureSeed'] : (($l['token'] ?? '') !== '' ? $l['token'] : ($l['id'] ?? '')));
        return $titles[hexdec(substr(hash('sha256', 'title' . $seed), 0, 8)) % count($titles)];
    }
    if ($mode === 'custom' && trim((string) ($l['titleText'] ?? '')) !== '') return (string) $l['titleText'];
    return gallery_title_early($dir);
}

/** The picture a link's message preview and opening page show, when the link has its picture switched on: the gallery's own cover if
 *  it has one, else a cover from one of the PUBLIC folders (a public photo from the front page when there are no folders). It is
 *  worked out as a signed-out visitor would see the gallery, whoever is asking, so a private photo can never be chosen; the same one
 *  every time for a given link. A relative file path, or null (switched off, or nothing public to show). */
/** Is this photo one a link with this scope covers, as far as a preview picture goes? A link to everything or to the public gallery covers every photo
 *  (they are filtered to the public ones elsewhere); a link limited to folders and/or photos covers only those. $draft is the form's unsaved choice
 *  as paths (type, folders, photos); without it the saved link's own record decides. */
function link_cover_in_scope($l, $dir, $f, $draft = null) {
    $type = $draft !== null ? (string) ($draft['type'] ?? 'all') : (string) ($l['scope']['type'] ?? 'all');
    if (!in_array($type, ['folders', 'photos', 'mixed'], true)) return true;
    if ($draft === null) return link_allows_item($l, $dir, $f);
    if ($type !== 'photos') foreach ((array) ($draft['folders'] ?? []) as $d) {
        if ($d !== '' && str_starts_with($f, $d . '/')) return true;
        if ($d !== '' && ($c = collection_at($dir, $d)) !== null && in_array($f, collection_member_files($dir, $c, $GLOBALS['allFiles'] ?? ($GLOBALS['files'] ?? [])), true)) return true;
    }
    return $type !== 'folders' && in_array($f, (array) ($draft['photos'] ?? []), true);
}

/** The form's unsaved choice of what a link covers, from a request's scope_type / scope_folders / scope_photos (null when they are not sent). */
function link_draft_scope_from_request() {
    if (!isset($_GET['scope_type']) || !is_string($_GET['scope_type'])) return null;
    $list = function ($k) { $v = json_decode(is_string($_GET[$k] ?? null) ? $_GET[$k] : '[]', true); return is_array($v) ? array_values(array_filter($v, 'is_string')) : []; };
    return ['type' => $_GET['scope_type'], 'folders' => $list('scope_folders'), 'photos' => $list('scope_photos')];
}

function link_preview_picture($l, $dir, $draft = null) {
    if (empty($l['picture'])) return null;
    [, $public] = link_public_media($dir);
    $photo = function ($f) { return !is_video_file($f); };
    // A link limited to some folders and/or photos takes its picture, chosen or automatic, only from the public photos it covers: the opening page
    // and a chat's preview show it to anyone before the link is opened, so a photo the link does not cover must not appear there. A link whose
    // picks hold no public photo shows the gallery's icon.
    $public = array_values(array_filter($public, function ($f) use ($l, $dir, $draft) { return link_cover_in_scope($l, $dir, $f, $draft); }));
    // The owner's own choice, looked at again every time it is used: a photo that has since gone private, been deleted or fallen outside what the link covers is not in the list, and the automatic pick takes over.
    $chosen = (string) ($l['pictureFile'] ?? '');
    if ($chosen !== '' && $photo($chosen) && in_array($chosen, $public, true)) return $chosen;
    $rootCover = root_display_meta($dir)['cover'];
    if ($rootCover !== null && in_array($rootCover, $public, true) && $photo($rootCover)) return $rootCover;
    $level = split_folder_level($public, '');
    $pool = [];
    foreach ($level['folders'] as $top => $members) {
        $cover = pick_folder_cover($members, folder_display_meta($dir, $top)['cover'], $top);
        if ($cover !== null && $photo($cover)) $pool[] = $cover;
    }
    if (!$pool) $pool = array_values(array_filter($public, $photo));
    if (!$pool) return null;
    $seed = (string) (($l['pictureSeed'] ?? '') !== '' ? $l['pictureSeed'] : ($l['token'] ?? ''));   // (a link made before the seed existed keeps the pick its address gave it)
    return $pool[hexdec(substr(hash('sha256', $seed), 0, 8)) % count($pool)];
}

/** Every photo and video of the gallery in its own order, and the ones a signed-out visitor could see: [all, public]. Worked out once a request. */
function link_public_media($dir) {
    global $mediaExtensions, $self;
    static $cache = [];
    if (isset($cache[$dir])) return $cache[$dir];
    if (AUTO_GROUP_BY_FOLDER) {
        $all = flatten_folder_tree(merge_extra_folders(scan_folder_tree($dir, $mediaExtensions, $self), $mediaExtensions, $self));
    } else {
        $all = [];
        foreach ((array) @scandir($dir) as $f) {
            if ($f === $self || $f === '.' || $f === '..' || !is_file("$dir/$f")) continue;
            if (in_array(strtolower(pathinfo($f, PATHINFO_EXTENSION)), $mediaExtensions, true)) $all[] = $f;
        }
        usort($all, 'strnatcasecmp');
    }
    $all = array_values(media_sort_apply($all, $dir));
    $itemsData = items_get_all_for_files($dir, $all);
    $public = array_values(array_filter($all, function ($f) use ($dir, $itemsData) { return !file_is_hidden($dir, $f, $itemsData); }));
    return $cache[$dir] = [$all, $public];
}

/** May this file be a link's cover? Only a public photo (never a private one, never a video). */
function link_picture_ok($rel, $dir) {
    [, $public] = link_public_media($dir);
    return $rel !== '' && !is_video_file($rel) && in_array($rel, $public, true);
}

/** A folder's last known path (from the links file), if the folder is still there carrying that id. */
function link_folder_path_hint($fid) {
    $rel = (string) (links_read()['folderIndex'][$fid] ?? '');
    if ($rel === '') return null;
    $real = resolve_real_path(__DIR__, $rel);
    return is_dir($real) && folder_id_read($real) === $fid ? $rel : null;
}

/** Where pressing "Open the gallery" leads: the front page (for a link to photos, the grid of them; for exactly one photo, the viewer on it) or the folder the link opens in. */
function link_open_in_href($l) {
    $root = gallery_root_href();
    if (($l['scope']['type'] ?? '') === 'photos') {
        // One photo opens straight in the viewer; several open on the grid of them.
        $picked = (array) ($l['scope']['photos'] ?? []);
        $p = count($picked) === 1 ? reset($picked) : null;
        if (is_array($p) && is_string($p['fid'] ?? null) && is_string($p['name'] ?? null)) {
            $rel = $p['fid'] === folder_id_read(__DIR__) ? '' : link_folder_path_hint($p['fid']);
            if ($rel !== null) {
                $file = ($rel === '' ? '' : $rel . '/') . $p['name'];
                if (is_file(resolve_real_path(__DIR__, $file))) return $root . '?photo=' . rawurlencode($file);
            }
        }
        return $root;
    }
    $in = (string) ($l['openIn'] ?? '');
    if ($in !== '') {
        $rel = link_folder_path_hint($in);
        if ($rel !== null) return $root . '?folder=' . rawurlencode($rel);
    }
    return $root;
}

/** A link's addresses: the tidy one (needs the server rule) and the one that always works. */
function link_urls($l) {
    $base = current_base_url();
    return ['short' => $base . '/' . $l['token'], 'long' => $base . '/?' . $l['token']];   // (?link=<token> works too)
}

function link_standalone_head($title, $picture = '') {
    header('Content-Type: text/html; charset=UTF-8');
    header('Cache-Control: no-store');
    header('X-Robots-Tag: noindex, nofollow');
    header('Referrer-Policy: no-referrer');
    header("Content-Security-Policy: default-src 'none'; " . ($picture !== '' ? "img-src 'self'; " : '') . "style-src 'unsafe-inline'; script-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
    $t = htmlspecialchars($title, ENT_QUOTES, 'UTF-8');
    $og = $picture === '' ? '' : '<meta property="og:image" content="' . htmlspecialchars(current_base_url() . '/' . img_url($picture, 'share'), ENT_QUOTES, 'UTF-8') . '"><meta name="twitter:card" content="summary_large_image">';
    return '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="robots" content="noindex, nofollow"><meta name="referrer" content="no-referrer"><title>' . $t . '</title>'
        . '<meta property="og:title" content="' . $t . '"><meta property="og:type" content="website">' . $og
        . '<style>:root{color-scheme:dark}html,body{height:100%}body{margin:0;background:#0f0f10;color:#eaeaea;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;line-height:1.5}'
        . '.wrap{box-sizing:border-box;min-height:100%;max-width:420px;margin:0 auto;padding:6vh 24px 24px;text-align:center}'
        . '.ico{width:64px;height:64px;border-radius:50%;background:#1a1a1c;display:inline-flex;align-items:center;justify-content:center;color:#aab2ff;margin-bottom:6px}.ico svg{width:30px;height:30px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}'
        . 'h1{font-size:1.5rem;margin:14px 0 10px}p{color:#b9b9c0;font-size:1rem;margin:0 0 20px}'
        . '.note{margin:6px 0 22px;padding:12px 14px;border-left:3px solid #5865f2;background:#141416;border-radius:0 8px 8px 0;font-size:1rem;line-height:1.45;color:#e4e4e8;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere}'
        . '.big{display:block;width:100%;box-sizing:border-box;height:50px;border:0;border-radius:12px;background:#5865f2;color:#fff;font:inherit;font-size:1.05rem;font-weight:600;cursor:pointer}.big:focus-visible{outline:2px solid #fff;outline-offset:2px}'
        . '.pic{display:block;width:auto;height:auto;max-width:100%;max-height:60vh;margin:0 auto 18px;border-radius:14px;background:#1a1a1c}.wrap.has-pic{padding-top:6vh}'   // (the whole photo at its own proportions: as wide as the page allows and no taller than 60% of the screen, never cropped)
        . '.small{font-size:.8rem;color:#6f6f77;margin-top:14px}</style></head><body><div class="wrap' . ($picture !== '' ? ' has-pic' : '') . '">';
}


/** The page behind a link that doesn't work: the same for every reason (expired, used up, paused, revoked, mistyped,
 *  switched off), with nothing to press and nothing about why. The person using it is meant to tell whoever sent it. */
function render_link_invalid_page($status = 404) {
    http_response_code($status);
    header('X-Gallery-Link: invalid');
    echo link_standalone_head('This link is not valid');
    echo '<div class="ico" style="color:#8a8a8f">' . LINK_ICON_WARN . '</div><h1>This link is not valid</h1><p>Please contact the person who gave it to you.</p></div></body></html>';
}

/** The page a working link opens: its title, an optional note, and the one button that counts as using it. */
function render_link_open_page($l, $dir) {
    header('X-Gallery-Link: open');
    $picture = link_preview_picture($l, $dir);
    echo link_standalone_head(link_page_title($l, $dir), (string) $picture);
    echo ($picture !== null ? '<img class="pic" src="' . htmlspecialchars(gallery_root_href() . img_url($picture, 'share'), ENT_QUOTES, 'UTF-8') . '" alt="">' : '<div class="ico">' . LINK_ICON_GALLERY . '</div>') . '<h1>' . htmlspecialchars(link_page_title($l, $dir), ENT_QUOTES, 'UTF-8') . '</h1>';
    if (trim((string) ($l['note'] ?? '')) !== '') echo '<div class="note">' . htmlspecialchars((string) $l['note'], ENT_QUOTES, 'UTF-8') . '</div>';
    echo '<form method="post" action=""><input type="hidden" name="go" value="1"><button type="submit" class="big">Open the gallery</button></form>';
    if ((int) ($l['endsAt'] ?? 0) > 0) {
        $ts = (int) $l['endsAt'];
        echo '<div class="small">This link works until <span id="until" data-ts="' . $ts . '">' . htmlspecialchars(gmdate('D, M j, Y g:i a', $ts) . ' UTC', ENT_QUOTES, 'UTF-8') . '</span>.</div>'
           . '<script>(function(){var s=document.getElementById("until");var d=new Date(+s.getAttribute("data-ts")*1000);if(isNaN(d))return;'
           . 's.textContent=d.toLocaleDateString(undefined,{weekday:"long",month:"short",day:"numeric"})+" at "+d.toLocaleTimeString(undefined,{hour:"numeric",minute:"2-digit"});})();</script>';
    }
    echo '</div></body></html>';
}

/** The page for a visitor held back for guessing addresses: wait a minute and try again. A right address gets the same until the minute is over (or
 *  nothing would slow a guesser down). */
function render_link_locked_page($dir) {
    render_lockout_page('Please wait a moment', 'Too many addresses that did not work were tried from your connection.', login_throttle_wait($dir, 'link', client_ip()));
}

/** The page for anyone held back by a lockout (wrong access codes, wrong setup codes, wrong addresses): says what happened in the words of where they
 *  are, counts the seconds left down, and tries again by itself when they are up (a plain fresh visit, never a second post of what was typed, so it
 *  can't count as another wrong guess). Without script it says how long and has a link to press. */
function render_lockout_page($heading, $text, $seconds) {
    $seconds = max(1, min(900, (int) $seconds));
    http_response_code(429);
    header('Retry-After: ' . $seconds);
    $h = htmlspecialchars($heading, ENT_QUOTES, 'UTF-8');
    $clock = intdiv($seconds, 60) . ':' . str_pad((string) ($seconds % 60), 2, '0', STR_PAD_LEFT);
    echo link_standalone_head($heading);
    echo '<div class="ico" style="color:#8a8a8f">' . LINK_ICON_WARN . '</div><h1>' . $h . '</h1><p>' . htmlspecialchars($text, ENT_QUOTES, 'UTF-8') . '</p>'
        . '<p id="lock-line" role="timer">Try again in <strong id="lock-secs" style="color:#fff;font-variant-numeric:tabular-nums">' . $clock . '</strong></p>'
        . '<a class="big" id="lock-again" href="" style="display:none;align-items:center;justify-content:center;text-decoration:none">Try again</a>'
        . '<noscript><a class="big" href="" style="display:flex;align-items:center;justify-content:center;text-decoration:none">Try again</a></noscript>'
        . '<script>(function(){var end=Date.now()+' . $seconds . '*1000,e=document.getElementById("lock-secs"),l=document.getElementById("lock-line"),b=document.getElementById("lock-again");'
        . 'function tick(){var n=Math.max(0,Math.ceil((end-Date.now())/1000));e.textContent=Math.floor(n/60)+":"+("0"+n%60).slice(-2);'
        . 'if(n>0){setTimeout(tick,250);return}l.textContent="You can try again now.";b.style.display="flex";setTimeout(function(){location.assign(location.href)},1500)}tick()})();</script>'
        . '</div></body></html>';
}

/** Is this visitor held back for guessing? (You, and anyone with the private-view password, never are.) Says so with the page when they are. */
function link_guess_locked($dir) {
    if (is_admin_browser() || is_revealed() || login_throttle_allows($dir, 'link', client_ip())) return false;
    render_link_locked_page($dir);
    return true;
}

/** A wrong address was tried. It counts against the visitor only when it is shaped like one (4 to 40 letters, digits and hyphens): that is what a
 *  guess looks like; a stray word or a mistyped bit of a web address is not held against anyone. You and the private-view password never count. */
function link_guess_failed($dir, $token) {
    if (is_admin_browser() || is_revealed() || !link_token_format_ok($token)) return;
    login_throttle_record_failure($dir, 'link', client_ip(), LINK_GUESS_LIMIT);
}

/** ?link=<token> (and the tidy address the server rule maps onto it). */
function run_link_route($dir) {
    geo_maybe_refresh();
    $token = $_GET['link'] ?? '';
    // The server rule for tidy addresses sends every one-word path here (/gallery/carol), so a few of them are not links: the
    // sign-in ("admin" or "reveal") and a real folder typed without its closing slash (sent on to the folder, as the server itself would have).
    // A link of that name wins over both.
    if (is_string($token) && preg_match('/^[A-Za-z0-9][A-Za-z0-9-]*$/', $token) === 1 && $token !== LINK_PROBE_TOKEN) {
        $isLink = false;
        if (ENABLE_SHARE_LINKS && link_token_format_ok($token)) { $all = links_read(); $isLink = link_find_by_token($all, $token) !== null || link_find_by_alias($all, $token) !== null; }
        if (!$isLink && in_array(strtolower($token), ['admin', 'reveal'], true) && !is_dir($dir . '/' . $token)) sign_in_redirect();
        $mayLook = !gallery_is_closed() || is_revealed() || is_admin_browser() || link_viewer() !== null;   // (a closed gallery doesn't tell a stranger which folders exist)
        if ($mayLook && !is_admin_browser() && (is_dir($dir . '/' . $token) || isset(gallery_mounts()[$token])) && folder_is_unlisted($dir, $token)) $mayLook = false;   // (nor does it say a Not listed folder is there: it answers as for a name that isn't)
        if (!$isLink && $mayLook && (is_dir($dir . '/' . $token) || isset(gallery_mounts()[$token]))) {
            header('Cache-Control: no-store');
            header('Location: ' . gallery_root_href() . rawurlencode($token) . '/', true, 302);
            return;
        }
    }
    if ($token === LINK_PROBE_TOKEN) { render_link_invalid_page(200); return; }   // the check that the tidy address works (the admin's, and the owner's Copy address on a photo): not a guess, and not a 404, which a browser would log in its console. Before the switches below: a Not listed photo's short address needs the server rule whether or not share links are on
    if (!ENABLE_SHARE_LINKS) { if (link_guess_locked($dir)) return; link_guess_failed($dir, $token); render_link_invalid_page(); return; }   // (still counted: a Not listed photo's address is guessed here too)
    if (!is_https_request() && !is_local_request()) { render_https_required_page(); return; }
    $ip = client_ip();
    $allLinks = links_read();
    $link = link_token_format_ok($token) ? link_find_by_token($allLinks, $token) : null;
    $viaAlias = null;   // (an old address the owner kept working: it sends people on to the link's present one)
    if ($link === null && link_token_format_ok($token) && ($hit = link_find_by_alias($allLinks, $token)) !== null) [$link, $viaAlias] = $hit;
    // The owner, signed in, just goes where the link goes: nothing is counted or logged, no cookie is set, and the throttle
    // (which is for guessing) doesn't apply.
    if ($link !== null && is_admin_browser()) {
        header('Cache-Control: no-store');
        header('Location: ' . link_open_in_href($link), true, 303);
        return;
    }
    if (link_guess_locked($dir)) return;
    if ($link !== null && $viaAlias !== null && ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET' && link_state($link) === 'active') {
        // (a temporary redirect, never a permanent one: it must stop the moment the owner removes the old address; and the same form the person used, short or long)
        link_alias_used($link['id'], $viaAlias);
        link_note_address($link, 'via', $viaAlias);
        header('Cache-Control: no-store');
        header('Location: ' . link_urls($link)[strpos((string) ($_SERVER['REQUEST_URI'] ?? ''), '?') !== false ? 'long' : 'short'], true, 302);
        return;
    }
    if ($link === null) {
        // An address from before a link was given a new one: not a guess, so not held against the visitor, but noted in that link's log.
        $oldOwner = link_token_format_ok($token) ? link_find_by_old_token(links_read(), $token) : null;
        if ($oldOwner !== null) { link_note_blocked($oldOwner, 'replaced'); link_note_address($oldOwner, 'tried', link_old_name($oldOwner, $token)); render_link_invalid_page(); return; }
        link_guess_failed($dir, $token);
        render_link_invalid_page();
        return;
    }
    $cookie = $_COOKIE[LINK_COOKIE_NAME] ?? '';
    install_secret(true);
    $hasCookie = is_string($cookie) && hash_equals(link_cookie_value($link), $cookie) && link_is_live($link);
    $posted = ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && isset($_POST['go']);
    if (!$posted) {
        if ($hasCookie) { header('Cache-Control: no-store'); header('Location: ' . link_open_in_href($link), true, 303); return; }
        if (link_state($link) === 'active') { render_link_open_page($link, $dir); return; }
        link_note_blocked($link, link_state($link));
        render_link_invalid_page();
        return;
    }
    // The button was pressed: count the use, atomically, so a link for one opening can't be opened twice at the same moment.
    $outcome = 'blocked'; $stateNow = 'revoked'; $now = time(); $counted = false;
    links_update(function (&$d) use ($link, $ip, $hasCookie, $now, &$outcome, &$stateNow, &$counted) {
        $l = $d['links'][$link['id']] ?? null;
        if (!is_array($l)) return;
        $stateNow = link_state($l, $now);
        if (!link_is_live($l, $now)) return;
        if ($hasCookie) { $outcome = 'ok'; return; }
        if (($l['lastOpen']['ip'] ?? '') === $ip && $now - (int) ($l['lastOpen']['at'] ?? 0) < LINK_REOPEN_GRACE_SECONDS) {
            $d['links'][$link['id']]['lastOpen']['at'] = $now;
            $outcome = 'ok';
            return;
        }
        if ($stateNow !== 'active') return;   // no opens left
        $d['links'][$link['id']]['opens'] = (int) ($l['opens'] ?? 0) + 1;
        $d['links'][$link['id']]['lastOpened'] = $now;
        $d['links'][$link['id']]['lastOpen'] = ['ip' => $ip, 'at' => $now];
        $outcome = 'ok'; $counted = true;
    });
    if ($outcome !== 'ok') {
        link_note_blocked($link, $stateNow);
        render_link_invalid_page();
        return;
    }
    link_set_cookie($link);
    if ($counted) link_log_opened($link);
    header('Cache-Control: no-store');
    header('Location: ' . link_open_in_href($link), true, 303);
}


/* -----------------------------------------------------------------------
 * Folder levels. $files (already hiding-filtered by the time a page is
 * built from it) is the allowlist for everything here: a folder path is
 * only ever "valid" because some file the script itself found sits under
 * it, never because a request said so — the same discipline as ?img=.
 * ----------------------------------------------------------------------- */

/** Splits $files under $prefix ('' for the root, else 'A/B/') into the
 *  files loose directly at that level and each immediate subfolder's
 *  recursive members. */
function split_folder_level($files, $prefix) {
    $folders = [];
    $loose = [];
    $len = strlen($prefix);
    foreach ($files as $f) {
        if ($prefix !== '' && strncmp($f, $prefix, $len) !== 0) continue;
        $rest = substr($f, $len);
        $slash = strpos($rest, '/');
        if ($slash === false) {
            $loose[] = $f;
        } else {
            $folders[substr($rest, 0, $slash)][] = $f;
        }
    }
    return ['folders' => $folders, 'loose' => $loose];
}

/** Every folder path (at any depth) that has at least one file under it,
 *  parents before their children. */
function all_folder_paths($files) {
    $set = [];
    foreach ($files as $f) {
        $d = dirname($f);
        while ($d !== '.' && $d !== '' && !isset($set[$d])) {
            $set[$d] = true;
            $d = dirname($d);
        }
    }
    $paths = array_keys($set);
    usort($paths, 'strnatcasecmp');
    return $paths;
}

/** Folder paths as a tree in the gallery's own order (a position set by the owner first, then by name): each folder is followed by
 *  the folders inside it. A folder's parents are added when they are not in the list, so the tree always reads. Rows: p (path),
 *  d (depth, 0 at the top), n (its own name as the gallery shows it). */
function folder_tree_rows($dir, array $paths) {
    $set = [];
    foreach ($paths as $p) { $p = (string) $p; while ($p !== '' && $p !== '.') { $set[$p] = true; $p = dirname($p); } }
    $kids = [];
    foreach (array_keys($set) as $p) { $p = (string) $p; $parent = dirname($p); $kids[$parent === '.' ? '' : $parent][] = basename($p); }
    $rows = [];
    $walk = function ($parent, $depth) use (&$walk, &$rows, $dir, $kids) {
        if (empty($kids[$parent])) return;
        foreach (order_folder_children($dir, $parent === '' ? '' : $parent . '/', array_map('strval', $kids[$parent])) as $name) {
            $path = $parent === '' ? $name : $parent . '/' . $name;
            $label = folder_display_meta($dir, $path)['label'];
            $rows[] = ['p' => $path, 'd' => $depth, 'n' => $label !== '' ? $label : $name];
            $walk($path, $depth + 1);
        }
    };
    $walk('', 0);
    return $rows;
}

/** The files under a folder path, or [] if no file does — which is also
 *  the "this folder doesn't exist (or is hidden from you)" answer. */
function folder_files_under($files, $folderPath) {
    if (!is_string($folderPath) || $folderPath === '') return [];
    $prefix = $folderPath . '/';
    $len = strlen($prefix);
    return array_values(array_filter($files, function ($f) use ($prefix, $len) {
        return strncmp($f, $prefix, $len) === 0;
    }));
}

/** A folder's own admin-set identity, read from its own
 *  .gallery-items.php, normalized so callers never re-check types. */
/** The gallery root's own title, dates, description and cover — the same
 *  record a folder keeps (in the root's .gallery-items.php), so the root is
 *  configured the same way folders are. */
function root_display_meta($dir) {
    $d = items_read($dir);
    return [
        'label' => is_string($d['displayName'] ?? null) ? $d['displayName'] : '',
        'cover' => is_string($d['cover'] ?? null) && $d['cover'] !== '' ? $d['cover'] : null,
        'description' => is_string($d['description'] ?? null) ? $d['description'] : '',
        'dates' => is_string($d['dates'] ?? null) ? $d['dates'] : '',
    ];
}

function folder_display_meta($dir, $folderRel) {
    if ($folderRel !== '' && collections_any() && ($coll = collection_at($dir, $folderRel)) !== null) return collection_display_meta($coll);   // (a collection is a folder that exists only in the gallery: its own record answers)
    $d = items_read(resolve_real_path($dir, $folderRel));
    $cover = is_string($d['cover'] ?? null) && $d['cover'] !== '' ? $d['cover'] : null;   // (a photo's name, or its path inside this folder when the photo is in a folder under it)
    if ($cover === null && is_string($d['coverFollow'] ?? null) && $d['coverFollow'] !== '' && strpbrk($d['coverFollow'], "/\\") === false) $cover = 'follow:' . $d['coverFollow'];   // (the cover of a folder directly under it)
    return [
        'label' => is_string($d['displayName'] ?? null) ? $d['displayName'] : '',
        'cover' => $cover,
        'description' => is_string($d['description'] ?? null) ? $d['description'] : '',
        'dates' => is_string($d['dates'] ?? null) ? $d['dates'] : '',
        'sortOrder' => is_int($d['sortOrder'] ?? null) ? $d['sortOrder'] : null,
    ];
}

/** Orders sibling folder names: an explicit admin-set position first
 *  (ascending), everything else after in natural order — by name, or by
 *  folder mtime when PHOTO_SORT_ORDER says so. */
function order_folder_children($dir, $prefix, $names) {
    $meta = [];
    foreach ($names as $name) {
        $meta[$name] = folder_display_meta($dir, $prefix . $name);
    }
    usort($names, function ($a, $b) use ($meta, $dir, $prefix) {
        $oa = $meta[$a]['sortOrder'];
        $ob = $meta[$b]['sortOrder'];
        if ($oa !== null && $ob !== null && $oa !== $ob) return $oa <=> $ob;
        if ($oa !== null && $ob === null) return -1;
        if ($oa === null && $ob !== null) return 1;
        if (PHOTO_SORT_ORDER === 'mtime') {
            $ma = @filemtime(resolve_real_path($dir, $prefix . $a)) ?: 0;
            $mb = @filemtime(resolve_real_path($dir, $prefix . $b)) ?: 0;
            if ($ma !== $mb) return $ma <=> $mb;
        }
        return strnatcasecmp($a, $b);
    });
    return $names;
}

/**
 * ?reveal — the only thing that invokes a real HTTP Basic Auth prompt
 * for PRIVATE_VIEW_PASSWORD. Same HTTPS requirement and failed-attempt
 * throttle as ?admin (a separate throttle realm, so failures on one
 * password never lock out the other). On success, sets the reveal
 * cookie and redirects back to the bare URL — dropping ?reveal from the
 * address bar, not just leaving it there, so "bookmark the plain gallery
 * link afterward" is literally true.
 */
function run_reveal_route($dir) {
    send_sensitive_page_headers();
    // One sign-in for the lock in the icon strip: the private-view password shows the private items, the admin password
    // signs in to the admin. Either alone is enough for the form to exist.
    if (PRIVATE_VIEW_PASSWORD === '' && ADMIN_PASSWORD === '') {
        http_response_code(404);
        return;
    }
    // Back to the very same page the visitor came from: a folder, an open photo, the open map.
    $backPage = login_return_query();
    // The lock in the icon strip, when it is open, locks the private items again: whoever is signed in (a viewer with the
    // private-view password, or the owner signed in to the admin) is signed out of this browser.
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['logout'])) {
        if (is_admin_browser()) {
            admin_start_session();
            $_SESSION = [];
            if (ini_get('session.use_cookies')) {
                gallery_cookie_expire(session_name(), 'Strict');
            }
            session_destroy();
        }
        browser_revoke_current();
        header('Location: ./' . $backPage, true, 303);
        return;
    }
    if (!is_https_request() && !is_local_request()) {
        render_https_required_page();
        return;
    }
    $ip = client_ip();
    // One plain prompt, whichever password it turns out to be.
    $heading = 'Enter your access code';
    $prompt = '';
    // The form is the normal way in; a Basic Authorization header (a script,
    // a bookmarked login) is still honored. Only a password that was
    // actually *supplied* and wrong counts against the throttle: a plain
    // visit to the form tells us nothing about guessing.
    $pass = $_SERVER['PHP_AUTH_PW'] ?? null;
    $formPass = login_form_password();
    $supplied = $formPass ?? $pass;
    // Both passwords are guessed at through this one box, so a visitor who keeps failing is held back from the admin
    // sign-in as well (per address), and the admin's own lockout holds here too. Only an attempt is refused: just
    // looking at the form never is.
    $attempting = $formPass !== null || isset($_SERVER['PHP_AUTH_USER']) || isset($_SERVER['PHP_AUTH_PW']);
    if ($attempting && (!login_throttle_allows($dir, 'reveal', $ip) || (ADMIN_PASSWORD !== '' && !login_throttle_allows($dir, 'admin', $ip)))) {
        render_lockout_page('Sign-in paused', 'Too many wrong access codes were entered from your connection. Sign-in is paused for a moment.', max(login_throttle_wait($dir, 'reveal', $ip), login_throttle_wait($dir, 'admin', $ip)));
        return;
    }
    $asAdmin = is_string($supplied) && ADMIN_PASSWORD !== '' && password_matches(ADMIN_PASSWORD, $supplied);
    $asViewer = !$asAdmin && is_string($supplied) && PRIVATE_VIEW_PASSWORD !== '' && password_matches(PRIVATE_VIEW_PASSWORD, $supplied);
    if (!$asAdmin && !$asViewer) {
        if (isset($_SERVER['PHP_AUTH_USER']) || isset($_SERVER['PHP_AUTH_PW']) || $formPass !== null) {
            login_throttle_record_failure($dir, 'reveal', $ip);
            if (ADMIN_PASSWORD !== '') login_throttle_record_failure($dir, 'admin', $ip);
        }
        if ($formPass === null && (isset($_SERVER['PHP_AUTH_USER']) || isset($_SERVER['PHP_AUTH_PW']))) {
            // A wrong saved Basic password (see admin_reject_saved_credentials): the form, never a challenge.
            http_response_code(401);
            render_login_page($heading, $prompt, 'Your browser sent a saved login that no longer matches. Type the current access code.');
            return;
        }
        render_login_page($heading, $prompt, $formPass !== null ? 'That code isn\'t right.' : '');
        return;
    }
    login_throttle_record_success($dir, 'reveal', $ip);
    // A password still in plain text in the settings file becomes a hash now (everything below uses what is stored).
    $upgraded = upgrade_plaintext_passwords();
    if ($asAdmin) {
        // The owner: a fresh admin session, exactly as the admin's own sign-in makes one, then back to the very page they
        // were on (the title leads on to the admin).
        admin_start_session();
        session_regenerate_id(true);
        $_SESSION['admin_auth'] = admin_session_marker($upgraded['ADMIN_PASSWORD'] ?? null);
        login_throttle_record_success($dir, 'admin', $ip);
        set_admin_reveal_cookie($upgraded['ADMIN_PASSWORD'] ?? null);
        header('Location: ./' . $backPage, true, 303);
        return;
    }
    set_reveal_cookie($upgraded['PRIVATE_VIEW_PASSWORD'] ?? null);
    header('Location: ./' . $backPage, true, 302);
}

/* -----------------------------------------------------------------------
 * Collections. A collection is a folder that exists only in the gallery: it has no place on disk. It lives inside a parent (the front
 * page or any folder) and holds members: real folders and single photos from anywhere. Nothing moves on disk, and a collection never
 * takes anything away from the place a member really is. It grants nothing and hides nothing: a visitor sees, in a collection, only the
 * members they could already see where they really are.
 *
 * The records are in .gallery-collections.php beside index.php (a guarded data file, like the share links):
 *   {collections: [{id, parent, name, title, description, cover, dates, position, private, front, ownGallery, subfolderStyle, photoSort,
 *                   items: [{fid, mode: all|own} | {fid, file}], at}]}
 * A folder is remembered by its hidden id (folder_id_stamp), as share links do, so renaming or moving a folder keeps the collection whole;
 * `parent` is such an id too ('' is the front page). The address is the parent's path plus `name`, like a folder's: ?folder=<parent>/<name>.
 * A real folder with the same path always wins (the collection is then "address taken" and is not shown).
 * ----------------------------------------------------------------------- */

function collections_path() { return __DIR__ . '/.gallery-collections.php'; }
function collections_default() { return ['collections' => []]; }
function collections_read() { return json_file_read(collections_path(), collections_default()); }
function collections_update($modifier) { collections_cache_reset(); $r = json_file_update(collections_path(), collections_default(), $modifier, true); collections_cache_reset(); return $r; }
/** Forget what was worked out this request (after a change, and between the parts of a test). */
function collections_cache_reset() { $GLOBALS['__collections_cache'] = null; $GLOBALS['__collections_registry'] = null; }

/** Is a collection's address name well formed? Letters, digits, dot, dash, underscore; not starting with a dot; at most 60 characters;
 *  and not a word the gallery uses as an address itself. */
function collection_name_shape_ok($name) {
    return is_string($name) && preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]{0,59}$/D', $name) === 1 && !in_array(strtolower($name), ['admin', 'reveal', 'link', 'photo', 'index.php'], true);
}

/** An address name made from a title: lower case, runs of other characters become one dash. */
function collection_slug($title) {
    $s = strtolower(trim((string) $title));
    $s = preg_replace('/[^a-z0-9]+/', '-', $s);
    $s = trim((string) $s, '-');
    if ($s === '') $s = 'collection';
    return substr($s, 0, 60);
}

/** One stored record, made safe to use (every field the right type), or null when it is not a collection at all. */
function collection_clean($r) {
    if (!is_array($r) || !is_string($r['id'] ?? null) || !preg_match('/^c[0-9a-f]{12}$/D', $r['id']) || !collection_name_shape_ok($r['name'] ?? null)) return null;
    $parent = $r['parent'] ?? '';
    if (!is_string($parent) || ($parent !== '' && !preg_match('/^[0-9a-f]{12}$/D', $parent))) return null;
    $items = [];
    foreach ((array) ($r['items'] ?? []) as $it) {
        if (!is_array($it) || !is_string($it['fid'] ?? null) || !preg_match('/^[0-9a-f]{12}$/D', $it['fid'])) continue;
        if (isset($it['file'])) {
            if (is_string($it['file']) && $it['file'] !== '' && strpos($it['file'], '/') === false && strpos($it['file'], "\0") === false && strlen($it['file']) <= 255) $items[] = ['fid' => $it['fid'], 'file' => $it['file']];
        } else {
            $items[] = ['fid' => $it['fid'], 'mode' => ($it['mode'] ?? 'all') === 'own' ? 'own' : 'all'];
        }
    }
    $style = $r['subfolderStyle'] ?? null;
    return [
        'id' => $r['id'], 'parent' => $parent, 'name' => $r['name'],
        'title' => is_string($r['title'] ?? null) ? $r['title'] : '',
        'description' => is_string($r['description'] ?? null) ? $r['description'] : '',
        'cover' => is_string($r['cover'] ?? null) && $r['cover'] !== '' ? $r['cover'] : null,
        'dates' => is_string($r['dates'] ?? null) ? $r['dates'] : '',
        'position' => is_int($r['position'] ?? null) ? $r['position'] : null,
        'private' => !empty($r['private']), 'front' => !empty($r['front']), 'ownGallery' => !empty($r['ownGallery']),
        'subfolderStyle' => $style === 'flat' || $style === 'overview' ? $style : null,
        'flatNames' => is_bool($r['flatNames'] ?? null) ? $r['flatNames'] : null, 'flatNotes' => is_bool($r['flatNotes'] ?? null) ? $r['flatNotes'] : null,
        'photoSort' => is_array($r['photoSort'] ?? null) ? $r['photoSort'] : [],
        'items' => $items, 'at' => is_int($r['at'] ?? null) ? $r['at'] : 0,
    ];
}

/** Every well-formed record, in the order stored. [] when there is no file, or it can't be read. */
function collections_list() {
    if (isset($GLOBALS['__collections_cache']) && is_array($GLOBALS['__collections_cache'])) return $GLOBALS['__collections_cache'];
    $out = [];
    if (is_file(collections_path())) {
        [$state, $data] = json_file_load(collections_path(), collections_default());
        if ($state === 'ok') foreach ((array) ($data['collections'] ?? []) as $r) if (($c = collection_clean($r)) !== null) $out[] = $c;
    }
    return $GLOBALS['__collections_cache'] = $out;
}

/** Has the gallery any collections at all (the cheap question the rest of the code asks first)? */
function collections_any() { return is_file(collections_path()) && collections_list() !== []; }

/** The collections, with where they are: ['byPath' => full path => record, 'byParent' => parent path => [records], 'idPaths' => folder id => its path, 'taken' => the
 *  records whose address a real folder holds]. Each record gains 'path' and 'parentPath'. A record whose parent folder can't be found is left out of
 *  byPath/byParent (and is in 'lost'); so is one whose address a real folder has. $files is the complete list of the gallery's files (not the one
 *  filtered for a visitor): a folder is found by its id through the folders that hold files. */
function collections_registry($dir, $files = null) {
    if ($files === null) $files = $GLOBALS['allFiles'] ?? ($GLOBALS['files'] ?? []);
    $key = count($files) . '|' . (string) ($files[0] ?? '') . '|' . (string) ($files[count($files) - 1] ?? '');
    $cached = $GLOBALS['__collections_registry'] ?? null;
    if (is_array($cached) && $cached['key'] === $key && $files !== []) return $cached['reg'];
    $reg = ['byPath' => [], 'byParent' => [], 'idPaths' => [], 'taken' => [], 'lost' => []];
    $list = collections_list();
    if ($list) {
        foreach (folder_id_map_folders($dir, $files) as $id => $paths) if (count($paths) === 1) $reg['idPaths'][$id] = $paths[0];   // (an id that more than one folder carries points at nothing until it is sorted out)
        $real = array_flip(all_folder_paths($files));
        foreach (array_keys(gallery_mounts()) as $m) $real[$m] = true;
        foreach ($list as $r) {
            $parentPath = $r['parent'] === '' ? '' : ($reg['idPaths'][$r['parent']] ?? null);
            if ($parentPath === null) { $reg['lost'][] = $r; continue; }
            $path = $parentPath === '' ? $r['name'] : $parentPath . '/' . $r['name'];
            $r['path'] = $path; $r['parentPath'] = $parentPath;
            if (isset($real[$path])) { $reg['taken'][] = $r; continue; }
            if (isset($reg['byPath'][$path])) continue;   // (the first one stored keeps an address two share)
            $reg['byPath'][$path] = $r; $reg['byParent'][$parentPath][] = $r;
        }
    }
    if ($files !== []) $GLOBALS['__collections_registry'] = ['key' => $key, 'reg' => $reg];
    return $reg;
}

/** The collection at this full path, or null. */
function collection_at($dir, $path, $files = null) {
    if (!is_string($path) || $path === '' || !collections_any()) return null;
    return collections_registry($dir, $files)['byPath'][$path] ?? null;
}

/** May this visitor see this collection at all (its own card and page)? A private one is for the owner, the people who have the private-view
 *  password, and people on a share link that names it or is for everything; whoever may not sees nothing of it, not even that it is there. A link that
 *  limits what is seen shows only the collections it names. */
function collection_viewer_sees($rec) {
    if (is_revealed()) return true;
    $l = link_viewer();
    if ($l !== null) {
        $type = $l['scope']['type'] ?? 'all';
        if (in_array($type, ['folders', 'photos', 'mixed'], true)) return in_array($rec['id'], (array) ($l['scope']['folders'] ?? []), true);   // (a link that limits what is seen shows only the collections it names)
        if ($type === 'all') return true;   // (everything, public and private)
    }
    return empty($rec['private']);
}

/** Does the collection with this id hold this file (as it holds it: folders everything-inside or own-photos, single photos)? Worked out once per collection. */
function collection_holds_file($dir, $collectionId, $file) {
    static $sets = [];
    if (!isset($sets[$collectionId])) {
        $rec = collection_find_by_id($collectionId);
        $sets[$collectionId] = $rec === null ? [] : array_fill_keys(collection_member_files($dir, $rec, $GLOBALS['allFiles'] ?? ($GLOBALS['files'] ?? [])), true);
    }
    return isset($sets[$collectionId][$file]);
}

/** The files a collection holds, in the order of its members (a folder's files in the folder's order, a single photo where it is listed), not
 *  yet narrowed to what a visitor may see: that is done by the caller from the visitor's own list. $files is the complete list. */
function collection_member_files($dir, $rec, $files) {
    $reg = collections_registry($dir, $files);
    $by = []; $folderOf = [];
    foreach ($files as $f) { $by[$f] = true; $d = dirname($f); $folderOf[$f] = ($d === '.' || $d === '') ? '' : $d; }
    $out = []; $seen = [];
    foreach ($rec['items'] as $it) {
        $path = $reg['idPaths'][$it['fid']] ?? null;
        if ($path === null) continue;   // (the folder is gone, or its id is shared: the member is missing, and shows nowhere)
        if (isset($it['file'])) {
            $f = $path === '' ? $it['file'] : $path . '/' . $it['file'];
            if (isset($by[$f]) && !isset($seen[$f])) { $seen[$f] = true; $out[] = $f; }
            continue;
        }
        $prefix = $path === '' ? '' : $path . '/';
        foreach ($files as $f) {
            if ($prefix !== '' && strncmp($f, $prefix, strlen($prefix)) !== 0) continue;
            if (($it['mode'] ?? 'all') === 'own' && $folderOf[$f] !== $path) continue;
            if (!isset($seen[$f])) { $seen[$f] = true; $out[] = $f; }
        }
    }
    return $out;
}

/** What a folder's own record says about itself, for a collection: the same shape folder_display_meta gives, so a card, a page title and the
 *  order among siblings treat a collection like a folder. */
function collection_display_meta($rec) {
    return ['label' => $rec['title'], 'cover' => $rec['cover'], 'description' => $rec['description'], 'dates' => $rec['dates'], 'sortOrder' => $rec['position']];
}

/** The collections shown as cards on a page: those in this parent ('' is the front page), plus, on the front page, those from any other parent
 *  that are marked to show there. Each card is [key, record, files]: the key is the card's name on the page (the address name for a collection in
 *  this parent, its full path for one shown elsewhere), the files are the members the visitor may see ($visible is that visitor's list, and $all the complete one).
 *  A collection with nothing the visitor may see, or a private one for a visitor who may not, is left out. */
function collection_cards($dir, $parentPath, $all, $visible) {
    if (!collections_any()) return [];
    $reg = collections_registry($dir, $all);
    $vis = array_flip($visible);
    $recs = $reg['byParent'][$parentPath] ?? [];
    $fromElsewhere = [];
    if ($parentPath === '') foreach ($reg['byPath'] as $path => $r) if ($r['front'] && $r['parentPath'] !== '') $fromElsewhere[$path] = $r;
    $out = [];
    foreach ($recs as $r) {
        if (!collection_viewer_sees($r)) continue;
        $files = array_values(array_filter(collection_member_files($dir, $r, $all), function ($f) use ($vis) { return isset($vis[$f]); }));
        if ($files) $out[] = [$r['name'], $r, $files];
    }
    foreach ($fromElsewhere as $path => $r) {
        if (!collection_viewer_sees($r)) continue;
        $files = array_values(array_filter(collection_member_files($dir, $r, $all), function ($f) use ($vis) { return isset($vis[$f]); }));
        if ($files) $out[] = [$path, $r, $files];
    }
    return $out;
}

/** What the page for a collection address needs: ['rec' => the record, 'files' => the members this visitor may see, 'folders' => [member folder path =>
 *  its files], 'loose' => [single photos]], or null when there is no such collection for this visitor (the answer is then the same missing page as any
 *  other address that leads nowhere). $all is the complete list of files, $visible this visitor's. */
function collection_page($dir, $path, $all, $visible) {
    $rec = collection_at($dir, $path);
    if ($rec === null || !collection_viewer_sees($rec)) return null;
    $vis = array_flip($visible);
    $reg = collections_registry($dir, $all);
    if ($rec['parentPath'] !== '' && !array_filter($visible, function ($f) use ($rec) { return strncmp($f, $rec['parentPath'] . '/', strlen($rec['parentPath']) + 1) === 0; })) return null;   // (the folder it is in shows this visitor nothing: nor does it)
    $folders = []; $loose = []; $files = [];
    foreach ($rec['items'] as $it) {
        $p = $reg['idPaths'][$it['fid']] ?? null;
        if ($p === null) continue;
        if (isset($it['file'])) {
            $f = $p === '' ? $it['file'] : $p . '/' . $it['file'];
            if (isset($vis[$f]) && !isset($files[$f])) { $files[$f] = true; $loose[] = $f; }
            continue;
        }
        if ($p === '') continue;   // (the gallery's own top is not a member)
        $mine = collection_member_files($dir, ['items' => [$it]], $all);
        $mine = array_values(array_filter($mine, function ($f) use ($vis) { return isset($vis[$f]); }));
        if (!$mine) continue;
        $folders[$p] = isset($folders[$p]) ? array_values(array_unique(array_merge($folders[$p], $mine))) : $mine;
        foreach ($mine as $f) $files[$f] = true;
    }
    if (!$files) return null;
    return ['rec' => $rec, 'files' => array_keys($files), 'folders' => $folders, 'loose' => $loose];
}
/* -----------------------------------------------------------------------
 * The trip map (?map, ENABLE_PHOTO_LOCATION): one overview map per gallery root,
 * every subfolder's pins together. Leaflet + OpenStreetMap tiles — the
 * only realistic option with no API key — loaded from a CDN only when
 * this is actually on, since it's the first thing in this script to ever
 * make an outbound, third-party request. Clustering is plain haversine-
 * distance arithmetic, no mapping-library plugin for that part.
 * ----------------------------------------------------------------------- */

/** Great-circle distance between two lat/lng points, in miles. */
function haversine_miles($lat1, $lng1, $lat2, $lng2) {
    $earthRadiusMiles = 3958.8;
    $dLat = deg2rad($lat2 - $lat1);
    $dLng = deg2rad($lng2 - $lng1);
    $a = sin($dLat / 2) ** 2 + cos(deg2rad($lat1)) * cos(deg2rad($lat2)) * sin($dLng / 2) ** 2;
    return $earthRadiusMiles * 2 * atan2(sqrt($a), sqrt(1 - $a));
}

/** Greedy single-pass clustering: the first not-yet-clustered point
 *  anchors a new cluster and absorbs every remaining point within
 *  MAP_CLUSTER_RADIUS_MILES of *that anchor* (not re-measured from newly
 *  absorbed members) — simple and deterministic, not necessarily the
 *  tightest possible grouping, which is fine for "nearby photos read as
 *  one pin," not a precision clustering problem. */
function cluster_map_points($points, $radiusMiles) {
    // 0 means no grouping at all: every photo is its own pin (for a dense city, where even a tenth of a mile is too much).
    if ($radiusMiles <= 0) return array_map(function ($p) { return [$p]; }, array_values($points));
    $clusters = [];
    $used = array_fill(0, count($points), false);
    for ($i = 0; $i < count($points); $i++) {
        if ($used[$i]) continue;
        $cluster = [$points[$i]];
        $used[$i] = true;
        for ($j = $i + 1; $j < count($points); $j++) {
            if ($used[$j]) continue;
            if (haversine_miles($points[$i]['lat'], $points[$i]['lng'], $points[$j]['lat'], $points[$j]['lng']) <= $radiusMiles) {
                $cluster[] = $points[$j];
                $used[$j] = true;
            }
        }
        $clusters[] = $cluster;
    }
    return $clusters;
}

/** A fixed, high-contrast palette cycling by index — plenty of
 *  realistic top-level groups (trip folders) will fit before repeating,
 *  and a repeat is a cosmetic coincidence, not a correctness problem
 *  (the legend still names each group correctly regardless). */
function map_group_color($index) {
    static $palette = ['#e6194b', '#3cb44b', '#4363d8', '#f58231', '#911eb4', '#42d4f4', '#f032e6', '#bfef45', '#fabed4', '#469990'];
    return $palette[$index % count($palette)];
}

/** Where a pin's popup link actually goes — the identical destination
 *  logic already used for mention-links and copy-link buttons: a
 *  top-level folder-group in 'overview' mode gets its own ?folder= page;
 *  anything else (a filename-based group, an explicit group, or a plain
 *  standalone single) gets its #group-<slug> anchor on the current page,
 *  not a separate linking system. */
function map_point_link($file, $groupKey, $folderGroupKeys) {
    if ($groupKey !== null && isset($folderGroupKeys[$groupKey]) && !folder_style_flat()) {
        // The photo is inside a folder this page shows only as a card: open the folder it is really in, on that photo (a bare folder link
        // left you at the top of a page of hundreds with no sign of the one you pressed). If the photo is part of a group there, the
        // anchor finds nothing and the folder's page simply opens.
        $dirOf = dirname($file);
        return '?folder=' . rawurlencode($dirOf !== '.' && $dirOf !== '' ? $dirOf : $groupKey) . '#group-' . slugify(pathinfo(basename($file), PATHINFO_FILENAME));
    }
    $slug = slugify($groupKey !== null ? $groupKey : pathinfo(basename($file), PATHINFO_FILENAME));
    return '#group-' . $slug;
}

/** Whether a folder — or the gallery root, with $folderPath null — shows a map
 *  of its own photos on its page (and has its own ?map&folder= page). Stored
 *  with the folder like its location switch. The root keeps the behaviour it
 *  always had, so it is on unless switched off; a folder starts off, since
 *  turning one on makes its page load a third-party map. */
function folder_map_enabled($dir, $folderPath) {
    $data = items_read($folderPath === null ? $dir : resolve_real_path($dir, $folderPath));
    $v = $data['mapEnabled'] ?? null;
    return $folderPath === null ? $v !== false : $v === true;
}

/** How close (in miles) photos must be to share one pin on this page's map:
 *  the folder's own setting if it has one, else the site-wide default. */
function folder_map_radius($dir, $folderPath) {
    $data = items_read($folderPath === null ? $dir : resolve_real_path($dir, $folderPath));
    $r = $data['mapRadius'] ?? null;
    return (is_int($r) || is_float($r)) && $r >= 0 && $r <= 10000 ? $r : MAP_CLUSTER_RADIUS_MILES;
}

/** The points for one folder's map: just those inside it (and its subfolders),
 *  coloured by which subfolder they are in, with the photos directly in the
 *  folder under the folder's own name. At the root this is every point, as
 *  collected. Nothing here widens what is shown: the points arrive already
 *  filtered by hiding and by the location switches. */
function map_points_for_folder($points, $dir, $folderPath) {
    if ($folderPath === null) return $points;
    $prefix = $folderPath . '/';
    $metaLabel = folder_display_meta($dir, $folderPath)['label'];
    $folderLabel = $metaLabel !== '' ? $metaLabel : basename($folderPath);
    $out = []; $colorIndex = []; $next = 0;
    foreach ($points as $p) {
        if (strpos($p['file'], $prefix) !== 0) continue;
        $rest = substr($p['file'], strlen($prefix));
        $slash = strpos($rest, '/');
        $child = $slash === false ? '' : substr($rest, 0, $slash);
        if (!isset($colorIndex[$child])) $colorIndex[$child] = $next++;
        if ($child === '') {
            $p['label'] = $folderLabel;
            $p['link'] = '#group-' . slugify(pathinfo(basename($p['file']), PATHINFO_FILENAME));
        } else {
            $childMeta = folder_display_meta($dir, $prefix . $child);
            $p['label'] = $childMeta['label'] !== '' ? $childMeta['label'] : $child;
            $p['link'] = '?folder=' . rawurlencode(dirname($p['file'])) . '#group-' . slugify(pathinfo(basename($p['file']), PATHINFO_FILENAME));   // (the folder the photo is really in, on that photo)
        }
        $p['color'] = map_group_color($colorIndex[$child]);
        $out[] = $p;
    }
    return $out;
}

/**
 * Every visible, located point worth plotting — already filtered the
 * same way everything else on the page is: $files/$itemsData here are
 * whatever they stand as *after* the hiding filter above, so a hidden
 * item is never plotted, same as its thumbnail and its file bytes never
 * load for an unrevealed visitor. photo_location_visible() applies the
 * same three location gates (global/folder/per-item) a grid badge
 * already does. Each point is colored and grouped by its top-level
 * identity (folder-group if it has one, otherwise its own group key) so
 * a Paris cluster and a StTropez cluster read as visually distinct.
 */
function collect_map_points($dir, $files, $itemsData, $fileToGroupKey, $folderGroupKeys, $groupLabels) {
    $points = [];
    $groupColorIndex = [];
    $nextColorIndex = 0;
    foreach ($files as $file) {
        $entry = $itemsData[$file] ?? [];
        if (!photo_location_visible($entry)) continue;
        $loc = $entry['location'];
        $groupKey = $fileToGroupKey[$file] ?? null;
        $colorKey = $groupKey ?? $file;
        if (!isset($groupColorIndex[$colorKey])) {
            $groupColorIndex[$colorKey] = $nextColorIndex++;
        }
        $label = $groupKey !== null ? ($groupLabels[$groupKey] ?? $groupKey) : pathinfo(basename($file), PATHINFO_FILENAME);
        $points[] = [
            'lat' => (float) $loc['lat'],
            'lng' => (float) $loc['lng'],
            'file' => $file,
            'caption' => $entry['caption'] ?? '',
            'label' => $label,
            'color' => map_group_color($groupColorIndex[$colorKey]),
            'thumbUrl' => img_url($file, 'thumb'),
            'link' => map_point_link($file, $groupKey, $folderGroupKeys),
        ];
    }
    return $points;
}

/** Recolours map pins by what the page's notes say about the group each photo is in: a {color:} gives its photos
 *  that colour, {sold} and {reserved} the same red and orange as their ribbons (status wins over colour, as it does on
 *  the page). A recoloured pin takes its group's name in the legend. Photos in groups the notes don't mention keep their
 *  folder colour. */
function apply_note_colors_to_points($points, $groups, $groupColors, $groupStatus, $groupLabels) {
    $byFile = [];
    foreach ($groups as $key => $members) {
        $status = $groupStatus[$key] ?? '';
        $color = $status === 'sold' ? '#e5484d' : ($status === 'reserved' ? '#f5a623' : ($groupColors[$key] ?? null));
        if ($color === null || !is_safe_color($color)) continue;
        foreach ($members as $f) $byFile[$f] = [$color, $groupLabels[$key] ?? $key];
    }
    foreach ($points as &$pt) {
        if (isset($byFile[$pt['file']])) { $pt['color'] = $byFile[$pt['file']][0]; $pt['label'] = $byFile[$pt['file']][1]; }
    }
    unset($pt);
    return $points;
}

/** The legend: one swatch + label per distinct group actually plotted,
 *  in first-seen order — a color-coded map means nothing without a key
 *  to read it against. */
function map_legend_from_points($points) {
    $seen = [];
    $legend = [];
    foreach ($points as $p) {
        if (isset($seen[$p['color'] . '|' . $p['label']])) continue;
        $seen[$p['color'] . '|' . $p['label']] = true;
        $legend[] = ['color' => $p['color'], 'label' => $p['label']];
    }
    return $legend;
}

/**
 * Renders one Leaflet map instance — the shared markup/JS for both the
 * condensed root-page preview and the full ?map page, parameterized over
 * container id and height so the same code draws both. Loads Leaflet's
 * CSS and JS from the cdnjs CDN (two third-party requests, plus the OSM
 * tiles themselves) — only emitted when there's actually at least one
 * point to plot.
 */
function render_leaflet_map($points, $legend, $mapId, $heightCss, $loadLibrary, $radiusMiles = null, $lazy = false, $twoFingers = false) {
    if (empty($points)) return;
    $clusters = cluster_map_points($points, $radiusMiles ?? MAP_CLUSTER_RADIUS_MILES);
    // Hex-escaped so the raw JSON can sit directly inside a <script>
    // block with no further quoting — safe even if a caption happens to
    // contain "</script>", a quote, or an ampersand.
    $clustersJson = json_encode($clusters, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
?>
<?php if ($loadLibrary && !$lazy): ?>
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.css" integrity="sha384-sHL9NAb7lN7rfvG5lfHpm643Xkcjzp4jFvuavGOndn6pjVqS6ny56CAt3nsEVT4H" crossorigin="anonymous">
<script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js" integrity="sha384-cxOPjt7s7Iz04uaHJceBmS+qpjv2JkIHNVcuOrM+YHwZOmJGBXI00mdUXEq65HTH" crossorigin="anonymous"></script>
<?php endif; ?>
<div id="<?= htmlspecialchars($mapId, ENT_QUOTES, 'UTF-8') ?>" style="height:<?= htmlspecialchars($heightCss, ENT_QUOTES, 'UTF-8') ?>; border-radius:10px;"></div>
<?php if (!empty($legend)): ?>
<div class="map-legend">
  <?php foreach ($legend as $l): ?>
    <span class="map-legend-item"><span class="map-legend-swatch" style="background:<?= htmlspecialchars($l['color'], ENT_QUOTES, 'UTF-8') ?>;"></span><?= htmlspecialchars($l['label'], ENT_QUOTES, 'UTF-8') ?></span>
  <?php endforeach; ?>
</div>
<?php endif; ?>
<script>
(function () {
  var clusters = <?= $clustersJson ?>;
  var mapEl = document.getElementById('<?= htmlspecialchars($mapId, ENT_QUOTES, 'UTF-8') ?>');
  function draw() {
  if (!mapEl || !window.L) return;
  var coarse = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
  var twoFingers = <?= $twoFingers ? 'true' : 'false' ?> && coarse;   // (a map in the middle of a page on a phone: one finger scrolls the page, two move the map)
  var groupOnScreen = <?= (($radiusMiles ?? MAP_CLUSTER_RADIUS_MILES) > 0) ? 'true' : 'false' ?>;
  var map = L.map(mapEl, { dragging: !twoFingers });
  if (twoFingers) {
    var hint = document.createElement('div'); hint.className = 'map-hint'; hint.hidden = true; hint.textContent = 'Use two fingers to move the map'; mapEl.appendChild(hint);
    var hintTimer = null, hintFrom = null;
    mapEl.addEventListener('touchstart', function (e) { hintFrom = e.touches.length === 1 ? [e.touches[0].clientX, e.touches[0].clientY] : null; if (e.touches.length > 1) hint.hidden = true; }, { passive: true });
    mapEl.addEventListener('touchmove', function (e) {
      if (e.touches.length !== 1 || !hintFrom) return;
      if (Math.abs(e.touches[0].clientX - hintFrom[0]) + Math.abs(e.touches[0].clientY - hintFrom[1]) < 10) return;
      hint.hidden = false; clearTimeout(hintTimer); hintTimer = setTimeout(function () { hint.hidden = true; }, 1400);
    }, { passive: true });
  }
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a> contributors',
    maxZoom: 19,
  }).addTo(map);

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = s;
    return d.innerHTML;
  }

  function popupHtml(pt) {
    var cap = pt.caption ? pt.caption : pt.label;
    return '<a href="' + escapeHtml(pt.link) + '" style="display:block;text-decoration:none;color:inherit;">' +
      '<img src="' + escapeHtml(pt.thumbUrl) + '" style="width:120px;height:120px;object-fit:cover;border-radius:6px;display:block;margin-bottom:6px;" loading="lazy">' +
      '<strong>' + escapeHtml(cap) + '</strong></a>';
  }

  // Pins: photos within the grouping distance (server side, in miles) always share a pin. On top of that, pins that would
  // overlap on screen at the current zoom are merged (and split again as the map is zoomed in), so every pin on screen can be
  // pressed with a finger. Pressing a group zooms in until its photos part; where they can't (the zoom is at its limit) it
  // opens into one pin per photo. A distance of 0 means no grouping at all, so nothing is merged then either.
  var SEP = 40;
  var layer = L.layerGroup().addTo(map);
  var shown = null, n = 0;
  clusters.forEach(function (ms) { ms.forEach(function (m) { m._i = n++; }); });
  var base = clusters.map(function (ms) {
    return { members: ms, lat: ms.reduce(function (s, m) { return s + m.lat; }, 0) / ms.length, lng: ms.reduce(function (s, m) { return s + m.lng; }, 0) / ms.length, solo: false };
  });
  function keyOf(ms) { return ms.map(function (m) { return m._i; }).join(','); }
  function partsOf(it) { return it.parts || [it]; }
  function combine(a, b) {
    var na = a.members.length, nb = b.members.length;
    return { members: a.members.concat(b.members), parts: partsOf(a).concat(partsOf(b)), solo: false, lat: (a.lat * na + b.lat * nb) / (na + nb), lng: (a.lng * na + b.lng * nb) / (na + nb) };
  }
  function merge(items) {
    var out = [], used = [], pts = items.map(function (it) { return map.latLngToLayerPoint([it.lat, it.lng]); }), i, j;
    for (i = 0; i < items.length; i++) {
      if (used[i]) continue;
      var it = items[i]; used[i] = true;
      for (j = i + 1; !it.solo && j < items.length; j++) {
        if (!used[j] && !items[j].solo && pts[i].distanceTo(pts[j]) < SEP) { it = combine(it, items[j]); used[j] = true; }
      }
      out.push(it);
    }
    return out;
  }
  function arrange() {
    var items = base.slice();
    if (groupOnScreen) {
      items = merge(items);
      // (a merged group sits at its middle, which can be near another one: go again until none are, for a page of a sensible size)
      for (var pass = 0; pass < 6 && items.length <= 300; pass++) {
        var next = merge(items); if (next.length === items.length) break; items = next;
      }
    }
    var sig = items.map(function (it) { return keyOf(it.members); }).join('|');
    if (sig === shown) return;
    shown = sig;
    layer.clearLayers();
    items.forEach(function (it) { if (it.members.length === 1) addSingle(it.members[0]); else addCluster(it); });
  }
  function addSingle(pt) {
    L.circleMarker([pt.lat, pt.lng], { radius: coarse ? 12 : 9, color: '#fff', weight: 2, fillColor: pt.color, fillOpacity: 0.9 })
      .addTo(layer)
      .bindPopup(popupHtml(pt));
  }
  function addCluster(it) {
    var members = it.members;
    var marker = L.marker([it.lat, it.lng], {
      icon: L.divIcon({
        html: '<div style="background:' + members[0].color + ';color:#fff;border-radius:50%;width:32px;height:32px;display:flex;align-items:center;justify-content:center;font-size:0.85rem;font-weight:600;box-shadow:0 0 0 2px #fff;">' + members.length + '</div>',
        className: '', iconSize: [32, 32], iconAnchor: [16, 16],
      }),
    }).addTo(layer);
    marker.on('click', function () {
      var parts = partsOf(it);
      var bounds = L.latLngBounds(members.map(function (m) { return [m.lat, m.lng]; }));
      var z = Math.min(18, map.getBoundsZoom(bounds, false, L.point(86, 86)));
      if (parts.length === 1) {   // one pin of photos within the grouping distance: it opens into its photos (which then group by screen distance like any others)
        var at = base.indexOf(parts[0]);
        base.splice.apply(base, [at, 1].concat(members.map(function (m) { return { members: [m], lat: m.lat, lng: m.lng, solo: false }; })));
      } else if (z >= 18 || z <= map.getZoom()) {   // several pins that zooming can't part: they stay as they are, each pin on its own
        parts.forEach(function (p) { p.solo = true; });
      }
      if (z > map.getZoom()) map.fitBounds(bounds, { maxZoom: 18, paddingTopLeft: [56, 56], paddingBottomRight: [30, 30] });   // (the zoom's end groups again)
      else arrange();
    });
  }

  var allBounds = [];
  clusters.forEach(function (members) { members.forEach(function (m) { allBounds.push([m.lat, m.lng]); }); });
  if (allBounds.length === 1) {
    map.setView(allBounds[0], 13);
  } else {
    map.fitBounds(allBounds, { paddingTopLeft: [56, 56], paddingBottomRight: [30, 30] });   // (the zoom buttons sit in the top left corner: keep the pins out from under them)
  }
  arrange();
  map.on('zoomend', arrange);
  }
<?php if ($lazy): ?>
  // Nothing is fetched from anywhere until a visitor asks for the map (see showLazyMap in the page script).
  (window.__lazyMaps = window.__lazyMaps || {})['<?= htmlspecialchars($mapId, ENT_QUOTES, 'UTF-8') ?>'] = draw;
<?php else: ?>
  draw();
<?php endif; ?>
})();
