            ['name' => 'ADMIN_STAY_SIGNED_IN_DAYS', 'type' => 'number', 'label' => 'Stay signed in as the admin for (days)', 'min' => 0, 'max' => 365, 'step' => 1,
             'help' => 'Counted from your last visit, so regular use never signs you out; it keeps a Home Screen app signed in. 0 signs you out when the browser closes. Changing the password or pressing Log out ends it on every device, and the list below ends one device at a time.',
             'risk' => 'A phone or computer that is lost or left unlocked stays signed in as the admin for that long. End it in the list below, or change the admin password.'],
            ['name' => 'PRIVATE_VIEW_SIGNED_IN_DAYS', 'type' => 'number', 'label' => 'Stay in private view for (days)', 'min' => 0, 'max' => 365, 'step' => 1,
             'help' => 'How long a phone or computer that was given the private-view password keeps seeing private items, counted from its last visit. 0 ends it when the browser closes. Changing the private-view password ends it for everyone; the list below ends one device at a time.',
             'risk' => 'Whoever has typed the private-view password stays in private view on that device for that long.'],
            ['name' => 'COUNTRY_LOOKUP', 'type' => 'bool', 'in' => true, 'label' => 'Look up the country of each address', 'help' => ''],
            ['name' => 'COUNTRY_DB_URL', 'type' => 'text', 'in' => true, 'label' => 'Where the country file comes from', 'help' => ''],
            ['name' => 'BROWSER_HISTORY_DAYS', 'type' => 'number', 'label' => 'Keep each browser\'s address history for (days)', 'min' => 1, 'max' => 3650, 'step' => 1,
             'help' => 'Every address a signed-in browser has used, with the time, the country when known and the device it said it was. Inside this time nothing limits how much is kept; the list shows how big each one has grown.'],
            ['name' => 'BROWSER_ENDED_DAYS', 'type' => 'number', 'label' => 'Keep signed-out browsers listed for (days)', 'min' => 0, 'max' => 3650, 'step' => 1,
             'help' => 'A browser that was signed out, logged out, expired or ended automatically stays under Recently signed out, with its addresses, so you can see what it did. 0 forgets it at once.'],
            ['name' => 'BROWSER_NETWORKS_ALARM', 'type' => 'number', 'label' => 'Flag a browser used from more than this many networks in 24 hours', 'min' => 2, 'max' => 1000, 'step' => 1,
             'help' => 'A network is an IPv4 block of 256 addresses or an IPv6 /64 (one home, one phone connection). A phone moving between wifi and mobile data uses a few; a stolen cookie sent through a rotating pool uses many. Each row shows its busiest day: set this above your own.'],
            ['name' => 'BROWSER_END_ON_DEVICE', 'type' => 'bool', 'label' => 'Sign a browser out if it is used from a different device of the same kind',
             'help' => 'A sign-in made on an iPhone, then seen as an iPad or a Mac. An iPad (and an iPhone using "Request Desktop Website") says it is a Mac, so this can sign the right person out. Always flagged in amber; best left off.'],
            ['name' => 'BROWSER_END_ON_FAMILY', 'type' => 'bool', 'label' => 'Sign a browser out if it is used from a different kind of device',
             'help' => 'Apple (iPhone, iPad, Mac), Android, Windows and Linux are kinds: a sign-in made on an iPhone that is then used as a Windows PC. Always flagged in red; this also signs it out.'],
            ['name' => 'BROWSER_END_ON_COUNTRY', 'type' => 'bool', 'label' => 'Sign a browser out if it is used from a new country',
             'help' => 'Needs a country for each address (the country lookup below, or a country header from your proxy). Always flagged in red; this also signs it out. Someone travelling or on a VPN will have to type the password again.'],
            ['name' => 'BROWSER_END_ON_NETWORKS', 'type' => 'bool', 'label' => 'Sign a browser out if it passes the networks limit',
             'help' => 'The limit above. Always flagged in red; this also signs it out.'],
        ]],
        ['title' => 'Server setup (advanced)', 'items' => [
            ['name' => 'CHECK_FOR_UPDATES', 'type' => 'bool', 'label' => 'Look for a new version of the gallery',
             'help' => 'Once a day the Health check asks GitHub which version is newest and says so when it is newer, with View release and Update now. Only an ordinary request is made (GitHub sees this server\'s address); nothing about your gallery is sent. Off: no automatic look; Check now still works.'],
            ['name' => 'UPDATE_FEED_URL', 'type' => 'text', 'in' => true, 'label' => 'Where new versions are announced', 'help' => ''],
            ['name' => 'TRUSTED_PROXY', 'type' => 'enum', 'label' => 'Where visitors\' IP addresses come from', 'status' => 'clientip',
             'options' => ['direct' => 'The connection', 'cloudflare' => 'Cloudflare', 'proxy' => 'Another proxy'],
             'help' => 'Behind Cloudflare or another CDN, every visitor looks the same unless the gallery reads their real address. Choose yours; leave it on "The connection" if your web server already passes the real address on (the Visitors tab then shows no country, which comes from Cloudflare). Another proxy: set TRUSTED_PROXY_RANGES in .gallery-config.php.'],
            ['name' => 'EXTRA_FOLDERS', 'type' => 'folders', 'label' => 'Folders from elsewhere on the server',
             'help' => 'Show a place elsewhere on the server (an archive on another disk). Without a name, the folders inside it appear at the top of the gallery (/space/trip holding Paris and StTropez gives you Paris and StTropez); with a name, the whole place shows as that one folder. Needs "Show subfolders".',
             'risk' => 'Every photo and video there becomes visible.'],
            ['name' => 'NGINX_ACCEL_REDIRECT_PREFIX', 'type' => 'text', 'label' => 'nginx internal redirect', 'status' => 'accel',
             'help' => 'Lets nginx send photos and videos instead of PHP: faster, and videos seek better. Needs the matching internal location (the rule is under this row) and the gallery\'s own address, such as /kb. Files from elsewhere are always sent by the gallery.',
             'risk' => 'Without the matching nginx location, photos and videos stop loading.'],
        ]],
    ];
}

/** Checks the places from elsewhere that the Settings screen posts (JSON: {"named": {name: path}, "roots": [path]})
 *  before anything is stored. A path must be a real, readable folder, written as the real path (no symlink anywhere in
 *  it, since the scan refuses to follow them), outside this gallery's own folder and not one that contains it. Returns
 *  ['named' => ..., 'roots' => ...] clean, or null with reasons in $errors. */
function site_settings_validate_extra_folders($raw, &$errors) {
    $in = json_decode((string) $raw, true);
    if (!is_array($in) || !isset($in['named'], $in['roots']) || !is_array($in['named']) || !is_array($in['roots']) || !array_is_list($in['roots'])) { $errors[] = 'The list of folders from elsewhere wasn\'t understood.'; return null; }
    if (count($in['named']) + count($in['roots']) > 50) { $errors[] = 'That is more folders from elsewhere than the gallery allows (50).'; return null; }
    $gallery = realpath(__DIR__);
    $bad = false;
    // One path check for both kinds; $q names the entry in any message.
    $checkPath = function ($path, $q) use ($gallery, &$errors, &$bad) {
        if (!is_string($path)) { $errors[] = "The path for $q isn't text."; $bad = true; return null; }
        $p = rtrim($path, '/\\');
        if ($p === '' || preg_match('#[\x00-\x1F\x7F]#', $path) || !preg_match('#^(/|[A-Za-z]:[\\\\/])#', $p) || preg_grep('#^\.\.?$#', preg_split('#[\\\\/]+#', $p))) {
            $errors[] = "The path for $q must be a full path starting with / (no .. in it)."; $bad = true; return null;
        }
        if (!@is_dir($p) || !@is_readable($p)) {
            $errors[] = "The path for $q ($p) isn't a folder this server can read. Check it exists and that the web server may open it (and, on shared hosting, that PHP is allowed outside the website's folder)."; $bad = true; return null;
        }
        $real = realpath($p);
        if (is_link($p) || $real === false || $real !== $p) {
            $errors[] = "The path for $q goes through a link or isn't written as its real path" . ($real ? " (it is $real)" : '') . ". The gallery doesn't follow links, so give the real path."; $bad = true; return null;
        }
        if ($gallery !== false && ($real === $gallery || str_starts_with($real . '/', $gallery . '/') || str_starts_with($gallery . '/', $real . '/'))) {
            $errors[] = "The path for $q overlaps this gallery's own folder (inside it, or containing it), which would show things twice or expose too much."; $bad = true; return null;
        }
        return $real;
    };
    $named = []; $seen = [];
    foreach ($in['named'] as $name => $path) {
        $name = (string) $name; $q = '"' . $name . '"';
        if ($name === '' || $name !== trim($name) || strlen($name) > 60 || $name[0] === '.' || preg_match('#[/\\\\\x00-\x1F\x7F]#', $name)) {
            $errors[] = "$q isn't a usable folder name: 1 to 60 characters, no slashes, no leading dot or space."; $bad = true; continue;
        }
        if (isset($seen[strtolower($name)])) { $errors[] = "The name $q is used twice."; $bad = true; continue; }
        $seen[strtolower($name)] = true;
        if (is_dir(__DIR__ . '/' . $name)) { $errors[] = "A folder called $q already exists in the gallery, so that name is taken."; $bad = true; continue; }
        $real = $checkPath($path, $q);
        if ($real !== null) $named[$name] = $real;
    }
    $roots = [];
    foreach ($in['roots'] as $path) {
        $real = $checkPath($path, is_string($path) ? '"' . $path . '"' : 'a folder');
        if ($real === null) continue;
        if (in_array($real, $roots, true)) { $errors[] = '"' . $real . '" is listed twice.'; $bad = true; continue; }
        $roots[] = $real;
    }
    $edit = null;   // (an Edit names the place it started from: its path, to carry that place's list of names to the new path)
    if (isset($in['edit']) && is_array($in['edit']) && is_string($in['edit']['path'] ?? null) && is_string($in['edit']['label'] ?? null)) $edit = ['path' => rtrim($in['edit']['path'], '/\\'), 'label' => $in['edit']['label']];
    return $bad ? null : ['named' => $named, 'roots' => $roots, 'edit' => $edit];
}

/** The names each named place has been shown under (path => [names]) after a save of the list: every name in the list before and after joins its
 *  place's names, and an Edit that moved the place to another path takes its names along. Kept short. $after is the validated name => path. */
function extra_folder_names_update($history, $before, $after, $edit) {
    $h = [];
    foreach ((array) $history as $path => $names) if (is_string($path) && is_array($names)) $h[$path] = array_values(array_filter($names, 'is_string'));
    foreach ([(array) $before, (array) $after] as $map) {
        foreach ($map as $label => $path) {
            if (!is_string($path) || !is_string($label)) continue;
            if (!isset($h[$path])) $h[$path] = [];
            if (!in_array($label, $h[$path], true)) $h[$path][] = $label;
        }
    }
    if ($edit !== null && isset($after[$edit['label']])) {
        $new = $after[$edit['label']];
        if ($edit['path'] !== '' && $edit['path'] !== $new && isset($h[$edit['path']]) && !in_array($edit['path'], array_values($after), true)) {
            foreach ($h[$edit['path']] as $label) { if (!isset($h[$new])) $h[$new] = []; if (!in_array($label, $h[$new], true)) $h[$new][] = $label; }
            unset($h[$edit['path']]);
        }
    }
    $shown = array_values((array) $after);
    foreach ($h as $path => $names) { if (count($names) < 2 && in_array($path, $shown, true)) unset($h[$path]); else $h[$path] = array_slice($names, -20); }   // (a place shown under one name needs no list; one taken out keeps its name for when it is added again)
    return array_slice($h, -50, null, true);
}

/** The nginx prefix: empty, or a plain URL path such as /kb. */
function site_settings_valid_nginx_prefix($value) {
    if ($value === '') return true;
    if (strlen($value) > 120 || $value[0] !== '/' || str_ends_with($value, '/') || str_contains($value, '//')) return false;
    foreach (explode('/', substr($value, 1)) as $segment) {
        if ($segment === '' || $segment === '.' || $segment === '..' || !preg_match('/^[A-Za-z0-9._~-]+$/', $segment)) return false;
    }
    return true;
}

/** The settings file's exact text for $cfg: the data guard, then the keys in
 *  a stable order as JSON. Returns null if it can't be encoded (invalid
 *  UTF-8 in a value). */
function gallery_config_render($cfg) {
    $order = [];
    foreach (gallery_setting_definitions() as $group) foreach ($group['items'] as $d) $order[] = $d['name'];
    foreach (['ADMIN_PASSWORD', 'PRIVATE_VIEW_PASSWORD', 'EXTRA_FOLDERS', 'EXTRA_FOLDER_NAMES', 'HEALTH_SET_ASIDE', 'PUBLIC_DOWNLOAD_MODE', 'PUBLIC_DOWNLOAD_FOLDERS', 'PUBLIC_DOWNLOAD_ROOT', 'EXTRA_ROOTS', 'NGINX_ACCEL_REDIRECT_PREFIX'] as $n) $order[] = $n;
    $keys = array_values(array_unique(array_merge(array_values(array_intersect($order, array_keys($cfg))), array_keys($cfg))));
    $ordered = [];
    foreach ($keys as $k) $ordered[$k] = $cfg[$k];
    $json = json_encode($ordered === [] ? new stdClass() : $ordered, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG);
    return $json === false ? null : data_file_guard_line() . $json . "\n";
}

/** Validates the Settings form and rewrites .gallery-config.php, and
 *  nothing else: captions, locations, hide flags, stats and notes are never
 *  read or written here. Returns an admin result array. */
function site_settings_save($ajax = false) {
    $state = gallery_config_load();
    $path = gallery_config_path();
    if (!in_array($state['status'], ['absent', 'ok'], true)) {
        return ['type' => 'error', 'text' => 'The settings file (.gallery-config.php) exists but can\'t be read as settings, so nothing was changed — saving would overwrite whatever is in it. Fix or delete that file, then try again.'];
    }
    $currentRaw = is_file($path) ? (string) file_get_contents($path) : '';
    if (!hash_equals(md5($currentRaw), (string) ($_POST['config_hash'] ?? ''))) {
        return ['type' => 'error', 'text' => 'The settings file' . admin_stale_message()];
    }
    $cfg = $state['cfg'];
    $defaults = $GLOBALS['__gallery_defaults'] ?? [];
    $errors = [];
    $setOrUnset = function ($name, $value) use (&$cfg, $defaults) {
        if (array_key_exists($name, $defaults) && $defaults[$name] === $value) unset($cfg[$name]); else $cfg[$name] = $value;
    };
    foreach (gallery_setting_definitions() as $group) {
        foreach ($group['items'] as $d) {
            $name = $d['name'];
            if (!isset($_POST['set_' . $name]) || !is_string($_POST['set_' . $name])) continue;
            $raw = $_POST['set_' . $name];
            if ($d['type'] === 'bool') {
                $value = $raw === '1';
            } elseif ($d['type'] === 'folders') {
                $value = site_settings_validate_extra_folders($raw, $errors);
                if ($value === null) continue;
                $setOrUnset('EXTRA_ROOTS', $value['roots']);
                $history = extra_folder_names_update($cfg['EXTRA_FOLDER_NAMES'] ?? [], $state['cfg']['EXTRA_FOLDERS'] ?? [], $value['named'], $value['edit']);
                if ($history) $cfg['EXTRA_FOLDER_NAMES'] = $history; else unset($cfg['EXTRA_FOLDER_NAMES']);
                $value = $value['named'];
            } elseif ($d['type'] === 'text') {
                if (!site_settings_valid_nginx_prefix($raw)) { $errors[] = '"' . $d['label'] . '" must be empty or a plain path like /kb (starting with /, no trailing slash, letters, digits and . _ ~ - only).'; continue; }
                $value = $raw;
            } elseif ($d['type'] === 'pathlist') {
                $list = json_decode($raw, true);
                $value = [];
                if (!is_array($list) || count($list) > 500) { $errors[] = '"' . $d['label'] . '" must be a list of folders.'; continue; }
                foreach ($list as $p) {
                    if (!is_string($p) || $p === '' || strlen($p) > 400 || $p[0] === '/' || strpbrk($p, "\0\\") !== false || preg_match('~(^|/)\.\.?(/|$)~', $p)) { $errors[] = '"' . $d['label'] . '" holds something that is not a folder of the gallery.'; continue 2; }
                    $value[] = rtrim($p, '/');
                }
                $value = array_values(array_unique($value));
            } elseif ($d['type'] === 'sortfirst') {
                $kinds = array_map('trim', explode(',', $raw));
                $want = ['private', 'video', 'located']; $sorted = $kinds; sort($sorted); sort($want);
                if ($sorted !== $want) { $errors[] = '"' . $d['label'] . '" must list private, video and located, each once.'; continue; }
                $value = implode(',', $kinds);
            } elseif ($d['type'] === 'enum') {
                if (!array_key_exists($raw, $d['options'])) { $errors[] = '"' . $d['label'] . '" must be one of the choices offered.'; continue; }
                $value = $raw;
            } else {
                if (!is_numeric($raw) || (float) $raw < $d['min'] || (float) $raw > $d['max']) { $errors[] = '"' . $d['label'] . '" must be a number from ' . $d['min'] . ' to ' . $d['max'] . '.'; continue; }
                $value = (float) $raw == (int) $raw ? (int) $raw : (float) $raw;
            }
            $setOrUnset($name, $value);
            if ($name === 'PUBLIC_DOWNLOAD_MODE') unset($cfg['ENABLE_PUBLIC_DOWNLOAD']);   // (the answer is now this setting's: the older on/off line would only get in its way)
        }
    }
    unset($cfg['ENABLE_MAP']);   // (the gallery-wide Map switch is gone: an older file's line is dropped by the next save)
    $newAdmin = null;
    $adminPw = (string) ($_POST['pw_admin'] ?? '');
    if ($adminPw !== '') {
        if ($adminPw !== (string) ($_POST['pw_admin2'] ?? '')) $errors[] = 'The two admin passwords you typed don\'t match.';
        elseif (!admin_password_ok($adminPw)) $errors[] = 'The admin password needs at least 8 characters, with at least one letter and one number: it is the one credential that can change your gallery.';
        elseif (preg_match('/[\x00-\x1F\x7F]/', $adminPw)) $errors[] = 'The admin password can\'t contain control characters.';
        else { $newAdmin = password_for_storage($adminPw); $setOrUnset('ADMIN_PASSWORD', $newAdmin); }
    }
    $viewPw = (string) ($_POST['pw_private'] ?? '');
    if (!empty($_POST['pw_private_remove'])) {
        $setOrUnset('PRIVATE_VIEW_PASSWORD', '');
    } elseif ($viewPw !== '') {
        if ($viewPw !== (string) ($_POST['pw_private2'] ?? '')) $errors[] = 'The two private-view passwords you typed don\'t match.';
        elseif (preg_match('/[\x00-\x1F\x7F]/', $viewPw)) $errors[] = 'The private-view password can\'t contain control characters.';
        else $setOrUnset('PRIVATE_VIEW_PASSWORD', password_for_storage($viewPw));
    }
    // A closed gallery needs a way in: share links on and an admin password. Refused only when this save is what makes it so (a settings
    // file that was already that way by hand does not block every other change).
    $effective = function ($c, $n) use ($defaults) { return array_key_exists($n, $c) ? $c[$n] : ($defaults[$n] ?? false); };
    // The visitor log needs SQLite and a folder it can write to: it can't be switched on without them (the page greys the switch; this is the same answer for a request made by hand).
    if ($effective($cfg, 'LOG_PUBLIC_VISITS') === true && $effective($state['cfg'], 'LOG_PUBLIC_VISITS') !== true && !visitlog_usable()) $errors[] = '"Log visitors to the public address" can\'t be switched on here: ' . visitlog_check()[1];
    if ($effective($cfg, 'CLOSE_PUBLIC_GALLERY') === true
        && ($effective($cfg, 'CLOSE_PUBLIC_GALLERY') !== $effective($state['cfg'], 'CLOSE_PUBLIC_GALLERY') || $effective($cfg, 'ENABLE_SHARE_LINKS') !== $effective($state['cfg'], 'ENABLE_SHARE_LINKS'))) {
        if ($effective($cfg, 'ENABLE_SHARE_LINKS') !== true) $errors[] = '"Close the public gallery" needs share links: they are the only way in for anyone else. Turn "Allow share links" on, or switch "Close the public gallery" off first.';
        elseif ($newAdmin === null && (string) $effective($cfg, 'ADMIN_PASSWORD') === '') $errors[] = '"Close the public gallery" needs an admin password first, or nobody could sign in.';
    }
    if ($errors) {
        return ['type' => 'error', 'text' => 'Nothing was saved. ' . implode(' ', $errors)];
    }
    $a = $cfg; $b = $state['cfg']; ksort($a); ksort($b);
    if ($a === $b) {
        return ['type' => 'ok', 'text' => 'Nothing to change: those are the settings already in use.', 'hash' => md5($currentRaw), 'unchanged' => true];
    }
    $content = gallery_config_render($cfg);
    if ($content === null) {
        return ['type' => 'error', 'text' => 'Nothing was saved: one of the values isn\'t valid text (it has bytes that aren\'t UTF-8).'];
    }
    $fail = function ($why) use ($content) {
        $GLOBALS['__site_settings_manual'] = $content;
        return ['type' => 'error', 'text' => 'Nothing was saved: ' . $why . ' The text below is the settings file; put it in a file named .gallery-config.php next to index.php yourself.', 'manual' => $content];
    };
    if (!is_writable(__DIR__)) return $fail('the gallery\'s folder isn\'t writable by the web server.');
    $tmp = $path . '.tmp.' . bin2hex(random_bytes(4));
    if (@file_put_contents($tmp, $content, LOCK_EX) === false) { @unlink($tmp); return $fail('the settings file couldn\'t be written.'); }
    @chmod($tmp, 0600);
    // Read back what was written, as the loader will, and refuse to install it unless it is exactly the settings intended.
    [$roundStatus, $roundTrip] = gallery_config_parse((string) @file_get_contents($tmp));
    ksort($roundTrip);
    if ($roundStatus !== 'ok' || $roundTrip !== $a) { @unlink($tmp); return $fail('the file that would have been written didn\'t read back correctly, so it was not installed.'); }
    if (!@rename($tmp, $path)) { @unlink($tmp); return $fail('the settings file couldn\'t be replaced.'); }
    // Changing the admin password must not log the person who just changed it out.
    if ($newAdmin !== null) {
        $_SESSION['admin_auth'] = admin_session_marker($newAdmin);
        set_admin_reveal_cookie($newAdmin);   // every token made under the old password stops working; this browser gets a new one
    }
    $n = count($cfg);
    if ($ajax) {
        // The page updates in place, so there is no "next page" to carry a message: say it now, and hand back the new file fingerprint.
        return ['type' => 'ok', 'text' => ($newAdmin !== null ? 'Admin password changed; you stay signed in.' : 'Saved.'), 'hash' => md5_file($path), 'differing' => $n, 'extra' => ['named' => (object) ($cfg['EXTRA_FOLDERS'] ?? []), 'roots' => array_values($cfg['EXTRA_ROOTS'] ?? [])]];
    }
    $_SESSION['admin_flash'] = ['type' => 'ok', 'text' => 'Settings saved' . ($newAdmin !== null ? ' (admin password changed; you stay signed in)' : '') . '. ' . ($n === 0 ? 'Everything is on its default.' : $n . ' setting' . ($n === 1 ? '' : 's') . ' differ' . ($n === 1 ? 's' : '') . ' from the defaults and will survive updating index.php.') . ' Your photos, captions, locations and counts were not touched.'];
    return ['type' => 'redirect'];
}

/* -----------------------------------------------------------------------
 * Share links: the admin side. The Shares tab lists every link, makes
 * new ones and changes them; each change is a small POST that answers JSON
 * (the page then fetches itself again, as the Private tab does, so what it
 * shows is always what is stored). Nothing here is reachable without the
 * admin's own session and CSRF token.
 * ----------------------------------------------------------------------- */

function link_clip($s, $max) {
    $s = (string) $s;
    return function_exists('mb_substr') ? mb_substr($s, 0, $max) : substr($s, 0, $max);
}

function link_state_label($state) {
    return ['active' => 'Active', 'paused' => 'Paused', 'scheduled' => 'Starts later', 'expired' => 'Expired', 'used_up' => 'Used up', 'revoked' => 'Revoked'][$state] ?? $state;
}

/** The labels of the folders on the way to a folder, joined ("Eurotrip 2026 / Rome"). */
function link_folder_label($dir, $rel) {
    $out = []; $prefix = '';
    foreach (explode('/', $rel) as $seg) {
        $prefix = $prefix === '' ? $seg : $prefix . '/' . $seg;
        $label = folder_display_meta($dir, $prefix)['label'];
        $out[] = $label !== '' ? $label : $seg;
    }
    return implode(' / ', $out);
}

/** The New link / Edit form's fields, checked. Returns [fields, errors]; $existing is the link being edited (its own end time may
 *  stay as it is). Folders arrive as paths and leave as hidden ids (stamped into the folder on the way). */
function link_input_from_post($now, $existing, $dir, $files) {
    $errors = [];
    $label = link_clip(trim((string) preg_replace('/[\x00-\x1F\x7F]+/u', ' ', (string) ($_POST['label'] ?? ''))), 80);
    if ($label === '') $errors[] = 'Give the link a name, so you can recognise it later.';
    $note = (string) preg_replace('/[^\P{C}\n]+/u', '', str_replace("\r\n", "\n", (string) ($_POST['note'] ?? '')));
    $note = link_clip(trim($note), 200);
    $titleMode = (string) ($_POST['title_mode'] ?? 'gallery');
    if (!in_array($titleMode, ['gallery', 'neutral', 'custom'], true)) $titleMode = 'gallery';
    $titleText = link_clip(trim((string) preg_replace('/[\x00-\x1F\x7F]+/u', ' ', (string) ($_POST['title_text'] ?? ''))), 80);
    if ($titleMode === 'custom' && $titleText === '') $titleMode = 'gallery';
    // A preview photo in the message preview and on the opening page: on when the title is the gallery's own, unless the form says otherwise;
    // a request that doesn't say (an older page, a script) leaves an existing link as it was.
    $picture = isset($_POST['picture']) ? $_POST['picture'] === '1' : ($existing !== null ? !empty($existing['picture']) : $titleMode === 'gallery');
    // Which cover: a small number that makes the automatic pick (kept for the link's life, so the picture is the same every time), and the owner's own choice, if any.
    $pictureSeed = (string) ($existing['pictureSeed'] ?? '');
    if (isset($_POST['picture_seed']) && is_string($_POST['picture_seed']) && preg_match('/^[0-9a-f]{8}$/', $_POST['picture_seed'])) $pictureSeed = $_POST['picture_seed'];
    if ($pictureSeed === '' && $existing === null) $pictureSeed = bin2hex(random_bytes(4));
    $pictureFile = (string) ($existing['pictureFile'] ?? '');
    if (isset($_POST['picture_file']) && is_string($_POST['picture_file'])) {
        $want = trim(str_replace(['\\', "\0"], ['/', ''], $_POST['picture_file']), '/');
        if ($want === '') $pictureFile = '';
        elseif ($want === $pictureFile) { /* unchanged: left as it is (it is looked at again whenever it is used) */ }
        elseif (link_picture_ok($want, $dir)) $pictureFile = $want;
        else $errors[] = 'That photo can\'t be the preview photo: only a public photo can.';
    }
    // The link's own address: left blank it keeps the random one it has (or gets one); a custom name is checked here, and again where it is saved.
    // '_address' is null when nothing changes, '' for "back to a random one" and the name otherwise.
    $address = null;
    if (isset($_POST['address']) && is_string($_POST['address'])) {
        $want = strtolower(trim($_POST['address']));
        $current = $existing !== null && !empty($existing['custom']) ? strtolower((string) $existing['token']) : '';
        if ($want !== $current) {
            if ($want === '') $address = '';
            else {
                $why = link_custom_name_problem($want, $dir, (string) ($existing['id'] ?? ''));
                // An address made from the link's name ("address_auto"): when it is taken or is one the gallery uses itself, a number goes on the end
                // (johndoe2) and the owner is told, instead of being refused. A name that is too short or has odd characters is still refused.
                if ($why !== '' && ($_POST['address_auto'] ?? '') === '1' && preg_match('/^[a-z0-9][a-z0-9-]*[a-z0-9]$/', $want) === 1 && strlen($want) >= 4) {
                    for ($n = 2; $n <= 99 && $why !== ''; $n++) {
                        $try = substr($want, 0, 40 - strlen((string) $n)) . $n;
                        if (link_custom_name_problem($try, $dir, (string) ($existing['id'] ?? '')) === '') { $GLOBALS['__address_renamed'] = [$want, $try]; $want = $try; $why = ''; }
                    }
                }
                if ($why !== '') $errors[] = $why; else $address = $want;
            }
        }
    }
    $maxOpens = max(0, min(100000, (int) ($_POST['max_opens'] ?? 0)));
    $endsAt = max(0, (int) ($_POST['ends_at'] ?? 0));
    $startsAt = max(0, (int) ($_POST['starts_at'] ?? 0));
    if ($endsAt > $now + 3650 * 86400) $endsAt = $now + 3650 * 86400;
    if ($endsAt > 0 && $endsAt <= $now && !($existing !== null && (int) ($existing['endsAt'] ?? 0) === $endsAt)) $errors[] = 'The end time has to be in the future.';
    if ($startsAt > 0 && $startsAt <= $now) $startsAt = 0;
    if ($startsAt > 0 && $endsAt > 0 && $startsAt >= $endsAt) $errors[] = 'The link has to start before it ends.';
    $locations = (string) ($_POST['locations'] ?? 'public');
    if (!in_array($locations, ['public', 'all'], true)) $locations = 'public';
    $headsUp = (string) ($_POST['heads_up'] ?? 'default');
    if (!in_array($headsUp, ['default', 'on', 'off'], true)) $headsUp = 'default';

    // What it covers, and where it opens. Folders come as paths; each is checked against the folders that really exist, and
    // stamped with its hidden id (a folder that can't be written to can't be remembered, so it is refused).
    $validFolders = array_fill_keys(all_folder_paths($files), true);
    $collectionIds = [];   // a collection can be picked like a folder: the link remembers it by the collection's own id
    if (AUTO_GROUP_BY_FOLDER && collections_any()) foreach (collections_registry($dir, $files)['byPath'] as $cPath => $cRec) { $validFolders[$cPath] = true; $collectionIds[$cPath] = $cRec['id']; }
    $validFiles = array_fill_keys($files, true);
    $index = [];   // id => path, for the links file's list of where folders were last seen
    $list = function ($key) { $v = json_decode((string) ($_POST[$key] ?? '[]'), true); return is_array($v) ? array_slice(array_values(array_unique(array_filter($v, 'is_string'))), 0, 60) : []; };
    $stamp = function ($rel) use ($dir, $validFolders, $collectionIds, &$errors, &$index) {
        if (!isset($validFolders[$rel])) { $errors[] = 'One of the folders you chose isn\'t in the gallery any more.'; return null; }
        if (isset($collectionIds[$rel])) { $index[$collectionIds[$rel]] = $rel; return $collectionIds[$rel]; }
        $id = folder_id_stamp(resolve_real_path($dir, $rel));
        if ($id === '') { $errors[] = 'A link can\'t be limited to "' . link_clip($rel, 60) . '": the web server can\'t write in that folder, and a link remembers a folder by a small id kept in it.'; return null; }
        $index[$id] = $rel;
        return $id;
    };
    $scopeType = (string) ($_POST['scope_type'] ?? 'all');
    if (!in_array($scopeType, ['all', 'folders', 'photos', 'mixed', 'public'], true)) $scopeType = 'all';
    $scopeFolderPaths = [];
    $scope = ['type' => 'all', 'folders' => [], 'photos' => []];
    // The picked photos, each remembered by the id of its folder and its name (shared by "only some photos" and "some folders and some photos").
    $stampPhotos = function ($rels) use ($validFiles, $dir, $stamp, &$errors, &$index) {
        $photos = [];
        foreach ($rels as $rel) {
            if (!isset($validFiles[$rel])) { $errors[] = 'One of the photos you chose isn\'t in the gallery any more.'; continue; }
            $slash = strrpos($rel, '/');
            $folderRel = $slash === false ? '' : substr($rel, 0, $slash);
            $fid = $folderRel === '' ? folder_id_stamp($dir) : $stamp($folderRel);
            if ($folderRel === '' && $fid === '') { $errors[] = 'The gallery\'s own folder can\'t be written to, so a link can\'t remember a photo in it.'; continue; }
            if ($fid !== null) { $photos[] = ['fid' => $fid, 'name' => basename($rel)]; if ($folderRel === '') $index[$fid] = ''; }
        }
        return $photos;
    };
    if ($scopeType === 'folders' || $scopeType === 'mixed') {
        if (!AUTO_GROUP_BY_FOLDER) $errors[] = 'Turn on "Show subfolders" in Settings to limit a link to folders.';
        $scopeFolderPaths = $list('scope_folders');
        $ids = [];
        foreach ($scopeFolderPaths as $rel) { $id = $stamp($rel); if ($id !== null) $ids[] = $id; }
        $photos = $scopeType === 'mixed' ? $stampPhotos($list('scope_photos')) : [];
        if ($scopeType === 'folders' && !$scopeFolderPaths) $errors[] = 'Choose at least one folder, or choose "Everything".';
        if ($scopeType === 'mixed' && !$scopeFolderPaths && !$photos) $errors[] = 'Choose at least one folder or photo.';
        // "Public items only", folder by folder: the private photos and videos inside it are left out (unless one is named in this link).
        $pubIds = [];
        foreach (array_values(array_intersect($list('scope_public_only'), $scopeFolderPaths)) as $rel) {
            if (folder_is_private($dir, $rel)) { $errors[] = '"' . link_clip($rel, 60) . '" is private as a whole, so "Public items only" would show nothing in it. Choose "Everything" for it, or make the folder visible first.'; continue; }
            $id = $stamp($rel); if ($id !== null) $pubIds[] = $id;
        }
        $scope = ['type' => $scopeType, 'folders' => $ids, 'photos' => $photos, 'publicOnly' => $pubIds];
    } elseif ($scopeType === 'photos') {
        $photos = $stampPhotos($list('scope_photos'));
        if (!$photos) $errors[] = 'Choose at least one photo.';
        $scope = ['type' => 'photos', 'folders' => [], 'photos' => $photos];
    } elseif ($scopeType === 'public') {
        $scope = ['type' => 'public', 'folders' => [], 'photos' => []];   // nothing private: the person sees what any visitor sees, and the log records it
    }
    $underScope = function ($rel) use ($scopeType, $scopeFolderPaths) {
        if ($scopeType !== 'folders' && $scopeType !== 'mixed') return true;
        foreach ($scopeFolderPaths as $s) if ($rel === $s || str_starts_with($rel, $s . '/')) return true;
        return false;
    };
    $openIn = '';
    $inRel = trim((string) ($_POST['open_in'] ?? ''));
    if ($inRel !== '' && $scopeType !== 'photos') {
        if (!$underScope($inRel)) $errors[] = 'It can only open in a folder it covers.';
        elseif ($scopeType === 'public' && folder_is_private($dir, $inRel)) $errors[] = 'A link to the public gallery can\'t open in a private folder.';
        else { $id = $stamp($inRel); if ($id !== null) $openIn = $id; }
    }
    $cap = function ($modeKey, $listKey, $noun) use ($stamp, $list, $underScope, &$errors, $scopeType) {
        $mode = (string) ($_POST[$modeKey] ?? 'off');
        if (!in_array($mode, ['off', 'all', 'public', 'some'], true)) $mode = 'off';
        if ($mode === 'public' && $scopeType === 'public') $mode = 'all';   // (a link that shows nothing private: "everything" and "everything but private" are the same)
        $ids = [];
        if ($mode === 'some') {
            $paths = $list($listKey);
            if (!$paths) $errors[] = 'Choose the folders ' . $noun . ' is allowed in, or pick another choice.';
            foreach ($paths as $rel) {
                if (!$underScope($rel)) { $errors[] = 'The ' . $noun . ' folders have to be among the folders the link covers.'; continue; }
                $id = $stamp($rel); if ($id !== null) $ids[] = $id;
            }
        }
        return ['mode' => $mode, 'folders' => $ids];
    };
    if ($pictureFile !== '' && in_array($scopeType, ['folders', 'photos', 'mixed'], true)
        && !link_cover_in_scope(null, $dir, $pictureFile, ['type' => $scopeType, 'folders' => $scopeFolderPaths, 'photos' => $scopeType === 'folders' ? [] : $list('scope_photos')])) $pictureFile = '';   // (a chosen preview photo the link does not cover: the automatic pick takes over)
    $downloads = $cap('downloads', 'downloads_folders', 'downloads');
    $zip = $cap('zip', 'zip_folders', 'ZIP downloads');
    $only = ($scopeType === 'folders' || $scopeType === 'photos' || $scopeType === 'mixed') && ($_POST['only'] ?? '') === '1';   // "show only these": the person's pages list nothing but what the link covers, the rest of the public gallery too
    return [[
        'label' => $label, 'note' => $note, 'titleMode' => $titleMode, 'titleText' => $titleText, 'picture' => $picture, 'pictureSeed' => $pictureSeed, 'pictureFile' => $pictureFile, 'maxOpens' => $maxOpens,
        'startsAt' => $startsAt, 'endsAt' => $endsAt, 'locations' => $locations, 'headsUp' => $headsUp,
        'scope' => $scope, 'only' => $only, 'openIn' => $openIn, 'downloads' => $downloads, 'zip' => $zip, '_index' => $index, '_address' => $address, '_keep' => ($_POST['keep_old'] ?? '') === '1',
    ], $errors];
}

/** Gives a link record its address: a custom name, or ('') a fresh random token. The address it had goes to the list of replaced
 *  ones (so it is noted in the log as such and stops working), or, with $keep, to the ones kept working (they send people on to the
 *  new address); $d is the links file's data, to refuse a name another link took in the meantime. Returns '' or the reason it
 *  couldn't be done. */
function link_apply_address(&$rec, $address, $d = null, $keep = false) {
    if ($address === null) return '';
    if ($address !== '' && $d !== null) {
        foreach ((array) ($d['links'] ?? []) as $other) {
            if (!is_array($other) || ($other['id'] ?? '') === ($rec['id'] ?? '')) continue;
            foreach (link_all_addresses($other) as $t) if (strtolower($t) === $address) return LINK_ADDRESS_TAKEN;
        }
    }
    $aliases = array_values(array_filter((array) ($rec['aliases'] ?? []), 'is_array'));
    // (a name this link already keeps working becomes its address: it stops being a kept one)
    if ($address !== '') $aliases = array_values(array_filter($aliases, function ($a) use ($address) { return strtolower((string) ($a['name'] ?? '')) !== $address; }));
    $hadOne = ($rec['token'] ?? '') !== '' && empty($rec['_new']);
    if ($hadOne && $keep) {
        if (count($aliases) >= LINK_ALIASES_MAX) return 'This link already has ' . LINK_ALIASES_MAX . ' old addresses working. Pause or kill one first (Settings, "Also works at").';
        $aliases[] = ['name' => $rec['token'], 'custom' => !empty($rec['custom']), 'added' => time(), 'hits' => 0, 'last' => 0];
        if (empty($rec['aliasSince'])) $rec['aliasSince'] = time();
    } elseif ($hadOne) {
        $old = (array) ($rec['oldTokens'] ?? []); $old[] = $rec['token'];
        $rec['oldTokens'] = array_values(array_unique($old));   // (replaced addresses are all kept: that is what stops another link taking the name)
    }
    $rec['aliases'] = $aliases;
    $rec['token'] = $address === '' ? link_new_token() : $address;
    $rec['custom'] = $address !== '';
    return '';
}

function link_apply_fields(&$rec, $f) {
    foreach (['label', 'note', 'titleMode', 'titleText', 'picture', 'pictureSeed', 'pictureFile', 'maxOpens', 'startsAt', 'endsAt', 'locations', 'headsUp', 'scope', 'only', 'openIn', 'downloads', 'zip'] as $k) $rec[$k] = $f[$k];
}

/** The Shares tab's POST actions (link_create, link_save, link_pause, link_resume, link_revoke, link_extend, link_replace,
 *  link_delete). Always answers JSON and ends the request. */
function links_admin_action($action, $dir, $files) {
    $now = time();
    $bad = function ($text) { admin_json_exit(['ok' => false, 'text' => $text]); };
    if (!ENABLE_SHARE_LINKS) $bad('Share links are switched off in Settings.');
    $id = (string) ($_POST['id'] ?? '');
    if ($action !== 'link_create' && $action !== 'link_seen' && !preg_match('/^[0-9a-f]{10}$/', $id)) $bad('Unknown link.');
    $wrote = function () use ($bad) {
        if (!empty($GLOBALS['__data_write_failed'])) $bad(data_write_failure_text('the gallery\'s folder'));
    };
    if ($id === PUBLIC_LOG_ID) $bad('That is not a link.');
    if ($action === 'link_seen') {   // the owner has looked at the tab: what happened before now is no longer "new"
        links_update(function (&$d) use ($now) { $d['seenAt'] = $now; });
        admin_json_exit(['ok' => true, 'text' => '']);
    }
    if ($action === 'link_create') {
        [$f, $errors] = link_input_from_post($now, null, $dir, $files);
        if ($errors) $bad(implode(' ', array_unique($errors)));
        $rec = link_record_new($now);
        link_apply_fields($rec, $f);
        $rec['_new'] = true;
        $taken = false;
        $GLOBALS['__data_write_failed'] = false; $GLOBALS['__data_refused'] = [];
        links_update(function (&$d) use (&$rec, $f, &$taken) {
            if (($why = link_apply_address($rec, $f['_address'], $d)) !== '') { $taken = $why; return; }
            unset($rec['_new']);
            $d['links'][$rec['id']] = $rec; foreach ($f['_index'] as $fid => $rel) $d['folderIndex'][$fid] = $rel;
        });
        if ($taken !== false) $bad($taken);
        $wrote();
        $renamed = $GLOBALS['__address_renamed'] ?? null;
        admin_json_exit(['ok' => true, 'id' => $rec['id'], 'text' => 'Link made.' . ($renamed ? ' The address "' . $renamed[0] . '" is taken or is one the gallery uses, so this link\'s address is "' . $renamed[1] . '".' : ''), 'urls' => link_urls($rec)]);
    }
    $problem = null; $text = 'Saved.';
    $saveFields = null; $saveErrors = [];
    if ($action === 'link_save') [$saveFields, $saveErrors] = link_input_from_post($now, ($links0 = links_read()['links'][$id] ?? null) === null ? null : $links0, $dir, $files);
    $restoreName = ''; $restoreWhy = ''; $killName = ''; $killUse = [0, 0, 0]; $killTried = [0, 0, 0];
    if ($action === 'link_alias_resume') {
        $restoreName = (string) ($_POST['alias'] ?? '');
        if (link_address_is_custom($restoreName)) $restoreWhy = link_custom_name_problem(strtolower($restoreName), $dir, $id);   // (a folder may have taken the name since)
    }
    if ($action === 'link_alias_kill') {   // (what the log says about it now, for the line that is left behind)
        $killName = (string) ($_POST['alias'] ?? '');
        $killLog = link_log_read($id);
        $killUse = link_address_log_stats($killLog, 'via', $killName); $killTried = link_address_log_stats($killLog, 'tried', $killName);
    }
    links_update(function (&$d) use ($action, $id, $now, &$problem, &$text, $saveFields, $saveErrors, $restoreName, $restoreWhy, $killName, $killUse, $killTried) {
        $l = $d['links'][$id] ?? null;
        if (!is_array($l)) { $problem = 'That link no longer exists.'; return; }
        $state = link_state($l, $now);
        if ($action === 'link_delete') { unset($d['links'][$id]); $text = 'Link and its log deleted.'; return; }
        if ($action === 'link_save') {
            if ($state === 'revoked') { $problem = 'A revoked link can\'t be changed.'; return; }
            if ($saveErrors) { $problem = implode(' ', array_unique($saveErrors)); return; }
            if (($why = link_apply_address($d['links'][$id], $saveFields['_address'], $d, !empty($saveFields['_keep']))) !== '') { $problem = $why; return; }
            link_apply_fields($d['links'][$id], $saveFields);
            foreach ($saveFields['_index'] as $fid => $rel) $d['folderIndex'][$fid] = $rel;
            return;
        }
        if ($action === 'link_forget') {
            // A folder that is gone: take it out of this link (and out of what it opens in, downloads and ZIPs).
            $fid = (string) ($_POST['fid'] ?? '');
            $had = in_array($fid, $d['links'][$id]['scope']['folders'] ?? [], true);
            $photosLeft = count(array_filter((array) ($d['links'][$id]['scope']['photos'] ?? []), function ($p) use ($fid) { return ($p['fid'] ?? '') !== $fid; }));
            if ($had && count($d['links'][$id]['scope']['folders']) < 2 && !(($d['links'][$id]['scope']['type'] ?? '') === 'mixed' && $photosLeft > 0)) { $problem = 'A link has to keep at least one folder: pick another one with Edit, or delete the link.'; return; }
            $keep = function ($ids) use ($fid) { return array_values(array_filter((array) $ids, function ($x) use ($fid) { return $x !== $fid; })); };
            $d['links'][$id]['scope']['folders'] = $keep($d['links'][$id]['scope']['folders'] ?? []);
            $d['links'][$id]['scope']['publicOnly'] = $keep($d['links'][$id]['scope']['publicOnly'] ?? []);
            $d['links'][$id]['scope']['photos'] = array_values(array_filter((array) ($d['links'][$id]['scope']['photos'] ?? []), function ($p) use ($fid) { return ($p['fid'] ?? '') !== $fid; }));
            foreach (['downloads', 'zip'] as $c) $d['links'][$id][$c]['folders'] = $keep($d['links'][$id][$c]['folders'] ?? []);
            if (($d['links'][$id]['openIn'] ?? '') === $fid) $d['links'][$id]['openIn'] = '';
            $text = 'Taken out of this link.';
            return;
        }
        if ($action === 'link_pause') {
            if (($l['status'] ?? '') !== 'active') { $problem = 'Only an active link can be paused.'; return; }
            $d['links'][$id]['status'] = 'paused'; $d['links'][$id]['pausedAt'] = $now; $text = 'Paused. Anyone using it is locked out until you resume it.';
            return;
        }
        if ($action === 'link_resume') {
            if (($l['status'] ?? '') !== 'paused') { $problem = 'That link isn\'t paused.'; return; }
            $d['links'][$id]['status'] = 'active'; $d['links'][$id]['pausedAt'] = 0; $text = 'Resumed.';
            return;
        }
        if ($action === 'link_revoke') {
            if (($l['status'] ?? '') === 'revoked') { $problem = 'Already revoked.'; return; }
            $d['links'][$id]['status'] = 'revoked'; $d['links'][$id]['revokedAt'] = $now; $text = 'Revoked. It stays here with its log.';
            return;
        }
        if ($action === 'link_replace') {
            if ($state === 'revoked') { $problem = 'A revoked link can\'t be given a new address.'; return; }
            // (this is the "it leaked" button: addresses kept working go the same way as the current one)
            $old = (array) ($d['links'][$id]['oldTokens'] ?? []); $old[] = $l['token'];
            $kept = 0;
            $stats = (array) ($l['aliasStats'] ?? []);
            foreach ((array) ($l['aliases'] ?? []) as $a) if (is_array($a) && ($a['name'] ?? '') !== '') { $old[] = $a['name']; $kept++; $stats[$a['name']] = ['hits' => (int) ($a['hits'] ?? 0), 'last' => (int) ($a['last'] ?? 0)]; }
            $d['links'][$id]['oldTokens'] = array_values(array_unique($old));
            $d['links'][$id]['aliasStats'] = $stats;
            $d['links'][$id]['aliases'] = [];
            $d['links'][$id]['token'] = link_new_token(); $d['links'][$id]['custom'] = false;
            $text = $kept > 0 ? 'New address ready. The old one, and the ' . ($kept === 1 ? 'one' : $kept) . ' you kept working, are paused.' : 'New address ready. The old one no longer works.';
            return;
        }
        if ($action === 'link_alias_resume') {
            if ($state === 'revoked') { $problem = 'A revoked link can\'t be changed.'; return; }
            if ($restoreWhy !== '') { $problem = $restoreWhy; return; }
            $old = array_values(array_map('strval', (array) ($l['oldTokens'] ?? [])));
            if (!in_array($restoreName, $old, true)) { $problem = 'That address isn\'t paused.'; return; }
            if (strtolower($restoreName) === strtolower((string) ($l['token'] ?? ''))) { $problem = 'That is the link\'s own address.'; return; }
            foreach ((array) ($d['links'] ?? []) as $other) {
                if (!is_array($other) || ($other['id'] ?? '') === $id) continue;
                foreach (link_all_addresses($other) as $t) if (strtolower($t) === strtolower($restoreName)) { $problem = LINK_ADDRESS_TAKEN; return; }
            }
            $aliases = array_values(array_filter((array) ($l['aliases'] ?? []), 'is_array'));
            if (count($aliases) >= LINK_ALIASES_MAX) { $problem = 'This link already has ' . LINK_ALIASES_MAX . ' old addresses working. Pause or kill one first (Settings, "Also works at").'; return; }
            $stats = (array) ($l['aliasStats'] ?? []); $was = (array) ($stats[$restoreName] ?? []);
            $aliases[] = ['name' => $restoreName, 'custom' => link_address_is_custom($restoreName), 'added' => $now, 'hits' => (int) ($was['hits'] ?? 0), 'last' => (int) ($was['last'] ?? 0)];
            unset($stats[$restoreName]);
            $d['links'][$id]['aliases'] = $aliases;
            $d['links'][$id]['aliasStats'] = $stats;
            $d['links'][$id]['oldTokens'] = array_values(array_filter($old, function ($t) use ($restoreName) { return $t !== $restoreName; }));
            if (empty($l['aliasSince'])) $d['links'][$id]['aliasSince'] = $now;
            $text = 'Resumed. It sends people on to the link\'s present address again.';
            return;
        }
        if ($action === 'link_alias_pause') {
            $name = (string) ($_POST['alias'] ?? ''); $left = []; $gone = null;
            foreach ((array) ($l['aliases'] ?? []) as $a) {
                if (is_array($a) && ($a['name'] ?? '') === $name) { $gone = $a; continue; }
                if (is_array($a)) $left[] = $a;
            }
            if ($gone === null) { $problem = 'That address isn\'t working any more.'; return; }
            $old = (array) ($l['oldTokens'] ?? []); $old[] = $name;
            $stats = (array) ($l['aliasStats'] ?? []); $stats[$name] = ['hits' => (int) ($gone['hits'] ?? 0), 'last' => (int) ($gone['last'] ?? 0)];   // (kept, so Resume gives them back)
            $d['links'][$id]['oldTokens'] = array_values(array_unique($old));
            $d['links'][$id]['aliasStats'] = $stats;
            $d['links'][$id]['aliases'] = $left;
            $text = 'Paused. It shows the “not valid” page until you resume it.';
            return;
        }
        if ($action === 'link_alias_kill') {
            $name = $killName; $custom = link_address_is_custom($name); $hits = 0; $last = 0; $found = false; $left = [];
            foreach ((array) ($l['aliases'] ?? []) as $a) {
                if (is_array($a) && ($a['name'] ?? '') === $name) { $found = true; $hits = (int) ($a['hits'] ?? 0); $last = (int) ($a['last'] ?? 0); continue; }
                if (is_array($a)) $left[] = $a;
            }
            $old = array_values(array_filter(array_map('strval', (array) ($l['oldTokens'] ?? [])), function ($t) use ($name, &$found) { if ($t === $name) { $found = true; return false; } return true; }));
            $stats = (array) ($l['aliasStats'] ?? []);
            if (isset($stats[$name])) { $hits = (int) ($stats[$name]['hits'] ?? 0); $last = (int) ($stats[$name]['last'] ?? 0); unset($stats[$name]); }
            if (!$found) { $problem = 'That address isn\'t one of this link\'s old addresses.'; return; }
            // (only the short label is kept, never the address itself: a killed address can't be brought back, and its name is free)
            $killed = (array) ($l['killed'] ?? []);
            $killed[] = ['label' => link_address_label($name, $custom), 'custom' => $custom, 'killedAt' => $now, 'hits' => $hits, 'ips' => (int) $killUse[1], 'tries' => (int) $killTried[0], 'last' => max($last, (int) $killUse[2])];
            $d['links'][$id]['aliases'] = $left; $d['links'][$id]['oldTokens'] = $old; $d['links'][$id]['aliasStats'] = $stats; $d['links'][$id]['killed'] = $killed;
            $text = $custom ? 'Killed. The name is free to use again.' : 'Killed.';
            return;
        }
        if ($action === 'link_killed_clear') {
            $d['links'][$id]['killed'] = [];
            $text = 'Cleared.';
            return;
        }
        if ($action === 'link_extend') {
            if ($state === 'revoked') { $problem = 'A revoked link can\'t be extended.'; return; }
            $endsAt = (int) ($_POST['ends_at'] ?? 0);
            $addOpens = max(0, min(100000, (int) ($_POST['add_opens'] ?? 0)));
            if ($endsAt > 0) {
                if ($endsAt <= $now) { $problem = 'The new end time has to be in the future.'; return; }
                $d['links'][$id]['endsAt'] = min($endsAt, $now + 3650 * 86400);
            } elseif (($_POST['no_end'] ?? '') === '1') {
                $d['links'][$id]['endsAt'] = 0;
            }
            if (($_POST['no_limit'] ?? '') === '1') $d['links'][$id]['maxOpens'] = 0;   // "Unlimited": the limit comes off
            elseif ($addOpens > 0 && (int) ($l['maxOpens'] ?? 0) > 0) $d['links'][$id]['maxOpens'] = (int) $l['maxOpens'] + $addOpens;
            $text = 'Extended.';
            return;
        }
        $problem = 'Unknown action.';
    });
    if ($problem !== null) $bad($problem);
    $wrote();
    if ($action === 'link_delete') link_delete_log($id);
    admin_json_exit(['ok' => true, 'id' => $id, 'text' => $text]);
}

/** The server rules that make https://example.com/<gallery>/<token> reach the script, written for this install's own address. */
function render_link_rules_help() {
    $esc = function ($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); };
    $base = rtrim(str_replace('\\', '/', dirname($_SERVER['SCRIPT_NAME'] ?? '/')), '/');
    $loc = $base === '' ? '/' : $base . '/';
    // (nginx reads a { in an unquoted pattern as the start of a block, so both patterns are quoted)
    $shape = '[A-Za-z0-9][A-Za-z0-9-]{2,38}[A-Za-z0-9]';   // a random address or a custom name: 4 to 40 letters, digits and hyphens, none at either end
    $nginx = "location ~ \"^" . $loc . $shape . "\$\" {\n    rewrite \"^" . $loc . "(" . $shape . ")\$\" " . $loc . "index.php?link=\$1 last;\n}\n";
    $apache = "RewriteEngine On\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteRule ^(" . $shape . ")\$ index.php?link=\$1 [L,QSA]\n";
    ob_start();
?>
    <div class="rules-help">
      <details class="fold">
        <summary><strong>nginx</strong> (needs shell access to the server)</summary>
        <p>Add inside the site's <code>server { }</code> block, next to the other rules, then run <code>sudo nginx -t &amp;&amp; sudo systemctl reload nginx</code>. Written for this gallery's address, <code><?= $esc($loc) ?></code>. <strong>It replaces the older rule that matched exactly <?= (int) LINK_TOKEN_LENGTH ?> letters and digits: remove that one.</strong><?= $base === '' ? ' <strong>At the top of the site it would also catch any other one-word address: narrow its path first.</strong>' : '' ?></p>
        <details class="fold rule-details"><summary>What it matches</summary><p>One word of 4 to 40 letters, digits and hyphens, with no dot and no closing slash: a photo (it has a dot) and a folder's own address (it ends in a slash) are never touched, and a folder typed without its slash is sent on to the folder by the gallery.</p></details>
        <div class="rules-box"><button type="button" class="secondary copy-rules">Copy</button><pre><code><?= $esc($nginx) ?></code></pre></div>
      </details>
      <details class="fold">
        <summary><strong>Apache</strong> (works on FTP-only hosting)</summary>
        <p>Add to <code>.htaccess</code> in the gallery's folder (needs <code>mod_rewrite</code> and <code>AllowOverride FileInfo</code>). <strong>It replaces the older rule for exactly <?= (int) LINK_TOKEN_LENGTH ?> letters and digits: remove that one.</strong></p>
        <details class="fold rule-details"><summary>What it matches</summary><p>One word of 4 to 40 letters, digits and hyphens, with no dot and no closing slash. A real folder with the same name as a link doesn't hide it: the folder's own address (with the closing slash) still opens the folder.</p></details>
        <div class="rules-box"><button type="button" class="secondary copy-rules">Copy</button><pre><code><?= $esc($apache) ?></code></pre></div>
      </details>
    </div>
<?php
    return ob_get_clean();
}

/** One date for the tab: the page's script turns it into the visitor's own time zone; without it, UTC. */
function link_time_html($ts) {
    $ts = (int) $ts;
    return '<time class="sl-time" data-ts="' . $ts . '" datetime="' . gmdate('c', $ts) . '">' . htmlspecialchars(gmdate('D, M j, g:i a', $ts) . ' UTC', ENT_QUOTES, 'UTF-8') . '</time>';
}

/* -----------------------------------------------------------------------
 * Collections, the owner's side (see 021a-collections.php). Every change is a change to one record in .gallery-collections.php: nothing
 * here ever writes in, moves or deletes anything in a photo folder, except that a folder used as a parent or a member is given its hidden id
 * (folder_id_stamp, the same small field a share link puts there) so the collection can find it again whatever it is renamed.
 * ----------------------------------------------------------------------- */

/** The stored record with this id, whether or not its parent can be found. */
function collection_find_by_id($id) {
    foreach (collections_list() as $r) if ($r['id'] === $id) return $r;
    return null;
}

/** '' when $name may be the address name of a collection in $parentPath, else what is wrong (said to the owner). $exceptId is the collection being renamed. */
function collection_address_problem($dir, $files, $parentPath, $name, $exceptId = '') {
    if (!collection_name_shape_ok($name)) return 'An address uses letters, digits, dots, dashes and underscores, starts with a letter or digit, and is not a word the gallery uses itself.';
    $path = $parentPath === '' ? $name : $parentPath . '/' . $name;
    $real = array_flip(array_map('strtolower', all_folder_paths($files)));   // (compared without regard to case: on some servers Italy and italy are one place)
    $mounts = array_flip(array_map('strtolower', array_keys(gallery_mounts())));
    if (isset($real[strtolower($path)]) || ($parentPath === '' && isset($mounts[strtolower($name)]))) return 'A folder is already at that address.';
    foreach (collections_registry($dir, $files)['byPath'] as $p => $r) if (strtolower($p) === strtolower($path) && $r['id'] !== $exceptId) return 'Another collection is already at that address.';
    return '';
}

/** An address name that is free in $parentPath, made from $base (a dash and a number added when it is taken). */
function collection_free_name($dir, $files, $parentPath, $base) {
    $base = collection_slug($base);
    for ($n = 1; $n < 200; $n++) {
        $try = $n === 1 ? $base : substr($base, 0, 56) . '-' . $n;
        if (collection_address_problem($dir, $files, $parentPath, $try) === '') return $try;
    }
    return $base . '-' . bin2hex(random_bytes(2));
}

/** The folder's id for a record to remember, '' when it can't be written: ($relFolder is a folder path; '' is the gallery's own folder). */
function collection_folder_id($dir, $relFolder) {
    return folder_id_stamp($relFolder === '' ? $dir : resolve_real_path($dir, $relFolder));
}

/** The record as the folder settings form knows a folder's own settings (so the same form and fingerprint serve both). */
function collection_as_items($r) {
    return ['displayName' => $r['title'] !== '' ? $r['title'] : null, 'description' => $r['description'] !== '' ? $r['description'] : null, 'dates' => $r['dates'] !== '' ? $r['dates'] : null,
            'sortOrder' => $r['position'], 'photoSort' => $r['photoSort'] ?: null, 'subfolderStyle' => $r['subfolderStyle'], 'flatNames' => $r['flatNames'], 'flatNotes' => $r['flatNotes']];
}

/** Does any folder or collection use "Gallery of its own"? The gallery's own record keeps the answer so that a gallery that uses none reads nothing more. */
function own_galleries_recompute($dir, $files) {
    $any = false;
    foreach (all_folder_paths($files) as $p) { if ($p !== '' && folder_own_gallery_cached($dir, $p)) { $any = true; break; } }
    if (!$any) foreach (collections_list() as $r) if ($r['ownGallery']) { $any = true; break; }
    items_update($dir, function (&$data) use ($any) { if ($any) $data['ownGalleries'] = true; else unset($data['ownGalleries']); });
}

function collection_fail_warn($text) { admin_json_exit(['ok' => true, 'text' => '', 'warn' => $text]); }
function collection_fail($text) { admin_json_exit(['ok' => false, 'text' => $text]); }
function collection_saved_or_fail() { if (!empty($GLOBALS['__data_write_failed'])) collection_fail(data_write_failure_text('the gallery\'s folder')); }

/** The members a posted list names, as records to add: [{path, file?}] where path is a folder's path ('' only for a photo at the gallery's top). Checked
 *  against the gallery's own file list, never trusted. Returns [records, error]. */
function collection_members_from_post($dir, $files, $json) {
    $list = json_decode((string) $json, true);
    if (!is_array($list) || !$list || count($list) > 2000) return [[], 'Nothing was chosen.'];
    $out = [];
    foreach ($list as $m) {
        if (!is_array($m) || !is_string($m['path'] ?? null)) continue;
        $path = trim($m['path'], '/');
        if (isset($m['file'])) {
            if (!is_string($m['file']) || $m['file'] === '' || strpos($m['file'], '/') !== false) continue;
            $f = $path === '' ? $m['file'] : $path . '/' . $m['file'];
            if (!in_array($f, $files, true)) continue;
            $fid = collection_folder_id($dir, $path);
            if ($fid === '') return [[], 'Nothing was saved: ' . data_write_failure_place($dir, $path === '' ? $dir : resolve_real_path($dir, $path)) . ' isn\'t writable by the web server, so the photo can\'t be remembered there. Give the web server\'s user write permission on it, then try again.'];
            $out[] = ['fid' => $fid, 'file' => $m['file']];
        } else {
            if ($path === '' || empty(folder_files_under($files, $path))) continue;
            $fid = collection_folder_id($dir, $path);
            if ($fid === '') return [[], 'Nothing was saved: ' . data_write_failure_place($dir, resolve_real_path($dir, $path)) . ' isn\'t writable by the web server, so the folder can\'t be remembered there. Give the web server\'s user write permission on it, then try again.'];
            $out[] = ['fid' => $fid, 'mode' => ($m['mode'] ?? 'all') === 'own' ? 'own' : 'all'];
        }
    }
    return [$out, $out ? '' : 'Nothing that is here was chosen.'];
}

/** The owner's collection actions (they answer in JSON and end the request, like the Shares tab's). $adminFolderPath is the page being edited (a collection's own
 *  address for the settings and the switches). */
function collections_admin_action($action, $dir, $adminFolderPath, $files) {
    if ($action === 'collection_create') {
        $parentRel = trim((string) ($_POST['parent'] ?? ''), '/');
        if ($parentRel !== '' && empty(folder_files_under($files, $parentRel))) collection_fail('That folder is not here.');
        $title = trim((string) ($_POST['title'] ?? ''));
        if ($title === '') collection_fail('Give the collection a name.');
        if (strlen($title) > 200) $title = substr($title, 0, 200);
        $parentFid = '';
        if ($parentRel !== '') {
            $parentFid = collection_folder_id($dir, $parentRel);
            if ($parentFid === '') collection_fail('Nothing was saved: ' . data_write_failure_place($dir, resolve_real_path($dir, $parentRel)) . ' isn\'t writable by the web server, and a collection kept in a folder needs the folder to remember it by. Give the web server\'s user write permission on it, then try again.');
        }
        $name = collection_free_name($dir, $files, $parentRel, $title);
        $rec = ['id' => 'c' . bin2hex(random_bytes(6)), 'parent' => $parentFid, 'name' => $name, 'title' => $title, 'description' => '', 'cover' => null, 'dates' => '', 'position' => null,
                'private' => false, 'front' => false, 'ownGallery' => false, 'items' => [], 'at' => time()];
        $GLOBALS['__data_write_failed'] = false; $GLOBALS['__data_refused'] = [];
        collections_update(function (&$d) use ($rec) { $d['collections'][] = $rec; });
        collection_saved_or_fail();
        $path = $parentRel === '' ? $name : $parentRel . '/' . $name;
        admin_json_exit(['ok' => true, 'text' => 'Collection made.', 'url' => '?admin&folder=' . rawurlencode($path), 'path' => $path, 'name' => $name, 'id' => $rec['id']]);
    }
    if ($action === 'collection_delete') {
        $id = (string) ($_POST['id'] ?? '');
        if (collection_find_by_id($id) === null) collection_fail('That collection is not here (it may already be gone).');
        $GLOBALS['__data_write_failed'] = false; $GLOBALS['__data_refused'] = [];
        collections_update(function (&$d) use ($id) { $d['collections'] = array_values(array_filter((array) $d['collections'], function ($r) use ($id) { return !is_array($r) || ($r['id'] ?? '') !== $id; })); });
        collection_saved_or_fail();
        own_galleries_recompute($dir, $files);
        admin_json_exit(['ok' => true, 'text' => 'Collection deleted. Nothing in it was touched.']);
    }
    if ($action === 'collection_photos') {   // the photos directly in a folder, for the picker (names, thumbnails, whether each is public)
        $folder = trim((string) ($_POST['folder'] ?? ''), '/');
        $out = [];
        foreach ($files as $f) {
            $d = dirname($f); $d = ($d === '.' || $d === '') ? '' : $d;
            if ($d !== $folder) continue;
            $out[] = ['file' => basename($f), 'thumb' => img_url($f, 'thumb'), 'state' => file_is_unlisted($dir, $f) ? 'unlisted' : (file_is_hidden($dir, $f, items_get_all_for_files($dir, [$f])) ? 'private' : 'public')];
            if (count($out) >= 600) break;
        }
        admin_json_exit(['ok' => true, 'text' => '', 'photos' => $out]);
    }
    // Everything below changes one collection: the one at the page being edited, or the one named by id.
    $rec = isset($_POST['id']) ? collection_find_by_id((string) $_POST['id']) : ($adminFolderPath !== null ? collection_at($dir, $adminFolderPath, $files) : null);
    if ($rec === null) collection_fail('That collection is not here.');
    $id = $rec['id'];
    $GLOBALS['__data_write_failed'] = false; $GLOBALS['__data_refused'] = [];
    if ($action === 'toggle_collection_flag') {
        $field = isset($_POST['front']) ? 'front' : (isset($_POST['owngallery']) ? 'ownGallery' : (isset($_POST['private']) ? 'private' : ''));
        if ($field === '') collection_fail('Nothing to change.');
        $on = (string) ($_POST[$field === 'ownGallery' ? 'owngallery' : $field]) === '1';
        collections_update(function (&$d) use ($id, $field, $on) { foreach ($d['collections'] as &$r) if (is_array($r) && ($r['id'] ?? '') === $id) $r[$field] = $on; });
        collection_saved_or_fail();
        if ($field === 'ownGallery') own_galleries_recompute($dir, $files);
        $now = collection_find_by_id($id);
        admin_json_exit(['ok' => true, 'private' => $now['private'], 'text' => $field === 'front' ? ($on ? 'It shows on the front page too.' : 'It no longer shows on the front page.') : ($field === 'private' ? ($on ? 'Private: visitors see nothing of this collection (its folders and photos stay as they are).' : 'Public again.') : ($on ? 'Visitors who arrive in this collection are offered nothing above it.' : 'Back to ordinary.'))]);
    }
    if ($action === 'save_folder_identity') {
        $changes = [];
        if (array_key_exists('display_name', $_POST)) $changes['title'] = substr(trim((string) $_POST['display_name']), 0, 200);
        if (array_key_exists('description', $_POST)) $changes['description'] = admin_clean_description($_POST['description'], 1000);
        if (array_key_exists('dates', $_POST)) $changes['dates'] = admin_clean_text($_POST['dates'], 80);
        if (array_key_exists('sort_order', $_POST)) {
            $raw = trim((string) $_POST['sort_order']);
            if ($raw === '') $changes['position'] = null;
            elseif (preg_match('/^-?\d{1,5}$/', $raw)) $changes['position'] = (int) $raw;
            else collection_fail('Position must be a whole number (or blank for natural order).');
        }
        if (array_key_exists('subfolder_style', $_POST)) { $st = (string) $_POST['subfolder_style']; $changes['subfolderStyle'] = in_array($st, ['overview', 'flat'], true) ? $st : null; }
        foreach (['flat_names' => 'flatNames', 'flat_notes' => 'flatNotes'] as $pk => $rk) if (array_key_exists($pk, $_POST)) { $v = (string) $_POST[$pk]; $changes[$rk] = $v === '1' ? true : ($v === '0' ? false : null); }
        if (array_key_exists('photo_sort_order', $_POST)) $changes['photoSort'] = admin_photo_sort_from_post();
        if (array_key_exists('coll_address', $_POST)) {
            $name = trim((string) $_POST['coll_address']);
            if ($name !== $rec['name']) {
                $why = collection_address_problem($dir, $files, $rec['parentPath'] ?? ($adminFolderPath !== null && strpos($adminFolderPath, '/') !== false ? dirname($adminFolderPath) : ''), $name, $id);
                if ($why !== '') collection_fail($why);
                $changes['name'] = $name;
            }
        }
        $loaded = isset($_POST['loaded_hash']) ? (string) $_POST['loaded_hash'] : null;
        $stale = false; $newHash = null;
        collections_update(function (&$d) use ($id, $changes, $loaded, &$stale, &$newHash) {
            foreach ($d['collections'] as &$r) {
                if (!is_array($r) || ($r['id'] ?? '') !== $id) continue;
                $cur = collection_clean($r);
                if ($loaded !== null && !hash_equals(admin_record_hash(folder_identity_record(collection_as_items($cur))), $loaded)) { $stale = true; return; }
                foreach ($changes as $k => $v) $r[$k] = $v;
                $newHash = admin_record_hash(folder_identity_record(collection_as_items(collection_clean($r))));
            }
        });
        if ($stale) admin_json_exit(['ok' => false, 'stale' => true, 'text' => 'This collection\'s settings' . admin_stale_message()]);
        collection_saved_or_fail();
        $now = collection_find_by_id($id);
        $reg = collections_registry($dir, $files);
        $newPath = null; foreach ($reg['byPath'] as $p => $r) if ($r['id'] === $id) $newPath = $p;
        admin_json_exit(['ok' => true, 'text' => 'Saved', 'hash' => $newHash, 'path' => $newPath, 'name' => $now['name']]);
    }
    if ($action === 'collection_member_add' || $action === 'collection_member_add_files') {
        $json = (string) ($_POST['items'] ?? '');
        if ($action === 'collection_member_add_files') {   // the Select bar: photos of one folder page, by their names
            $folder = trim((string) ($_POST['folder'] ?? ''), '/');
            $names = json_decode((string) ($_POST['files'] ?? ''), true);
            if (!is_array($names)) collection_fail('Nothing was chosen.');
            $json = json_encode(array_map(function ($n) use ($folder) { return ['path' => $folder, 'file' => is_string($n) ? basename($n) : '']; }, $names));
        }
        [$add, $err] = collection_members_from_post($dir, $files, $json);
        if ($err !== '') collection_fail($err);
        if (!empty($_POST['check'])) {   // the page asks first: would this open anything private to people on a share link that names this collection?
            $linkNames = [];
            foreach ((array) (links_read()['links'] ?? []) as $lk) if (is_array($lk) && in_array($id, (array) ($lk['scope']['folders'] ?? []), true) && !link_is_public_log($lk)) $linkNames[] = (string) ($lk['label'] ?? 'a link');
            $reg = collections_registry($dir, $files); $opens = [];
            foreach ($add as $m) {
                $p = $reg['idPaths'][$m['fid']] ?? null; if ($p === null) continue;
                if (isset($m['file'])) { $f = $p === '' ? $m['file'] : $p . '/' . $m['file']; if (file_is_unlisted($dir, $f) || file_is_hidden($dir, $f, items_get_all_for_files($dir, [$f]))) $opens[] = $m['file']; }
                elseif (folder_is_unlisted($dir, $p) || folder_is_private($dir, $p) || folder_above_is_private($dir, $p)) $opens[] = $p;
            }
            if ($linkNames && $opens) {
                $n = count($linkNames);
                collection_fail_warn($n . ' share link' . ($n === 1 ? '' : 's') . ' include' . ($n === 1 ? 's' : '') . ' this collection (' . implode(', ', array_slice($linkNames, 0, 3)) . ($n > 3 ? ' and ' . ($n - 3) . ' more' : '') . '): ' . ($n === 1 ? 'it' : 'they') . ' would gain access to ' . implode(', ', array_slice($opens, 0, 3)) . (count($opens) > 3 ? ' and ' . (count($opens) - 3) . ' more' : '') . ', which ' . (count($opens) === 1 ? 'is' : 'are') . ' private.');
            }
            admin_json_exit(['ok' => true, 'text' => '', 'warn' => '']);
        }
        $added = 0;
        collections_update(function (&$d) use ($id, $add, &$added) {
            foreach ($d['collections'] as &$r) {
                if (!is_array($r) || ($r['id'] ?? '') !== $id) continue;
                $r['items'] = array_values((array) ($r['items'] ?? []));
                foreach ($add as $m) {
                    $dup = false;
                    foreach ($r['items'] as $have) if (is_array($have) && ($have['fid'] ?? '') === $m['fid'] && ((isset($m['file']) && ($have['file'] ?? null) === $m['file']) || (!isset($m['file']) && !isset($have['file'])))) { $dup = true; break; }
                    if (!$dup) { $r['items'][] = $m; $added++; }
                }
            }
        });
        collection_saved_or_fail();
        admin_json_exit(['ok' => true, 'added' => $added, 'text' => $added === 0 ? 'They were all in it already.' : 'Added ' . $added . ($added === 1 ? ' member.' : ' members.')]);
    }
    if ($action === 'collection_member_remove') {
        $key = (string) ($_POST['key'] ?? '');   // f:<folder id> or p:<folder id>/<file name>
        $removed = 0;
        collections_update(function (&$d) use ($id, $key, &$removed) {
            foreach ($d['collections'] as &$r) {
                if (!is_array($r) || ($r['id'] ?? '') !== $id) continue;
                $keep = [];
                foreach ((array) ($r['items'] ?? []) as $it) {
                    $k = !is_array($it) ? '' : (isset($it['file']) ? 'p:' . ($it['fid'] ?? '') . '/' . $it['file'] : 'f:' . ($it['fid'] ?? ''));
                    if ($k === $key && !$removed) { $removed++; continue; }
                    $keep[] = $it;
                }
                $r['items'] = $keep;
            }
        });
        collection_saved_or_fail();
        admin_json_exit(['ok' => true, 'removed' => $removed, 'text' => $removed ? 'Taken out of the collection. Nothing was deleted.' : 'It was not in the collection.']);
    }
    if ($action === 'collection_member_remove_files') {   // the Select bar on a collection's page: single photos by their full path
        $paths = json_decode((string) ($_POST['files'] ?? ''), true);
        if (!is_array($paths) || !$paths) collection_fail('Nothing was chosen.');
        $reg = collections_registry($dir, $files);
        $removed = 0; $covered = 0;
        $want = [];
        foreach ($paths as $f) { if (!is_string($f)) continue; $d = dirname($f); $fid = collection_folder_id($dir, ($d === '.' || $d === '') ? '' : $d); if ($fid !== '') $want['p:' . $fid . '/' . basename($f)] = true; }
        collections_update(function (&$d) use ($id, $want, &$removed) {
            foreach ($d['collections'] as &$r) {
                if (!is_array($r) || ($r['id'] ?? '') !== $id) continue;
                $keep = [];
                foreach ((array) ($r['items'] ?? []) as $it) {
                    $k = is_array($it) && isset($it['file']) ? 'p:' . ($it['fid'] ?? '') . '/' . $it['file'] : '';
                    if ($k !== '' && isset($want[$k])) { $removed++; continue; }
                    $keep[] = $it;
                }
                $r['items'] = $keep;
            }
        });
        collection_saved_or_fail();
        $covered = max(0, count($want) - $removed);
        admin_json_exit(['ok' => true, 'removed' => $removed, 'covered' => $covered, 'text' => ($removed ? 'Taken out of the collection (nothing was deleted).' : 'Nothing was taken out.') . ($covered ? ' ' . $covered . ' of them come with a whole folder in it: take that folder out, or change it to "Only its own photos", to remove them.' : '')]);
    }
    if ($action === 'collection_member_mode') {
        $fid = (string) ($_POST['fid'] ?? ''); $mode = (string) ($_POST['mode'] ?? '') === 'own' ? 'own' : 'all';
        collections_update(function (&$d) use ($id, $fid, $mode) {
            foreach ($d['collections'] as &$r) {
                if (!is_array($r) || ($r['id'] ?? '') !== $id) continue;
                foreach ($r['items'] as &$it) if (is_array($it) && !isset($it['file']) && ($it['fid'] ?? '') === $fid) $it['mode'] = $mode;
            }
        });
        collection_saved_or_fail();
        admin_json_exit(['ok' => true, 'text' => $mode === 'own' ? 'Only that folder\'s own photos are in it.' : 'Everything inside that folder is in it.']);
    }
    collection_fail('Unknown collection action.');
}

/* ---- what the owner sees ------------------------------------------------ */

/** The address of a collection as someone types it: the gallery's own address and the path (the tidy form where the server has the rule). */
function collection_address_text($path) {
    $base = rtrim(str_replace('\\', '/', dirname($_SERVER['SCRIPT_NAME'] ?? '/')), '/');
    return $base . '/' . $path;
}

/** One line per member of a collection, with what the owner needs to see: where it is, whether it is public, how much of it is there, or that it is
 *  missing. key is what a remove names. */
function collection_member_rows($dir, $rec, $files) {
    $reg = collections_registry($dir, $files);
    $rows = [];
    foreach ($rec['items'] as $it) {
        $path = $reg['idPaths'][$it['fid']] ?? null;
        if (isset($it['file'])) {
            $key = 'p:' . $it['fid'] . '/' . $it['file'];
            $file = $path === null ? null : ($path === '' ? $it['file'] : $path . '/' . $it['file']);
            if ($file === null || !in_array($file, $files, true)) { $rows[] = ['key' => $key, 'kind' => 'photo', 'label' => $it['file'], 'where' => $path ?? '', 'state' => 'missing', 'count' => 0, 'mode' => '', 'thumb' => null]; continue; }
            $state = file_is_unlisted($dir, $file) ? 'unlisted' : (file_is_hidden($dir, $file, items_get_all_for_files($dir, [$file])) ? 'private' : 'public');
            $rows[] = ['key' => $key, 'kind' => 'photo', 'label' => $it['file'], 'where' => $path, 'path' => $file, 'state' => $state, 'count' => 1, 'mode' => '', 'thumb' => img_url($file, 'thumb')];
            continue;
        }
        $key = 'f:' . $it['fid'];
        if ($path === null || $path === '' || empty(folder_files_under($files, $path))) { $rows[] = ['key' => $key, 'kind' => 'folder', 'fid' => $it['fid'], 'label' => $path === null ? 'a folder that is gone' : $path, 'where' => '', 'state' => 'missing', 'count' => 0, 'mode' => $it['mode'], 'thumb' => null]; continue; }
        $own = $it['mode'] === 'own';
        $n = 0; foreach ($files as $f) { if (strncmp($f, $path . '/', strlen($path) + 1) !== 0) continue; if ($own && dirname($f) !== $path) continue; $n++; }
        $state = folder_is_unlisted($dir, $path) ? 'unlisted' : (folder_is_private($dir, $path) || folder_above_is_private($dir, $path) ? 'private' : 'public');
        $rows[] = ['key' => $key, 'kind' => 'folder', 'fid' => $it['fid'], 'label' => $path, 'where' => '', 'path' => $path, 'state' => $state, 'count' => $n, 'mode' => $it['mode'], 'thumb' => null];
    }
    return $rows;
}

function collection_pill($state) {
    $t = ['public' => ['', 'Public'], 'private' => [' priv', 'Private'], 'unlisted' => [' priv', 'Not listed'], 'missing' => [' miss', 'Not found']][$state] ?? ['', ''];
    return '<span class="cm-pill' . $t[0] . '">' . $t[1] . '</span>';
}

/** The "Collections" section of a folder's (or the front page's) settings: the collections in it, with a way into each and to delete it, and a box to make one
 *  from just a name. $parentPath is the folder (null or '' for the front page). */
function render_admin_collections_section($dir, $files, $parentPath, $csrfToken) {
    $parent = (string) $parentPath;
    $reg = collections_registry($dir, $files);
    $here = $reg['byParent'][$parent] ?? [];
    $esc = function ($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); };
?>
    <h3 class="subhead">Collections</h3>
    <div class="cm-section" data-csrf="<?= $csrfToken ?>" data-parent="<?= $esc($parent) ?>">
    <p class="hint" style="margin:0 0 6px"><?= $parent === '' ? 'A collection is a hand-picked set that shows up on the front page as a card of its own.' : 'A collection is a hand-picked set that shows up in this folder as a card of its own.' ?> What is in it stays where it is on disk.</p>
    <?php if ($here): ?>
    <ul class="cm-list">
      <?php foreach ($here as $r): $rows = collection_member_rows($dir, $r, $files); $nf = count(array_filter($rows, fn ($x) => $x['kind'] === 'folder')); $np = count($rows) - $nf; $nested = array_sum(array_map(fn ($x) => (int) $x['count'], array_filter($rows, fn ($x) => $x['kind'] === 'folder'))); $href = '?admin&amp;folder=' . $esc(rawurlencode($r['path'])) . '#settings'; ?>
      <li class="cm-row" data-id="<?= $esc($r['id']) ?>">
        <div class="cm-main"><a class="coll" href="<?= $href ?>"><?= $esc($r['title'] !== '' ? $r['title'] : $r['name']) ?></a><?= $r['private'] ? ' ' . collection_pill('private') : '' ?>
          <div class="cm-sub"><?= $nf ?> folder<?= $nf === 1 ? '' : 's' ?>, <?= number_format($nested) ?> nested photo<?= $nested === 1 ? '' : 's' ?><?= $np ? ' and ' . $np . ' picked on their own' : '' ?> &middot; <?= $esc(collection_address_text($r['path'])) ?></div></div>
        <div class="cm-acts"><a class="secondary btn-link" href="<?= $href ?>">Open settings</a><button type="button" class="secondary cm-del" data-id="<?= $esc($r['id']) ?>" data-title="<?= $esc($r['title'] !== '' ? $r['title'] : $r['name']) ?>">Delete collection</button></div>
      </li>
      <?php endforeach; ?>
    </ul>
    <?php endif; ?>
    <form class="cm-new" method="post" onsubmit="return false;">
      <input type="text" name="title" maxlength="80" placeholder="Name of the new collection" aria-label="Name of the new collection">
      <button type="submit" class="primary">New collection</button>
      <span class="rowstate" role="status" aria-live="polite"></span>
    </form>
    <p class="hint">You only choose a name now; everything else is on the next page. Deleting a collection removes only the collection: nothing in it is touched on disk.</p>
    </div>
<?php
}

/** A collection's own settings page: the folder settings form (with the address after the name), the three switches, the order of its photos, and Members. */
function render_admin_collection_panel($dir, $files, $rec, $csrfToken) {
    $esc = function ($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); };
    $items = collection_as_items($rec);
    $path = $rec['path'];
    $rows = collection_member_rows($dir, $rec, $files);
    $hidden = ['folder' => 0, 'photo' => 0];
    foreach ($rows as $m) if (in_array($m['state'], ['private', 'unlisted'], true)) $hidden[$m['kind']]++;
    $onFront = $rec['parentPath'] === '';
?>
  <section class="panel" id="settings" data-collection="<?= $esc($rec['id']) ?>">
    <h2 class="section-title">This collection's own settings</h2>
    <?php render_admin_identity_form($items, $csrfToken, $path, null, 'main', $rec); ?>
    <div class="folder-switches coll-switches" data-private="<?= $rec['private'] ? '1' : '0' ?>">
      <?php if (!$onFront) render_admin_instant_toggle($csrfToken, 'toggle_collection_flag', 'front', $rec['front'] && !$rec['private'], 'Show on front page', '', '', 'unlisted-form coll-front' . ($rec['private'] ? ' is-off' : '')); ?>
      <?php render_admin_instant_toggle($csrfToken, 'toggle_collection_flag', 'owngallery', $rec['ownGallery'], 'Gallery of its own', '', ' <small class="muted">(limits navigation)</small>', 'unlisted-form'); ?>
      <?php render_admin_instant_toggle($csrfToken, 'toggle_collection_flag', 'private', $rec['private'], 'Private collection', '', '', 'unlisted-form coll-private'); ?>
    </div>
    <?php render_admin_identity_form($items, $csrfToken, $path, null, 'sort', $rec); ?>
    <h3 class="subhead">Members</h3>
    <?php
      $folderOpts = [];
      foreach (folder_tree_rows($dir, all_folder_paths($files)) as $fr) $folderOpts[] = ['p' => $fr['p'], 'n' => $fr['n'], 'd' => $fr['d'], 'x' => folder_is_private($dir, $fr['p']) || folder_above_is_private($dir, $fr['p']), 'u' => folder_is_unlisted($dir, $fr['p'])];
      $memberFolders = []; $memberPhotos = [];
      foreach ($rows as $m) { if ($m['state'] === 'missing') continue; if ($m['kind'] === 'folder') $memberFolders[] = $m['path']; else $memberPhotos[] = $m['path']; }
    ?>
    <div class="cm-members" data-csrf="<?= $csrfToken ?>" data-id="<?= $esc($rec['id']) ?>" data-folder="<?= $esc($path) ?>" data-title="<?= $esc($rec['title'] !== '' ? $rec['title'] : $rec['name']) ?>" data-folders="<?= $esc(json_encode($folderOpts, JSON_HEX_TAG | JSON_HEX_AMP)) ?>" data-have="<?= $esc(json_encode(['folders' => $memberFolders, 'photos' => $memberPhotos], JSON_HEX_TAG | JSON_HEX_AMP)) ?>">
    <p class="hint" style="margin:0 0 6px">The folders and photos shown in this collection. They stay where they are on disk: removing one here only takes it out of the collection.</p>
    <ul class="cm-list" id="cm-members">
      <?php foreach ($rows as $m): ?>
      <li class="cm-row" data-key="<?= $esc($m['key']) ?>"<?= isset($m['fid']) ? ' data-fid="' . $esc($m['fid']) . '"' : '' ?>>
        <span class="cm-kind"><?= $m['kind'] === 'folder' ? 'Folder' : 'Photo' ?></span>
        <?php if ($m['thumb'] !== null): ?><img class="cm-th" src="<?= $esc($m['thumb']) ?>" alt="" loading="lazy"><?php endif; ?>
        <div class="cm-main">
          <?php if ($m['state'] === 'missing'): ?><span class="coll"><?= $esc($m['label']) ?></span><?php else: ?><a href="<?= $m['kind'] === 'folder' ? '?folder=' . $esc(rawurlencode($m['path'])) : '?folder=' . $esc(rawurlencode($m['where'])) ?>"><?= $esc($m['label']) ?></a><?php endif; ?>
          <?= collection_pill($m['state']) ?>
          <div class="cm-sub"><?php
            if ($m['state'] === 'missing') echo $m['kind'] === 'photo' ? 'It was renamed or moved. Remove it, or put it back.' : 'The folder is gone, or has no photos. Remove it, or put it back.';
            elseif ($m['kind'] === 'photo') echo $m['where'] === '' ? 'at the top of the gallery' : 'in ' . $esc($m['where']);
            elseif (in_array($m['state'], ['private', 'unlisted'], true)) echo 'Visitors will not see this one in the collection until it is public.';
            else echo number_format($m['count']) . ' photo' . ($m['count'] === 1 ? '' : 's');
          ?></div>
        </div>
        <?php if ($m['kind'] === 'folder' && $m['state'] !== 'missing'): ?>
        <span class="cm-seg" role="radiogroup" aria-label="What is in it">
          <label><input type="radio" name="cm-mode-<?= $esc($m['fid']) ?>" value="all"<?= $m['mode'] === 'all' ? ' checked' : '' ?>><span>Everything inside</span></label><label><input type="radio" name="cm-mode-<?= $esc($m['fid']) ?>" value="own"<?= $m['mode'] === 'own' ? ' checked' : '' ?>><span>Only its own photos</span></label>
        </span>
        <?php endif; ?>
        <button type="button" class="secondary cm-rm">Remove</button>
      </li>
      <?php endforeach; ?>
    </ul>
    <?php if ($hidden['folder'] + $hidden['photo'] > 0): ?>
    <div class="warn-note"><?= $hidden['folder'] ? $hidden['folder'] . ' folder' . ($hidden['folder'] === 1 ? '' : 's') : '' ?><?= $hidden['folder'] && $hidden['photo'] ? ' and ' : '' ?><?= $hidden['photo'] ? $hidden['photo'] . ' photo' . ($hidden['photo'] === 1 ? '' : 's') : '' ?> here <?= $hidden['folder'] + $hidden['photo'] === 1 ? 'is' : 'are' ?> private. Visitors will not see <?= $hidden['folder'] + $hidden['photo'] === 1 ? 'it' : 'them' ?> in this collection.</div>
    <?php endif; ?>
    <p class="cm-addrow"><button type="button" class="secondary cm-add">Add folders or photos&hellip;</button></p>
    <div id="cm-picker" hidden></div>
