/** "today", "yesterday", "3 days ago". */
function signin_ago($t, $now = null) {
    $d = (int) floor((($now ?? time()) - $t) / 86400);
    return $d <= 0 ? 'today' : ($d === 1 ? 'yesterday' : $d . ' days ago');
}

