  .ed-folder[hidden], .ed-it[hidden], .ed-fset[hidden], .ed-strip[hidden], .ed-more[hidden], .ed-body[hidden] { display:none; }
  .ed-head { display:flex; flex-wrap:wrap; align-items:center; gap:6px 10px; width:100%; padding:12px 14px; background:none; border:0; color:inherit; font:inherit; text-align:left; cursor:pointer; }
  .ed-head:hover { background:rgba(255,255,255,0.04); }
  .ed-head:focus-visible { outline:2px solid var(--accent); outline-offset:-2px; }
  .ed-name { font-weight:700; flex:1 1 200px; min-width:0; overflow-wrap:anywhere; }
  .ed-name small { display:block; font-weight:400; color:var(--muted); font-size:0.8rem; }
  .ed-chev { margin-left:auto; color:var(--muted); font-size:1.3rem; line-height:1; transition:transform .15s; }
  .ed-folder.open .ed-chev { transform:rotate(90deg); }
  .ed-folder.open .ed-head { border-bottom:1px solid #2c2c31; }
  .ed-fsum { display:flex; flex-wrap:wrap; align-items:center; gap:5px; flex:1 1 100%; order:3; }
  .ed-fsum:empty { display:none; }
  .ed .tag { display:inline-flex; align-items:center; padding:2px 9px; border-radius:999px; font-size:0.78rem; font-weight:700; background:#232327; border:1px solid #3a3a42; color:#cfcfd6; white-space:nowrap; }
  .ed .tag.ed-priv, .ed .tag.ed-hid { background:rgba(237,66,69,0.14); border-color:rgba(237,66,69,0.4); color:#ff8587; }
  .ed .tag.ed-pub { background:rgba(59,165,92,0.14); border-color:rgba(59,165,92,0.4); color:#5fcf8b; }
  .ed .tag.ed-cap { background:rgba(88,101,242,0.16); border-color:rgba(88,101,242,0.45); color:#aab2ff; }
  .ed .tag.ed-loc { background:rgba(240,178,50,0.13); border-color:rgba(240,178,50,0.4); color:#f0b232; }
  .ed-fset { padding:9px 14px; display:flex; flex-wrap:wrap; gap:6px; align-items:center; font-size:0.85rem; }
  .ed-btn { display:inline-flex; align-items:center; min-height:30px; padding:3px 11px; border-radius:8px; background:#232327; border:1px solid #3a3a42; color:var(--text); font-size:0.85rem; font-weight:600; text-decoration:none; }
  .ed-btn:hover { background:#2c2c31; }
  .ed-row { display:flex; gap:12px; padding:11px 14px; border-top:1px solid #26262a; align-items:flex-start; }
  .ed-fset + .ed-row, .ed-fset-links + .ed-row { border-top:0; }
  .ed-th { position:relative; flex:none; width:84px; height:84px; border-radius:8px; overflow:hidden; background:#26262b; display:block; }
  .ed-th .pv-img img { width:100%; height:100%; object-fit:cover; display:block; }
  .ed-rb { flex:1; min-width:0; }
  .ed-rn { font-weight:700; font-size:0.92rem; overflow-wrap:anywhere; }
  .ed-tags { display:flex; flex-wrap:wrap; gap:5px; margin:4px 0 2px; }
  .ed-t { color:#cfcfd6; font-size:0.88rem; overflow-wrap:anywhere; }
  .ed-strip { padding:11px 14px; border-top:1px solid #26262a; }
  .ed-strip-h { margin:0 0 8px; font-size:0.85rem; color:var(--muted); font-weight:600; display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
  .ed-sth { display:flex; flex-wrap:wrap; gap:5px; }
  .ed-sth { gap:10px; }
  .ed-more { width:84px; height:84px; border-radius:8px; background:#232327; border:1px dashed #3a3a42; color:#aab2ff; font:inherit; font-weight:700; font-size:0.95rem; cursor:pointer; }
  .ed-more { transition:border-color .15s, background .15s, transform .12s; }
  .ed-more:active { transform:scale(0.96); }
  @media (hover: hover) { .ed-more:hover { border-color:#6b77f0; background:#2c2c31; } }
  .ed-top { display:flex; gap:14px; align-items:flex-start; padding:12px 14px 0; }
  .ed-top-r { flex:1; min-width:0; }
  .ed-top .ed-fset-links { padding:0; display:flex; flex-wrap:wrap; gap:8px; }
  .ed-top .ed-fset { padding:10px 0 12px; border-bottom:0; }
  .ed-pf { margin:8px 0 0; font-size:0.85rem; }
  .ed-cover { position:relative; flex:none; width:84px; height:84px; border-radius:8px; overflow:hidden; display:block; background:#26262b; box-shadow:0 0 0 1px #34343a; }
  .ed-cover img { width:100%; height:100%; object-fit:cover; display:block; }
  .ed-cover i { position:absolute; left:5px; bottom:5px; width:26px; height:26px; border-radius:50%; background:#f5c542; color:#1a1a1c; display:grid; place-items:center; border:1px solid rgba(255,255,255,0.35); }
  .ed-cover i .ico { width:14px; height:14px; fill:currentColor; }
  .ed-cover:hover { box-shadow:0 0 0 2px var(--accent); }
  .ed-top + .ed-row { border-top:1px solid #26262a; }
  .ed-top + .ed-strip { border-top:1px solid #26262a; }
  .hidden-warning { display:flex; flex-wrap:wrap; align-items:center; gap:6px 14px; }
  .hidden-warning[hidden] { display:none; }
  .hidden-warning .lock-open-text { flex:1 1 320px; }
  .ed-more-note { margin:6px 14px 10px; font-size:0.82rem; }
  .side-hidden.edited { color:var(--text); background:rgba(255,255,255,0.04); border-color:#2c2c31; }
  .side-hidden.edited .count { background:rgba(255,255,255,0.09); color:#b0b0b6; }
  .side-hidden.edited:hover { background:rgba(255,255,255,0.08); }
  .side-hidden.edited.active { color:#fff; background:rgba(88,101,242,0.3); border-color:var(--accent); }
  .side-hidden.edited.active .count { background:rgba(88,101,242,0.7); color:#fff; }
  @media (max-width: 520px) { .ed-row { flex-wrap:wrap; } .ed-rb { flex:1 1 calc(100% - 100px); } .ed-row > .ed-btn { margin-left:88px; } .ed-th { width:76px; height:76px; } }
  /* The Edited tab: a photo's thumbnail in a strip, with its lock. */
  .pv-th { position:relative; width:84px; height:84px; border-radius:8px; overflow:hidden; background:#26262a; display:block; }
  .pv-img { display:block; width:100%; height:100%; }
  .pv-img img { width:100%; height:100%; object-fit:cover; display:block; }
  .pv-lock { display:none; position:absolute; left:5px; bottom:5px; width:28px; height:28px; padding:0; border-radius:50%; align-items:center; justify-content:center; color:#fff; border:1px solid rgba(255,255,255,0.35); cursor:pointer; transition:transform .12s, box-shadow .12s, background .15s; }
  .js-tabs .pv-lock { display:flex; }
  .pv-lock .ico { width:15px; height:15px; }
  .pv-lock.own { background:rgba(237,66,69,0.92); }
  .pv-lock.pub { background:rgba(0,0,0,0.62); }
  .pv-lock::after { content:''; position:absolute; inset:-6px; }   /* a bigger target for a finger */
  @media (hover: hover) { .pv-lock:hover { transform:scale(1.14); box-shadow:0 0 0 2px #fff; background:var(--accent); border-color:#fff; } }
  .pv-lock:active { transform:scale(0.92); }
  .pv-lock:disabled { opacity:.4; pointer-events:none; }
  .pv-lock:focus-visible { outline:2px solid #fff; outline-offset:2px; }
  .pv-hint { font-size:0.8rem; color:var(--muted); margin:10px 0 0; line-height:1.45; }
  .pv-toast { position:fixed; left:50%; bottom:24px; transform:translateX(-50%); z-index:150; background:#26262a; border:1px solid #34343a; border-radius:10px; padding:10px 16px; font-size:0.9rem; box-shadow:0 8px 28px rgba(0,0,0,0.5); max-width:calc(100vw - 32px); }
  .pv-toast[hidden] { display:none; }
  .pv-toast button { color:#aab2ff; font-weight:600; margin-left:10px; }
  .pv-toast.err { border-color:rgba(237,66,69,0.6); color:#ff9a9c; }
  @media (max-width:600px) { .pv-th { width:76px; height:76px; } }
  .admin-layout { max-width:1180px; margin:0 auto; padding:18px 16px 64px; display:grid; grid-template-columns:210px minmax(0,1fr); gap:22px; align-items:start; }
  .admin-side { position:sticky; top:76px; max-height:calc(100vh - 92px); overflow-y:auto; }
  .admin-folders > summary { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.06em; color:var(--muted); margin:0 0 8px; padding-left:12px; cursor:pointer; list-style:none; }
  .admin-side .muted { padding-left:12px; }
  .admin-folders > summary::-webkit-details-marker { display:none; }
  .admin-folders > summary, .site-group > summary { position:relative; padding-right:30px; }
  .admin-folders > summary::after, .site-group > summary::after { content:""; position:absolute; right:12px; top:50%; width:7px; height:7px; border-right:2px solid var(--muted); border-bottom:2px solid var(--muted); transform:translateY(-70%) rotate(45deg); transition:transform .15s; }
  .admin-folders[open] > summary::after, .site-group[open] > summary::after { transform:translateY(-30%) rotate(-135deg); }
  .admin-folders > summary:hover::after, .site-group > summary:hover::after { border-color:var(--text); }
  .site-group > summary { list-style:none; }
  .site-group > summary::-webkit-details-marker { display:none; }
  .admin-folders > summary .here { text-transform:none; letter-spacing:0; display:none; color:var(--text); }
  .admin-folder-nav ul { list-style:none; margin:0; padding:0; }
  .admin-folder-nav li { position:relative; margin:1px 0; }
  /* A level in: a guide line down the left, so a child clearly belongs to its parent. */
  .admin-folder-nav li > ul { margin-left:15px; border-left:1px solid #34343a; }
  .admin-folder-nav a { display:flex; align-items:center; justify-content:space-between; gap:8px; color:var(--muted); text-decoration:none; padding:5px 8px 5px 12px; border-radius:6px; font-size:0.85rem; }
  .admin-folder-nav a .fname { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; min-width:0; }
  .admin-folder-nav a .fcount { flex:none; font-size:0.72rem; color:#6f6f78; font-variant-numeric:tabular-nums; }
  .admin-folder-nav a:hover { color:var(--text); background:var(--card); }
  .admin-folder-nav a:hover .fcount { color:var(--muted); }
  .admin-folder-nav a.current { color:#fff; background:var(--accent); font-weight:600; }
  .admin-folder-nav a.current .fcount { color:rgba(255,255,255,0.8); font-weight:500; }
  /* While Settings (or Private) is the section on show, the folder you came from is only marked, not lit like the selection. */
  .admin-layout.off-folder .admin-folder-nav a.current { color:var(--text); background:rgba(255,255,255,0.05); font-weight:500; }
  .admin-layout.off-folder .admin-folder-nav a.current .fcount { color:#6f6f78; }
  /* The fold chevron sits in the gutter left of the name, so names stay in one column. */
  .admin-folder-nav .ftoggle { position:absolute; left:-1px; top:5px; width:14px; height:22px; padding:0; border:0; background:transparent; color:var(--muted); cursor:pointer; z-index:1; border-radius:4px; }
  .admin-folder-nav .ftoggle::before { content:""; font-size:0.7rem; display:block; margin:calc((22px - .43em) / 2) auto 0; width:0; height:0; border-left:.3em solid transparent; border-right:.3em solid transparent; border-top:.43em solid currentColor; transition:transform .12s; }
  .admin-folder-nav li.collapsed > .ftoggle::before { transform:rotate(-90deg); }
  .admin-folder-nav .ftoggle:hover { color:var(--text); background:rgba(255,255,255,0.08); }
  .admin-folder-nav li.collapsed > ul { display:none; }
  .admin-main { min-width:0; }
  .admin-main section, .admin-main details.panel { scroll-margin-top:84px; }
  .admin-main h2.section-title { font-size:1.05rem; margin:0 0 12px; }
  .admin-main details.panel > summary { cursor:pointer; font-weight:600; font-size:1.05rem; list-style:none; display:flex; align-items:center; gap:10px; }
  .admin-main details.panel > summary::-webkit-details-marker { display:none; }
  .admin-main details.panel > summary::before { content:""; flex:none; width:0; height:0; font-size:.9em; border-top:.3em solid transparent; border-bottom:.3em solid transparent; border-left:.43em solid var(--muted); transition:transform .15s; }
  .admin-main details.panel[open] > summary::before { transform:rotate(90deg); }
  .admin-main details.panel > summary .count { font-weight:400; font-size:0.8rem; color:var(--muted); }
  .admin-main details.panel[open] > summary { margin-bottom:12px; }
  details.subtle { margin-top:10px; }
  details.subtle > summary { cursor:pointer; color:var(--muted); font-size:0.85rem; }
  .hint { color:var(--muted); font-size:0.75rem; margin:3px 0 0; }
  .hint.unlisted-note { margin:4px 0 14px; }
  h3.subhead { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.06em; color:var(--muted); margin:18px 0 8px; font-weight:600; }
  .settings-grid { display:grid; grid-template-columns:2fr 1fr 1fr; gap:10px 14px; }
  .settings-grid.root { grid-template-columns:2fr 1fr; }
  .settings-grid .wide { grid-column:1 / -1; }
  .hidden-warning { font-size:0.9rem; line-height:1.55; }
  .lock-result { margin-top:6px; font-size:0.85rem; }
  .lock-result:empty { display:none; }
  /* Links in the admin's running text: the teal of the sidebar link, not the browser's default blue. */
  .admin-main p a, .admin-main li a, .admin-main .help a, .admin-main .muted a, .admin-main .dl-inside a { color:#aab2ff; border-radius:3px; transition:color .15s, background .15s, box-shadow .15s; }
  .admin-main p a:hover, .admin-main li a:hover, .admin-main dd a:hover, .admin-main td a:hover, .admin-main .hint a:hover, .admin-main .help a:hover, .admin-main .muted a:hover, .admin-main .dl-inside a:hover { color:#e1e4ff; background:rgba(170,178,255,0.16); box-shadow:0 0 0 3px rgba(170,178,255,0.16); border-radius:3px; }
  .admin-main .flash a, .admin-main .flash a:hover { color:inherit; }
  .admin-main .flash .linklike { color:inherit; }
  .admin-main .flash a:hover { background:rgba(255,255,255,0.14); box-shadow:0 0 0 3px rgba(255,255,255,0.14); }
  .subhead { scroll-margin-top:70px; }
  .site-group.flash-target { outline:2px solid var(--accent); outline-offset:3px; }
  .site-row.flash-target { outline:2px solid var(--accent); outline-offset:3px; border-radius:6px; }
  .subhead.flash-target { outline:2px solid var(--accent); outline-offset:4px; border-radius:4px; }
  .media-panel.flash-target { outline:2px solid var(--accent); outline-offset:3px; }
  .dl-folders { margin:10px 0; }
  .dl-folders[hidden], .dl-none[hidden] { display:none; }
  .dl-folders .dl-menu { display:block; margin-left:0; }
  .dl-folders .dl-menu .menu-pop { left:0; right:auto; min-width:max(100%, 260px); max-width:min(440px, 92vw); max-height:320px; overflow:auto; }
  .dl-opt { display:flex; justify-content:space-between; align-items:center; gap:16px; min-height:44px; padding:0 14px; cursor:pointer; font-size:0.9rem; position:relative; }
  .dl-opt input { position:absolute; opacity:0; width:100%; height:100%; left:0; top:0; margin:0; cursor:pointer; }
  .dl-opt .dl-tick { color:#aab2ff; opacity:0; flex:none; }
