  var framed = /[?&]inframe=1/.test(location.search), tickAt = 0, busy = false, bar = null, marked = 0;
  function url(extra) { return '?admin&changed=1' + (folder ? '&folder=' + encodeURIComponent(folder) : '') + extra; }
